#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CruftScriptSourceProvenance {
    pub path: String,
    pub source_len: usize,
    pub span: Span,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CruftScriptDiagnosticStage {
    Parse,
    Check,
    Lower,
    RuntimeBoundary,
}

impl CruftScriptDiagnosticStage {
    pub fn as_str(self) -> &'static str {
        match self {
            CruftScriptDiagnosticStage::Parse => "parse",
            CruftScriptDiagnosticStage::Check => "check",
            CruftScriptDiagnosticStage::Lower => "lower",
            CruftScriptDiagnosticStage::RuntimeBoundary => "runtime-boundary",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CruftScriptDiagnosticRecord {
    pub path: String,
    pub stage: CruftScriptDiagnosticStage,
    pub code: String,
    pub span: Span,
    pub message: String,
    pub exit_code: u8,
}

impl CruftScriptDiagnosticRecord {
    pub fn from_check(
        provenance: &CruftScriptSourceProvenance,
        diagnostic: &CheckDiagnostic,
        exit_code: u8,
    ) -> Self {
        let (stage, code) = match diagnostic.code {
            CheckDiagnosticCode::ParserDiagnostic(code) => {
                (CruftScriptDiagnosticStage::Parse, format!("{code:?}"))
            }
            code => (CruftScriptDiagnosticStage::Check, format!("{code:?}")),
        };
        Self {
            path: provenance.path.clone(),
            stage,
            code,
            span: diagnostic.span,
            message: diagnostic.message.clone(),
            exit_code,
        }
    }

    pub fn from_lowering(
        provenance: &CruftScriptSourceProvenance,
        diagnostic: &LoweringDiagnostic,
        exit_code: u8,
    ) -> Self {
        Self {
            path: provenance.path.clone(),
            stage: CruftScriptDiagnosticStage::Lower,
            code: format!("{:?}", diagnostic.code),
            span: diagnostic.span,
            message: diagnostic.message.clone(),
            exit_code,
        }
    }

    pub fn runtime_boundary(
        path: impl Into<String>,
        code: impl Into<String>,
        span: Span,
        message: impl Into<String>,
        exit_code: u8,
    ) -> Self {
        Self {
            path: path.into(),
            stage: CruftScriptDiagnosticStage::RuntimeBoundary,
            code: code.into(),
            span,
            message: message.into(),
            exit_code,
        }
    }

    pub fn tooling_line(&self) -> String {
        format!(
            "cruft: fts diagnostic stage={} path={} code={} span={}..{} exit={} message={}",
            self.stage.as_str(),
            self.path,
            self.code,
            self.span.start,
            self.span.end,
            self.exit_code,
            self.message
        )
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CruftScriptCheckedUnit {
    pub provenance: CruftScriptSourceProvenance,
    pub source_unit: cruftscript_parser::CruftScriptSourceUnit,
    pub report: CheckReport,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RejectedCruftScriptUnit {
    pub provenance: CruftScriptSourceProvenance,
    pub source_unit: cruftscript_parser::CruftScriptSourceUnit,
    pub report: CheckReport,
}

impl CruftScriptCheckedUnit {
    pub fn parse_and_check(
        path: impl Into<String>,
        src: &str,
    ) -> Result<Self, RejectedCruftScriptUnit> {
        let source_unit = parse_source_unit(src);
        let report = check_source_unit(&source_unit);
        let provenance = CruftScriptSourceProvenance {
            path: path.into(),
            source_len: src.len(),
            span: source_unit.span,
        };
        Self::from_parts(provenance, source_unit, report)
    }

    pub fn from_parts(
        provenance: CruftScriptSourceProvenance,
        source_unit: cruftscript_parser::CruftScriptSourceUnit,
        report: CheckReport,
    ) -> Result<Self, RejectedCruftScriptUnit> {
        if report.accepted {
            Ok(Self {
                provenance,
                source_unit,
                report,
            })
        } else {
            Err(RejectedCruftScriptUnit {
                provenance,
                source_unit,
                report,
            })
        }
    }

    pub fn handoff(&self) -> &HandoffFacts {
        &self.report.handoff
    }

    pub fn body_facts(&self) -> &BodyFacts {
        &self.report.body_facts
    }

    pub fn boundary_facts(&self) -> &BoundaryFacts {
        &self.report.boundary_facts
    }
}

