#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CruftScriptExportModule {
    pub provenance: CruftScriptSourceProvenance,
    pub compartment: String,
    pub exports: Vec<CruftScriptExport>,
}

impl CruftScriptExportModule {

    pub fn selected_entry(&self) -> Option<&CruftScriptExport> {
        if let Some(main) = self.exports.iter().find(|export| export.name == "main") {
            Some(main)
        } else if self.exports.len() == 1 {
            self.exports.first()
        } else {
            None
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EntryParamScalar {
    Number,
    String,
    Boolean,
}

pub fn entry_param_scalar_plan(
    checked: &CruftScriptCheckedUnit,
    entry_name: &str,
) -> Option<Vec<EntryParamScalar>> {
    let signature = function_signature_for_install(checked, entry_name)?;
    signature
        .params
        .iter()
        .map(|param| match &param.ty {
            TypeTerm::Named { name, .. } => match name.as_str() {
                "number" => Some(EntryParamScalar::Number),
                "string" => Some(EntryParamScalar::String),
                "boolean" => Some(EntryParamScalar::Boolean),
                _ => None,
            },
            _ => None,
        })
        .collect()
}

