impl LoweredValue {
    pub fn as_stdout(&self) -> String {
        match self {
            LoweredValue::Undefined => "undefined".to_string(),
            LoweredValue::Null => "null".to_string(),
            LoweredValue::String(value) | LoweredValue::Number(value) => value.clone(),
            LoweredValue::Boolean(true) => "true".to_string(),
            LoweredValue::Boolean(false) => "false".to_string(),
            LoweredValue::BigInt(value) => format!("{value}n"),
            LoweredValue::FunctionRef(name) => format!("[function {name}]"),
            LoweredValue::ClassConstructorRef(name) => format!("[class {name}]"),
            LoweredValue::Array(elements) => elements
                .iter()
                .map(LoweredValue::as_stdout)
                .collect::<Vec<_>>()
                .join(","),
            LoweredValue::Object(_) => "[object Object]".to_string(),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LoweringDiagnostic {
    pub code: LoweringDiagnosticCode,
    pub span: Span,
    pub message: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LoweringDiagnosticCode {
    ArgumentTypeMismatch,
    AsyncCallbackBoundaryUnsupported,
    RecursiveCallGraph,
    UnsupportedCompartmentShape,
    UnsupportedImportShape,
    UnsupportedFunctionShape,
    UnsupportedBodyShape,
    UnsupportedReturnExpression,
}

impl CruftScriptExportModule {
    pub fn lower_exports(
        checked: &CruftScriptCheckedUnit,
    ) -> Result<Self, Vec<LoweringDiagnostic>> {
        lower_export_module(checked)
    }

    pub fn get(&self, name: &str) -> Option<&CruftScriptExport> {
        self.exports.iter().find(|export| export.name == name)
    }

    pub fn call_no_args_stdout(&self, name: &str) -> Option<String> {
        self.get(name)
            .and_then(|export| match &export.function.body {
                LoweredFunctionBody::Constant(value) => Some(value.as_stdout()),
                LoweredFunctionBody::ImportedCall(_) => None,
                LoweredFunctionBody::RuntimeExpression(_) => None,
                LoweredFunctionBody::RuntimeParameterizedExport(_) => None,
            })
    }
}

impl LoweredFunction {
    pub fn validate_lowered_args(&self, args: &[LoweredValue]) -> Result<(), LoweringDiagnostic> {
        let LoweredFunctionBody::RuntimeParameterizedExport(template) = &self.body else {
            return Ok(());
        };
        let args = normalize_runtime_export_lowered_args(template, args)?;
        let type_args = infer_runtime_export_type_args(template, &args).map_err(|message| {
            LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedFunctionShape,
                span: template.span,
                message,
            }
        })?;
        validate_runtime_export_args(template, &args, &type_args)
    }

    pub fn call_with_lowered_args(
        &self,
        args: Vec<LoweredValue>,
    ) -> Result<LoweredValue, LoweringDiagnostic> {
        match &self.body {
            LoweredFunctionBody::Constant(value) if args.is_empty() => Ok(value.clone()),
            LoweredFunctionBody::Constant(_) => Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedFunctionShape,
                span: self.span,
                message: format!(
                    "CruftScript runtime export `{}` expects 0 argument(s), got {}",
                    self.function_name,
                    args.len()
                ),
            }),
            LoweredFunctionBody::ImportedCall(_) => Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedFunctionShape,
                span: self.span,
                message: format!(
                    "CruftScript runtime export `{}` is an import-edge zero-argument thunk, not a parameterized export",
                    self.function_name
                ),
            }),
            LoweredFunctionBody::RuntimeExpression(_) => Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedFunctionShape,
                span: self.span,
                message: format!(
                    "CruftScript runtime export `{}` is a zero-argument runtime expression, not a parameterized export",
                    self.function_name
                ),
            }),
            LoweredFunctionBody::RuntimeParameterizedExport(template) => {
                let args = normalize_runtime_export_lowered_args(template, &args)?;
                let type_args =
                    infer_runtime_export_type_args(template, &args).map_err(|message| {
                        LoweringDiagnostic {
                            code: LoweringDiagnosticCode::UnsupportedFunctionShape,
                            span: template.span,
                            message,
                        }
                    })?;
                validate_runtime_export_args(template, &args, &type_args)?;
                if let Some(body) = &template.body {
                    return evaluate_lowered_runtime_expression_with_args(template, body, &args);
                }
                let context =
                    LoweringContext::new(&template.compartment, &template.type_environment);
                let Some(function) = context.get_function(&template.function_name) else {
                    return Err(LoweringDiagnostic {
                        code: LoweringDiagnosticCode::UnsupportedFunctionShape,
                        span: template.span,
                        message: format!(
                            "CruftScript runtime export `{}` is not a known exported function",
                            template.function_name
                        ),
                    });
                };
                if !function.type_params.is_empty()
                    && function
                        .type_params
                        .iter()
                        .any(|param| !type_args.contains_key(&param.name))
                {
                    return Err(LoweringDiagnostic {
                        code: LoweringDiagnosticCode::UnsupportedFunctionShape,
                        span: template.span,
                        message: format!(
                            "CruftScript runtime export `{}` could not infer every generic parameter from runtime arguments",
                            template.function_name
                        ),
                    });
                }
                let bindings = template
                    .params
                    .iter()
                    .cloned()
                    .zip(args)
                    .collect::<HashMap<_, _>>();
                let lowered = lower_exported_function_with_bindings(
                    &context,
                    function,
                    bindings,
                    &mut Vec::new(),
                    FunctionRefReturnPolicy::AllowBoundaryWrappedExport,
                )?;
                match lowered.body {
                    LoweredFunctionBody::Constant(value) => Ok(value),
                    LoweredFunctionBody::ImportedCall(_)
                    | LoweredFunctionBody::RuntimeExpression(_)
                    | LoweredFunctionBody::RuntimeParameterizedExport(_) => Err(
                        LoweringDiagnostic {
                            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                            span: template.span,
                            message: format!(
                                "CruftScript runtime export `{}` did not lower to a value",
                                template.function_name
                            ),
                        },
                    ),
                }
            }
        }
    }
}

fn normalize_runtime_export_lowered_args(
    template: &LoweredRuntimeParameterizedExport,
    args: &[LoweredValue],
) -> Result<Vec<LoweredValue>, LoweringDiagnostic> {
    if args.len() > template.params.len() {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedFunctionShape,
            span: template.span,
            message: format!(
                "CruftScript runtime export `{}` expects {} argument(s), got {}",
                template.function_name,
                template.params.len(),
                args.len()
            ),
        });
    }
    let mut env = HashMap::new();
    let mut normalized = Vec::with_capacity(template.params.len());
    for (index, name) in template.params.iter().enumerate() {
        let value = match args.get(index) {
            Some(LoweredValue::Undefined) | None => {
                if let Some(default) = template.param_defaults.get(index).and_then(|d| d.as_ref()) {
                    evaluate_lowered_runtime_expression_constant(default, &env).ok_or_else(|| {
                        LoweringDiagnostic {
                            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                            span: template.span,
                            message: format!(
                                "CruftScript runtime export `{}` default for parameter `{}` cannot be evaluated in the pure runtime substrate",
                                template.function_name, name
                            ),
                        }
                    })?
                } else if let Some(value) = args.get(index) {
                    value.clone()
                } else {
                    return Err(LoweringDiagnostic {
                        code: LoweringDiagnosticCode::UnsupportedFunctionShape,
                        span: template.span,
                        message: format!(
                            "CruftScript runtime export `{}` missing required parameter `{}`",
                            template.function_name, name
                        ),
                    });
                }
            }
            Some(value) => value.clone(),
        };
        env.insert(name.clone(), value.clone());
        normalized.push(value);
    }
    Ok(normalized)
}

impl CruftScriptBoundaryWrapperPlan {
    pub fn emit_installs(
        checked: &CruftScriptCheckedUnit,
    ) -> Result<Self, Vec<BoundaryWrapperEmissionDiagnostic>> {
        emit_boundary_wrapper_installs(checked)
    }

    pub fn by_target(&self, name: &str) -> Option<&BoundaryWrapperInstallRecord> {
        self.installs
            .iter()
            .find(|install| install.target_name == name)
    }
}

impl CruftScriptRuntimePolicyCallPlan {
    pub fn from_wrapper_plan(
        plan: &CruftScriptBoundaryWrapperPlan,
    ) -> Result<Self, Vec<RuntimePolicyCallDiagnostic>> {
        lower_runtime_policy_call_plan(plan)
    }

    pub fn by_target(&self, name: &str) -> Option<&RuntimePolicyCallRecord> {
        self.calls.iter().find(|call| call.target_name == name)
    }
}

impl CruftScriptLoweredUnit {
    pub fn lower_minimal_erased_body(
        checked: &CruftScriptCheckedUnit,
    ) -> Result<Self, Vec<LoweringDiagnostic>> {
        lower_minimal_erased_body(checked)
    }

    pub fn stdout(&self) -> String {
        match &self.entry.body {
            LoweredFunctionBody::Constant(value) => value.as_stdout(),
            LoweredFunctionBody::ImportedCall(_)
            | LoweredFunctionBody::RuntimeExpression(_)
            | LoweredFunctionBody::RuntimeParameterizedExport(_) => String::new(),
        }
    }

    pub fn static_stdout(&self) -> Option<String> {
        match &self.entry.body {
            LoweredFunctionBody::Constant(value) => Some(value.as_stdout()),
            LoweredFunctionBody::ImportedCall(_)
            | LoweredFunctionBody::RuntimeExpression(_)
            | LoweredFunctionBody::RuntimeParameterizedExport(_) => None,
        }
    }

    pub fn contains_runtime_builtin_method_call(&self) -> bool {
        match &self.entry.body {
            LoweredFunctionBody::RuntimeExpression(expr) => {
                lowered_runtime_expression_contains_builtin_method_call(expr)
            }
            LoweredFunctionBody::Constant(_)
            | LoweredFunctionBody::ImportedCall(_)
            | LoweredFunctionBody::RuntimeParameterizedExport(_) => false,
        }
    }

    pub fn is_import_edge_thunk(&self) -> bool {
        match &self.entry.body {
            LoweredFunctionBody::ImportedCall(_) => true,
            LoweredFunctionBody::RuntimeExpression(expr) => {
                lowered_runtime_expression_contains_import_edge_call(expr)
            }
            LoweredFunctionBody::Constant(_)
            | LoweredFunctionBody::RuntimeParameterizedExport(_) => false,
        }
    }
}

fn lowered_runtime_expression_contains_import_edge_call(expr: &LoweredRuntimeExpression) -> bool {
    match expr {
        LoweredRuntimeExpression::ImportedCall(_) => true,
        LoweredRuntimeExpression::Let { value, body, .. } => {
            lowered_runtime_expression_contains_import_edge_call(value)
                || lowered_runtime_expression_contains_import_edge_call(body)
        }
        LoweredRuntimeExpression::Array(items) => items
            .iter()
            .any(lowered_runtime_expression_contains_import_edge_call),
        LoweredRuntimeExpression::Object(properties)
        | LoweredRuntimeExpression::ClassObject { properties, .. } => properties
            .iter()
            .any(|property| lowered_runtime_expression_contains_import_edge_call(&property.value)),
        LoweredRuntimeExpression::PropertyAccess { object, .. }
        | LoweredRuntimeExpression::NonNullCheck { expr: object, .. }
        | LoweredRuntimeExpression::TypeCheck { expr: object, .. } => {
            lowered_runtime_expression_contains_import_edge_call(object)
        }
        LoweredRuntimeExpression::ComputedPropertyAccess { object, key, .. } => {
            lowered_runtime_expression_contains_import_edge_call(object)
                || lowered_runtime_expression_contains_import_edge_call(key)
        }
        LoweredRuntimeExpression::BuiltinConstruct { args, .. } => args
            .iter()
            .any(lowered_runtime_expression_contains_import_edge_call),
        LoweredRuntimeExpression::Binary { left, right, .. } => {
            lowered_runtime_expression_contains_import_edge_call(left)
                || lowered_runtime_expression_contains_import_edge_call(right)
        }
        LoweredRuntimeExpression::Conditional {
            subject,
            consequent,
            alternate,
            ..
        } => {
            lowered_runtime_expression_contains_import_edge_call(subject)
                || lowered_runtime_expression_contains_import_edge_call(consequent)
                || lowered_runtime_expression_contains_import_edge_call(alternate)
        }
        LoweredRuntimeExpression::Ternary {
            condition,
            consequent,
            alternate,
        } => {
            lowered_runtime_expression_contains_import_edge_call(condition)
                || lowered_runtime_expression_contains_import_edge_call(consequent)
                || lowered_runtime_expression_contains_import_edge_call(alternate)
        }
        LoweredRuntimeExpression::BuiltinMethodCall { .. }
        | LoweredRuntimeExpression::CrossCompartmentCall(_)
        | LoweredRuntimeExpression::RuntimeCallbackCall(_)
        | LoweredRuntimeExpression::PredicateRecordCall(_)
        | LoweredRuntimeExpression::Value(_)
        | LoweredRuntimeExpression::LocalRef(_)
        | LoweredRuntimeExpression::EndowmentRef(_)
        | LoweredRuntimeExpression::IntrinsicRef(_)
        | LoweredRuntimeExpression::Arrow { .. } => false,
    }
}

fn lowered_runtime_expression_contains_builtin_method_call(
    expr: &LoweredRuntimeExpression,
) -> bool {
    match expr {
        LoweredRuntimeExpression::BuiltinMethodCall { .. } => true,
        LoweredRuntimeExpression::Let { value, body, .. } => {
            lowered_runtime_expression_contains_builtin_method_call(value)
                || lowered_runtime_expression_contains_builtin_method_call(body)
        }
        LoweredRuntimeExpression::ImportedCall(_)
        | LoweredRuntimeExpression::CrossCompartmentCall(_)
        | LoweredRuntimeExpression::RuntimeCallbackCall(_)
        | LoweredRuntimeExpression::PredicateRecordCall(_)
        | LoweredRuntimeExpression::Value(_)
        | LoweredRuntimeExpression::LocalRef(_)
        | LoweredRuntimeExpression::EndowmentRef(_)
        | LoweredRuntimeExpression::IntrinsicRef(_) => false,
        LoweredRuntimeExpression::Array(items) => items
            .iter()
            .any(lowered_runtime_expression_contains_builtin_method_call),
        LoweredRuntimeExpression::Object(properties)
        | LoweredRuntimeExpression::ClassObject { properties, .. } => {
            properties.iter().any(|property| {
                lowered_runtime_expression_contains_builtin_method_call(&property.value)
            })
        }
        LoweredRuntimeExpression::PropertyAccess { object, .. }
        | LoweredRuntimeExpression::NonNullCheck { expr: object, .. }
        | LoweredRuntimeExpression::TypeCheck { expr: object, .. } => {
            lowered_runtime_expression_contains_builtin_method_call(object)
        }
        LoweredRuntimeExpression::ComputedPropertyAccess { object, key, .. } => {
            lowered_runtime_expression_contains_builtin_method_call(object)
                || lowered_runtime_expression_contains_builtin_method_call(key)
        }
        LoweredRuntimeExpression::BuiltinConstruct { args, .. } => args
            .iter()
            .any(lowered_runtime_expression_contains_builtin_method_call),
        LoweredRuntimeExpression::Arrow { body, .. } => {
            lowered_runtime_expression_contains_builtin_method_call(body)
        }
        LoweredRuntimeExpression::Binary { left, right, .. } => {
            lowered_runtime_expression_contains_builtin_method_call(left)
                || lowered_runtime_expression_contains_builtin_method_call(right)
        }
        LoweredRuntimeExpression::Conditional {
            subject,
            consequent,
            alternate,
            ..
        } => {
            lowered_runtime_expression_contains_builtin_method_call(subject)
                || lowered_runtime_expression_contains_builtin_method_call(consequent)
                || lowered_runtime_expression_contains_builtin_method_call(alternate)
        }
        LoweredRuntimeExpression::Ternary {
            condition,
            consequent,
            alternate,
        } => {
            lowered_runtime_expression_contains_builtin_method_call(condition)
                || lowered_runtime_expression_contains_builtin_method_call(consequent)
                || lowered_runtime_expression_contains_builtin_method_call(alternate)
        }
    }
}

