pub const STRING_CHAR_CODE_AT_STDLIB_SIGNATURE: GeneratedStdlibSignatureSpec =
    GeneratedStdlibSignatureSpec {
        api: "String.prototype.charCodeAt",
        receiver: GeneratedStdlibReceiver::String,
        property: "charCodeAt",
        arity: 1,
        args: &[GeneratedStdlibDomain::Number],
        returns: &[GeneratedStdlibDomain::Number],
        nullish_receiver_rejects: true,
        boundary_safe: true,
    };

pub const fn string_char_code_at_generated_stdlib_signature_spec() -> GeneratedStdlibSignatureSpec {
    STRING_CHAR_CODE_AT_STDLIB_SIGNATURE
}

impl TypeTerm {
    fn span(&self) -> Span {
        match self {
            TypeTerm::Unknown { span }
            | TypeTerm::Never { span }
            | TypeTerm::Named { span, .. }
            | TypeTerm::TypeRef { span, .. }
            | TypeTerm::Infer { span, .. }
            | TypeTerm::Union { span, .. }
            | TypeTerm::Function { span, .. }
            | TypeTerm::TypePredicate { span, .. }
            | TypeTerm::Constructor { span, .. }
            | TypeTerm::Tuple { span, .. }
            | TypeTerm::Conditional { span, .. }
            | TypeTerm::Mapped { span, .. }
            | TypeTerm::Object { span, .. }
            | TypeTerm::IndexedAccess { span, .. }
            | TypeTerm::Opaque { span, .. } => *span,
        }
    }
}

