fn validate_same_compartment_call_graph_acyclic(
    compartment: &CompartmentDecl,
) -> Vec<LoweringDiagnostic> {
    let functions = compartment_functions(compartment);
    let known: HashSet<String> = functions
        .iter()
        .map(|function| function.name.clone())
        .collect();
    let spans: HashMap<String, Span> = functions
        .iter()
        .map(|function| (function.name.clone(), function.span))
        .collect();
    let mut graph = HashMap::new();
    for function in functions {
        let mut calls = Vec::new();
        collect_same_compartment_calls_from_body(&function.body, &known, &mut calls);
        calls.sort();
        calls.dedup();
        graph.insert(function.name.clone(), calls);
    }

    let mut diagnostics = Vec::new();
    for mut component in strongly_connected_components(&graph) {
        component.sort();
        let has_self_edge = component.len() == 1
            && graph
                .get(&component[0])
                .is_some_and(|calls| calls.iter().any(|callee| callee == &component[0]));
        if component.len() <= 1 && !has_self_edge {
            continue;
        }
        let span = component
            .first()
            .and_then(|name| spans.get(name))
            .copied()
            .unwrap_or(compartment.body_span);
        let participants = component
            .iter()
            .map(|name| format!("`{name}`"))
            .collect::<Vec<_>>()
            .join(", ");
        let message = if has_self_edge {
            format!(
                "CruftScript same-compartment call graph rejects self-recursive function {participants}"
            )
        } else {
            format!(
                "CruftScript same-compartment call graph rejects cyclic SCC containing {participants}"
            )
        };
        diagnostics.push(LoweringDiagnostic {
            code: LoweringDiagnosticCode::RecursiveCallGraph,
            span,
            message,
        });
    }
    diagnostics
}

fn collect_same_compartment_calls_from_body(
    body: &FunctionBody,
    known: &HashSet<String>,
    calls: &mut Vec<String>,
) {
    for statement in &body.statements {
        collect_same_compartment_calls_from_statement(statement, known, calls);
    }
}

fn collect_same_compartment_calls_from_statement(
    statement: &BodyStmt,
    known: &HashSet<String>,
    calls: &mut Vec<String>,
) {
    match statement {
        BodyStmt::LocalDecl(local) => {
            if let Some(initializer) = &local.initializer {
                collect_same_compartment_calls_from_expr(initializer, known, calls);
            }
        }
        BodyStmt::Assignment(assignment) => {
            collect_same_compartment_calls_from_expr(&assignment.value, known, calls);
        }
        BodyStmt::Update(_) => {}
        BodyStmt::Return(ret) => {
            if let Some(argument) = &ret.argument {
                collect_same_compartment_calls_from_expr(argument, known, calls);
            }
        }
        BodyStmt::IfGuard(guard) => {
            collect_same_compartment_calls_from_expr(&guard.subject, known, calls);
        }
        BodyStmt::If(if_stmt) => {
            collect_same_compartment_calls_from_expr(&if_stmt.subject, known, calls);
            collect_same_compartment_calls_from_body(&if_stmt.then_body, known, calls);
            if let Some(else_body) = &if_stmt.else_body {
                collect_same_compartment_calls_from_body(else_body, known, calls);
            }
        }
        BodyStmt::While(while_stmt) => {
            collect_same_compartment_calls_from_expr(&while_stmt.subject, known, calls);
            collect_same_compartment_calls_from_body(&while_stmt.body, known, calls);
        }
        BodyStmt::For(for_stmt) => {
            if let Some(initializer) = &for_stmt.initializer {
                match initializer {
                    cruftscript_parser::ForInitializer::LocalDecl(local) => {
                        if let Some(initializer) = &local.initializer {
                            collect_same_compartment_calls_from_expr(initializer, known, calls);
                        }
                    }
                    cruftscript_parser::ForInitializer::Assignment(assignment) => {
                        collect_same_compartment_calls_from_expr(&assignment.value, known, calls);
                    }
                    cruftscript_parser::ForInitializer::Update(_) => {}
                }
            }
            collect_same_compartment_calls_from_expr(&for_stmt.subject, known, calls);
            collect_same_compartment_calls_from_body(&for_stmt.body, known, calls);
            if let Some(cruftscript_parser::ForUpdate::Assignment(assignment)) = &for_stmt.update {
                collect_same_compartment_calls_from_expr(&assignment.value, known, calls);
            }
        }
        BodyStmt::DoWhile(do_while_stmt) => {
            collect_same_compartment_calls_from_body(&do_while_stmt.body, known, calls);
            collect_same_compartment_calls_from_expr(&do_while_stmt.subject, known, calls);
        }
        BodyStmt::Switch(switch_stmt) => {
            collect_same_compartment_calls_from_expr(&switch_stmt.subject, known, calls);
            for case in &switch_stmt.cases {
                collect_same_compartment_calls_from_expr(&case.test, known, calls);
                collect_same_compartment_calls_from_body(&case.body, known, calls);
            }
            if let Some(default) = &switch_stmt.default {
                collect_same_compartment_calls_from_body(default, known, calls);
            }
        }
        BodyStmt::Unsupported(_) => {}
    }
}

fn collect_same_compartment_calls_from_expr(
    expr: &ExprEnvelope,
    known: &HashSet<String>,
    calls: &mut Vec<String>,
) {
    match &expr.kind {
        ExprEnvelopeKind::Identifier(_)
        | ExprEnvelopeKind::StringLiteral(_)
        | ExprEnvelopeKind::NumberLiteral(_)
        | ExprEnvelopeKind::BooleanLiteral(_)
        | ExprEnvelopeKind::NullLiteral
        | ExprEnvelopeKind::Opaque(_) => {}
        ExprEnvelopeKind::Arrow { body, .. } => {
            collect_same_compartment_calls_from_expr(body, known, calls);
        }
        ExprEnvelopeKind::ArrayLiteral(elements) => {
            for element in elements {
                collect_same_compartment_calls_from_expr(element, known, calls);
            }
        }
        ExprEnvelopeKind::ObjectLiteral(properties) => {
            for property in properties {
                collect_same_compartment_calls_from_expr(&property.value, known, calls);
            }
        }
        ExprEnvelopeKind::PropertyAccess { object, .. } => {
            collect_same_compartment_calls_from_expr(object, known, calls);
        }
        ExprEnvelopeKind::ElementAccess { object, index, .. } => {
            collect_same_compartment_calls_from_expr(object, known, calls);
            collect_same_compartment_calls_from_expr(index, known, calls);
        }
        ExprEnvelopeKind::Call { callee, args, .. } => {
            if let ExprEnvelopeKind::Identifier(name) = &callee.kind {
                if known.contains(name) {
                    calls.push(name.clone());
                }
            } else {
                collect_same_compartment_calls_from_expr(callee, known, calls);
            }
            for arg in args {
                collect_same_compartment_calls_from_expr(arg, known, calls);
            }
        }
        ExprEnvelopeKind::New { args, .. } => {
            for arg in args {
                collect_same_compartment_calls_from_expr(arg, known, calls);
            }
        }
        ExprEnvelopeKind::BinaryAdd { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::BinarySub { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::BinaryMul { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::BinaryPow { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::BinaryDiv { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::BinaryRem { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::NullishCoalesce { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::BinaryBitwiseAnd { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::BinaryBitwiseOr { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::BinaryBitwiseXor { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::BinaryShiftLeft { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::BinaryShiftRight { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::BinaryLessThan { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::BinaryGreaterThan { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::BinaryLessThanOrEqual { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::BinaryGreaterThanOrEqual { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::BinaryStrictEqual { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::BinaryStrictNotEqual { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::LogicalAnd { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::LogicalOr { left, right } => {
            collect_same_compartment_calls_from_expr(left, known, calls);
            collect_same_compartment_calls_from_expr(right, known, calls);
        }
        ExprEnvelopeKind::LogicalNot { expr } => {
            collect_same_compartment_calls_from_expr(expr, known, calls);
        }
        ExprEnvelopeKind::UnaryMinus { expr } => {
            collect_same_compartment_calls_from_expr(expr, known, calls);
        }
        ExprEnvelopeKind::Update { target, .. } => {
            collect_same_compartment_calls_from_expr(target, known, calls);
        }
        ExprEnvelopeKind::Delete { target } => {
            collect_same_compartment_calls_from_expr(target, known, calls);
        }
        ExprEnvelopeKind::Conditional {
            subject,
            consequent,
            alternate,
            ..
        } => {
            collect_same_compartment_calls_from_expr(subject, known, calls);
            collect_same_compartment_calls_from_expr(consequent, known, calls);
            collect_same_compartment_calls_from_expr(alternate, known, calls);
        }
        ExprEnvelopeKind::Ternary {
            condition,
            consequent,
            alternate,
        } => {
            collect_same_compartment_calls_from_expr(condition, known, calls);
            collect_same_compartment_calls_from_expr(consequent, known, calls);
            collect_same_compartment_calls_from_expr(alternate, known, calls);
        }
        ExprEnvelopeKind::LetIn { value, body, .. } => {
            collect_same_compartment_calls_from_expr(value, known, calls);
            collect_same_compartment_calls_from_expr(body, known, calls);
        }
        ExprEnvelopeKind::Assertion { expr, .. } | ExprEnvelopeKind::NonNull { expr } => {
            collect_same_compartment_calls_from_expr(expr, known, calls);
        }
    }
}

fn strongly_connected_components(graph: &HashMap<String, Vec<String>>) -> Vec<Vec<String>> {
    struct Tarjan<'a> {
        graph: &'a HashMap<String, Vec<String>>,
        index: usize,
        indexes: HashMap<String, usize>,
        lowlinks: HashMap<String, usize>,
        stack: Vec<String>,
        on_stack: HashSet<String>,
        components: Vec<Vec<String>>,
    }

    impl<'a> Tarjan<'a> {
        fn visit(&mut self, node: &str) {
            let node_name = node.to_string();
            self.indexes.insert(node_name.clone(), self.index);
            self.lowlinks.insert(node_name.clone(), self.index);
            self.index += 1;
            self.stack.push(node_name.clone());
            self.on_stack.insert(node_name.clone());

            if let Some(neighbors) = self.graph.get(node) {
                for neighbor in neighbors {
                    if !self.indexes.contains_key(neighbor) {
                        self.visit(neighbor);
                        let lowlink = self.lowlinks[node].min(self.lowlinks[neighbor]);
                        self.lowlinks.insert(node_name.clone(), lowlink);
                    } else if self.on_stack.contains(neighbor) {
                        let lowlink = self.lowlinks[node].min(self.indexes[neighbor]);
                        self.lowlinks.insert(node_name.clone(), lowlink);
                    }
                }
            }

            if self.lowlinks[&node_name] == self.indexes[&node_name] {
                let mut component = Vec::new();
                while let Some(member) = self.stack.pop() {
                    self.on_stack.remove(&member);
                    let done = member == node_name;
                    component.push(member);
                    if done {
                        break;
                    }
                }
                self.components.push(component);
            }
        }
    }

    let mut tarjan = Tarjan {
        graph,
        index: 0,
        indexes: HashMap::new(),
        lowlinks: HashMap::new(),
        stack: Vec::new(),
        on_stack: HashSet::new(),
        components: Vec::new(),
    };
    let mut nodes = graph.keys().cloned().collect::<Vec<_>>();
    nodes.sort();
    for node in nodes {
        if !tarjan.indexes.contains_key(&node) {
            tarjan.visit(&node);
        }
    }
    tarjan.components
}

fn lower_exported_function(
    context: &LoweringContext<'_>,
    function: &ExportedFunction,
    stack: &mut Vec<String>,
) -> Result<LoweredFunction, LoweringDiagnostic> {
    if !function.params.is_empty() {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedFunctionShape,
            span: function.span,
            message: "minimal CruftScript lowering executes only no-argument exported functions"
                .to_string(),
        });
    }
    lower_exported_function_with_bindings(
        context,
        function,
        HashMap::new(),
        stack,
        FunctionRefReturnPolicy::RejectRawEscape,
    )
}

fn lower_exported_function_with_bindings(
    context: &LoweringContext<'_>,
    function: &ExportedFunction,
    initial_locals: HashMap<String, LoweredValue>,
    stack: &mut Vec<String>,
    function_ref_return_policy: FunctionRefReturnPolicy,
) -> Result<LoweredFunction, LoweringDiagnostic> {
    if stack.iter().any(|name| name == &function.name) {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span: function.span,
            message: format!(
                "CruftScript same-compartment call lowering rejects recursive/cyclic call graph at `{}`",
                function.name
            ),
        });
    }
    stack.push(function.name.clone());
    let result = lower_exported_function_inner(
        context,
        function,
        initial_locals,
        stack,
        function_ref_return_policy,
    );
    stack.pop();
    result
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FunctionRefReturnPolicy {
    RejectRawEscape,
    AllowBoundaryWrappedExport,
}

fn execute_binding_statement(
    statement: &BodyStmt,
    locals: &mut HashMap<String, LoweredValue>,
    static_index_locals: &mut HashSet<String>,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<bool, LoweringDiagnostic> {
    match statement {
        BodyStmt::LocalDecl(local) => {
            let Some(initializer) = &local.initializer else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: local.span,
                    message: format!(
                        "minimal CruftScript lowering requires local `{}` to have a primitive initializer",
                        local.name
                    ),
                });
            };
            let value = lower_constant_expression(
                initializer,
                &*locals,
                &*static_index_locals,
                context,
                stack,
            )?;
            if is_non_negative_integral_number_literal(initializer) {
                static_index_locals.insert(local.name.clone());
            } else {
                static_index_locals.remove(&local.name);
            }
            locals.insert(local.name.clone(), value);
            Ok(true)
        }
        BodyStmt::Assignment(assignment) => {
            lower_prefix_assignment(assignment, locals, static_index_locals, context, stack)?;
            Ok(true)
        }
        BodyStmt::Update(update) => {
            let _ = lower_update_stmt(update, locals, static_index_locals)?;
            Ok(true)
        }
        _ => Ok(false),
    }
}

fn lower_exported_function_inner(
    context: &LoweringContext<'_>,
    function: &ExportedFunction,
    initial_locals: HashMap<String, LoweredValue>,
    stack: &mut Vec<String>,
    function_ref_return_policy: FunctionRefReturnPolicy,
) -> Result<LoweredFunction, LoweringDiagnostic> {
    let Some((last, prefix)) = function.body.statements.split_last() else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span: function.body_span,
            message: "minimal CruftScript lowering requires a return statement".to_string(),
        });
    };
    let mut locals = initial_locals;
    let mut static_index_locals = HashSet::new();
    for statement in prefix {
        match statement {
            BodyStmt::LocalDecl(local) => {
                let Some(initializer) = &local.initializer else {
                    return Err(LoweringDiagnostic {
                        code: LoweringDiagnosticCode::UnsupportedBodyShape,
                        span: local.span,
                        message: format!(
                            "minimal CruftScript lowering requires local `{}` to have a primitive initializer",
                            local.name
                        ),
                    });
                };
                let value = lower_constant_expression(
                    initializer,
                    &locals,
                    &static_index_locals,
                    context,
                    stack,
                )?;
                if is_non_negative_integral_number_literal(initializer) {
                    static_index_locals.insert(local.name.clone());
                } else {
                    static_index_locals.remove(&local.name);
                }
                locals.insert(local.name.clone(), value);
            }
            BodyStmt::Assignment(assignment) => {
                lower_prefix_assignment(
                    assignment,
                    &mut locals,
                    &mut static_index_locals,
                    context,
                    stack,
                )?;
            }
            BodyStmt::Update(update) => {
                let _ = lower_update_stmt(update, &mut locals, &mut static_index_locals)?;
            }

            BodyStmt::While(while_stmt) => {
                const MAX_FOLD_STEPS: usize = 1_000_000;
                let mut steps: usize = 0;
                while evaluate_lowered_narrowing_guard(
                    &while_stmt.subject,
                    &while_stmt.guard,
                    &locals,
                    &static_index_locals,
                    context,
                    stack,
                )? {
                    for body_stmt in &while_stmt.body.statements {
                        if !execute_binding_statement(
                            body_stmt,
                            &mut locals,
                            &mut static_index_locals,
                            context,
                            stack,
                        )? {
                            return Err(LoweringDiagnostic {
                                code: LoweringDiagnosticCode::UnsupportedBodyShape,
                                span: body_stmt.span(),
                                message: "minimal CruftScript lowering supports only local declarations, assignments, and proven numeric updates inside a bounded loop body".to_string(),
                            });
                        }
                    }
                    steps += 1;
                    if steps > MAX_FOLD_STEPS {
                        return Err(LoweringDiagnostic {
                            code: LoweringDiagnosticCode::UnsupportedBodyShape,
                            span: while_stmt.span,
                            message: "minimal CruftScript lowering: bounded while exceeded the fold step budget".to_string(),
                        });
                    }
                }
            }
            BodyStmt::For(for_stmt) => {
                if let Some(init) = &for_stmt.initializer {
                    let init_stmt = match init {
                        cruftscript_parser::ForInitializer::LocalDecl(local) => {
                            BodyStmt::LocalDecl(local.clone())
                        }
                        cruftscript_parser::ForInitializer::Assignment(assignment) => {
                            BodyStmt::Assignment(assignment.clone())
                        }
                        cruftscript_parser::ForInitializer::Update(update) => {
                            BodyStmt::Update(update.clone())
                        }
                    };
                    execute_binding_statement(
                        &init_stmt,
                        &mut locals,
                        &mut static_index_locals,
                        context,
                        stack,
                    )?;
                }
                const MAX_FOLD_STEPS: usize = 1_000_000;
                let mut steps: usize = 0;
                while evaluate_lowered_narrowing_guard(
                    &for_stmt.subject,
                    &for_stmt.guard,
                    &locals,
                    &static_index_locals,
                    context,
                    stack,
                )? {
                    for body_stmt in &for_stmt.body.statements {
                        if !execute_binding_statement(
                            body_stmt,
                            &mut locals,
                            &mut static_index_locals,
                            context,
                            stack,
                        )? {
                            return Err(LoweringDiagnostic {
                                code: LoweringDiagnosticCode::UnsupportedBodyShape,
                                span: body_stmt.span(),
                                message: "minimal CruftScript lowering supports only local declarations, assignments, and proven numeric updates inside a bounded loop body".to_string(),
                            });
                        }
                    }
                    if let Some(update) = &for_stmt.update {
                        let update_stmt = match update {
                            cruftscript_parser::ForUpdate::Assignment(assignment) => {
                                BodyStmt::Assignment(assignment.clone())
                            }
                            cruftscript_parser::ForUpdate::Update(update) => {
                                BodyStmt::Update(update.clone())
                            }
                        };
                        execute_binding_statement(
                            &update_stmt,
                            &mut locals,
                            &mut static_index_locals,
                            context,
                            stack,
                        )?;
                    }
                    steps += 1;
                    if steps > MAX_FOLD_STEPS {
                        return Err(LoweringDiagnostic {
                            code: LoweringDiagnosticCode::UnsupportedBodyShape,
                            span: for_stmt.span,
                            message: "minimal CruftScript lowering: bounded for exceeded the fold step budget".to_string(),
                        });
                    }
                }
            }

            BodyStmt::If(if_stmt)
                if if_stmt.else_body.is_none()
                    && matches!(
                        if_stmt.then_body.statements.as_slice(),
                        [BodyStmt::Return(_)]
                    ) =>
            {
                let [BodyStmt::Return(guard_return)] = if_stmt.then_body.statements.as_slice()
                else {
                    unreachable!("guard-clause shape checked in match arm guard")
                };
                if evaluate_lowered_narrowing_guard(
                    &if_stmt.subject,
                    &if_stmt.guard,
                    &locals,
                    &static_index_locals,
                    context,
                    stack,
                )? {
                    let Some(argument) = &guard_return.argument else {
                        return Err(LoweringDiagnostic {
                            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                            span: guard_return.span,
                            message: "minimal CruftScript lowering requires a returned value"
                                .to_string(),
                        });
                    };
                    let result = lower_constant_expression(
                        argument,
                        &locals,
                        &static_index_locals,
                        context,
                        stack,
                    )?;
                    let result = project_boundary_return_value(
                        result,
                        context,
                        function.return_type.as_ref(),
                        argument.span,
                        function_ref_return_policy,
                    )?;
                    if function_ref_return_policy == FunctionRefReturnPolicy::RejectRawEscape
                        && lowered_value_contains_function_ref(&result)
                    {
                        return Err(LoweringDiagnostic {
                            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                            span: argument.span,
                            message: "function values may be called when statically proven, but cannot escape as CruftScript return values"
                                .to_string(),
                        });
                    }
                    return Ok(LoweredFunction {
                        compartment: context.compartment.name.clone(),
                        function_name: function.name.clone(),
                        arity: function.params.len(),
                        body: LoweredFunctionBody::Constant(result),
                        span: function.span,
                    });
                }

            }
            _ => {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: statement.span(),
                    message: "minimal CruftScript lowering supports only local declarations, local/property/element assignments, and proven numeric local updates before the final return".to_string(),
                });
            }
        }
    }

    if let BodyStmt::If(if_stmt) = last {
        let Some(else_body) = &if_stmt.else_body else {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedBodyShape,
                span: last.span(),
                message: "minimal CruftScript lowering supports only a final return statement"
                    .to_string(),
            });
        };
        let [BodyStmt::Return(then_return)] = if_stmt.then_body.statements.as_slice() else {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedBodyShape,
                span: if_stmt.then_body.span,
                message: "minimal CruftScript lowering supports only return statements in terminal if/else branches"
                    .to_string(),
            });
        };
        let [BodyStmt::Return(else_return)] = else_body.statements.as_slice() else {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedBodyShape,
                span: else_body.span,
                message: "minimal CruftScript lowering supports only return statements in terminal if/else branches"
                    .to_string(),
            });
        };
        let selected = if evaluate_lowered_narrowing_guard(
            &if_stmt.subject,
            &if_stmt.guard,
            &locals,
            &static_index_locals,
            context,
            stack,
        )? {
            then_return.argument.as_ref()
        } else {
            else_return.argument.as_ref()
        };
        let Some(argument) = selected else {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                span: last.span(),
                message: "minimal CruftScript lowering requires terminal if/else branches to return values"
                    .to_string(),
            });
        };
        let result =
            lower_constant_expression(argument, &locals, &static_index_locals, context, stack)?;
        let result = project_boundary_return_value(
            result,
            context,
            function.return_type.as_ref(),
            argument.span,
            function_ref_return_policy,
        )?;
        if function_ref_return_policy == FunctionRefReturnPolicy::RejectRawEscape
            && lowered_value_contains_function_ref(&result)
        {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                span: argument.span,
                message: "function values may be called when statically proven, but cannot escape as CruftScript return values"
                    .to_string(),
            });
        }
        return Ok(LoweredFunction {
            compartment: context.compartment.name.clone(),
            function_name: function.name.clone(),
            arity: function.params.len(),
            body: LoweredFunctionBody::Constant(result),
            span: function.span,
        });
    }

    if let BodyStmt::Switch(switch_stmt) = last {
        let subject = lower_constant_expression(
            &switch_stmt.subject,
            &locals,
            &static_index_locals,
            context,
            stack,
        )?;
        let selected_body = {
            let mut found = None;
            for case in &switch_stmt.cases {
                let test = lower_constant_expression(
                    &case.test,
                    &locals,
                    &static_index_locals,
                    context,
                    stack,
                )?;
                if test == subject {
                    found = Some(&case.body);
                    break;
                }
            }
            found.or(switch_stmt.default.as_ref())
        };
        let Some(selected_body) = selected_body else {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedBodyShape,
                span: switch_stmt.span,
                message: "minimal CruftScript lowering: terminal switch has no matching case and no default".to_string(),
            });
        };
        let [BodyStmt::Return(case_return)] = selected_body.statements.as_slice() else {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedBodyShape,
                span: selected_body.span,
                message: "minimal CruftScript lowering supports only a single return statement in a terminal switch case".to_string(),
            });
        };
        let Some(argument) = &case_return.argument else {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                span: case_return.span,
                message: "minimal CruftScript lowering requires a returned value".to_string(),
            });
        };
        let result =
            lower_constant_expression(argument, &locals, &static_index_locals, context, stack)?;
        let result = project_boundary_return_value(
            result,
            context,
            function.return_type.as_ref(),
            argument.span,
            function_ref_return_policy,
        )?;
        if function_ref_return_policy == FunctionRefReturnPolicy::RejectRawEscape
            && lowered_value_contains_function_ref(&result)
        {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                span: argument.span,
                message: "function values may be called when statically proven, but cannot escape as CruftScript return values"
                    .to_string(),
            });
        }
        return Ok(LoweredFunction {
            compartment: context.compartment.name.clone(),
            function_name: function.name.clone(),
            arity: function.params.len(),
            body: LoweredFunctionBody::Constant(result),
            span: function.span,
        });
    }

    let BodyStmt::Return(ret) = last else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span: last.span(),
            message: "minimal CruftScript lowering supports only a final return statement"
                .to_string(),
        });
    };
    let Some(argument) = &ret.argument else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span: ret.span,
            message: "minimal CruftScript lowering requires a returned value".to_string(),
        });
    };
    let result = if let ExprEnvelopeKind::Update {
        target,
        op,
        position,
    } = &argument.kind
    {
        lower_update_expression(
            target,
            *op,
            *position,
            argument.span,
            &mut locals,
            &mut static_index_locals,
        )?
    } else {
        lower_constant_expression(argument, &locals, &static_index_locals, context, stack)?
    };
    let result = project_boundary_return_value(
        result,
        context,
        function.return_type.as_ref(),
        argument.span,
        function_ref_return_policy,
    )?;
    if function_ref_return_policy == FunctionRefReturnPolicy::RejectRawEscape
        && lowered_value_contains_function_ref(&result)
    {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span: argument.span,
            message: "CruftScript function values may be called when statically proven, but cannot escape as returned structural data until BoundaryWrapper function-value crossing is derived".to_string(),
        });
    }

    Ok(LoweredFunction {
        compartment: context.compartment.name.clone(),
        function_name: function.name.clone(),
        arity: function.params.len(),
        body: LoweredFunctionBody::Constant(result),
        span: function.span,
    })
}

fn lowered_value_contains_function_ref(value: &LoweredValue) -> bool {
    match value {
        LoweredValue::FunctionRef(_) => true,
        LoweredValue::ClassConstructorRef(_) => false,
        LoweredValue::Array(elements) => elements.iter().any(lowered_value_contains_function_ref),
        LoweredValue::Object(properties) => properties
            .iter()
            .any(|property| lowered_value_contains_function_ref(&property.value)),
        LoweredValue::Undefined
        | LoweredValue::Null
        | LoweredValue::String(_)
        | LoweredValue::Number(_)
        | LoweredValue::Boolean(_)
        | LoweredValue::BigInt(_) => false,
    }
}

fn project_boundary_return_value(
    value: LoweredValue,
    context: &LoweringContext<'_>,
    return_type: Option<&TypeExpr>,
    span: Span,
    function_ref_return_policy: FunctionRefReturnPolicy,
) -> Result<LoweredValue, LoweringDiagnostic> {
    if function_ref_return_policy != FunctionRefReturnPolicy::AllowBoundaryWrappedExport {
        return Ok(value);
    }
    let Some(return_type) = return_type else {
        return Ok(value);
    };
    let lowered_return_type = lower_type_term(return_type);
    project_boundary_return_type_term(value, context, Some(&lowered_return_type), span)
}

fn project_boundary_return_type_term(
    value: LoweredValue,
    context: &LoweringContext<'_>,
    return_type: Option<&TypeTerm>,
    span: Span,
) -> Result<LoweredValue, LoweringDiagnostic> {
    let Some(TypeTerm::Named { name, .. }) = return_type else {
        return Ok(value);
    };
    let Some(class_decl) = context.get_class(&name) else {
        return Ok(value);
    };
    project_class_instance_boundary_snapshot(value, class_decl).ok_or_else(|| LoweringDiagnostic {
        code: LoweringDiagnosticCode::UnsupportedReturnExpression,
        span,
        message: format!(
            "CruftScript boundary return `{name}` cannot project a method-bearing class instance as structural data"
        ),
    })
}

fn project_class_instance_boundary_snapshot(
    value: LoweredValue,
    class_decl: &ClassDecl,
) -> Option<LoweredValue> {
    if !lowered_value_matches_class_instance(&value, class_decl) {
        return None;
    }
    let LoweredValue::Object(properties) = value else {
        return None;
    };
    let method_refs = class_decl
        .methods
        .iter()
        .map(|method| {
            (
                method.name.as_str(),
                class_method_ref_name(&class_decl.name, &method.name),
            )
        })
        .collect::<Vec<_>>();
    let projected = properties
        .into_iter()
        .filter(|property| {
            !method_refs.iter().any(|(method_name, expected_ref)| {
                property.name == *method_name
                    && matches!(&property.value, LoweredValue::FunctionRef(name) if name == expected_ref)
            })
        })
        .collect::<Vec<_>>();
    if projected
        .iter()
        .any(|property| lowered_value_contains_function_ref(&property.value))
    {
        return None;
    }
    Some(LoweredValue::Object(projected))
}

fn lower_update_stmt(
    update: &cruftscript_parser::UpdateStmt,
    locals: &mut HashMap<String, LoweredValue>,
    static_index_locals: &mut HashSet<String>,
) -> Result<LoweredValue, LoweringDiagnostic> {
    match &update.target {
        cruftscript_parser::UpdateTarget::Local(name) => lower_update_local(
            name,
            update.op,
            update.position,
            update.span,
            locals,
            static_index_locals,
        ),
        cruftscript_parser::UpdateTarget::Property {
            object,
            property,
            optional: false,
        } => lower_update_property(
            object,
            property,
            update.op,
            update.position,
            update.span,
            locals,
            static_index_locals,
        ),
        cruftscript_parser::UpdateTarget::Element {
            object,
            index,
            optional: false,
        } => lower_update_element(
            object,
            index,
            update.op,
            update.position,
            update.span,
            locals,
            static_index_locals,
        ),
        cruftscript_parser::UpdateTarget::Property { .. }
        | cruftscript_parser::UpdateTarget::Element { .. } => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span: update.span,
            message: "minimal CruftScript lowering supports update only on non-optional proven numeric local, property, or bounded element targets"
                .to_string(),
        }),
        cruftscript_parser::UpdateTarget::Unsupported(_) => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span: update.span,
            message:
                "minimal CruftScript lowering supports update only on proven numeric local bindings"
                    .to_string(),
        }),
    }
}

fn lower_update_expression(
    target: &ExprEnvelope,
    op: cruftscript_parser::UpdateOp,
    position: cruftscript_parser::UpdatePosition,
    span: Span,
    locals: &mut HashMap<String, LoweredValue>,
    static_index_locals: &mut HashSet<String>,
) -> Result<LoweredValue, LoweringDiagnostic> {
    match &target.kind {
        ExprEnvelopeKind::Identifier(name) => {
            lower_update_local(name, op, position, span, locals, static_index_locals)
        }
        ExprEnvelopeKind::PropertyAccess {
            object,
            property,
            optional: false,
        } => lower_update_property(object, property, op, position, span, locals, static_index_locals),
        ExprEnvelopeKind::ElementAccess {
            object,
            index,
            optional: false,
        } => lower_update_element(object, index, op, position, span, locals, static_index_locals),
        _ => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span,
            message:
                "minimal CruftScript lowering supports update expressions only on non-optional proven numeric local, property, or bounded element targets"
                    .to_string(),
        }),
    }
}

fn lower_update_local(
    name: &str,
    op: cruftscript_parser::UpdateOp,
    position: cruftscript_parser::UpdatePosition,
    span: Span,
    locals: &mut HashMap<String, LoweredValue>,
    static_index_locals: &mut HashSet<String>,
) -> Result<LoweredValue, LoweringDiagnostic> {
    let Some(LoweredValue::Number(old)) = locals.get(name).cloned() else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span,
            message: format!(
                "minimal CruftScript lowering cannot update non-numeric local `{name}`"
            ),
        });
    };
    let old_number = old.parse::<i128>().map_err(|_| LoweringDiagnostic {
        code: LoweringDiagnosticCode::UnsupportedBodyShape,
        span,
        message: format!(
            "minimal CruftScript lowering cannot update non-integral numeric local `{name}`"
        ),
    })?;
    let new_number = match op {
        cruftscript_parser::UpdateOp::Increment => old_number + 1,
        cruftscript_parser::UpdateOp::Decrement => old_number - 1,
    };
    let new = LoweredValue::Number(new_number.to_string());
    locals.insert(name.to_string(), new.clone());
    static_index_locals.insert(name.to_string());
    match position {
        cruftscript_parser::UpdatePosition::Prefix => Ok(new),
        cruftscript_parser::UpdatePosition::Postfix => Ok(LoweredValue::Number(old)),
    }
}

fn lower_update_property(
    object: &ExprEnvelope,
    property: &str,
    op: cruftscript_parser::UpdateOp,
    position: cruftscript_parser::UpdatePosition,
    span: Span,
    locals: &mut HashMap<String, LoweredValue>,
    static_index_locals: &mut HashSet<String>,
) -> Result<LoweredValue, LoweringDiagnostic> {
    let ExprEnvelopeKind::Identifier(object_name) = &object.kind else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span,
            message: "minimal CruftScript lowering supports property update only on local object bindings"
                .to_string(),
        });
    };
    let Some(LoweredValue::Object(properties)) = locals.get_mut(object_name) else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span,
            message: format!(
                "minimal CruftScript lowering cannot update property `{property}` on non-object local `{object_name}`"
            ),
        });
    };
    let Some(slot) = properties
        .iter_mut()
        .find(|candidate| candidate.name == property)
    else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span,
            message: format!(
                "minimal CruftScript lowering cannot find property `{property}` on local `{object_name}`"
            ),
        });
    };
    let LoweredValue::Number(old) = slot.value.clone() else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span,
            message: format!(
                "minimal CruftScript lowering cannot update non-numeric property `{object_name}.{property}`"
            ),
        });
    };
    let old_number = old.parse::<i128>().map_err(|_| LoweringDiagnostic {
        code: LoweringDiagnosticCode::UnsupportedBodyShape,
        span,
        message: format!(
            "minimal CruftScript lowering cannot update non-integral numeric property `{object_name}.{property}`"
        ),
    })?;
    let new_number = match op {
        cruftscript_parser::UpdateOp::Increment => old_number + 1,
        cruftscript_parser::UpdateOp::Decrement => old_number - 1,
    };
    let new = LoweredValue::Number(new_number.to_string());
    slot.value = new.clone();
    static_index_locals.remove(object_name);
    match position {
        cruftscript_parser::UpdatePosition::Prefix => Ok(new),
        cruftscript_parser::UpdatePosition::Postfix => Ok(LoweredValue::Number(old)),
    }
}

fn lower_update_element(
    object: &ExprEnvelope,
    index: &ExprEnvelope,
    op: cruftscript_parser::UpdateOp,
    position: cruftscript_parser::UpdatePosition,
    span: Span,
    locals: &mut HashMap<String, LoweredValue>,
    static_index_locals: &mut HashSet<String>,
) -> Result<LoweredValue, LoweringDiagnostic> {
    let ExprEnvelopeKind::Identifier(object_name) = &object.kind else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span,
            message:
                "minimal CruftScript lowering supports element update only on local array bindings"
                    .to_string(),
        });
    };
    let index = lower_bounded_element_index(index, locals, static_index_locals, span)?;
    let Some(LoweredValue::Array(elements)) = locals.get_mut(object_name) else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span,
            message: format!(
                "minimal CruftScript lowering cannot update element on non-array local `{object_name}`"
            ),
        });
    };
    let Some(slot) = elements.get_mut(index) else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span,
            message: format!(
                "minimal CruftScript lowering cannot update out-of-bounds element `{index}` on local `{object_name}`"
            ),
        });
    };
    let LoweredValue::Number(old) = slot.clone() else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span,
            message: format!(
                "minimal CruftScript lowering cannot update non-numeric element `{object_name}[{index}]`"
            ),
        });
    };
    let old_number = old.parse::<i128>().map_err(|_| LoweringDiagnostic {
        code: LoweringDiagnosticCode::UnsupportedBodyShape,
        span,
        message: format!(
            "minimal CruftScript lowering cannot update non-integral numeric element `{object_name}[{index}]`"
        ),
    })?;
    let new_number = match op {
        cruftscript_parser::UpdateOp::Increment => old_number + 1,
        cruftscript_parser::UpdateOp::Decrement => old_number - 1,
    };
    let new = LoweredValue::Number(new_number.to_string());
    *slot = new.clone();
    static_index_locals.remove(object_name);
    match position {
        cruftscript_parser::UpdatePosition::Prefix => Ok(new),
        cruftscript_parser::UpdatePosition::Postfix => Ok(LoweredValue::Number(old)),
    }
}

fn lower_prefix_assignment(
    assignment: &cruftscript_parser::AssignmentStmt,
    locals: &mut HashMap<String, LoweredValue>,
    static_index_locals: &mut HashSet<String>,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<(), LoweringDiagnostic> {
    match &assignment.target {
        cruftscript_parser::AssignmentTarget::Local(target) => {
            if !locals.contains_key(target) {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: assignment.span,
                    message: format!(
                        "minimal CruftScript lowering cannot assign undeclared local `{target}`"
                    ),
                });
            }
            let value = lower_constant_expression(
                &assignment.value,
                locals,
                static_index_locals,
                context,
                stack,
            )?;
            if is_non_negative_integral_number_literal(&assignment.value) {
                static_index_locals.insert(target.clone());
            } else {
                static_index_locals.remove(target);
            }
            locals.insert(target.clone(), value);
            Ok(())
        }
        cruftscript_parser::AssignmentTarget::Property {
            object,
            property,
            optional: false,
        } => {
            let ExprEnvelopeKind::Identifier(object_name) = &object.kind else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: assignment.span,
                    message: "minimal CruftScript lowering supports property assignment only on local object bindings"
                        .to_string(),
                });
            };
            let value = lower_constant_expression(
                &assignment.value,
                locals,
                static_index_locals,
                context,
                stack,
            )?;
            let Some(LoweredValue::Object(properties)) = locals.get_mut(object_name) else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: assignment.span,
                    message: format!(
                        "minimal CruftScript lowering cannot assign property `{property}` on non-object local `{object_name}`"
                    ),
                });
            };
            let Some(slot) = properties
                .iter_mut()
                .find(|candidate| candidate.name == *property)
            else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: assignment.span,
                    message: format!(
                        "minimal CruftScript lowering cannot find property `{property}` on local `{object_name}`"
                    ),
                });
            };
            slot.value = value;
            static_index_locals.remove(object_name);
            Ok(())
        }
        cruftscript_parser::AssignmentTarget::Element {
            object,
            index,
            optional: false,
        } => {
            let ExprEnvelopeKind::Identifier(object_name) = &object.kind else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: assignment.span,
                    message: "minimal CruftScript lowering supports element assignment only on local array bindings"
                        .to_string(),
                });
            };
            let value = lower_constant_expression(
                &assignment.value,
                locals,
                static_index_locals,
                context,
                stack,
            )?;
            let index = lower_bounded_element_index(index, locals, static_index_locals, assignment.span)?;
            let Some(LoweredValue::Array(elements)) = locals.get_mut(object_name) else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: assignment.span,
                    message: format!(
                        "minimal CruftScript lowering cannot assign element on non-array local `{object_name}`"
                    ),
                });
            };
            let Some(slot) = elements.get_mut(index) else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: assignment.span,
                    message: format!(
                        "minimal CruftScript lowering cannot assign out-of-bounds element `{index}` on local `{object_name}`"
                    ),
                });
            };
            *slot = value;
            static_index_locals.remove(object_name);
            Ok(())
        }
        cruftscript_parser::AssignmentTarget::Property { .. }
        | cruftscript_parser::AssignmentTarget::Element { .. }
        | cruftscript_parser::AssignmentTarget::Unsupported(_) => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span: assignment.span,
            message: "minimal CruftScript lowering supports only local, proven object-property, and bounded array-element assignments before the final return"
                .to_string(),
        }),
    }
}

fn lower_constant_expression(
    expr: &ExprEnvelope,
    locals: &HashMap<String, LoweredValue>,
    static_index_locals: &HashSet<String>,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<LoweredValue, LoweringDiagnostic> {
    match &expr.kind {
        ExprEnvelopeKind::StringLiteral(value) => Ok(LoweredValue::String(value.clone())),
        ExprEnvelopeKind::NumberLiteral(value) => Ok(LoweredValue::Number(value.clone())),
        ExprEnvelopeKind::BooleanLiteral(value) => Ok(LoweredValue::Boolean(*value)),
        ExprEnvelopeKind::NullLiteral => Ok(LoweredValue::Null),
        ExprEnvelopeKind::Identifier(name) => {
            if let Some(value) = locals.get(name) {
                Ok(value.clone())
            } else if context.get_function(name).is_some() {
                Ok(LoweredValue::FunctionRef(name.clone()))
            } else if context.get_class(name).is_some() {
                Ok(LoweredValue::ClassConstructorRef(name.clone()))
            } else {
                Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                    span: expr.span,
                    message: format!(
                        "minimal CruftScript lowering cannot resolve `{name}` as a primitive local"
                    ),
                })
            }
        }
        ExprEnvelopeKind::ArrayLiteral(elements) => elements
            .iter()
            .map(|element| {
                lower_constant_expression(element, locals, static_index_locals, context, stack)
            })
            .collect::<Result<Vec<_>, _>>()
            .map(LoweredValue::Array),
        ExprEnvelopeKind::ObjectLiteral(properties) => properties
            .iter()
            .map(|property| {
                Ok(LoweredObjectProperty {
                    name: property.name.clone(),
                    value: lower_constant_expression(
                        &property.value,
                        locals,
                        static_index_locals,
                        context,
                        stack,
                    )?,
                })
            })
            .collect::<Result<Vec<_>, LoweringDiagnostic>>()
            .map(LoweredValue::Object),
        ExprEnvelopeKind::PropertyAccess {
            object,
            property,
            optional,
        } => {
            if let ExprEnvelopeKind::Identifier(class_name) = &object.kind {
                if let Some((_, field)) =
                    context.get_class_static_field(&class_static_field_ref_name(class_name, property))
                {
                    if let Some(initializer) = &field.initializer {
                        return lower_constant_expression(
                            initializer,
                            locals,
                            static_index_locals,
                            context,
                            stack,
                        );
                    }
                }
            }
            let object =
                lower_constant_expression(object, locals, static_index_locals, context, stack)?;
            if *optional && matches!(object, LoweredValue::Undefined) {
                return Ok(LoweredValue::Undefined);
            }
            let LoweredValue::Object(properties) = object else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                    span: expr.span,
                    message: format!(
                        "CruftScript lowering requires `{property}` to be read from a lowered object literal"
                    ),
                });
            };
            properties
                .into_iter()
                .find(|candidate| candidate.name == *property)
                .map(|candidate| candidate.value)
                .ok_or_else(|| LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                    span: expr.span,
                    message: format!(
                        "CruftScript lowering cannot find property `{property}` on the lowered object"
                    ),
                })
        }
        ExprEnvelopeKind::ElementAccess {
            object,
            index,
            optional,
        } => {
            let object =
                lower_constant_expression(object, locals, static_index_locals, context, stack)?;
            if *optional && matches!(object, LoweredValue::Undefined) {
                return Ok(LoweredValue::Undefined);
            }
            match object {
                LoweredValue::Array(elements) => {
                    let index =
                        lower_bounded_element_index(index, locals, static_index_locals, expr.span)?;
                    Ok(elements
                        .get(index)
                        .cloned()
                        .unwrap_or(LoweredValue::Undefined))
                }
                LoweredValue::Object(properties) => {
                    let key =
                        lower_bounded_property_key(index, locals, static_index_locals, expr.span)?;
                    Ok(properties
                        .into_iter()
                        .find(|candidate| candidate.name == key)
                        .map(|candidate| candidate.value)
                        .unwrap_or(LoweredValue::Undefined))
                }
                _ => Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                    span: expr.span,
                    message:
                        "CruftScript lowering requires element access to read from a lowered array or object"
                            .to_string(),
                }),
            }
        }
        ExprEnvelopeKind::Call {
            callee,
            args,
            optional,
        } => {
            if matches!(
                &callee.kind,
                ExprEnvelopeKind::PropertyAccess { .. } | ExprEnvelopeKind::ElementAccess { .. }
            ) {
                lower_function_value_call_expression(
                    expr.span,
                    callee,
                    args,
                    locals,
                    static_index_locals,
                    context,
                    stack,
                )
            } else {
                lower_same_compartment_call_expression(
                    expr.span,
                    callee,
                    args,
                    *optional,
                    locals,
                    static_index_locals,
                    context,
                    stack,
                )
            }
        }
        ExprEnvelopeKind::New { class_name, args } => {
            let resolved_class_name =
                lowered_constructor_name_for_new(class_name, locals).unwrap_or(class_name);
            if let Some(class_decl) = context.get_class(resolved_class_name) {
                if let Some(value) = lower_class_constructor_value(
                    class_decl,
                    args,
                    locals,
                    static_index_locals,
                    context,
                    stack,
                ) {
                    return Ok(value);
                }
            }
            if args.is_empty() && context.has_empty_constructible_class(resolved_class_name) {
                Ok(LoweredValue::Object(Vec::new()))
            } else {
                Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                    span: expr.span,
                    message:
                        "CruftScript lowering supports only fieldless or optional-field class constructors in this rung"
                            .to_string(),
                })
            }
        }
        ExprEnvelopeKind::BinaryAdd { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_binary_add_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::BinarySub { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_binary_sub_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::BinaryMul { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_binary_mul_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::BinaryPow { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_binary_pow_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::BinaryDiv { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_binary_div_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::BinaryRem { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_binary_rem_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::NullishCoalesce { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            if matches!(left_value, LoweredValue::Null | LoweredValue::Undefined) {
                lower_constant_expression(right, locals, static_index_locals, context, stack)
            } else {
                Ok(left_value)
            }
        }
        ExprEnvelopeKind::BinaryBitwiseAnd { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_binary_bitwise_and_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::BinaryBitwiseOr { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_binary_bitwise_or_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::BinaryBitwiseXor { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_binary_bitwise_xor_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::BinaryShiftLeft { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_binary_shift_left_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::BinaryShiftRight { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_binary_shift_right_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::BinaryLessThan { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_binary_less_than_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::BinaryGreaterThan { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_binary_greater_than_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::BinaryLessThanOrEqual { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_binary_less_than_or_equal_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::BinaryGreaterThanOrEqual { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_binary_greater_than_or_equal_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::BinaryStrictEqual { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_binary_strict_equal_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::BinaryStrictNotEqual { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_binary_strict_not_equal_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::LogicalAnd { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_logical_and_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::LogicalOr { left, right } => {
            let left_value =
                lower_constant_expression(left, locals, static_index_locals, context, stack)?;
            let right_value =
                lower_constant_expression(right, locals, static_index_locals, context, stack)?;
            lower_logical_or_value(left_value, right_value, expr.span)
        }
        ExprEnvelopeKind::LogicalNot { expr: inner } => {
            let value =
                lower_constant_expression(inner, locals, static_index_locals, context, stack)?;
            lower_logical_not_value(value, expr.span)
        }
        ExprEnvelopeKind::UnaryMinus { expr: inner } => {
            let value =
                lower_constant_expression(inner, locals, static_index_locals, context, stack)?;
            lower_unary_minus_value(value, expr.span)
        }
        ExprEnvelopeKind::Conditional {
            subject,
            guard,
            consequent,
            alternate,
        } => {
            let choose_consequent =
                evaluate_lowered_narrowing_guard(subject, guard, locals, static_index_locals, context, stack)?;
            let selected = if choose_consequent {
                consequent
            } else {
                alternate
            };
            lower_constant_expression(selected, locals, static_index_locals, context, stack)
        }
        ExprEnvelopeKind::Assertion {
            expr,
            target,
            satisfies,
        } => {
            let value = lower_constant_expression(expr, locals, static_index_locals, context, stack)?;

            if *satisfies {
                return Ok(value);
            }
            if let Some(target_type) = runtime_assertion_target_type_from_type_expr(
                target,
                &AliasExpansionContext::new(context.type_environment),
            ) {
                if lowered_value_matches_type(&value, &target_type) {
                    Ok(value)
                } else {
                    Err(LoweringDiagnostic {
                        code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                        span: expr.span,
                        message:
                            "CruftScript runtime assertion failed during constant lowering"
                                .to_string(),
                    })
                }
            } else {
                Ok(value)
            }
        }
        ExprEnvelopeKind::NonNull { expr } => {
            lower_constant_expression(expr, locals, static_index_locals, context, stack)
        }
        ExprEnvelopeKind::Update { .. } => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span: expr.span,
            message:
                "minimal CruftScript lowering supports update expressions only as the final return expression"
                    .to_string(),
        }),
        ExprEnvelopeKind::Delete { .. } => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span: expr.span,
            message:
                "CruftScript delete lowering is not derived for executable handoff targets"
                    .to_string(),
        }),
        ExprEnvelopeKind::Arrow { .. } => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span: expr.span,
            message: "CruftScript arrow functions require runtime lowering".to_string(),
        }),
        ExprEnvelopeKind::Ternary { .. } => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span: expr.span,
            message: "CruftScript general ternary requires runtime lowering".to_string(),
        }),
        ExprEnvelopeKind::LetIn { .. } => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span: expr.span,
            message: "CruftScript let-binding expression requires runtime lowering".to_string(),
        }),
        ExprEnvelopeKind::Opaque(spelling) => {
            if let Some(class_name) = parse_zero_arg_new_expression(spelling) {
                if let Some(class_decl) = context.get_class(class_name) {
                    if let Some(value) = lower_class_constructor_value(
                        class_decl,
                        &[],
                        locals,
                        static_index_locals,
                        context,
                        stack,
                    ) {
                        return Ok(value);
                    }
                }
            }
            Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                span: expr.span,
                message: "CruftScript lowering supports only primitive literals, structured literals, same-compartment calls with lowerable arguments, property reads over lowered object literals, bounded fieldless or optional-field class construction, and local identifiers".to_string(),
            })
        }
    }
}

fn lowered_constructor_name_for_new<'a>(
    class_name: &'a str,
    locals: &'a HashMap<String, LoweredValue>,
) -> Option<&'a str> {
    match locals.get(class_name) {
        Some(LoweredValue::ClassConstructorRef(resolved)) => Some(resolved.as_str()),
        _ => None,
    }
}

fn lower_binary_add_value(
    left: LoweredValue,
    right: LoweredValue,
    span: Span,
) -> Result<LoweredValue, LoweringDiagnostic> {
    match (left, right) {
        (LoweredValue::Number(a), LoweredValue::Number(b)) => {
            let parsed_a = a.parse::<f64>().map_err(|_| LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                span,
                message: "CruftScript binary `+` requires parseable numeric operands".to_string(),
            })?;
            let parsed_b = b.parse::<f64>().map_err(|_| LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                span,
                message: "CruftScript binary `+` requires parseable numeric operands".to_string(),
            })?;
            Ok(LoweredValue::Number(format_number_literal(
                parsed_a + parsed_b,
            )))
        }
        (LoweredValue::String(a), LoweredValue::String(b)) => Ok(LoweredValue::String(a + &b)),
        (LoweredValue::String(a), LoweredValue::Number(b)) => Ok(LoweredValue::String(a + &b)),
        (LoweredValue::Number(a), LoweredValue::String(b)) => Ok(LoweredValue::String(a + &b)),
        _ => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message:
                "CruftScript binary `+` lowering supports only lowered number and string operands"
                    .to_string(),
        }),
    }
}

