fn lower_binary_shift_left_value(
    left: LoweredValue,
    right: LoweredValue,
    span: Span,
) -> Result<LoweredValue, LoweringDiagnostic> {
    match (left, right) {
        (LoweredValue::Number(a), LoweredValue::Number(b)) => {
            let parsed_a = parse_bitwise_i32_operand(&a, span, "<<")?;
            let parsed_b = parse_bitwise_i32_operand(&b, span, "<<")?;
            if !(0..=31).contains(&parsed_b) {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                    span,
                    message: "CruftScript binary `<<` admits only shift counts in the range 0..31"
                        .to_string(),
                });
            }
            Ok(LoweredValue::Number(
                parsed_a.wrapping_shl(parsed_b as u32).to_string(),
            ))
        }
        _ => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: "CruftScript binary `<<` lowering supports only lowered number operands"
                .to_string(),
        }),
    }
}

