fn lower_binary_strict_equal_value(
    left: LoweredValue,
    right: LoweredValue,
    span: Span,
) -> Result<LoweredValue, LoweringDiagnostic> {
    match (left, right) {
        (LoweredValue::Undefined, LoweredValue::Undefined)
        | (LoweredValue::Null, LoweredValue::Null) => Ok(LoweredValue::Boolean(true)),
        (LoweredValue::String(a), LoweredValue::String(b)) => Ok(LoweredValue::Boolean(a == b)),
        (LoweredValue::Number(a), LoweredValue::Number(b)) => Ok(LoweredValue::Boolean(a == b)),
        (LoweredValue::Boolean(a), LoweredValue::Boolean(b)) => Ok(LoweredValue::Boolean(a == b)),
        (left, right) if lowered_values_are_strict_comparable(&left, &right) => {
            Ok(LoweredValue::Boolean(false))
        }
        _ => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: "CruftScript binary `===` lowering supports only matching primitive operands"
                .to_string(),
        }),
    }
}

fn lower_binary_strict_not_equal_value(
    left: LoweredValue,
    right: LoweredValue,
    span: Span,
) -> Result<LoweredValue, LoweringDiagnostic> {
    match (left, right) {
        (LoweredValue::Undefined, LoweredValue::Undefined)
        | (LoweredValue::Null, LoweredValue::Null) => Ok(LoweredValue::Boolean(false)),
        (LoweredValue::String(a), LoweredValue::String(b)) => Ok(LoweredValue::Boolean(a != b)),
        (LoweredValue::Number(a), LoweredValue::Number(b)) => Ok(LoweredValue::Boolean(a != b)),
        (LoweredValue::Boolean(a), LoweredValue::Boolean(b)) => Ok(LoweredValue::Boolean(a != b)),
        (left, right) if lowered_values_are_strict_comparable(&left, &right) => {
            Ok(LoweredValue::Boolean(true))
        }
        _ => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: "CruftScript binary `!==` lowering supports only matching primitive operands"
                .to_string(),
        }),
    }
}

fn lowered_values_are_strict_comparable(left: &LoweredValue, right: &LoweredValue) -> bool {
    matches!(
        (left, right),
        (
            LoweredValue::Undefined
                | LoweredValue::Null
                | LoweredValue::String(_)
                | LoweredValue::Number(_)
                | LoweredValue::Boolean(_)
                | LoweredValue::BigInt(_),
            LoweredValue::Undefined
                | LoweredValue::Null
                | LoweredValue::String(_)
                | LoweredValue::Number(_)
                | LoweredValue::Boolean(_)
                | LoweredValue::BigInt(_)
        )
    )
}

fn lower_logical_and_value(
    left: LoweredValue,
    right: LoweredValue,
    span: Span,
) -> Result<LoweredValue, LoweringDiagnostic> {
    match (left, right) {
        (LoweredValue::Boolean(a), LoweredValue::Boolean(b)) => Ok(LoweredValue::Boolean(a && b)),
        _ => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: "CruftScript logical `&&` lowering supports only boolean operands".to_string(),
        }),
    }
}

fn lower_logical_or_value(
    left: LoweredValue,
    right: LoweredValue,
    span: Span,
) -> Result<LoweredValue, LoweringDiagnostic> {
    match (left, right) {
        (LoweredValue::Boolean(a), LoweredValue::Boolean(b)) => Ok(LoweredValue::Boolean(a || b)),
        _ => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: "CruftScript logical `||` lowering supports only boolean operands".to_string(),
        }),
    }
}

fn lower_logical_not_value(
    value: LoweredValue,
    span: Span,
) -> Result<LoweredValue, LoweringDiagnostic> {
    match value {
        LoweredValue::Boolean(value) => Ok(LoweredValue::Boolean(!value)),
        _ => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: "CruftScript logical `!` lowering supports only boolean operands".to_string(),
        }),
    }
}

fn lower_unary_minus_value(
    value: LoweredValue,
    span: Span,
) -> Result<LoweredValue, LoweringDiagnostic> {
    match value {
        LoweredValue::Number(value) => {
            let parsed = value.parse::<f64>().map_err(|_| LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                span,
                message: "CruftScript unary `-` requires a parseable numeric operand".to_string(),
            })?;
            Ok(LoweredValue::Number(format_number_literal(-parsed)))
        }
        _ => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: "CruftScript unary `-` lowering supports only number operands".to_string(),
        }),
    }
}

fn format_number_literal(value: f64) -> String {
    if value.fract() == 0.0 {
        format!("{}", value as i64)
    } else {
        value.to_string()
    }
}

fn lower_class_constructor_value(
    class_decl: &ClassDecl,
    args: &[ExprEnvelope],
    locals: &HashMap<String, LoweredValue>,
    static_index_locals: &HashSet<String>,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Option<LoweredValue> {
    let mut constructor_locals = locals.clone();
    let assignments = if let Some(constructor) = &class_decl.constructor {
        if args.len() != constructor.params.len()
            || !class_decl_has_lowerable_constructor(class_decl)
        {
            return None;
        }
        for (param, arg) in constructor.params.iter().zip(args) {
            let value =
                lower_constant_expression(arg, locals, static_index_locals, context, stack).ok()?;
            constructor_locals.insert(param.name.clone(), value);
        }
        let assignments = class_constructor_assignments(class_decl)?;
        let constructor_local_decls = match &assignments {
            ConstructorAssignmentPlan::Direct { locals, .. }
            | ConstructorAssignmentPlan::IfElse { locals, .. } => locals.as_slice(),
        };
        for local in constructor_local_decls {
            let initializer = local.initializer.as_ref()?;
            let value = lower_constant_expression(
                initializer,
                &constructor_locals,
                static_index_locals,
                context,
                stack,
            )
            .ok()?;
            constructor_locals.insert(local.name.clone(), value);
        }
        if let ConstructorAssignmentPlan::IfElse {
            local_assignments, ..
        } = &assignments
        {
            for assignment in local_assignments {
                let AssignmentTarget::Local(target) = &assignment.target else {
                    return None;
                };
                let value = lower_constant_expression(
                    &assignment.value,
                    &constructor_locals,
                    static_index_locals,
                    context,
                    stack,
                )
                .ok()?;
                constructor_locals.insert(target.clone(), value);
            }
        }
        Some(assignments)
    } else {
        if !args.is_empty() {
            return None;
        }
        None
    };
    if assignments.is_none() && !class_decl.fields.iter().all(class_field_has_initial_state) {
        return None;
    }
    if let Some(ConstructorAssignmentPlan::Direct { .. }) = assignments.as_ref() {
        let mut properties = Vec::new();
        let mut assigned = HashSet::new();
        constructor_locals.insert("this".to_string(), LoweredValue::Object(Vec::new()));
        if let Some(constructor) = &class_decl.constructor {
            for statement in &constructor.body.statements {
                let BodyStmt::Assignment(assignment) = statement else {
                    continue;
                };
                if let AssignmentTarget::Local(target) = &assignment.target {
                    if !constructor_locals.contains_key(target) {
                        return None;
                    }
                    let value = lower_constant_expression(
                        &assignment.value,
                        &constructor_locals,
                        static_index_locals,
                        context,
                        stack,
                    )
                    .ok()?;
                    constructor_locals.insert(target.clone(), value);
                    continue;
                }
                let AssignmentTarget::Property {
                    object,
                    property,
                    optional: false,
                } = &assignment.target
                else {
                    continue;
                };
                if !matches!(&object.kind, ExprEnvelopeKind::Identifier(name) if name == "this") {
                    continue;
                }
                let value = lower_constant_expression(
                    &assignment.value,
                    &constructor_locals,
                    static_index_locals,
                    context,
                    stack,
                )
                .ok()?;
                properties.push(LoweredObjectProperty {
                    name: property.clone(),
                    value,
                });
                assigned.insert(property.as_str());
                constructor_locals
                    .insert("this".to_string(), LoweredValue::Object(properties.clone()));
            }
        }
        for field in &class_decl.fields {
            if assigned.contains(field.name.as_str()) {
                continue;
            }
            let Some(initializer) = field.initializer.as_ref() else {
                continue;
            };
            properties.push(LoweredObjectProperty {
                name: field.name.clone(),
                value: lower_constant_expression(
                    initializer,
                    &constructor_locals,
                    static_index_locals,
                    context,
                    stack,
                )
                .ok()?,
            });
        }
        properties.extend(
            class_decl
                .methods
                .iter()
                .map(|method| LoweredObjectProperty {
                    name: method.name.clone(),
                    value: LoweredValue::FunctionRef(class_method_ref_name(
                        &class_decl.name,
                        &method.name,
                    )),
                }),
        );
        return Some(LoweredValue::Object(properties));
    }
    if let Some(ConstructorAssignmentPlan::IfElse {
        if_stmt,
        then_branch,
        else_branch,
        ..
    }) = assignments.as_ref()
    {
        let choose_then = evaluate_lowered_narrowing_guard(
            &if_stmt.subject,
            &if_stmt.guard,
            &constructor_locals,
            static_index_locals,
            context,
            stack,
        )
        .ok()?;
        let branch = if choose_then {
            then_branch
        } else {
            else_branch
        };
        return lower_constant_constructor_branch_object(
            class_decl,
            branch,
            &constructor_locals,
            static_index_locals,
            context,
            stack,
        );
    }
    let mut properties = class_decl
        .fields
        .iter()
        .filter_map(|field| {
            let value = match assignments.as_ref() {
                Some(ConstructorAssignmentPlan::Direct { assignments, .. }) => {
                    let initializer = assignments
                        .get(field.name.as_str())
                        .copied()
                        .or(field.initializer.as_ref())?;
                    lower_constant_expression(
                        initializer,
                        &constructor_locals,
                        static_index_locals,
                        context,
                        stack,
                    )
                    .ok()?
                }
                Some(ConstructorAssignmentPlan::IfElse { .. }) => {
                    unreachable!("if/else constructor returned before per-field lowering")
                }
                None => {
                    let initializer = field.initializer.as_ref()?;
                    lower_constant_expression(
                        initializer,
                        &constructor_locals,
                        static_index_locals,
                        context,
                        stack,
                    )
                    .ok()?
                }
            };
            Some(Some(LoweredObjectProperty {
                name: field.name.clone(),
                value,
            }))
        })
        .collect::<Option<Vec<_>>>()?;
    properties.extend(
        class_decl
            .methods
            .iter()
            .map(|method| LoweredObjectProperty {
                name: method.name.clone(),
                value: LoweredValue::FunctionRef(class_method_ref_name(
                    &class_decl.name,
                    &method.name,
                )),
            }),
    );
    Some(LoweredValue::Object(properties))
}

fn lower_constant_constructor_branch_object(
    class_decl: &ClassDecl,
    branch: &ConstructorBranchPlan<'_>,
    constructor_locals: &HashMap<String, LoweredValue>,
    static_index_locals: &HashSet<String>,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Option<LoweredValue> {
    let mut branch_locals = constructor_locals.clone();
    for local in &branch.locals {
        let initializer = local.initializer.as_ref()?;
        let value = lower_constant_expression(
            initializer,
            &branch_locals,
            static_index_locals,
            context,
            stack,
        )
        .ok()?;
        branch_locals.insert(local.name.clone(), value);
    }
    for assignment in &branch.local_assignments {
        let AssignmentTarget::Local(target) = &assignment.target else {
            return None;
        };
        if !branch_locals.contains_key(target) {
            return None;
        }
        let value = lower_constant_expression(
            &assignment.value,
            &branch_locals,
            static_index_locals,
            context,
            stack,
        )
        .ok()?;
        branch_locals.insert(target.clone(), value);
    }
    let mut properties = Vec::new();
    let mut assigned = HashSet::new();
    branch_locals.insert("this".to_string(), LoweredValue::Object(Vec::new()));
    for (field_name, value_expr) in &branch.field_assignments {
        let value = lower_constant_constructor_field_value(
            value_expr,
            &branch_locals,
            static_index_locals,
            context,
            stack,
        )?;
        properties.push(LoweredObjectProperty {
            name: (*field_name).to_string(),
            value,
        });
        assigned.insert(*field_name);
        branch_locals.insert("this".to_string(), LoweredValue::Object(properties.clone()));
    }
    for field in &class_decl.fields {
        if assigned.contains(field.name.as_str()) {
            continue;
        }
        let Some(initializer) = field.initializer.as_ref() else {
            continue;
        };
        let value = lower_constant_expression(
            initializer,
            &branch_locals,
            static_index_locals,
            context,
            stack,
        )
        .ok()?;
        properties.push(LoweredObjectProperty {
            name: field.name.clone(),
            value,
        });
    }
    properties.extend(
        class_decl
            .methods
            .iter()
            .map(|method| LoweredObjectProperty {
                name: method.name.clone(),
                value: LoweredValue::FunctionRef(class_method_ref_name(
                    &class_decl.name,
                    &method.name,
                )),
            }),
    );
    Some(LoweredValue::Object(properties))
}

fn lower_constant_constructor_field_value(
    value: &ConstructorFieldAssignmentValue<'_>,
    locals: &HashMap<String, LoweredValue>,
    static_index_locals: &HashSet<String>,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Option<LoweredValue> {
    match value {
        ConstructorFieldAssignmentValue::Expr(expr) => {
            lower_constant_expression(expr, locals, static_index_locals, context, stack).ok()
        }
        ConstructorFieldAssignmentValue::Conditional {
            if_stmt,
            then_value,
            else_value,
        } => {
            let choose_then = evaluate_lowered_narrowing_guard(
                &if_stmt.subject,
                &if_stmt.guard,
                locals,
                static_index_locals,
                context,
                stack,
            )
            .ok()?;
            let selected = if choose_then { then_value } else { else_value };
            lower_constant_expression(selected, locals, static_index_locals, context, stack).ok()
        }
    }
}

fn evaluate_lowered_narrowing_guard(
    subject: &ExprEnvelope,
    guard: &NarrowingGuard,
    locals: &HashMap<String, LoweredValue>,
    static_index_locals: &HashSet<String>,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<bool, LoweringDiagnostic> {
    let value = lower_constant_expression(subject, locals, static_index_locals, context, stack)?;
    Ok(match guard {
        NarrowingGuard::TypeofEquals { expected, .. } => lowered_value_typeof(&value) == expected,
        NarrowingGuard::Instanceof { constructor, .. } => context
            .get_class(constructor)
            .is_some_and(|class_decl| lowered_value_matches_class_instance(&value, class_decl)),
        NarrowingGuard::OwnProperty { property, .. } => {
            lowered_value_has_own_property(&value, property)
        }
        NarrowingGuard::DynamicOwnProperty { key, span } => {
            let key_value =
                lower_constant_expression(key, locals, static_index_locals, context, stack)?;
            let LoweredValue::String(key) = key_value else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                    span: *span,
                    message: "CruftScript dynamic `in` guard requires a string key".to_string(),
                });
            };
            lowered_value_has_own_property(&value, &key)
        }
        NarrowingGuard::Truthy { .. } => lowered_value_truthy(&value),
    })
}

fn lowered_value_has_own_property(value: &LoweredValue, property: &str) -> bool {
    let LoweredValue::Object(properties) = value else {
        return false;
    };
    properties
        .iter()
        .any(|candidate| candidate.name == property)
}

fn lowered_value_typeof(value: &LoweredValue) -> &'static str {
    match value {
        LoweredValue::Undefined => "undefined",
        LoweredValue::Null => "object",
        LoweredValue::String(_) => "string",
        LoweredValue::Number(_) => "number",
        LoweredValue::Boolean(_) => "boolean",
        LoweredValue::BigInt(_) => "bigint",
        LoweredValue::FunctionRef(_) => "function",
        LoweredValue::ClassConstructorRef(_) => "function",
        LoweredValue::Array(_) | LoweredValue::Object(_) => "object",
    }
}

fn lowered_value_truthy(value: &LoweredValue) -> bool {
    match value {
        LoweredValue::Undefined => false,
        LoweredValue::Null => false,
        LoweredValue::String(value) => !value.is_empty(),
        LoweredValue::Number(value) => value != "0" && value != "NaN",
        LoweredValue::Boolean(value) => *value,
        LoweredValue::BigInt(value) => value != "0",
        LoweredValue::FunctionRef(_) => true,
        LoweredValue::ClassConstructorRef(_) => true,
        LoweredValue::Array(_) | LoweredValue::Object(_) => true,
    }
}

fn lower_runtime_expression_export(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    function: &ExportedFunction,
) -> Option<LoweredFunction> {
    if !function.params.is_empty() {
        return None;
    }
    if runtime_export_returns_function_value(checked, context, function) {
        return None;
    }
    let expression = lower_runtime_function_body_with_runtime_bindings(
        checked,
        context,
        all_compartments,
        function,
        HashSet::new(),
        HashMap::new(),
        &mut Vec::new(),
    )?;
    Some(LoweredFunction {
        compartment: context.compartment.name.clone(),
        function_name: function.name.clone(),
        arity: 0,
        body: LoweredFunctionBody::RuntimeExpression(expression),
        span: function.span,
    })
}

fn runtime_export_returns_function_value(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    function: &ExportedFunction,
) -> bool {
    checked
        .report
        .expression_checks
        .functions
        .iter()
        .find(|check| {
            check.compartment == context.compartment.name && check.function_name == function.name
        })
        .is_some_and(|check| {
            check
                .returns
                .iter()
                .any(|ret| matches!(ret.expression_type, Some(TypeTerm::Function { .. })))
        })
}

fn lower_runtime_function_body_expression(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    function: &ExportedFunction,
    constant_bindings: &HashMap<String, LoweredValue>,
    stack: &mut Vec<String>,
) -> Option<LoweredRuntimeExpression> {
    if stack.iter().any(|name| name == &function.name) {
        return None;
    }
    stack.push(function.name.clone());
    let result = lower_runtime_function_body_expression_inner(
        checked,
        context,
        all_compartments,
        function,
        constant_bindings,
        stack,
    );
    stack.pop();
    result
}

fn lower_runtime_function_body_expression_inner(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    function: &ExportedFunction,
    constant_bindings: &HashMap<String, LoweredValue>,
    stack: &mut Vec<String>,
) -> Option<LoweredRuntimeExpression> {
    let (last, prefix) = function.body.statements.split_last()?;
    let BodyStmt::Return(ret) = last else {
        return None;
    };
    let argument = ret.argument.as_ref()?;
    let mut runtime_locals = HashSet::new();
    let runtime_local_types = HashMap::new();
    let mut bindings = constant_bindings.clone();
    let mut declarations = Vec::new();
    for statement in prefix {
        let BodyStmt::LocalDecl(local) = statement else {
            return None;
        };
        let initializer = local.initializer.as_ref()?;
        let value = lower_runtime_expression(
            checked,
            context,
            all_compartments,
            initializer,
            &bindings,
            &runtime_locals,
            &runtime_local_types,
            stack,
        )?;
        declarations.push((local.name.clone(), value));
        runtime_locals.insert(local.name.clone());
        bindings.remove(&local.name);
    }
    let mut body = lower_runtime_expression(
        checked,
        context,
        all_compartments,
        argument,
        &bindings,
        &runtime_locals,
        &runtime_local_types,
        stack,
    )?;
    for (name, value) in declarations.into_iter().rev() {
        body = LoweredRuntimeExpression::Let {
            name,
            value: Box::new(value),
            body: Box::new(body),
        };
    }
    Some(body)
}

fn lower_runtime_function_body_with_runtime_bindings(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    function: &ExportedFunction,
    runtime_locals: HashSet<String>,
    runtime_local_types: HashMap<String, TypeTerm>,
    stack: &mut Vec<String>,
) -> Option<LoweredRuntimeExpression> {
    if stack.iter().any(|name| name == &function.name) {
        return None;
    }
    stack.push(function.name.clone());
    let result = lower_runtime_function_body_with_runtime_bindings_inner(
        checked,
        context,
        all_compartments,
        function,
        runtime_locals,
        runtime_local_types,
        stack,
    );
    stack.pop();
    result
}

fn lower_runtime_function_body_with_runtime_bindings_inner(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    function: &ExportedFunction,
    mut runtime_locals: HashSet<String>,
    mut runtime_local_types: HashMap<String, TypeTerm>,
    stack: &mut Vec<String>,
) -> Option<LoweredRuntimeExpression> {
    let (last, prefix) = function.body.statements.split_last()?;
    let (prefix, if_return_tail) = match prefix.split_last() {
        Some((BodyStmt::If(if_stmt), rest)) if if_stmt.else_body.is_none() => (rest, Some(if_stmt)),
        _ => (prefix, None),
    };
    let mut constant_bindings = HashMap::new();
    let mut declarations = Vec::new();
    let mut extra_if_returns: Vec<&cruftscript_parser::IfStmt> = Vec::new();
    for statement in prefix {
        if let BodyStmt::If(if_stmt) = statement {
            if if_stmt.else_body.is_none()
                && matches!(
                    if_stmt.then_body.statements.as_slice(),
                    [BodyStmt::Return(_)]
                )
            {
                extra_if_returns.push(if_stmt);
                continue;
            }
        }
        let BodyStmt::LocalDecl(local) = statement else {
            return None;
        };
        let initializer = local.initializer.as_ref()?;
        if !local.mutable {
            if let ExprEnvelopeKind::StringLiteral(value) = &initializer.kind {
                constant_bindings.insert(local.name.clone(), LoweredValue::String(value.clone()));
                continue;
            }
            if let Some(value) = same_compartment_function_ref_initializer(initializer, context) {
                constant_bindings.insert(local.name.clone(), value);
                continue;
            }
            if let Some(value) = same_compartment_constructor_ref_initializer(initializer, context)
            {
                constant_bindings.insert(local.name.clone(), value);
                continue;
            }
            if let Some(value) =
                lower_runtime_constant_callee_object(initializer, context, &constant_bindings)
            {
                constant_bindings.insert(local.name.clone(), value);
                continue;
            }
        }
        let value = lower_runtime_expression(
            checked,
            context,
            all_compartments,
            initializer,
            &constant_bindings,
            &runtime_locals,
            &runtime_local_types,
            stack,
        )?;
        declarations.push((local.name.clone(), value));
        runtime_locals.insert(local.name.clone());
        if let Some(annotation) = &local.type_annotation {
            runtime_local_types.insert(local.name.clone(), lower_type_term(annotation));
        }
    }
    if let BodyStmt::If(if_stmt) = last {
        if let Some(else_body) = &if_stmt.else_body {
            let [BodyStmt::Return(then_return)] = if_stmt.then_body.statements.as_slice() else {
                return None;
            };
            let [BodyStmt::Return(else_return)] = else_body.statements.as_slice() else {
                return None;
            };
            let then_argument = then_return.argument.as_ref()?;
            let else_argument = else_return.argument.as_ref()?;
            let consequent_runtime_local_types = runtime_local_types_with_guard_refinement(
                checked,
                context,
                &constant_bindings,
                &runtime_local_types,
                &if_stmt.subject,
                &if_stmt.guard,
            );
            let alternate_runtime_local_types = runtime_local_types_with_guard_negative_refinement(
                checked,
                context,
                &constant_bindings,
                &runtime_local_types,
                &if_stmt.subject,
                &if_stmt.guard,
            );
            let mut body = LoweredRuntimeExpression::Conditional {
                subject: Box::new(lower_runtime_expression(
                    checked,
                    context,
                    all_compartments,
                    &if_stmt.subject,
                    &constant_bindings,
                    &runtime_locals,
                    &runtime_local_types,
                    stack,
                )?),
                guard: lower_runtime_narrowing_guard(
                    checked,
                    context,
                    all_compartments,
                    &if_stmt.guard,
                    &constant_bindings,
                    &runtime_locals,
                    &runtime_local_types,
                    stack,
                )?,
                consequent: Box::new(lower_runtime_expression(
                    checked,
                    context,
                    all_compartments,
                    then_argument,
                    &constant_bindings,
                    &runtime_locals,
                    &consequent_runtime_local_types,
                    stack,
                )?),
                alternate: Box::new(lower_runtime_expression(
                    checked,
                    context,
                    all_compartments,
                    else_argument,
                    &constant_bindings,
                    &runtime_locals,
                    &alternate_runtime_local_types,
                    stack,
                )?),
            };
            for (name, value) in declarations.into_iter().rev() {
                body = LoweredRuntimeExpression::Let {
                    name,
                    value: Box::new(value),
                    body: Box::new(body),
                };
            }
            return Some(body);
        }
    }
    let BodyStmt::Return(ret) = last else {
        return None;
    };
    let argument = ret.argument.as_ref()?;
    if extra_if_returns.is_empty() {
        if let Some(body) = lower_runtime_if_assignment_tail(
            checked,
            context,
            all_compartments,
            if_return_tail,
            argument,
            &constant_bindings,
            &runtime_locals,
            &runtime_local_types,
            stack,
        ) {
            let mut body = body;
            for (name, value) in declarations.into_iter().rev() {
                body = LoweredRuntimeExpression::Let {
                    name,
                    value: Box::new(value),
                    body: Box::new(body),
                };
            }
            return Some(body);
        }
    }
    let alternate = lower_runtime_expression(
        checked,
        context,
        all_compartments,
        argument,
        &constant_bindings,
        &runtime_locals,
        &runtime_local_types,
        stack,
    )?;
    let mut body = if let Some(if_stmt) = if_return_tail {
        lower_runtime_if_return_conditional(
            checked,
            context,
            all_compartments,
            if_stmt,
            alternate,
            &constant_bindings,
            &runtime_locals,
            &runtime_local_types,
        )?
    } else {
        alternate
    };
    for if_stmt in extra_if_returns.into_iter().rev() {
        body = lower_runtime_if_return_conditional(
            checked,
            context,
            all_compartments,
            if_stmt,
            body,
            &constant_bindings,
            &runtime_locals,
            &runtime_local_types,
        )?;
    }
    for (name, value) in declarations.into_iter().rev() {
        body = LoweredRuntimeExpression::Let {
            name,
            value: Box::new(value),
            body: Box::new(body),
        };
    }
    Some(body)
}

fn lower_runtime_if_assignment_tail(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    if_return_tail: Option<&IfStmt>,
    final_argument: &ExprEnvelope,
    constant_bindings: &HashMap<String, LoweredValue>,
    runtime_locals: &HashSet<String>,
    runtime_local_types: &HashMap<String, TypeTerm>,
    stack: &mut Vec<String>,
) -> Option<LoweredRuntimeExpression> {
    let if_stmt = if_return_tail?;
    let ExprEnvelopeKind::Identifier(final_name) = &final_argument.kind else {
        return None;
    };
    let [BodyStmt::Assignment(assignment)] = if_stmt.then_body.statements.as_slice() else {
        return None;
    };
    let AssignmentTarget::Local(target_name) = &assignment.target else {
        return None;
    };
    if target_name != final_name {
        return None;
    }
    let consequent_runtime_local_types = runtime_local_types_with_guard_refinement(
        checked,
        context,
        constant_bindings,
        runtime_local_types,
        &if_stmt.subject,
        &if_stmt.guard,
    );
    Some(LoweredRuntimeExpression::Conditional {
        subject: Box::new(lower_runtime_expression(
            checked,
            context,
            all_compartments,
            &if_stmt.subject,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        )?),
        guard: lower_runtime_narrowing_guard(
            checked,
            context,
            all_compartments,
            &if_stmt.guard,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        )?,
        consequent: Box::new(lower_runtime_expression(
            checked,
            context,
            all_compartments,
            &assignment.value,
            constant_bindings,
            runtime_locals,
            &consequent_runtime_local_types,
            stack,
        )?),
        alternate: Box::new(lower_runtime_expression(
            checked,
            context,
            all_compartments,
            final_argument,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        )?),
    })
}

fn lower_runtime_expression(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    expr: &ExprEnvelope,
    constant_bindings: &HashMap<String, LoweredValue>,
    runtime_locals: &HashSet<String>,
    runtime_local_types: &HashMap<String, TypeTerm>,
    stack: &mut Vec<String>,
) -> Option<LoweredRuntimeExpression> {
    match &expr.kind {
        ExprEnvelopeKind::StringLiteral(value) => Some(LoweredRuntimeExpression::Value(
            LoweredValue::String(value.clone()),
        )),
        ExprEnvelopeKind::NumberLiteral(value) => Some(LoweredRuntimeExpression::Value(
            LoweredValue::Number(value.clone()),
        )),
        ExprEnvelopeKind::BooleanLiteral(value) => Some(LoweredRuntimeExpression::Value(
            LoweredValue::Boolean(*value),
        )),
        ExprEnvelopeKind::NullLiteral => Some(LoweredRuntimeExpression::Value(LoweredValue::Null)),
        ExprEnvelopeKind::Identifier(name) => constant_bindings
            .get(name)
            .cloned()
            .map(LoweredRuntimeExpression::Value)
            .or_else(|| {
                runtime_locals
                    .contains(name)
                    .then(|| LoweredRuntimeExpression::LocalRef(name.clone()))
            })
            .or_else(|| {
                context.has_endowment(name).then(|| {
                    LoweredRuntimeExpression::EndowmentRef(LoweredEndowmentRef {
                        compartment: context.compartment.name.clone(),
                        name: name.clone(),
                        span: expr.span,
                    })
                })
            })
            .or_else(|| {
                context.has_intrinsic(name).then(|| {
                    LoweredRuntimeExpression::IntrinsicRef(LoweredIntrinsicRef {
                        name: name.clone(),
                        span: expr.span,
                    })
                })
            }),
        ExprEnvelopeKind::ArrayLiteral(elements) => elements
            .iter()
            .map(|element| {
                lower_runtime_expression(
                    checked,
                    context,
                    all_compartments,
                    element,
                    constant_bindings,
                    runtime_locals,
                    runtime_local_types,
                    stack,
                )
            })
            .collect::<Option<Vec<_>>>()
            .map(LoweredRuntimeExpression::Array),
        ExprEnvelopeKind::ObjectLiteral(properties) => properties
            .iter()
            .map(|property| {
                Some(LoweredRuntimeObjectProperty {
                    name: property.name.clone(),
                    value: lower_runtime_expression(
                        checked,
                        context,
                        all_compartments,
                        &property.value,
                        constant_bindings,
                        runtime_locals,
                        runtime_local_types,
                        stack,
                    )?,
                })
            })
            .collect::<Option<Vec<_>>>()
            .map(LoweredRuntimeExpression::Object),
        ExprEnvelopeKind::PropertyAccess {
            object,
            property,
            optional,
        } => {
            if let ExprEnvelopeKind::Identifier(class_name) = &object.kind {
                if let Some((_, field)) = context
                    .get_class_static_field(&class_static_field_ref_name(class_name, property))
                {
                    let initializer = field.initializer.as_ref()?;
                    return lower_runtime_expression(
                        checked,
                        context,
                        all_compartments,
                        initializer,
                        constant_bindings,
                        runtime_locals,
                        runtime_local_types,
                        stack,
                    );
                }
            }
            Some(LoweredRuntimeExpression::PropertyAccess {
                object: Box::new(lower_runtime_expression(
                    checked,
                    context,
                    all_compartments,
                    object,
                    constant_bindings,
                    runtime_locals,
                    runtime_local_types,
                    stack,
                )?),
                property: property.clone(),
                optional: *optional,
                span: expr.span,
            })
        }
        ExprEnvelopeKind::ElementAccess {
            object,
            index,
            optional,
        } => {
            let object_type = match &object.kind {
                ExprEnvelopeKind::Identifier(object_name) => {
                    let object_type = runtime_local_types.get(object_name)?;
                    let mut diagnostics = Vec::new();
                    AliasExpansionContext::new(&checked.report.types)
                        .expand_for_assignability(object_type, &mut diagnostics)
                }
                ExprEnvelopeKind::Assertion { target, .. } => {
                    runtime_assertion_target_type_from_type_expr(
                        target,
                        &AliasExpansionContext::new(&checked.report.types),
                    )?
                }
                _ => {
                    let ExprEnvelopeKind::StringLiteral(property) = &index.kind else {
                        return None;
                    };
                    return Some(LoweredRuntimeExpression::PropertyAccess {
                        object: Box::new(lower_runtime_expression(
                            checked,
                            context,
                            all_compartments,
                            object,
                            constant_bindings,
                            runtime_locals,
                            runtime_local_types,
                            stack,
                        )?),
                        property: property.clone(),
                        optional: *optional,
                        span: expr.span,
                    });
                }
            };
            let property_access = if let ExprEnvelopeKind::StringLiteral(property) = &index.kind {
                LoweredRuntimeExpression::PropertyAccess {
                    object: Box::new(lower_runtime_expression(
                        checked,
                        context,
                        all_compartments,
                        object,
                        constant_bindings,
                        runtime_locals,
                        runtime_local_types,
                        stack,
                    )?),
                    property: property.clone(),
                    optional: *optional,
                    span: expr.span,
                }
            } else {
                LoweredRuntimeExpression::ComputedPropertyAccess {
                    object: Box::new(lower_runtime_expression(
                        checked,
                        context,
                        all_compartments,
                        object,
                        constant_bindings,
                        runtime_locals,
                        runtime_local_types,
                        stack,
                    )?),
                    key: Box::new(lower_runtime_expression(
                        checked,
                        context,
                        all_compartments,
                        index,
                        constant_bindings,
                        runtime_locals,
                        runtime_local_types,
                        stack,
                    )?),
                    optional: *optional,
                    span: expr.span,
                }
            };
            match object_type {
                TypeTerm::TypeRef {
                    name, type_args, ..
                } if name == "__CruftStringRecord" && type_args.len() == 1 => {
                    if !runtime_element_key_is_string(index, runtime_local_types) {
                        return None;
                    }
                    let target_type = if *optional {
                        TypeTerm::Union {
                            members: vec![
                                type_args[0].clone(),
                                TypeTerm::Named {
                                    name: "undefined".to_string(),
                                    span: expr.span,
                                },
                            ],
                            span: expr.span,
                        }
                    } else {
                        type_args[0].clone()
                    };
                    Some(LoweredRuntimeExpression::TypeCheck {
                        expr: Box::new(property_access),
                        target_type,
                        span: expr.span,
                    })
                }
                TypeTerm::TypeRef {
                    name, type_args, ..
                } if name == "Array" && type_args.len() == 1 => {
                    if !runtime_element_key_is_number(index, runtime_local_types) {
                        return None;
                    }
                    let target_type = if !*optional && runtime_element_key_is_static_index(index) {
                        type_args[0].clone()
                    } else {
                        TypeTerm::Union {
                            members: vec![
                                type_args[0].clone(),
                                TypeTerm::Named {
                                    name: "undefined".to_string(),
                                    span: expr.span,
                                },
                            ],
                            span: expr.span,
                        }
                    };
                    Some(LoweredRuntimeExpression::TypeCheck {
                        expr: Box::new(property_access),
                        target_type,
                        span: expr.span,
                    })
                }
                TypeTerm::Tuple { elements, .. } => {
                    let ExprEnvelopeKind::NumberLiteral(index_value) = &index.kind else {
                        return None;
                    };
                    if !is_non_negative_integral_number_spelling(index_value) {
                        return None;
                    }
                    let index_value = index_value.parse::<usize>().ok()?;
                    let element_type = elements.get(index_value)?.clone();
                    let target_type = if *optional {
                        TypeTerm::Union {
                            members: vec![
                                element_type,
                                TypeTerm::Named {
                                    name: "undefined".to_string(),
                                    span: expr.span,
                                },
                            ],
                            span: expr.span,
                        }
                    } else {
                        element_type
                    };
                    Some(LoweredRuntimeExpression::TypeCheck {
                        expr: Box::new(property_access),
                        target_type,
                        span: expr.span,
                    })
                }
                _ => {
                    let ExprEnvelopeKind::Identifier(_) = &object.kind else {
                        return None;
                    };
                    let ExprEnvelopeKind::StringLiteral(property) = &index.kind else {
                        return None;
                    };
                    Some(LoweredRuntimeExpression::PropertyAccess {
                        object: Box::new(lower_runtime_expression(
                            checked,
                            context,
                            all_compartments,
                            object,
                            constant_bindings,
                            runtime_locals,
                            runtime_local_types,
                            stack,
                        )?),
                        property: property.clone(),
                        optional: *optional,
                        span: expr.span,
                    })
                }
            }
        }
        ExprEnvelopeKind::Call {
            callee,
            args,
            optional,
        } => lower_runtime_imported_call_expression(
            checked,
            context.compartment,
            expr.span,
            callee,
            args,
        )
        .map(LoweredRuntimeExpression::ImportedCall)
        .or_else(|| {
            lower_runtime_cross_compartment_call_expression(
                checked,
                context,
                all_compartments,
                expr.span,
                callee,
                args,
                constant_bindings,
            )
            .map(LoweredRuntimeExpression::CrossCompartmentCall)
        })
        .or_else(|| {
            lower_runtime_callback_call_expression(
                checked,
                context,
                all_compartments,
                expr.span,
                callee,
                args,
                *optional,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )
            .map(LoweredRuntimeExpression::RuntimeCallbackCall)
        })
        .or_else(|| {
            lower_runtime_same_compartment_call_expression(
                checked,
                context,
                all_compartments,
                callee,
                args,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )
        })
        .or_else(|| {
            lower_runtime_predicate_record_call_expression(
                checked,
                context,
                all_compartments,
                expr.span,
                callee,
                args,
                *optional,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )
        })
        .or_else(|| {

            lower_runtime_builtin_method_call_expression(
                checked,
                context,
                all_compartments,
                expr.span,
                callee,
                args,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )
        }),
        ExprEnvelopeKind::New { class_name, args } => {

            if STDLIB_BUILTIN_CONSTRUCTORS.contains(&class_name.as_str()) {
                let lowered_args = args
                    .iter()
                    .map(|arg| {
                        lower_runtime_expression(
                            checked,
                            context,
                            all_compartments,
                            arg,
                            constant_bindings,
                            runtime_locals,
                            runtime_local_types,
                            stack,
                        )
                    })
                    .collect::<Option<Vec<_>>>()?;
                return Some(LoweredRuntimeExpression::BuiltinConstruct {
                    constructor: class_name.clone(),
                    args: lowered_args,
                    span: expr.span,
                });
            }
            let resolved_class_name =
                lowered_constructor_name_for_new(class_name, constant_bindings)
                    .unwrap_or(class_name);
            let class_decl = context.get_class(resolved_class_name)?;
            lower_class_constructor_runtime_expression(
                checked,
                context,
                all_compartments,
                class_decl,
                args,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )
        }
        ExprEnvelopeKind::Conditional {
            subject,
            guard,
            consequent,
            alternate,
        } => Some(LoweredRuntimeExpression::Conditional {
            subject: Box::new(lower_runtime_expression(
                checked,
                context,
                all_compartments,
                subject,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )?),
            guard: lower_runtime_narrowing_guard(
                checked,
                context,
                all_compartments,
                guard,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )?,
            consequent: Box::new(lower_runtime_expression(
                checked,
                context,
                all_compartments,
                consequent,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )?),
            alternate: Box::new(lower_runtime_expression(
                checked,
                context,
                all_compartments,
                alternate,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )?),
        }),
        ExprEnvelopeKind::Ternary {
            condition,
            consequent,
            alternate,
        } => Some(LoweredRuntimeExpression::Ternary {
            condition: Box::new(lower_runtime_expression(
                checked,
                context,
                all_compartments,
                condition,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )?),
            consequent: Box::new(lower_runtime_expression(
                checked,
                context,
                all_compartments,
                consequent,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )?),
            alternate: Box::new(lower_runtime_expression(
                checked,
                context,
                all_compartments,
                alternate,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )?),
        }),
        ExprEnvelopeKind::LetIn { name, value, body } => {

            let lowered_value = lower_runtime_expression(
                checked,
                context,
                all_compartments,
                value,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )?;
            let mut body_locals = runtime_locals.clone();
            body_locals.insert(name.clone());
            let mut body_bindings = constant_bindings.clone();
            body_bindings.remove(name);
            let lowered_body = lower_runtime_expression(
                checked,
                context,
                all_compartments,
                body,
                &body_bindings,
                &body_locals,
                runtime_local_types,
                stack,
            )?;
            Some(LoweredRuntimeExpression::Let {
                name: name.clone(),
                value: Box::new(lowered_value),
                body: Box::new(lowered_body),
            })
        }
        ExprEnvelopeKind::Assertion {
            expr,
            target,
            satisfies,
        } => {
            let lowered = lower_runtime_expression(
                checked,
                context,
                all_compartments,
                expr,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )?;

            if *satisfies {
                return Some(lowered);
            }
            if let Some(target_type) = runtime_assertion_target_type_from_type_expr(
                target,
                &AliasExpansionContext::new(&checked.report.types),
            ) {
                return Some(LoweredRuntimeExpression::TypeCheck {
                    expr: Box::new(lowered),
                    target_type,
                    span: expr.span,
                });
            }
            Some(lowered)
        }
        ExprEnvelopeKind::NonNull { expr } => Some(LoweredRuntimeExpression::NonNullCheck {
            expr: Box::new(lower_runtime_expression(
                checked,
                context,
                all_compartments,
                expr,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )?),
            span: expr.span,
        }),
        ExprEnvelopeKind::BinaryAdd { left, right } => lower_runtime_binary(
            RuntimeBinaryOp::Add,
            checked,
            context,
            all_compartments,
            left,
            right,
            expr.span,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        ),
        ExprEnvelopeKind::BinarySub { left, right } => lower_runtime_binary(
            RuntimeBinaryOp::Sub,
            checked,
            context,
            all_compartments,
            left,
            right,
            expr.span,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        ),
        ExprEnvelopeKind::BinaryMul { left, right } => lower_runtime_binary(
            RuntimeBinaryOp::Mul,
            checked,
            context,
            all_compartments,
            left,
            right,
            expr.span,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        ),
        ExprEnvelopeKind::BinaryPow { left, right } => lower_runtime_binary(
            RuntimeBinaryOp::Pow,
            checked,
            context,
            all_compartments,
            left,
            right,
            expr.span,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        ),
        ExprEnvelopeKind::BinaryDiv { left, right } => lower_runtime_binary(
            RuntimeBinaryOp::Div,
            checked,
            context,
            all_compartments,
            left,
            right,
            expr.span,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        ),
        ExprEnvelopeKind::BinaryRem { left, right } => lower_runtime_binary(
            RuntimeBinaryOp::Rem,
            checked,
            context,
            all_compartments,
            left,
            right,
            expr.span,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        ),
        ExprEnvelopeKind::NullishCoalesce { left, right } => lower_runtime_binary(
            RuntimeBinaryOp::NullishCoalesce,
            checked,
            context,
            all_compartments,
            left,
            right,
            expr.span,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        ),
        ExprEnvelopeKind::BinaryLessThan { left, right } => lower_runtime_binary(
            RuntimeBinaryOp::Lt,
            checked,
            context,
            all_compartments,
            left,
            right,
            expr.span,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        ),
        ExprEnvelopeKind::BinaryGreaterThan { left, right } => lower_runtime_binary(
            RuntimeBinaryOp::Gt,
            checked,
            context,
            all_compartments,
            left,
            right,
            expr.span,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        ),
        ExprEnvelopeKind::BinaryLessThanOrEqual { left, right } => lower_runtime_binary(
            RuntimeBinaryOp::Le,
            checked,
            context,
            all_compartments,
            left,
            right,
            expr.span,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        ),
        ExprEnvelopeKind::BinaryGreaterThanOrEqual { left, right } => lower_runtime_binary(
            RuntimeBinaryOp::Ge,
            checked,
            context,
            all_compartments,
            left,
            right,
            expr.span,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        ),
        ExprEnvelopeKind::BinaryStrictEqual { left, right } => lower_runtime_binary(
            RuntimeBinaryOp::StrictEq,
            checked,
            context,
            all_compartments,
            left,
            right,
            expr.span,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        ),
        ExprEnvelopeKind::BinaryStrictNotEqual { left, right } => lower_runtime_binary(
            RuntimeBinaryOp::StrictNe,
            checked,
            context,
            all_compartments,
            left,
            right,
            expr.span,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        ),
        ExprEnvelopeKind::LogicalAnd { left, right } => lower_runtime_binary(
            RuntimeBinaryOp::And,
            checked,
            context,
            all_compartments,
            left,
            right,
            expr.span,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        ),
        ExprEnvelopeKind::LogicalOr { left, right } => lower_runtime_binary(
            RuntimeBinaryOp::Or,
            checked,
            context,
            all_compartments,
            left,
            right,
            expr.span,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        ),
        ExprEnvelopeKind::Arrow { params, body } => {

            let mut body_locals = runtime_locals.clone();
            for param in params {
                body_locals.insert(param.name.clone());
            }
            let lowered_body = lower_runtime_expression(
                checked,
                context,
                all_compartments,
                body,
                constant_bindings,
                &body_locals,
                runtime_local_types,
                stack,
            )?;
            Some(LoweredRuntimeExpression::Arrow {
                params: params.iter().map(|p| p.name.clone()).collect(),
                body: Box::new(lowered_body),
                span: expr.span,
            })
        }
        ExprEnvelopeKind::Opaque(spelling) => {
            if let Some(class_name) = parse_zero_arg_new_expression(spelling) {
                if let Some(class_decl) = context.get_class(class_name) {
                    return lower_class_constructor_runtime_expression(
                        checked,
                        context,
                        all_compartments,
                        class_decl,
                        &[],
                        constant_bindings,
                        runtime_locals,
                        runtime_local_types,
                        stack,
                    );
                }
            }
            None
        }
        _ => None,
    }
}

fn expr_mentions_this(expr: &ExprEnvelope) -> bool {
    match &expr.kind {
        ExprEnvelopeKind::Identifier(name) => name == "this",
        ExprEnvelopeKind::PropertyAccess { object, .. }
        | ExprEnvelopeKind::NonNull { expr: object }
        | ExprEnvelopeKind::Assertion { expr: object, .. } => expr_mentions_this(object),
        ExprEnvelopeKind::ElementAccess { object, index, .. } => {
            expr_mentions_this(object) || expr_mentions_this(index)
        }
        ExprEnvelopeKind::Call { callee, args, .. } => {
            expr_mentions_this(callee) || args.iter().any(expr_mentions_this)
        }
        ExprEnvelopeKind::BinaryAdd { left, right }
        | ExprEnvelopeKind::BinarySub { left, right }
        | ExprEnvelopeKind::BinaryMul { left, right }
        | ExprEnvelopeKind::BinaryPow { left, right }
        | ExprEnvelopeKind::BinaryDiv { left, right }
        | ExprEnvelopeKind::BinaryRem { left, right }
        | ExprEnvelopeKind::NullishCoalesce { left, right }
        | ExprEnvelopeKind::BinaryLessThan { left, right }
        | ExprEnvelopeKind::BinaryGreaterThan { left, right }
        | ExprEnvelopeKind::BinaryLessThanOrEqual { left, right }
        | ExprEnvelopeKind::BinaryGreaterThanOrEqual { left, right }
        | ExprEnvelopeKind::BinaryStrictEqual { left, right }
        | ExprEnvelopeKind::BinaryStrictNotEqual { left, right }
        | ExprEnvelopeKind::LogicalAnd { left, right }
        | ExprEnvelopeKind::LogicalOr { left, right } => {
            expr_mentions_this(left) || expr_mentions_this(right)
        }
        _ => false,
    }
}

#[allow(clippy::too_many_arguments)]
fn lower_runtime_binary(
    op: RuntimeBinaryOp,
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    left: &ExprEnvelope,
    right: &ExprEnvelope,
    span: Span,
    constant_bindings: &HashMap<String, LoweredValue>,
    runtime_locals: &HashSet<String>,
    runtime_local_types: &HashMap<String, TypeTerm>,
    stack: &mut Vec<String>,
) -> Option<LoweredRuntimeExpression> {

    if expr_mentions_this(left) || expr_mentions_this(right) {
        return None;
    }
    let left = lower_runtime_expression(
        checked,
        context,
        all_compartments,
        left,
        constant_bindings,
        runtime_locals,
        runtime_local_types,
        stack,
    )?;
    let right = lower_runtime_expression(
        checked,
        context,
        all_compartments,
        right,
        constant_bindings,
        runtime_locals,
        runtime_local_types,
        stack,
    )?;
    Some(LoweredRuntimeExpression::Binary {
        op,
        left: Box::new(left),
        right: Box::new(right),
        span,
    })
}

fn stdlib_is_callable_method(property: &str) -> bool {
    if property == "length" {
        return false;
    }
    let is_fn = |member: Option<TypeTerm>| matches!(member, Some(TypeTerm::Function { .. }));
    is_fn(stdlib_string_member(property))
        || is_fn(stdlib_number_member(property))
        || is_fn(stdlib_boolean_member(property))
        || is_fn(stdlib_regexp_member(property))
        || is_fn(stdlib_array_member(property, &stdlib_unknown()))
        || is_fn(stdlib_json_member(property))
        || is_fn(stdlib_math_member(property))
        || is_fn(stdlib_object_static_member(property))
        || is_fn(stdlib_number_static_member(property))
}

fn lower_runtime_builtin_method_call_expression(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    span: Span,
    callee: &ExprEnvelope,
    args: &[ExprEnvelope],
    constant_bindings: &HashMap<String, LoweredValue>,
    runtime_locals: &HashSet<String>,
    runtime_local_types: &HashMap<String, TypeTerm>,
    stack: &mut Vec<String>,
) -> Option<LoweredRuntimeExpression> {
    let ExprEnvelopeKind::PropertyAccess {
        object, property, ..
    } = &callee.kind
    else {
        return None;
    };
    if !stdlib_is_callable_method(property) {
        return None;
    }
    let receiver = lower_runtime_expression(
        checked,
        context,
        all_compartments,
        object,
        constant_bindings,
        runtime_locals,
        runtime_local_types,
        stack,
    )?;
    let lowered_args = args
        .iter()
        .map(|arg| {
            lower_runtime_expression(
                checked,
                context,
                all_compartments,
                arg,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )
        })
        .collect::<Option<Vec<_>>>()?;
    Some(LoweredRuntimeExpression::BuiltinMethodCall {
        receiver: Box::new(receiver),
        method: property.clone(),
        args: lowered_args,
        span,
    })
}

fn lower_runtime_same_compartment_call_expression(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    callee: &ExprEnvelope,
    args: &[ExprEnvelope],
    constant_bindings: &HashMap<String, LoweredValue>,
    runtime_locals: &HashSet<String>,
    runtime_local_types: &HashMap<String, TypeTerm>,
    stack: &mut Vec<String>,
) -> Option<LoweredRuntimeExpression> {
    let function_name =
        same_compartment_function_name_for_callee(callee, context, constant_bindings)?;
    let function = context.get_function(&function_name)?;
    if function
        .params
        .first()
        .is_some_and(|param| param.name == "this")
    {
        return None;
    }
    if args.len() != function.params.len() {
        return None;
    }
    let mut bindings = HashMap::new();
    let mut runtime_arg_declarations = Vec::new();
    let mut runtime_arg_locals = HashSet::new();
    let mut runtime_arg_types = HashMap::new();
    for (param, arg) in function.params.iter().zip(args.iter()) {
        if let Some(value) = lower_runtime_constant_arg(arg, constant_bindings, runtime_locals) {
            bindings.insert(param.name.clone(), value);
            continue;
        }
        let value = lower_runtime_expression(
            checked,
            context,
            all_compartments,
            arg,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            stack,
        )?;
        runtime_arg_declarations.push((param.name.clone(), value));
        runtime_arg_locals.insert(param.name.clone());
        runtime_arg_types.insert(param.name.clone(), lower_type_term(&param.ty));
    }
    if runtime_arg_declarations.is_empty() {
        return lower_runtime_function_body_expression(
            checked,
            context,
            all_compartments,
            function,
            &bindings,
            stack,
        );
    }
    if !bindings.is_empty() {
        return None;
    }
    let mut body = lower_runtime_function_body_with_runtime_bindings(
        checked,
        context,
        all_compartments,
        function,
        runtime_arg_locals,
        runtime_arg_types,
        stack,
    )?;
    for (name, value) in runtime_arg_declarations.into_iter().rev() {
        body = LoweredRuntimeExpression::Let {
            name,
            value: Box::new(value),
            body: Box::new(body),
        };
    }
    Some(body)
}

fn same_compartment_function_name_for_callee(
    callee: &ExprEnvelope,
    context: &LoweringContext<'_>,
    constant_bindings: &HashMap<String, LoweredValue>,
) -> Option<String> {
    match &callee.kind {
        ExprEnvelopeKind::Identifier(name) => {
            if context.get_function(name).is_some() {
                Some(name.clone())
            } else if let Some(LoweredValue::FunctionRef(function_name)) =
                constant_bindings.get(name)
            {
                Some(function_name.clone())
            } else {
                None
            }
        }
        ExprEnvelopeKind::PropertyAccess {
            object, property, ..
        } => {
            let lowered_object =
                lower_runtime_constant_callee_object(object, context, constant_bindings)?;
            let LoweredValue::Object(properties) = lowered_object else {
                return None;
            };
            properties
                .iter()
                .find(|candidate| candidate.name == *property)
                .and_then(|candidate| match &candidate.value {
                    LoweredValue::FunctionRef(function_name) => Some(function_name.clone()),
                    _ => None,
                })
        }
        ExprEnvelopeKind::ElementAccess { object, index, .. } => {
            let property = runtime_static_string_key(index, constant_bindings)?;
            let lowered_object =
                lower_runtime_constant_callee_object(object, context, constant_bindings)?;
            let LoweredValue::Object(properties) = lowered_object else {
                return None;
            };
            properties
                .iter()
                .find(|candidate| candidate.name == property)
                .and_then(|candidate| match &candidate.value {
                    LoweredValue::FunctionRef(function_name) => Some(function_name.clone()),
                    _ => None,
                })
        }
        _ => None,
    }
}

fn runtime_static_string_key<'a>(
    index: &'a ExprEnvelope,
    constant_bindings: &'a HashMap<String, LoweredValue>,
) -> Option<&'a str> {
    match &index.kind {
        ExprEnvelopeKind::StringLiteral(value) => Some(value.as_str()),
        ExprEnvelopeKind::Identifier(name) => match constant_bindings.get(name) {
            Some(LoweredValue::String(value)) => Some(value.as_str()),
            _ => None,
        },
        _ => None,
    }
}

fn lower_runtime_constant_callee_object(
    expr: &ExprEnvelope,
    context: &LoweringContext<'_>,
    constant_bindings: &HashMap<String, LoweredValue>,
) -> Option<LoweredValue> {
    match &expr.kind {
        ExprEnvelopeKind::Identifier(name) => constant_bindings.get(name).cloned(),
        ExprEnvelopeKind::ObjectLiteral(properties) => properties
            .iter()
            .map(|property| {
                Some(LoweredObjectProperty {
                    name: property.name.clone(),
                    value: lower_runtime_constant_callee_object(
                        &property.value,
                        context,
                        constant_bindings,
                    )
                    .or_else(|| {
                        same_compartment_function_ref_initializer(&property.value, context)
                    })?,
                })
            })
            .collect::<Option<Vec<_>>>()
            .map(LoweredValue::Object),
        _ => same_compartment_function_ref_initializer(expr, context),
    }
}

fn same_compartment_function_ref_initializer(
    initializer: &ExprEnvelope,
    context: &LoweringContext<'_>,
) -> Option<LoweredValue> {
    let ExprEnvelopeKind::Identifier(name) = &initializer.kind else {
        return None;
    };
    context
        .get_function(name)
        .map(|_| LoweredValue::FunctionRef(name.clone()))
}

fn same_compartment_constructor_ref_initializer(
    initializer: &ExprEnvelope,
    context: &LoweringContext<'_>,
) -> Option<LoweredValue> {
    let ExprEnvelopeKind::Identifier(name) = &initializer.kind else {
        return None;
    };
    context
        .get_class(name)
        .map(|_| LoweredValue::ClassConstructorRef(name.clone()))
}

fn lower_runtime_constant_arg(
    arg: &ExprEnvelope,
    constant_bindings: &HashMap<String, LoweredValue>,
    runtime_locals: &HashSet<String>,
) -> Option<LoweredValue> {
    match &arg.kind {
        ExprEnvelopeKind::Identifier(name) if !runtime_locals.contains(name) => {
            constant_bindings.get(name).cloned()
        }
        ExprEnvelopeKind::StringLiteral(value) => Some(LoweredValue::String(value.clone())),
        ExprEnvelopeKind::NumberLiteral(value) => Some(LoweredValue::Number(value.clone())),
        ExprEnvelopeKind::BooleanLiteral(value) => Some(LoweredValue::Boolean(*value)),
        _ => None,
    }
}

fn lower_runtime_narrowing_guard(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    guard: &NarrowingGuard,
    constant_bindings: &HashMap<String, LoweredValue>,
    runtime_locals: &HashSet<String>,
    runtime_local_types: &HashMap<String, TypeTerm>,
    stack: &mut Vec<String>,
) -> Option<LoweredRuntimeNarrowingGuard> {
    match guard {
        NarrowingGuard::TypeofEquals { expected, .. } => {
            Some(LoweredRuntimeNarrowingGuard::TypeofEquals {
                expected: expected.clone(),
            })
        }
        NarrowingGuard::Instanceof { constructor, .. } => {
            Some(LoweredRuntimeNarrowingGuard::Instanceof {
                constructor: constructor.clone(),
            })
        }
        NarrowingGuard::OwnProperty { property, .. } => {
            Some(LoweredRuntimeNarrowingGuard::OwnProperty {
                property: property.clone(),
            })
        }
        NarrowingGuard::DynamicOwnProperty { key, .. } => {
            Some(LoweredRuntimeNarrowingGuard::DynamicOwnProperty {
                key: Box::new(lower_runtime_expression(
                    checked,
                    context,
                    all_compartments,
                    key,
                    constant_bindings,
                    runtime_locals,
                    runtime_local_types,
                    stack,
                )?),
            })
        }
        NarrowingGuard::Truthy { .. } => Some(LoweredRuntimeNarrowingGuard::Truthy),
    }
}

fn lower_runtime_cross_compartment_call_expression(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    span: Span,
    callee: &ExprEnvelope,
    args: &[ExprEnvelope],
    constant_bindings: &HashMap<String, LoweredValue>,
) -> Option<LoweredCrossCompartmentCall> {
    let ExprEnvelopeKind::Identifier(callee_name) = &callee.kind else {
        return None;
    };
    let mut candidates = all_compartments
        .iter()
        .copied()
        .filter(|candidate| candidate.name != context.compartment.name)
        .filter_map(|candidate| {
            exported_functions(candidate)
                .into_iter()
                .find(|function| function.name == *callee_name)
                .map(|function| (candidate, function))
        })
        .collect::<Vec<_>>();
    if candidates.len() != 1 {
        return None;
    }
    let (callee_compartment, function) = candidates.pop()?;
    if args.len() != function.params.len() {
        return None;
    }
    let lowered_args = args
        .iter()
        .map(|arg| {
            lower_constant_expression(
                arg,
                constant_bindings,
                &HashSet::new(),
                context,
                &mut Vec::new(),
            )
            .ok()
        })
        .collect::<Option<Vec<_>>>()?;
    let policy_ref = cross_compartment_policy_ref(function, callee_compartment, checked)?;
    let default_policy = checked
        .boundary_facts()
        .default_policy
        .as_ref()
        .map(|default| default.policy.as_str());
    let (policy_id, policy_name) =
        boundary_runtime_call_policy_resolution(checked, &policy_ref, default_policy).ok()?;
    Some(LoweredCrossCompartmentCall {
        callee_name: callee_name.clone(),
        caller_compartment: context.compartment.name.clone(),
        callee_compartment: callee_compartment.name.clone(),
        args: lowered_args,
        policy_id,
        policy_name: policy_name.clone(),
        resolution_chain: boundary_resolution_chain("cross-compartment", &policy_ref, &policy_name),
        span,
    })
}

fn cross_compartment_policy_ref(
    function: &ExportedFunction,
    callee_compartment: &CompartmentDecl,
    checked: &CruftScriptCheckedUnit,
) -> Option<BoundaryPolicyRef> {
    function
        .boundary_clause
        .as_ref()
        .and_then(policy_from_clause)
        .or_else(|| {
            callee_compartment
                .boundary_clause
                .as_ref()
                .and_then(policy_from_clause)
        })
        .or_else(|| {
            checked
                .boundary_facts()
                .default_policy
                .as_ref()
                .map(|_| BoundaryPolicyRef::Default)
        })
}

fn lower_runtime_imported_call_expression(
    checked: &CruftScriptCheckedUnit,
    compartment: &CompartmentDecl,
    span: Span,
    callee: &ExprEnvelope,
    args: &[ExprEnvelope],
) -> Option<LoweredImportedCall> {
    if !args.is_empty() {
        return None;
    }
    let ExprEnvelopeKind::Identifier(imported_name) = &callee.kind else {
        return None;
    };
    let import = find_single_named_import(compartment, imported_name)?;
    let policy = import.boundary_clause.as_ref()?;
    let policy_ref = policy_from_clause(policy)?;
    let default_policy = checked
        .boundary_facts()
        .default_policy
        .as_ref()
        .map(|default| default.policy.as_str());
    let (policy_id, policy_name) =
        boundary_policy_resolution(checked, &policy_ref, default_policy).ok()?;
    Some(LoweredImportedCall {
        imported_name: imported_name.clone(),
        source: import.source.clone(),
        policy_id,
        policy_name: policy_name.clone(),
        resolution_chain: boundary_resolution_chain("import", &policy_ref, &policy_name),
        sanitizer_defaults: sanitizer_defaults_for_policy_name(checked, &policy_name),
        expected_type: None,
        span,
    })
}

fn lower_bounded_element_index(
    expr: &ExprEnvelope,
    locals: &HashMap<String, LoweredValue>,
    _static_index_locals: &HashSet<String>,
    span: Span,
) -> Result<usize, LoweringDiagnostic> {
    let value = match &expr.kind {
        ExprEnvelopeKind::NumberLiteral(value) => LoweredValue::Number(value.clone()),
        ExprEnvelopeKind::Identifier(name) => {
            let Some(value) = locals.get(name).cloned() else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                    span,
                    message: format!(
                        "CruftScript element access lowering cannot resolve index `{name}`"
                    ),
                });
            };
            if !matches!(value, LoweredValue::Number(_)) {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                    span,
                    message: format!(
                        "CruftScript element access lowering requires `{name}` to be a lowered numeric index"
                    ),
                });
            }
            value
        }
        _ => {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                span,
                message: "CruftScript element access lowering requires a lowered numeric index"
                    .to_string(),
            });
        }
    };
    let LoweredValue::Number(index) = value else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: "CruftScript element access lowering requires a lowered numeric index"
                .to_string(),
        });
    };
    if !index.chars().all(|c| c.is_ascii_digit()) {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: format!(
                "CruftScript element access lowering requires a non-negative integral index, got `{index}`"
            ),
        });
    }
    index.parse::<usize>().map_err(|_| LoweringDiagnostic {
        code: LoweringDiagnosticCode::UnsupportedReturnExpression,
        span,
        message: format!("CruftScript element access lowering cannot represent index `{index}`"),
    })
}

fn lower_bounded_property_key(
    expr: &ExprEnvelope,
    locals: &HashMap<String, LoweredValue>,
    _static_index_locals: &HashSet<String>,
    span: Span,
) -> Result<String, LoweringDiagnostic> {
    match &expr.kind {
        ExprEnvelopeKind::StringLiteral(value) => Ok(value.clone()),
        ExprEnvelopeKind::Identifier(name) => match locals.get(name) {
            Some(LoweredValue::String(value)) => Ok(value.clone()),
            Some(_) => Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                span,
                message: format!(
                    "CruftScript object element access lowering requires `{name}` to be a lowered string key"
                ),
            }),
            None => Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                span,
                message: format!(
                    "CruftScript object element access lowering cannot resolve key `{name}`"
                ),
            }),
        },
        _ => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message:
                "CruftScript object element access lowering requires a lowered string key"
                    .to_string(),
        }),
    }
}

fn is_non_negative_integral_number_literal(expr: &ExprEnvelope) -> bool {
    matches!(&expr.kind, ExprEnvelopeKind::NumberLiteral(value) if is_non_negative_integral_number_spelling(value))
}

fn lower_function_value_call_expression(
    span: Span,
    callee: &ExprEnvelope,
    args: &[ExprEnvelope],
    locals: &HashMap<String, LoweredValue>,
    static_index_locals: &HashSet<String>,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<LoweredValue, LoweringDiagnostic> {
    if let Some(value) = lower_constant_builtin_method_call_expression(
        span,
        callee,
        args,
        locals,
        static_index_locals,
        context,
        stack,
    )? {
        return Ok(value);
    }
    if let Some((method_ref, class_decl, method)) =
        class_static_method_for_expr_callee(callee, context)
    {
        return lower_class_method_call_expression(
            span,
            &method_ref,
            class_decl,
            method,
            None,
            args,
            locals,
            static_index_locals,
            context,
            stack,
        );
    }
    let receiver = match &callee.kind {
        ExprEnvelopeKind::PropertyAccess { object, .. } => Some(lower_constant_expression(
            object,
            locals,
            static_index_locals,
            context,
            stack,
        )?),
        _ => None,
    };
    let lowered_callee =
        lower_constant_expression(callee, locals, static_index_locals, context, stack)?;
    let LoweredValue::FunctionRef(name) = lowered_callee else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: unsupported_receiver_or_function_value_callee_message(callee),
        });
    };
    if let Some((class_decl, method)) = context.get_class_method(&name) {
        let Some(receiver) = receiver else {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                span,
                message: format!("CruftScript class method call `{name}` requires a receiver"),
            });
        };
        return lower_class_method_call_expression(
            span,
            &name,
            class_decl,
            method,
            Some(receiver),
            args,
            locals,
            static_index_locals,
            context,
            stack,
        );
    }
    let Some(function) = context.get_function(&name) else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: format!(
                "CruftScript function-valued field call cannot resolve `{name}` as a same-compartment function or class method"
            ),
        });
    };
    let receiver_param = function.params.first().filter(|param| param.name == "this");
    let explicit_params = if receiver_param.is_some() {
        &function.params[1..]
    } else {
        &function.params[..]
    };
    if args.len() != explicit_params.len() {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: format!(
                "CruftScript function-valued field call arity mismatch for `{name}`: expected {} argument(s), got {}",
                explicit_params.len(),
                args.len()
            ),
        });
    }
    let mut bindings = HashMap::new();
    if let Some(param) = receiver_param {
        let Some(receiver) = receiver.clone() else {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                span,
                message: format!(
                    "CruftScript function-valued field call `{name}` requires a receiver for `this`"
                ),
            });
        };
        bindings.insert(param.name.clone(), receiver);
    }
    for (param, arg) in explicit_params.iter().zip(args.iter()) {
        let value = lower_constant_expression(arg, locals, static_index_locals, context, stack)?;
        bindings.insert(param.name.clone(), value);
    }
    let lowered = lower_exported_function_with_bindings(
        context,
        function,
        bindings,
        stack,
        FunctionRefReturnPolicy::RejectRawEscape,
    )?;
    match lowered.body {
        LoweredFunctionBody::Constant(value) => Ok(value),
        LoweredFunctionBody::ImportedCall(_)
        | LoweredFunctionBody::RuntimeExpression(_)
        | LoweredFunctionBody::RuntimeParameterizedExport(_) => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: format!(
                "CruftScript function-valued field call cannot inline non-constant function `{name}`"
            ),
        }),
    }
}

fn lower_constant_builtin_method_call_expression(
    span: Span,
    callee: &ExprEnvelope,
    args: &[ExprEnvelope],
    locals: &HashMap<String, LoweredValue>,
    static_index_locals: &HashSet<String>,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<Option<LoweredValue>, LoweringDiagnostic> {
    let ExprEnvelopeKind::PropertyAccess {
        object, property, ..
    } = &callee.kind
    else {
        return Ok(None);
    };
    if !constant_builtin_method_is_admitted(property) {
        return Ok(None);
    }
    let receiver = lower_constant_expression(object, locals, static_index_locals, context, stack)?;
    let lowered_args = args
        .iter()
        .map(|arg| lower_constant_expression(arg, locals, static_index_locals, context, stack))
        .collect::<Result<Vec<_>, _>>()?;
    match (receiver, property.as_str(), lowered_args.as_slice()) {
        (LoweredValue::String(value), "trim", []) => {
            Ok(Some(LoweredValue::String(value.trim().to_string())))
        }
        (LoweredValue::String(value), "toUpperCase", []) => {
            Ok(Some(LoweredValue::String(value.to_uppercase())))
        }
        (LoweredValue::String(value), "toLowerCase", []) => {
            Ok(Some(LoweredValue::String(value.to_lowercase())))
        }
        (
            LoweredValue::String(value),
            "replace",
            [LoweredValue::String(search), LoweredValue::String(replacement)],
        ) => Ok(Some(LoweredValue::String(
            value.replacen(search, replacement, 1),
        ))),
        (LoweredValue::String(value), "includes", [LoweredValue::String(needle)]) => {
            Ok(Some(LoweredValue::Boolean(value.contains(needle))))
        }
        (LoweredValue::String(value), "startsWith", [LoweredValue::String(needle)]) => {
            Ok(Some(LoweredValue::Boolean(value.starts_with(needle))))
        }
        (LoweredValue::String(value), "endsWith", [LoweredValue::String(needle)]) => {
            Ok(Some(LoweredValue::Boolean(value.ends_with(needle))))
        }
        (LoweredValue::String(value), "indexOf", [LoweredValue::String(needle)]) => {
            let index = value
                .find(needle)
                .map(|index| index.to_string())
                .unwrap_or_else(|| "-1".to_string());
            Ok(Some(LoweredValue::Number(index)))
        }
        (LoweredValue::String(value), "slice", [LoweredValue::Number(start)]) => {
            let start = lower_string_index(start, span, "slice")?;
            Ok(Some(LoweredValue::String(value.chars().skip(start).collect())))
        }
        (
            LoweredValue::String(value),
            "slice",
            [LoweredValue::Number(start), LoweredValue::Number(end)],
        ) => {
            let start = lower_string_index(start, span, "slice")?;
            let end = lower_string_index(end, span, "slice")?;
            Ok(Some(LoweredValue::String(
                value.chars().skip(start).take(end.saturating_sub(start)).collect(),
            )))
        }
        (LoweredValue::Array(elements), "includes", [needle]) => {
            Ok(Some(LoweredValue::Boolean(elements.contains(needle))))
        }
        (LoweredValue::Array(elements), "indexOf", [needle]) => {
            let index = elements
                .iter()
                .position(|element| element == needle)
                .map(|index| index.to_string())
                .unwrap_or_else(|| "-1".to_string());
            Ok(Some(LoweredValue::Number(index)))
        }
        (LoweredValue::Array(elements), "join", [LoweredValue::String(separator)]) => {
            let joined = elements
                .iter()
                .map(LoweredValue::as_stdout)
                .collect::<Vec<_>>()
                .join(separator);
            Ok(Some(LoweredValue::String(joined)))
        }
        (LoweredValue::Array(elements), "slice", [LoweredValue::Number(start)]) => {
            let start = lower_string_index(start, span, "slice")?;
            Ok(Some(LoweredValue::Array(
                elements.into_iter().skip(start).collect(),
            )))
        }
        (
            LoweredValue::Array(elements),
            "slice",
            [LoweredValue::Number(start), LoweredValue::Number(end)],
        ) => {
            let start = lower_string_index(start, span, "slice")?;
            let end = lower_string_index(end, span, "slice")?;
            Ok(Some(LoweredValue::Array(
                elements
                    .into_iter()
                    .skip(start)
                    .take(end.saturating_sub(start))
                    .collect(),
            )))
        }
        (LoweredValue::Array(_), _, _) | (LoweredValue::String(_), _, _) => {
            Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                span,
                message: format!(
                    "CruftScript constant builtin method lowering does not admit `{property}` for this receiver and argument shape"
                ),
            })
        }
        _ => Ok(None),
    }
}

fn constant_builtin_method_is_admitted(property: &str) -> bool {
    matches!(
        property,
        "trim"
            | "toUpperCase"
            | "toLowerCase"
            | "replace"
            | "includes"
            | "startsWith"
            | "endsWith"
            | "indexOf"
            | "join"
            | "slice"
    )
}

fn lower_string_index(value: &str, span: Span, method: &str) -> Result<usize, LoweringDiagnostic> {
    if !value.chars().all(|c| c.is_ascii_digit()) {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: format!(
                "CruftScript string `{method}` lowering requires a non-negative integral index"
            ),
        });
    }
    value.parse::<usize>().map_err(|_| LoweringDiagnostic {
        code: LoweringDiagnosticCode::UnsupportedReturnExpression,
        span,
        message: format!("CruftScript string `{method}` lowering cannot represent index `{value}`"),
    })
}

fn class_static_method_for_expr_callee<'a>(
    callee: &ExprEnvelope,
    context: &'a LoweringContext<'a>,
) -> Option<(String, &'a ClassDecl, &'a ClassMethodDecl)> {
    let ExprEnvelopeKind::PropertyAccess {
        object,
        property,
        optional: false,
    } = &callee.kind
    else {
        return None;
    };
    let ExprEnvelopeKind::Identifier(class_name) = &object.kind else {
        return None;
    };
    let method_ref = class_static_method_ref_name(class_name, property);
    let (class_decl, method) = context.get_class_static_method(&method_ref)?;
    Some((method_ref, class_decl, method))
}

fn lower_class_method_call_expression(
    span: Span,
    method_ref: &str,
    class_decl: &ClassDecl,
    method: &ClassMethodDecl,
    receiver: Option<LoweredValue>,
    args: &[ExprEnvelope],
    locals: &HashMap<String, LoweredValue>,
    static_index_locals: &HashSet<String>,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<LoweredValue, LoweringDiagnostic> {
    if stack.iter().any(|name| name == method_ref) {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span: method.span,
            message: format!(
                "CruftScript class method lowering rejects recursive/cyclic call graph at `{method_ref}`"
            ),
        });
    }
    if args.len() != method.params.len() {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: format!(
                "CruftScript class method call arity mismatch for `{method_ref}`: expected {} argument(s), got {}",
                method.params.len(),
                args.len()
            ),
        });
    }
    let Some((last, prefix)) = method.body.statements.split_last() else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span: method.body.span,
            message: format!("CruftScript class method `{method_ref}` requires a return statement"),
        });
    };
    let (
        prefix,
        if_return_tail,
        branch_prefix_tail,
        optional_branch_prefix_tail,
        final_argument,
        final_if_else,
        final_switch,
        terminal_span,
    ) = match last {
        BodyStmt::Return(ret) => {
            let (prefix, if_return_tail, branch_prefix_tail, optional_branch_prefix_tail) =
                match prefix.split_last() {
                    Some((BodyStmt::If(if_stmt), rest)) if if_stmt.else_body.is_none() => {
                        match if_stmt.then_body.statements.split_last() {
                            Some((BodyStmt::Return(_), _)) => (rest, Some(if_stmt), None, None),
                            _ => (rest, None, None, Some(if_stmt)),
                        }
                    }
                    Some((BodyStmt::If(if_stmt), rest)) if if_stmt.else_body.is_some() => {
                        (rest, None, Some(if_stmt), None)
                    }
                    _ => (prefix, None, None, None),
                };
            let Some(argument) = &ret.argument else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: ret.span,
                    message: format!("CruftScript class method `{method_ref}` must return a value"),
                });
            };
            (
                prefix,
                if_return_tail,
                branch_prefix_tail,
                optional_branch_prefix_tail,
                Some(argument),
                None,
                None,
                argument.span,
            )
        }
        BodyStmt::If(if_stmt) if if_stmt.else_body.is_some() => (
            prefix,
            None,
            None,
            None,
            None,
            Some(if_stmt),
            None,
            if_stmt.span,
        ),
        BodyStmt::Switch(switch_stmt) => (
            prefix,
            None,
            None,
            None,
            None,
            None,
            Some(switch_stmt),
            switch_stmt.span,
        ),
        _ => {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedBodyShape,
                span: last.span(),
                message: format!(
                    "CruftScript class method `{method_ref}` requires a final return or bounded if/else return"
                ),
            });
        }
    };

    stack.push(method_ref.to_string());
    let result = (|| {
        let mut bindings = HashMap::new();
        let mut method_static_index_locals = HashSet::new();
        if let Some(receiver) = receiver {
            bindings.insert("this".to_string(), receiver);
        }
        for (param, arg) in method.params.iter().zip(args.iter()) {
            let value =
                lower_constant_expression(arg, locals, static_index_locals, context, stack)?;
            bindings.insert(param.name.clone(), value);
        }
        if let Some(result) = lower_class_method_statement_sequence_inner(
            prefix,
            &mut bindings,
            &mut method_static_index_locals,
            method_ref,
            context,
            stack,
        )? {
            return Ok(result);
        }
        if let Some(if_stmt) = if_return_tail {
            let Some((BodyStmt::Return(then_return), then_prefix)) =
                if_stmt.then_body.statements.split_last()
            else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: if_stmt.span,
                    message: format!(
                        "CruftScript class method `{method_ref}` supports only a single return in a bounded if branch"
                    ),
                });
            };
            let Some(then_argument) = &then_return.argument else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: then_return.span,
                    message: format!(
                        "CruftScript class method `{method_ref}` bounded if branch must return a value"
                    ),
                });
            };
            let choose_then = evaluate_lowered_narrowing_guard(
                &if_stmt.subject,
                &if_stmt.guard,
                &bindings,
                &method_static_index_locals,
                context,
                stack,
            )?;
            let Some(argument) = final_argument else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: method.body.span,
                    message: format!(
                        "CruftScript class method `{method_ref}` bounded if branch requires a final return fallback"
                    ),
                });
            };
            let selected = if choose_then { then_argument } else { argument };
            let mut selected_bindings = bindings.clone();
            let mut selected_static_index_locals = method_static_index_locals.clone();
            if choose_then {
                lower_class_method_statement_sequence(
                    then_prefix,
                    Some(selected),
                    &mut selected_bindings,
                    &mut selected_static_index_locals,
                    method_ref,
                    context,
                    stack,
                )
            } else {
                lower_constant_expression(
                    selected,
                    &selected_bindings,
                    &selected_static_index_locals,
                    context,
                    stack,
                )
            }
        } else if let Some(if_stmt) = branch_prefix_tail {
            let choose_then = evaluate_lowered_narrowing_guard(
                &if_stmt.subject,
                &if_stmt.guard,
                &bindings,
                &method_static_index_locals,
                context,
                stack,
            )?;
            let Some(else_body) = &if_stmt.else_body else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: if_stmt.span,
                    message: format!(
                        "CruftScript class method `{method_ref}` bounded branch prefix requires an else branch"
                    ),
                });
            };
            let Some(argument) = final_argument else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: method.body.span,
                    message: format!(
                        "CruftScript class method `{method_ref}` bounded branch prefix requires a final return"
                    ),
                });
            };
            let selected_prefix = if choose_then {
                if_stmt.then_body.statements.as_slice()
            } else {
                else_body.statements.as_slice()
            };
            let mut selected_bindings = bindings.clone();
            let mut selected_static_index_locals = method_static_index_locals.clone();
            lower_class_method_statement_sequence(
                selected_prefix,
                Some(argument),
                &mut selected_bindings,
                &mut selected_static_index_locals,
                method_ref,
                context,
                stack,
            )
        } else if let Some(if_stmt) = optional_branch_prefix_tail {
            let choose_then = evaluate_lowered_narrowing_guard(
                &if_stmt.subject,
                &if_stmt.guard,
                &bindings,
                &method_static_index_locals,
                context,
                stack,
            )?;
            let mut selected_bindings = bindings.clone();
            let mut selected_static_index_locals = method_static_index_locals.clone();
            let Some(argument) = final_argument else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: method.body.span,
                    message: format!(
                        "CruftScript class method `{method_ref}` bounded optional branch prefix requires a final return"
                    ),
                });
            };
            if choose_then {
                lower_class_method_statement_sequence(
                    &if_stmt.then_body.statements,
                    Some(argument),
                    &mut selected_bindings,
                    &mut selected_static_index_locals,
                    method_ref,
                    context,
                    stack,
                )
            } else {
                lower_constant_expression(
                    argument,
                    &selected_bindings,
                    &selected_static_index_locals,
                    context,
                    stack,
                )
            }
        } else if let Some(if_stmt) = final_if_else {
            let Some((BodyStmt::Return(then_return), then_prefix)) =
                if_stmt.then_body.statements.split_last()
            else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: if_stmt.span,
                    message: format!(
                        "CruftScript class method `{method_ref}` bounded if/else then branch supports only a single return"
                    ),
                });
            };
            let Some(else_body) = &if_stmt.else_body else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: if_stmt.span,
                    message: format!(
                        "CruftScript class method `{method_ref}` bounded if/else requires an else branch"
                    ),
                });
            };
            let Some((BodyStmt::Return(else_return), else_prefix)) =
                else_body.statements.split_last()
            else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: else_body.span,
                    message: format!(
                        "CruftScript class method `{method_ref}` bounded if/else else branch supports only a single return"
                    ),
                });
            };
            let Some(then_argument) = &then_return.argument else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: then_return.span,
                    message: format!(
                        "CruftScript class method `{method_ref}` bounded if/else then branch must return a value"
                    ),
                });
            };
            let Some(else_argument) = &else_return.argument else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: else_return.span,
                    message: format!(
                        "CruftScript class method `{method_ref}` bounded if/else else branch must return a value"
                    ),
                });
            };
            let choose_then = evaluate_lowered_narrowing_guard(
                &if_stmt.subject,
                &if_stmt.guard,
                &bindings,
                &method_static_index_locals,
                context,
                stack,
            )?;
            let selected = if choose_then {
                then_argument
            } else {
                else_argument
            };
            let selected_prefix = if choose_then {
                then_prefix
            } else {
                else_prefix
            };
            let mut selected_bindings = bindings.clone();
            let mut selected_static_index_locals = method_static_index_locals.clone();
            lower_class_method_statement_sequence(
                selected_prefix,
                Some(selected),
                &mut selected_bindings,
                &mut selected_static_index_locals,
                method_ref,
                context,
                stack,
            )
        } else if let Some(switch_stmt) = final_switch {
            lower_class_method_switch_statement(
                switch_stmt,
                &mut bindings,
                &mut method_static_index_locals,
                method_ref,
                context,
                stack,
            )
        } else {
            let Some(argument) = final_argument else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: method.body.span,
                    message: format!("CruftScript class method `{method_ref}` requires a return"),
                });
            };
            lower_constant_expression(
                argument,
                &bindings,
                &method_static_index_locals,
                context,
                stack,
            )
        }
    })();
    stack.pop();
    let result = result?;
    if let Some(return_type) = &method.return_type {
        let mut diagnostics = Vec::new();
        let raw_expected = lower_type_term(return_type);
        let expected = AliasExpansionContext::new(context.type_environment)
            .expand_for_assignability(&raw_expected, &mut diagnostics);
        let matches_return = if matches!(expected, TypeTerm::TypePredicate { .. }) {
            matches!(result, LoweredValue::Boolean(_))
        } else if let TypeTerm::Named { name, .. } = &raw_expected {
            context.get_class(name).is_some_and(|expected_class| {
                lowered_value_matches_class_instance(&result, expected_class)
            }) || lowered_value_matches_type(&result, &expected)
        } else {
            lowered_value_matches_type(&result, &expected)
        };
        if !matches_return {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                span: terminal_span,
                message: format!(
                    "CruftScript class method `{method_ref}` returned value that does not match declared return type"
                ),
            });
        }
    }
    let class_instance_return = match method.return_type.as_ref().map(lower_type_term) {
        Some(TypeTerm::Named { name, .. }) => context.get_class(&name).is_some(),
        _ => false,
    };
    if !class_instance_return && lowered_value_contains_function_ref(&result) {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span: terminal_span,
            message: format!(
                "CruftScript class method `{}`.{} may call method refs but cannot return method authority",
                class_decl.name, method.name
            ),
        });
    }
    Ok(result)
}

fn lower_class_method_statement_sequence(
    statements: &[BodyStmt],
    fallback_return: Option<&ExprEnvelope>,
    bindings: &mut HashMap<String, LoweredValue>,
    static_index_locals: &mut HashSet<String>,
    method_ref: &str,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<LoweredValue, LoweringDiagnostic> {
    match lower_class_method_statement_sequence_inner(
        statements,
        bindings,
        static_index_locals,
        method_ref,
        context,
        stack,
    )? {
        Some(result) => Ok(result),
        None => {
            let Some(argument) = fallback_return else {
                let span = statements
                    .last()
                    .map(BodyStmt::span)
                    .or_else(|| fallback_return.map(|expr| expr.span))
                    .unwrap_or(Span { start: 0, end: 0 });
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span,
                    message: format!(
                        "CruftScript class method `{method_ref}` bounded nested branch requires a return"
                    ),
                });
            };
            lower_constant_expression(argument, bindings, static_index_locals, context, stack)
        }
    }
}

fn lower_class_method_statement_sequence_inner(
    statements: &[BodyStmt],
    bindings: &mut HashMap<String, LoweredValue>,
    static_index_locals: &mut HashSet<String>,
    method_ref: &str,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<Option<LoweredValue>, LoweringDiagnostic> {
    let Some((first, rest)) = statements.split_first() else {
        return Ok(None);
    };
    match first {
        BodyStmt::Return(ret) => {
            let Some(argument) = &ret.argument else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: ret.span,
                    message: format!(
                        "CruftScript class method `{method_ref}` bounded nested branch must return a value"
                    ),
                });
            };
            lower_constant_expression(argument, bindings, static_index_locals, context, stack)
                .map(Some)
        }
        BodyStmt::LocalDecl(_) | BodyStmt::Assignment(_) => {
            lower_class_method_prefix_statements(
                std::slice::from_ref(first),
                bindings,
                static_index_locals,
                method_ref,
                context,
                stack,
            )?;
            lower_class_method_statement_sequence_inner(
                rest,
                bindings,
                static_index_locals,
                method_ref,
                context,
                stack,
            )
        }
        BodyStmt::While(while_stmt) => {
            if let Some(result) = lower_class_method_bounded_while(
                while_stmt,
                bindings,
                static_index_locals,
                method_ref,
                context,
                stack,
            )? {
                return Ok(Some(result));
            }
            lower_class_method_statement_sequence_inner(
                rest,
                bindings,
                static_index_locals,
                method_ref,
                context,
                stack,
            )
        }
        BodyStmt::For(for_stmt) => {
            if let Some(result) = lower_class_method_bounded_for(
                for_stmt,
                bindings,
                static_index_locals,
                method_ref,
                context,
                stack,
            )? {
                return Ok(Some(result));
            }
            lower_class_method_statement_sequence_inner(
                rest,
                bindings,
                static_index_locals,
                method_ref,
                context,
                stack,
            )
        }
        BodyStmt::DoWhile(do_while_stmt) => {
            if let Some(result) = lower_class_method_bounded_do_while(
                do_while_stmt,
                bindings,
                static_index_locals,
                method_ref,
                context,
                stack,
            )? {
                return Ok(Some(result));
            }
            lower_class_method_statement_sequence_inner(
                rest,
                bindings,
                static_index_locals,
                method_ref,
                context,
                stack,
            )
        }
        BodyStmt::If(if_stmt) => {
            let choose_then = evaluate_lowered_narrowing_guard(
                &if_stmt.subject,
                &if_stmt.guard,
                bindings,
                static_index_locals,
                context,
                stack,
            )?;
            if choose_then {
                let mut then_bindings = bindings.clone();
                let mut then_static_index_locals = static_index_locals.clone();
                if let Some(result) = lower_class_method_statement_sequence_inner(
                    &if_stmt.then_body.statements,
                    &mut then_bindings,
                    &mut then_static_index_locals,
                    method_ref,
                    context,
                    stack,
                )? {
                    Ok(Some(result))
                } else {
                    lower_class_method_statement_sequence_inner(
                        rest,
                        bindings,
                        static_index_locals,
                        method_ref,
                        context,
                        stack,
                    )
                }
            } else if let Some(else_body) = &if_stmt.else_body {
                let mut else_bindings = bindings.clone();
                let mut else_static_index_locals = static_index_locals.clone();
                if let Some(result) = lower_class_method_statement_sequence_inner(
                    &else_body.statements,
                    &mut else_bindings,
                    &mut else_static_index_locals,
                    method_ref,
                    context,
                    stack,
                )? {
                    Ok(Some(result))
                } else {
                    lower_class_method_statement_sequence_inner(
                        rest,
                        bindings,
                        static_index_locals,
                        method_ref,
                        context,
                        stack,
                    )
                }
            } else {
                lower_class_method_statement_sequence_inner(
                    rest,
                    bindings,
                    static_index_locals,
                    method_ref,
                    context,
                    stack,
                )
            }
        }
        BodyStmt::Switch(switch_stmt) => lower_class_method_switch_statement(
            switch_stmt,
            bindings,
            static_index_locals,
            method_ref,
            context,
            stack,
        )
        .map(Some),
        _ => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span: first.span(),
            message: format!(
                "CruftScript class method `{method_ref}` supports only bounded nested if branches, local declarations, bounded assignments, and returns"
            ),
        }),
    }
}

fn lower_class_method_bounded_while(
    while_stmt: &cruftscript_parser::WhileStmt,
    bindings: &mut HashMap<String, LoweredValue>,
    static_index_locals: &mut HashSet<String>,
    method_ref: &str,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<Option<LoweredValue>, LoweringDiagnostic> {
    for iteration in 0..1024 {
        if !evaluate_lowered_narrowing_guard(
            &while_stmt.subject,
            &while_stmt.guard,
            bindings,
            static_index_locals,
            context,
            stack,
        )? {
            return Ok(None);
        }
        if let Some(result) = lower_class_method_loop_body_statements(
            &while_stmt.body.statements,
            bindings,
            static_index_locals,
            method_ref,
            context,
            stack,
        )? {
            return Ok(Some(result));
        }
        if iteration == 1023 {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedBodyShape,
                span: while_stmt.span,
                message: format!(
                    "CruftScript class method `{method_ref}` bounded while exceeded 1024 iterations"
                ),
            });
        }
    }
    Ok(None)
}

fn lower_class_method_bounded_for(
    for_stmt: &cruftscript_parser::ForStmt,
    bindings: &mut HashMap<String, LoweredValue>,
    static_index_locals: &mut HashSet<String>,
    method_ref: &str,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<Option<LoweredValue>, LoweringDiagnostic> {
    if let Some(initializer) = &for_stmt.initializer {
        match initializer {
            cruftscript_parser::ForInitializer::LocalDecl(local) => {
                lower_class_method_prefix_statements(
                    &[BodyStmt::LocalDecl(local.clone())],
                    bindings,
                    static_index_locals,
                    method_ref,
                    context,
                    stack,
                )?;
            }
            cruftscript_parser::ForInitializer::Assignment(assignment) => {
                lower_class_method_prefix_statements(
                    &[BodyStmt::Assignment(assignment.clone())],
                    bindings,
                    static_index_locals,
                    method_ref,
                    context,
                    stack,
                )?;
            }
            cruftscript_parser::ForInitializer::Update(update) => {
                let _ = lower_update_stmt(update, bindings, static_index_locals)?;
            }
        }
    }

    for iteration in 0..1024 {
        if !evaluate_lowered_narrowing_guard(
            &for_stmt.subject,
            &for_stmt.guard,
            bindings,
            static_index_locals,
            context,
            stack,
        )? {
            return Ok(None);
        }
        if let Some(result) = lower_class_method_loop_body_statements(
            &for_stmt.body.statements,
            bindings,
            static_index_locals,
            method_ref,
            context,
            stack,
        )? {
            return Ok(Some(result));
        }
        if let Some(update) = &for_stmt.update {
            match update {
                cruftscript_parser::ForUpdate::Assignment(assignment) => {
                    lower_class_method_prefix_statements(
                        &[BodyStmt::Assignment(assignment.clone())],
                        bindings,
                        static_index_locals,
                        method_ref,
                        context,
                        stack,
                    )?;
                }
                cruftscript_parser::ForUpdate::Update(update) => {
                    let _ = lower_update_stmt(update, bindings, static_index_locals)?;
                }
            }
        }
        if iteration == 1023 {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedBodyShape,
                span: for_stmt.span,
                message: format!(
                    "CruftScript class method `{method_ref}` bounded for exceeded 1024 iterations"
                ),
            });
        }
    }
    Ok(None)
}

fn lower_class_method_bounded_do_while(
    do_while_stmt: &cruftscript_parser::DoWhileStmt,
    bindings: &mut HashMap<String, LoweredValue>,
    static_index_locals: &mut HashSet<String>,
    method_ref: &str,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<Option<LoweredValue>, LoweringDiagnostic> {
    for iteration in 0..1024 {
        if let Some(result) = lower_class_method_loop_body_statements(
            &do_while_stmt.body.statements,
            bindings,
            static_index_locals,
            method_ref,
            context,
            stack,
        )? {
            return Ok(Some(result));
        }
        if !evaluate_lowered_narrowing_guard(
            &do_while_stmt.subject,
            &do_while_stmt.guard,
            bindings,
            static_index_locals,
            context,
            stack,
        )? {
            return Ok(None);
        }
        if iteration == 1023 {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedBodyShape,
                span: do_while_stmt.span,
                message: format!(
                    "CruftScript class method `{method_ref}` bounded do while exceeded 1024 iterations"
                ),
            });
        }
    }
    Ok(None)
}

fn lower_class_method_loop_body_statements(
    statements: &[BodyStmt],
    bindings: &mut HashMap<String, LoweredValue>,
    static_index_locals: &mut HashSet<String>,
    method_ref: &str,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<Option<LoweredValue>, LoweringDiagnostic> {
    for statement in statements {
        match statement {
            BodyStmt::Return(ret) => {
                let Some(argument) = &ret.argument else {
                    return Err(LoweringDiagnostic {
                        code: LoweringDiagnosticCode::UnsupportedBodyShape,
                        span: ret.span,
                        message: format!(
                            "CruftScript class method `{method_ref}` bounded loop return must return a value"
                        ),
                    });
                };
                return lower_constant_expression(
                    argument,
                    bindings,
                    static_index_locals,
                    context,
                    stack,
                )
                .map(Some);
            }
            BodyStmt::LocalDecl(_) | BodyStmt::Assignment(_) => {
                lower_class_method_prefix_statements(
                    std::slice::from_ref(statement),
                    bindings,
                    static_index_locals,
                    method_ref,
                    context,
                    stack,
                )?;
            }
            BodyStmt::Update(update) => {
                let _ = lower_update_stmt(update, bindings, static_index_locals)?;
            }
            BodyStmt::If(if_stmt) => {
                if let Some(result) = lower_class_method_loop_if_statement(
                    if_stmt,
                    bindings,
                    static_index_locals,
                    method_ref,
                    context,
                    stack,
                )? {
                    return Ok(Some(result));
                }
            }
            BodyStmt::While(while_stmt) => {
                if let Some(result) = lower_class_method_bounded_while(
                    while_stmt,
                    bindings,
                    static_index_locals,
                    method_ref,
                    context,
                    stack,
                )? {
                    return Ok(Some(result));
                }
            }
            BodyStmt::For(for_stmt) => {
                if let Some(result) = lower_class_method_bounded_for(
                    for_stmt,
                    bindings,
                    static_index_locals,
                    method_ref,
                    context,
                    stack,
                )? {
                    return Ok(Some(result));
                }
            }
            BodyStmt::DoWhile(do_while_stmt) => {
                if let Some(result) = lower_class_method_bounded_do_while(
                    do_while_stmt,
                    bindings,
                    static_index_locals,
                    method_ref,
                    context,
                    stack,
                )? {
                    return Ok(Some(result));
                }
            }
            _ => {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: statement.span(),
                    message: format!(
                        "CruftScript class method `{method_ref}` bounded loop supports only local declarations, bounded assignments, numeric updates, bounded nested if bodies, and bounded nested loops"
                    ),
                });
            }
        }
    }
    Ok(None)
}

fn lower_class_method_loop_if_statement(
    if_stmt: &cruftscript_parser::IfStmt,
    bindings: &mut HashMap<String, LoweredValue>,
    static_index_locals: &mut HashSet<String>,
    method_ref: &str,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<Option<LoweredValue>, LoweringDiagnostic> {
    let choose_then = evaluate_lowered_narrowing_guard(
        &if_stmt.subject,
        &if_stmt.guard,
        bindings,
        static_index_locals,
        context,
        stack,
    )?;
    if choose_then {
        lower_class_method_loop_body_statements(
            &if_stmt.then_body.statements,
            bindings,
            static_index_locals,
            method_ref,
            context,
            stack,
        )
    } else if let Some(else_body) = &if_stmt.else_body {
        lower_class_method_loop_body_statements(
            &else_body.statements,
            bindings,
            static_index_locals,
            method_ref,
            context,
            stack,
        )
    } else {
        Ok(None)
    }
}

fn lower_class_method_switch_statement(
    switch_stmt: &cruftscript_parser::SwitchStmt,
    bindings: &mut HashMap<String, LoweredValue>,
    static_index_locals: &mut HashSet<String>,
    method_ref: &str,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<LoweredValue, LoweringDiagnostic> {
    let subject = lower_constant_expression(
        &switch_stmt.subject,
        bindings,
        static_index_locals,
        context,
        stack,
    )?;
    for (index, case) in switch_stmt.cases.iter().enumerate() {
        let test =
            lower_constant_expression(&case.test, bindings, static_index_locals, context, stack)?;
        if !matches!(
            &test,
            LoweredValue::String(_) | LoweredValue::Number(_) | LoweredValue::Boolean(_)
        ) {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedBodyShape,
                span: case.test.span,
                message: format!(
                    "CruftScript class method `{method_ref}` bounded switch case labels must lower to primitive values"
                ),
            });
        }
        if subject == test {
            let mut case_bindings = bindings.clone();
            let mut case_static_index_locals = static_index_locals.clone();
            for fallthrough_case in switch_stmt.cases[index..].iter() {
                if let Some(result) = lower_class_method_statement_sequence_inner(
                    &fallthrough_case.body.statements,
                    &mut case_bindings,
                    &mut case_static_index_locals,
                    method_ref,
                    context,
                    stack,
                )? {
                    return Ok(result);
                }
            }
            let Some(default) = &switch_stmt.default else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: switch_stmt.span,
                    message: format!(
                        "CruftScript class method `{method_ref}` bounded switch requires a default return"
                    ),
                });
            };
            return lower_class_method_statement_sequence(
                &default.statements,
                None,
                &mut case_bindings,
                &mut case_static_index_locals,
                method_ref,
                context,
                stack,
            );
        }
    }
    let Some(default) = &switch_stmt.default else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedBodyShape,
            span: switch_stmt.span,
            message: format!(
                "CruftScript class method `{method_ref}` bounded switch requires a default return"
            ),
        });
    };
    let mut default_bindings = bindings.clone();
    let mut default_static_index_locals = static_index_locals.clone();
    lower_class_method_statement_sequence(
        &default.statements,
        None,
        &mut default_bindings,
        &mut default_static_index_locals,
        method_ref,
        context,
        stack,
    )
}

fn lowered_value_matches_class_instance(value: &LoweredValue, class_decl: &ClassDecl) -> bool {
    let LoweredValue::Object(properties) = value else {
        return false;
    };
    class_decl.fields.iter().all(|field| {
        properties
            .iter()
            .find(|property| property.name == field.name)
            .is_some_and(|property| {
                lowered_value_matches_type(&property.value, &lower_type_term(&field.ty))
            })
    }) && class_decl.methods.iter().all(|method| {
        let expected = class_method_ref_name(&class_decl.name, &method.name);
        properties.iter().any(|property| {
            property.name == method.name
                && matches!(&property.value, LoweredValue::FunctionRef(name) if name == &expected)
        })
    })
}

fn lower_class_method_prefix_statements(
    statements: &[BodyStmt],
    bindings: &mut HashMap<String, LoweredValue>,
    static_index_locals: &mut HashSet<String>,
    method_ref: &str,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<(), LoweringDiagnostic> {
    for statement in statements {
        match statement {
            BodyStmt::LocalDecl(local) => {
                let Some(initializer) = &local.initializer else {
                    return Err(LoweringDiagnostic {
                        code: LoweringDiagnosticCode::UnsupportedBodyShape,
                        span: local.span,
                        message: format!(
                            "CruftScript class method `{method_ref}` requires local `{}` to have a lowerable initializer",
                            local.name
                        ),
                    });
                };
                let value = lower_constant_expression(
                    initializer,
                    bindings,
                    static_index_locals,
                    context,
                    stack,
                )?;
                if is_non_negative_integral_number_literal(initializer) {
                    static_index_locals.insert(local.name.clone());
                } else {
                    static_index_locals.remove(&local.name);
                }
                bindings.insert(local.name.clone(), value);
            }
            BodyStmt::Assignment(assignment) => {
                lower_prefix_assignment(assignment, bindings, static_index_locals, context, stack)?;
            }
            BodyStmt::Update(update) => {
                let _ = lower_update_stmt(update, bindings, static_index_locals)?;
            }
            BodyStmt::While(while_stmt) => {
                lower_class_method_bounded_while(
                    while_stmt,
                    bindings,
                    static_index_locals,
                    method_ref,
                    context,
                    stack,
                )?;
            }
            BodyStmt::For(for_stmt) => {
                lower_class_method_bounded_for(
                    for_stmt,
                    bindings,
                    static_index_locals,
                    method_ref,
                    context,
                    stack,
                )?;
            }
            BodyStmt::DoWhile(do_while_stmt) => {
                lower_class_method_bounded_do_while(
                    do_while_stmt,
                    bindings,
                    static_index_locals,
                    method_ref,
                    context,
                    stack,
                )?;
            }
            _ => {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedBodyShape,
                    span: statement.span(),
                    message: format!(
                        "CruftScript class method `{method_ref}` supports only local declarations, bounded assignments, numeric updates, and bounded while loops before the terminal return"
                    ),
                });
            }
        }
    }
    Ok(())
}

fn lower_same_compartment_call_expression(
    span: Span,
    callee: &ExprEnvelope,
    args: &[ExprEnvelope],
    optional: bool,
    locals: &HashMap<String, LoweredValue>,
    static_index_locals: &HashSet<String>,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<LoweredValue, LoweringDiagnostic> {
    let ExprEnvelopeKind::Identifier(name) = &callee.kind else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: unsupported_receiver_or_function_value_callee_message(callee),
        });
    };
    let function = match context.get_function(name) {
        Some(function) => function,
        None if optional => {
            return lower_optional_local_direct_call(
                span,
                name,
                args,
                locals,
                static_index_locals,
                context,
                stack,
            );
        }
        None => {
            if let Some(LoweredValue::FunctionRef(function_name)) = locals.get(name) {
                let Some(function) = context.get_function(function_name) else {
                    return Err(LoweringDiagnostic {
                        code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                        span,
                        message: format!(
                            "CruftScript local function-value call cannot resolve `{name}` function ref `{function_name}`"
                        ),
                    });
                };
                return inline_same_compartment_function_call(
                    span,
                    function_name,
                    function,
                    args,
                    locals,
                    static_index_locals,
                    context,
                    stack,
                    "local function-value call",
                );
            }
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                span,
                message: format!(
                    "CruftScript same-compartment call lowering cannot resolve `{name}` as a known exported function or lowered function ref"
                ),
            });
        }
    };
    inline_same_compartment_function_call(
        span,
        name,
        function,
        args,
        locals,
        static_index_locals,
        context,
        stack,
        "same-compartment call",
    )
}

fn lower_optional_local_direct_call(
    span: Span,
    name: &str,
    args: &[ExprEnvelope],
    locals: &HashMap<String, LoweredValue>,
    static_index_locals: &HashSet<String>,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
) -> Result<LoweredValue, LoweringDiagnostic> {
    let Some(value) = locals.get(name) else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: format!(
                "CruftScript optional direct call cannot resolve `{name}` as a same-compartment function or lowered local"
            ),
        });
    };
    match value {
        LoweredValue::Undefined => Ok(LoweredValue::Undefined),
        LoweredValue::FunctionRef(function_name) => {
            let Some(function) = context.get_function(function_name) else {
                return Err(LoweringDiagnostic {
                    code: LoweringDiagnosticCode::UnsupportedReturnExpression,
                    span,
                    message: format!(
                        "CruftScript optional direct call cannot resolve local `{name}` function ref `{function_name}`"
                    ),
                });
            };
            inline_same_compartment_function_call(
                span,
                function_name,
                function,
                args,
                locals,
                static_index_locals,
                context,
                stack,
                "optional local function-value call",
            )
        }
        _ => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: unsupported_function_value_call_message(name, value),
        }),
    }
}

fn inline_same_compartment_function_call(
    span: Span,
    name: &str,
    function: &ExportedFunction,
    args: &[ExprEnvelope],
    locals: &HashMap<String, LoweredValue>,
    static_index_locals: &HashSet<String>,
    context: &LoweringContext<'_>,
    stack: &mut Vec<String>,
    call_kind: &str,
) -> Result<LoweredValue, LoweringDiagnostic> {
    if args.len() != function.params.len() {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: format!(
                "CruftScript {call_kind} lowering arity mismatch for `{name}`: expected {} argument(s), got {}",
                function.params.len(),
                args.len()
            ),
        });
    }
    let mut bindings = HashMap::new();
    for (param, arg) in function.params.iter().zip(args.iter()) {
        let value = lower_constant_expression(arg, locals, static_index_locals, context, stack)?;
        bindings.insert(param.name.clone(), value);
    }
    let lowered = lower_exported_function_with_bindings(
        context,
        function,
        bindings,
        stack,
        FunctionRefReturnPolicy::RejectRawEscape,
    )?;
    match lowered.body {
        LoweredFunctionBody::Constant(value) => Ok(value),
        LoweredFunctionBody::ImportedCall(_)
        | LoweredFunctionBody::RuntimeExpression(_)
        | LoweredFunctionBody::RuntimeParameterizedExport(_) => Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span,
            message: format!(
                "CruftScript {call_kind} lowering cannot inline import-edge function `{name}`"
            ),
        }),
    }
}

fn unsupported_receiver_or_function_value_callee_message(callee: &ExprEnvelope) -> String {
    match &callee.kind {
        ExprEnvelopeKind::PropertyAccess { property, .. } => format!(
            "CruftScript receiver/property call cannot call `{property}` without a statically proven function-valued field; dynamic or exotic callable dispatch is not represented"
        ),
        ExprEnvelopeKind::ElementAccess { .. } => {
            "CruftScript element-result call requires a statically proven function-valued indexed field; dynamic or exotic callable dispatch is not represented".to_string()
        }
        _ => {
            "CruftScript call lowering supports only statically proven same-compartment function values; dynamic or exotic callable dispatch is not represented".to_string()
        }
    }
}

fn unsupported_function_value_call_message(name: &str, value: &LoweredValue) -> String {
    match value {
        LoweredValue::Undefined => format!(
            "CruftScript optional direct call short-circuits nullish/undefined `{name}` only when it is a lowered local"
        ),
        _ => format!(
            "CruftScript optional direct call cannot invoke runtime parameter `{name}` as a callback; runtime callback authority and reentrancy substrate is not yet represented"
        ),
    }
}

fn lower_exported_function_for_module(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    function: &ExportedFunction,
) -> Result<LoweredFunction, LoweringDiagnostic> {
    if !function.params.is_empty() {
        return lower_runtime_parameterized_export(checked, context.compartment, function);
    }
    if !function.type_params.is_empty() {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedFunctionShape,
            span: function.span,
            message: format!(
                "CruftScript runtime export `{}` cannot monomorphize generic parameters without runtime arguments",
                function.name
            ),
        });
    }
    match lower_exported_function_with_bindings(
        context,
        function,
        HashMap::new(),
        &mut Vec::new(),
        FunctionRefReturnPolicy::AllowBoundaryWrappedExport,
    ) {
        Ok(lowered) => Ok(lowered),
        Err(diagnostic)
            if matches!(
                diagnostic.code,
                LoweringDiagnosticCode::UnsupportedReturnExpression
                    | LoweringDiagnosticCode::UnsupportedBodyShape
            ) =>
        {
            if let Some(async_callback_diagnostic) =
                diagnose_async_callback_import_edge(context.compartment, function)
            {
                return Err(async_callback_diagnostic);
            }
            if let Some(lowered) =
                lower_imported_call_export(checked, context.compartment, function)
            {
                return Ok(lowered);
            }
            lower_runtime_expression_export(checked, context, all_compartments, function)
                .ok_or(diagnostic)
        }
        Err(diagnostic) => Err(diagnostic),
    }
}

fn lower_runtime_parameterized_export(
    checked: &CruftScriptCheckedUnit,
    compartment: &CompartmentDecl,
    function: &ExportedFunction,
) -> Result<LoweredFunction, LoweringDiagnostic> {
    if function
        .type_params
        .iter()
        .any(|type_param| type_param.constraint.is_some())
    {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedFunctionShape,
            span: function.span,
            message: format!(
                "CruftScript runtime export `{}` cannot monomorphize constrained generic/type-parameterized functions yet",
                function.name
            ),
        });
    }
    Ok(LoweredFunction {
        compartment: compartment.name.clone(),
        function_name: function.name.clone(),
        arity: function.params.len(),
        body: LoweredFunctionBody::RuntimeParameterizedExport(LoweredRuntimeParameterizedExport {
            compartment: compartment.clone(),
            type_environment: checked.report.types.clone(),
            function_name: function.name.clone(),
            params: function
                .params
                .iter()
                .map(|param| param.name.clone())
                .collect(),
            param_defaults: lower_runtime_parameter_defaults(checked, compartment, function),
            return_type: function.return_type.as_ref().map(lower_type_term),
            body: lower_runtime_parameterized_export_body(checked, compartment, function),
            span: function.span,
        }),
        span: function.span,
    })
}

fn lower_runtime_parameter_defaults(
    checked: &CruftScriptCheckedUnit,
    compartment: &CompartmentDecl,
    function: &ExportedFunction,
) -> Vec<Option<LoweredRuntimeExpression>> {
    let context = LoweringContext::new(compartment, &checked.report.types);
    let all_compartments = vec![compartment];
    let runtime_locals = function
        .params
        .iter()
        .map(|param| param.name.clone())
        .collect::<HashSet<_>>();
    let runtime_local_types = function
        .params
        .iter()
        .map(|param| (param.name.clone(), lower_type_term(&param.ty)))
        .collect::<HashMap<_, _>>();
    function
        .params
        .iter()
        .map(|param| {
            param.default.as_ref().and_then(|default| {
                lower_runtime_expression(
                    checked,
                    &context,
                    &all_compartments,
                    default,
                    &HashMap::new(),
                    &runtime_locals,
                    &runtime_local_types,
                    &mut Vec::new(),
                )
            })
        })
        .collect()
}

#[allow(clippy::too_many_arguments)]
fn lower_runtime_if_return_conditional(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    if_stmt: &cruftscript_parser::IfStmt,
    alternate: LoweredRuntimeExpression,
    constant_bindings: &HashMap<String, LoweredValue>,
    runtime_locals: &HashSet<String>,
    runtime_local_types: &HashMap<String, TypeTerm>,
) -> Option<LoweredRuntimeExpression> {
    let [BodyStmt::Return(then_return)] = if_stmt.then_body.statements.as_slice() else {
        return None;
    };
    let consequent_argument = then_return.argument.as_ref()?;
    let consequent_runtime_local_types = runtime_local_types_with_guard_refinement(
        checked,
        context,
        constant_bindings,
        runtime_local_types,
        &if_stmt.subject,
        &if_stmt.guard,
    );
    Some(LoweredRuntimeExpression::Conditional {
        subject: Box::new(lower_runtime_expression(
            checked,
            context,
            all_compartments,
            &if_stmt.subject,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            &mut Vec::new(),
        )?),
        guard: lower_runtime_narrowing_guard(
            checked,
            context,
            all_compartments,
            &if_stmt.guard,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            &mut Vec::new(),
        )?,
        consequent: Box::new(lower_runtime_expression(
            checked,
            context,
            all_compartments,
            consequent_argument,
            constant_bindings,
            runtime_locals,
            &consequent_runtime_local_types,
            &mut Vec::new(),
        )?),
        alternate: Box::new(alternate),
    })
}

fn lower_runtime_parameterized_export_body(
    checked: &CruftScriptCheckedUnit,
    compartment: &CompartmentDecl,
    function: &ExportedFunction,
) -> Option<LoweredRuntimeExpression> {
    let context = LoweringContext::new(compartment, &checked.report.types);
    let runtime_locals = function
        .params
        .iter()
        .map(|param| param.name.clone())
        .collect::<HashSet<_>>();
    let mut runtime_locals = runtime_locals;
    let mut runtime_local_types = function
        .params
        .iter()
        .map(|param| (param.name.clone(), lower_type_term(&param.ty)))
        .collect::<HashMap<_, _>>();
    let (last, prefix) = function.body.statements.split_last()?;
    let (prefix, if_return_tail) = match prefix.split_last() {
        Some((BodyStmt::If(if_stmt), rest)) if if_stmt.else_body.is_none() => (rest, Some(if_stmt)),
        _ => (prefix, None),
    };
    let mut constant_bindings = HashMap::new();
    let mut declarations = Vec::new();

    let mut extra_if_returns: Vec<&cruftscript_parser::IfStmt> = Vec::new();
    for statement in prefix {
        if let BodyStmt::If(if_stmt) = statement {
            if if_stmt.else_body.is_none()
                && matches!(
                    if_stmt.then_body.statements.as_slice(),
                    [BodyStmt::Return(_)]
                )
            {
                extra_if_returns.push(if_stmt);
                continue;
            }
        }
        let BodyStmt::LocalDecl(local) = statement else {
            return None;
        };
        let initializer = local.initializer.as_ref()?;
        if !local.mutable {
            if let ExprEnvelopeKind::StringLiteral(value) = &initializer.kind {
                constant_bindings.insert(local.name.clone(), LoweredValue::String(value.clone()));
                continue;
            }
            if let Some(value) = same_compartment_function_ref_initializer(initializer, &context) {
                constant_bindings.insert(local.name.clone(), value);
                continue;
            }
            if let Some(value) = same_compartment_constructor_ref_initializer(initializer, &context)
            {
                constant_bindings.insert(local.name.clone(), value);
                continue;
            }
            if let Some(value) =
                lower_runtime_constant_callee_object(initializer, &context, &constant_bindings)
            {
                constant_bindings.insert(local.name.clone(), value);
                continue;
            }
        }
        let value = lower_runtime_expression(
            checked,
            &context,
            &[compartment],
            initializer,
            &constant_bindings,
            &runtime_locals,
            &runtime_local_types,
            &mut Vec::new(),
        )?;
        declarations.push((local.name.clone(), value));
        runtime_locals.insert(local.name.clone());
        if let Some(annotation) = &local.type_annotation {
            runtime_local_types.insert(local.name.clone(), lower_type_term(annotation));
        }
    }
    if let BodyStmt::Switch(switch_stmt) = last {
        let mut body = lower_runtime_terminal_switch(
            checked,
            &context,
            &[compartment],
            switch_stmt,
            &constant_bindings,
            &runtime_locals,
            &runtime_local_types,
        )?;
        for (name, value) in declarations.into_iter().rev() {
            body = LoweredRuntimeExpression::Let {
                name,
                value: Box::new(value),
                body: Box::new(body),
            };
        }
        return Some(body);
    }
    let BodyStmt::Return(ret) = last else {
        return None;
    };
    let argument = ret.argument.as_ref()?;
    if extra_if_returns.is_empty() {
        if let Some(body) = lower_runtime_if_assignment_tail(
            checked,
            &context,
            &[compartment],
            if_return_tail,
            argument,
            &constant_bindings,
            &runtime_locals,
            &runtime_local_types,
            &mut Vec::new(),
        ) {
            let mut body = body;
            for (name, value) in declarations.into_iter().rev() {
                body = LoweredRuntimeExpression::Let {
                    name,
                    value: Box::new(value),
                    body: Box::new(body),
                };
            }
            return Some(body);
        }
    }
    let alternate = lower_runtime_expression(
        checked,
        &context,
        &[compartment],
        argument,
        &constant_bindings,
        &runtime_locals,
        &runtime_local_types,
        &mut Vec::new(),
    )?;
    let mut body = if let Some(if_stmt) = if_return_tail {
        lower_runtime_if_return_conditional(
            checked,
            &context,
            &[compartment],
            if_stmt,
            alternate,
            &constant_bindings,
            &runtime_locals,
            &runtime_local_types,
        )?
    } else {
        alternate
    };

    for if_stmt in extra_if_returns.into_iter().rev() {
        body = lower_runtime_if_return_conditional(
            checked,
            &context,
            &[compartment],
            if_stmt,
            body,
            &constant_bindings,
            &runtime_locals,
            &runtime_local_types,
        )?;
    }
    for (name, value) in declarations.into_iter().rev() {
        body = LoweredRuntimeExpression::Let {
            name,
            value: Box::new(value),
            body: Box::new(body),
        };
    }
    Some(body)
}

#[allow(clippy::too_many_arguments)]
fn lower_runtime_terminal_switch(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    switch_stmt: &cruftscript_parser::SwitchStmt,
    constant_bindings: &HashMap<String, LoweredValue>,
    runtime_locals: &HashSet<String>,
    runtime_local_types: &HashMap<String, TypeTerm>,
) -> Option<LoweredRuntimeExpression> {
    let default = switch_stmt.default.as_ref()?;
    let mut body = lower_runtime_single_return_body(
        checked,
        context,
        all_compartments,
        default,
        constant_bindings,
        runtime_locals,
        runtime_local_types,
    )?;
    for case in switch_stmt.cases.iter().rev() {
        let case_body = lower_runtime_single_return_body(
            checked,
            context,
            all_compartments,
            &case.body,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
        )?;
        let subject = lower_runtime_expression(
            checked,
            context,
            all_compartments,
            &switch_stmt.subject,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            &mut Vec::new(),
        )?;
        let test = lower_runtime_expression(
            checked,
            context,
            all_compartments,
            &case.test,
            constant_bindings,
            runtime_locals,
            runtime_local_types,
            &mut Vec::new(),
        )?;
        body = LoweredRuntimeExpression::Ternary {
            condition: Box::new(LoweredRuntimeExpression::Binary {
                op: RuntimeBinaryOp::StrictEq,
                left: Box::new(subject),
                right: Box::new(test),
                span: case.test.span,
            }),
            consequent: Box::new(case_body),
            alternate: Box::new(body),
        };
    }
    Some(body)
}

fn lower_runtime_single_return_body(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    body: &FunctionBody,
    constant_bindings: &HashMap<String, LoweredValue>,
    runtime_locals: &HashSet<String>,
    runtime_local_types: &HashMap<String, TypeTerm>,
) -> Option<LoweredRuntimeExpression> {
    let [BodyStmt::Return(ret)] = body.statements.as_slice() else {
        return None;
    };
    lower_runtime_expression(
        checked,
        context,
        all_compartments,
        ret.argument.as_ref()?,
        constant_bindings,
        runtime_locals,
        runtime_local_types,
        &mut Vec::new(),
    )
}

fn runtime_local_types_with_guard_refinement(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    constant_bindings: &HashMap<String, LoweredValue>,
    runtime_local_types: &HashMap<String, TypeTerm>,
    subject: &ExprEnvelope,
    guard: &NarrowingGuard,
) -> HashMap<String, TypeTerm> {
    let mut refined = runtime_local_types.clone();
    if let Some((subject_name, target)) =
        runtime_type_predicate_guard_refinement(checked, context, constant_bindings, subject, guard)
    {
        refined.insert(subject_name, target);
        return refined;
    }
    let ExprEnvelopeKind::Identifier(subject_name) = &subject.kind else {
        return refined;
    };
    match guard {
        NarrowingGuard::DynamicOwnProperty { span, .. } => {
            refined.insert(
                subject_name.clone(),
                TypeTerm::TypeRef {
                    name: "__CruftStringRecord".to_string(),
                    type_args: vec![TypeTerm::Unknown { span: *span }],
                    span: *span,
                },
            );
        }
        NarrowingGuard::OwnProperty { property, span } => {
            refined.insert(
                subject_name.clone(),
                TypeTerm::Object {
                    properties: vec![ObjectPropertyTerm {
                        name: property.clone(),
                        ty: TypeTerm::Unknown { span: *span },
                        readonly: false,
                        optional: false,
                        span: *span,
                    }],
                    span: *span,
                },
            );
        }
        NarrowingGuard::Instanceof { constructor, .. } => {
            if let Some(class_decl) = context.get_class(constructor) {
                refined.insert(
                    subject_name.clone(),
                    lower_class_runtime_object_type(class_decl),
                );
            }
        }
        _ => {}
    }
    refined
}

fn runtime_local_types_with_guard_negative_refinement(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    constant_bindings: &HashMap<String, LoweredValue>,
    runtime_local_types: &HashMap<String, TypeTerm>,
    subject: &ExprEnvelope,
    guard: &NarrowingGuard,
) -> HashMap<String, TypeTerm> {
    let mut refined = runtime_local_types.clone();
    let Some((subject_name, target)) = runtime_type_predicate_guard_refinement(
        checked,
        context,
        constant_bindings,
        subject,
        guard,
    ) else {
        return refined;
    };
    let Some(source) = runtime_local_types.get(&subject_name) else {
        return refined;
    };
    let aliases = AliasExpansionContext::new(&checked.report.types);
    if let Some(next) =
        type_term_without_assignable_members(source, &target, subject.span, &aliases)
    {
        refined.insert(subject_name, next);
    }
    refined
}

fn runtime_type_predicate_guard_refinement(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    constant_bindings: &HashMap<String, LoweredValue>,
    subject: &ExprEnvelope,
    guard: &NarrowingGuard,
) -> Option<(String, TypeTerm)> {
    if !matches!(guard, NarrowingGuard::Truthy { .. }) {
        return None;
    }
    let ExprEnvelopeKind::Call { callee, args, .. } = &subject.kind else {
        return None;
    };
    let [arg] = args.as_slice() else {
        return None;
    };
    let ExprEnvelopeKind::Identifier(subject_name) = &arg.kind else {
        return None;
    };
    let callee_name =
        same_compartment_function_name_for_callee(callee, context, constant_bindings)?;
    let signature = function_signature_for_install(checked, &callee_name)?;
    let target = predicate_target_from_function_parts(
        signature.params.iter().map(|param| FunctionTypeParamTerm {
            name: Some(param.name.clone()),
            ty: param.ty.clone(),
            span: param.span,
        }),
        signature.return_type.as_ref(),
    )?;
    let aliases = AliasExpansionContext::new(&checked.report.types);
    Some((
        subject_name.clone(),
        aliases.expand_for_assignability(&target, &mut Vec::new()),
    ))
}

fn evaluate_lowered_runtime_expression_with_args(
    template: &LoweredRuntimeParameterizedExport,
    expression: &LoweredRuntimeExpression,
    args: &[LoweredValue],
) -> Result<LoweredValue, LoweringDiagnostic> {
    let env = template
        .params
        .iter()
        .cloned()
        .zip(args.iter().cloned())
        .collect::<HashMap<_, _>>();
    let value = evaluate_lowered_runtime_expression_constant(expression, &env).ok_or_else(|| {
        let message = if lowered_runtime_expression_has_non_integral_index(expression, &env) {
            "CruftScript runtime element access requires a non-negative integral index".to_string()
        } else {
            format!(
                "CruftScript runtime export `{}` requires runtime-only values and cannot lower to a compile-time value",
                template.function_name
            )
        };
        LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedReturnExpression,
            span: template.span,
            message,
        }
    })?;
    let context = LoweringContext::new(&template.compartment, &template.type_environment);
    project_boundary_return_type_term(
        value,
        &context,
        template.return_type.as_ref(),
        template.span,
    )
}

fn evaluate_lowered_runtime_expression_constant(
    expression: &LoweredRuntimeExpression,
    env: &HashMap<String, LoweredValue>,
) -> Option<LoweredValue> {
    match expression {
        LoweredRuntimeExpression::Value(value) => Some(value.clone()),
        LoweredRuntimeExpression::LocalRef(name) => env.get(name).cloned(),

        LoweredRuntimeExpression::BuiltinMethodCall { .. } => None,
        LoweredRuntimeExpression::BuiltinConstruct { .. } => None,
        LoweredRuntimeExpression::Arrow { .. } => None,
        LoweredRuntimeExpression::Binary { .. } => None,
        LoweredRuntimeExpression::Ternary { .. } => None,
        LoweredRuntimeExpression::Array(elements) => elements
            .iter()
            .map(|element| evaluate_lowered_runtime_expression_constant(element, env))
            .collect::<Option<Vec<_>>>()
            .map(LoweredValue::Array),
        LoweredRuntimeExpression::Object(properties)
        | LoweredRuntimeExpression::ClassObject { properties, .. } => properties
            .iter()
            .map(|property| {
                Some(LoweredObjectProperty {
                    name: property.name.clone(),
                    value: evaluate_lowered_runtime_expression_constant(&property.value, env)?,
                })
            })
            .collect::<Option<Vec<_>>>()
            .map(LoweredValue::Object),
        LoweredRuntimeExpression::PropertyAccess {
            object,
            property,
            optional,
            ..
        } => {
            let object = evaluate_lowered_runtime_expression_constant(object, env)?;
            if *optional && matches!(object, LoweredValue::Undefined) {
                return Some(LoweredValue::Undefined);
            }
            let LoweredValue::Object(properties) = object else {
                return None;
            };
            properties
                .into_iter()
                .find(|candidate| candidate.name == *property)
                .map(|candidate| candidate.value)
        }
        LoweredRuntimeExpression::ComputedPropertyAccess {
            object,
            key,
            optional,
            ..
        } => {
            let object = evaluate_lowered_runtime_expression_constant(object, env)?;
            if *optional && matches!(object, LoweredValue::Undefined) {
                return Some(LoweredValue::Undefined);
            }
            let key = evaluate_lowered_runtime_expression_constant(key, env)?;
            match object {
                LoweredValue::Array(elements) => {
                    let LoweredValue::Number(key) = key else {
                        return None;
                    };
                    let index = lowered_number_to_index(&key)?;
                    return Some(
                        elements
                            .get(index)
                            .cloned()
                            .unwrap_or(LoweredValue::Undefined),
                    );
                }
                LoweredValue::Object(properties) => {
                    let key = match key {
                        LoweredValue::String(key) => key,
                        LoweredValue::Number(key) => lowered_number_to_index(&key)?.to_string(),
                        _ => return None,
                    };
                    return properties
                        .into_iter()
                        .find(|candidate| candidate.name == key)
                        .map(|candidate| candidate.value);
                }
                _ => return None,
            };
        }
        LoweredRuntimeExpression::NonNullCheck { expr, .. } => {
            let value = evaluate_lowered_runtime_expression_constant(expr, env)?;
            (!matches!(value, LoweredValue::Undefined)).then_some(value)
        }
        LoweredRuntimeExpression::TypeCheck {
            expr, target_type, ..
        } => {
            let value = evaluate_lowered_runtime_expression_constant(expr, env)?;
            lowered_value_matches_type(&value, target_type).then_some(value)
        }
        LoweredRuntimeExpression::Let { name, value, body } => {
            let mut nested = env.clone();
            nested.insert(
                name.clone(),
                evaluate_lowered_runtime_expression_constant(value, env)?,
            );
            evaluate_lowered_runtime_expression_constant(body, &nested)
        }
        LoweredRuntimeExpression::Conditional {
            subject,
            guard,
            consequent,
            alternate,
        } => {
            let value = evaluate_lowered_runtime_expression_constant(subject, env)?;
            let branch = lowered_runtime_guard_matches_value(guard, &value, env)?;
            evaluate_lowered_runtime_expression_constant(
                if branch { consequent } else { alternate },
                env,
            )
        }
        LoweredRuntimeExpression::EndowmentRef(_)
        | LoweredRuntimeExpression::IntrinsicRef(_)
        | LoweredRuntimeExpression::ImportedCall(_)
        | LoweredRuntimeExpression::CrossCompartmentCall(_)
        | LoweredRuntimeExpression::RuntimeCallbackCall(_)
        | LoweredRuntimeExpression::PredicateRecordCall(_) => None,
    }
}

fn lowered_number_to_index(value: &str) -> Option<usize> {
    if !is_non_negative_integral_number_spelling(value) {
        return None;
    }
    value.parse::<usize>().ok()
}

fn lowered_runtime_expression_has_non_integral_index(
    expression: &LoweredRuntimeExpression,
    env: &HashMap<String, LoweredValue>,
) -> bool {
    match expression {
        LoweredRuntimeExpression::ComputedPropertyAccess { key, .. } => matches!(
            evaluate_lowered_runtime_expression_constant(key, env),
            Some(LoweredValue::Number(value)) if !is_non_negative_integral_number_spelling(&value)
        ),
        LoweredRuntimeExpression::TypeCheck { expr, .. }
        | LoweredRuntimeExpression::NonNullCheck { expr, .. } => {
            lowered_runtime_expression_has_non_integral_index(expr, env)
        }
        LoweredRuntimeExpression::BuiltinMethodCall { receiver, args, .. } => {
            lowered_runtime_expression_has_non_integral_index(receiver, env)
                || args
                    .iter()
                    .any(|arg| lowered_runtime_expression_has_non_integral_index(arg, env))
        }
        LoweredRuntimeExpression::BuiltinConstruct { args, .. } => args
            .iter()
            .any(|arg| lowered_runtime_expression_has_non_integral_index(arg, env)),
        LoweredRuntimeExpression::Arrow { body, .. } => {
            lowered_runtime_expression_has_non_integral_index(body, env)
        }
        LoweredRuntimeExpression::Binary { left, right, .. } => {
            lowered_runtime_expression_has_non_integral_index(left, env)
                || lowered_runtime_expression_has_non_integral_index(right, env)
        }
        LoweredRuntimeExpression::Let { value, body, .. } => {
            lowered_runtime_expression_has_non_integral_index(value, env)
                || lowered_runtime_expression_has_non_integral_index(body, env)
        }
        LoweredRuntimeExpression::Array(elements) => elements
            .iter()
            .any(|element| lowered_runtime_expression_has_non_integral_index(element, env)),
        LoweredRuntimeExpression::Object(properties)
        | LoweredRuntimeExpression::ClassObject { properties, .. } => {
            properties.iter().any(|property| {
                lowered_runtime_expression_has_non_integral_index(&property.value, env)
            })
        }
        LoweredRuntimeExpression::PropertyAccess { object, .. } => {
            lowered_runtime_expression_has_non_integral_index(object, env)
        }
        LoweredRuntimeExpression::RuntimeCallbackCall(call) => call
            .args
            .iter()
            .any(|arg| lowered_runtime_expression_has_non_integral_index(arg, env)),
        LoweredRuntimeExpression::PredicateRecordCall(call) => {
            lowered_runtime_expression_has_non_integral_index(&call.key, env)
                || lowered_runtime_expression_has_non_integral_index(&call.arg, env)
        }
        LoweredRuntimeExpression::Conditional {
            subject,
            consequent,
            alternate,
            ..
        } => {
            lowered_runtime_expression_has_non_integral_index(subject, env)
                || lowered_runtime_expression_has_non_integral_index(consequent, env)
                || lowered_runtime_expression_has_non_integral_index(alternate, env)
        }
        LoweredRuntimeExpression::Ternary {
            condition,
            consequent,
            alternate,
        } => {
            lowered_runtime_expression_has_non_integral_index(condition, env)
                || lowered_runtime_expression_has_non_integral_index(consequent, env)
                || lowered_runtime_expression_has_non_integral_index(alternate, env)
        }
        LoweredRuntimeExpression::Value(_)
        | LoweredRuntimeExpression::LocalRef(_)
        | LoweredRuntimeExpression::EndowmentRef(_)
        | LoweredRuntimeExpression::IntrinsicRef(_)
        | LoweredRuntimeExpression::ImportedCall(_)
        | LoweredRuntimeExpression::CrossCompartmentCall(_) => false,
    }
}

fn lowered_runtime_guard_matches_value(
    guard: &LoweredRuntimeNarrowingGuard,
    value: &LoweredValue,
    env: &HashMap<String, LoweredValue>,
) -> Option<bool> {
    match guard {
        LoweredRuntimeNarrowingGuard::Truthy => Some(lowered_value_truthy(value)),
        LoweredRuntimeNarrowingGuard::TypeofEquals { expected } => {
            Some(lowered_value_typeof(value) == expected)
        }
        LoweredRuntimeNarrowingGuard::OwnProperty { property } => {
            Some(lowered_value_has_own_property(value, property))
        }
        LoweredRuntimeNarrowingGuard::DynamicOwnProperty { key } => {
            let key = evaluate_lowered_runtime_expression_constant(key, env)?;
            let LoweredValue::String(key) = key else {
                return None;
            };
            Some(lowered_value_has_own_property(value, &key))
        }
        LoweredRuntimeNarrowingGuard::Instanceof { .. } => None,
    }
}

fn lower_class_constructor_runtime_expression(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    class_decl: &ClassDecl,
    args: &[ExprEnvelope],
    constant_bindings: &HashMap<String, LoweredValue>,
    runtime_locals: &HashSet<String>,
    runtime_local_types: &HashMap<String, TypeTerm>,
    stack: &mut Vec<String>,
) -> Option<LoweredRuntimeExpression> {
    let mut constructor_constants = constant_bindings.clone();
    let mut constructor_runtime_locals = runtime_locals.clone();
    let mut constructor_runtime_types = runtime_local_types.clone();
    let mut runtime_arg_declarations = Vec::new();
    let assignments = if let Some(constructor) = &class_decl.constructor {
        if args.len() != constructor.params.len()
            || !class_decl_has_lowerable_constructor(class_decl)
        {
            return None;
        }
        for (param, arg) in constructor.params.iter().zip(args) {
            if let Some(value) = lower_runtime_constant_arg(arg, constant_bindings, runtime_locals)
            {
                constructor_constants.insert(param.name.clone(), value);
                continue;
            }
            let value = lower_runtime_expression(
                checked,
                context,
                all_compartments,
                arg,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )?;
            constructor_runtime_locals.insert(param.name.clone());
            constructor_runtime_types.insert(param.name.clone(), lower_type_term(&param.ty));
            runtime_arg_declarations.push((param.name.clone(), value));
        }
        let assignments = class_constructor_assignments(class_decl)?;
        let constructor_local_decls = match &assignments {
            ConstructorAssignmentPlan::Direct { locals, .. }
            | ConstructorAssignmentPlan::IfElse { locals, .. } => locals.as_slice(),
        };
        for local in constructor_local_decls {
            let initializer = local.initializer.as_ref()?;
            if let Some(value) = lower_runtime_constant_arg(
                initializer,
                &constructor_constants,
                &constructor_runtime_locals,
            ) {
                constructor_constants.insert(local.name.clone(), value);
                continue;
            }
            let value = lower_runtime_expression(
                checked,
                context,
                all_compartments,
                initializer,
                &constructor_constants,
                &constructor_runtime_locals,
                &constructor_runtime_types,
                stack,
            )?;
            let annotation = local.type_annotation.as_ref()?;
            constructor_runtime_locals.insert(local.name.clone());
            constructor_runtime_types.insert(local.name.clone(), lower_type_term(annotation));
            runtime_arg_declarations.push((local.name.clone(), value));
        }
        if let ConstructorAssignmentPlan::IfElse {
            local_assignments, ..
        } = &assignments
        {
            for assignment in local_assignments {
                let AssignmentTarget::Local(target) = &assignment.target else {
                    return None;
                };
                if let Some(value) = lower_runtime_constant_arg(
                    &assignment.value,
                    &constructor_constants,
                    &constructor_runtime_locals,
                ) {
                    constructor_constants.insert(target.clone(), value);
                    continue;
                }
                let value = lower_runtime_expression(
                    checked,
                    context,
                    all_compartments,
                    &assignment.value,
                    &constructor_constants,
                    &constructor_runtime_locals,
                    &constructor_runtime_types,
                    stack,
                )?;
                constructor_constants.remove(target);
                runtime_arg_declarations.push((target.clone(), value));
            }
        }
        Some(assignments)
    } else {
        if !args.is_empty() {
            return None;
        }
        None
    };
    if assignments.is_none() && !class_decl.fields.iter().all(class_field_has_initial_state) {
        return None;
    }
    if let Some(ConstructorAssignmentPlan::Direct { .. }) = assignments.as_ref() {
        let mut properties = Vec::new();
        let mut assigned = HashSet::new();
        constructor_constants.insert("this".to_string(), LoweredValue::Object(Vec::new()));
        constructor_runtime_locals.insert("this".to_string());
        constructor_runtime_types.insert(
            "this".to_string(),
            lower_class_assigned_this_type(class_decl, &HashSet::new()),
        );
        if let Some(constructor) = &class_decl.constructor {
            for statement in &constructor.body.statements {
                let BodyStmt::Assignment(assignment) = statement else {
                    continue;
                };
                if let AssignmentTarget::Local(target) = &assignment.target {
                    if !constructor_runtime_locals.contains(target) {
                        return None;
                    }
                    if let Some(value) = lower_runtime_constant_arg(
                        &assignment.value,
                        &constructor_constants,
                        &constructor_runtime_locals,
                    ) {
                        constructor_constants.insert(target.clone(), value);
                        continue;
                    }
                    let value = lower_runtime_expression(
                        checked,
                        context,
                        all_compartments,
                        &assignment.value,
                        &constructor_constants,
                        &constructor_runtime_locals,
                        &constructor_runtime_types,
                        stack,
                    )?;
                    constructor_constants.remove(target);
                    runtime_arg_declarations.push((target.clone(), value));
                    continue;
                }
                let AssignmentTarget::Property {
                    object,
                    property,
                    optional: false,
                } = &assignment.target
                else {
                    continue;
                };
                if !matches!(&object.kind, ExprEnvelopeKind::Identifier(name) if name == "this") {
                    continue;
                }
                let value = lower_runtime_expression(
                    checked,
                    context,
                    all_compartments,
                    &assignment.value,
                    &constructor_constants,
                    &constructor_runtime_locals,
                    &constructor_runtime_types,
                    stack,
                )?;
                properties.push(LoweredRuntimeObjectProperty {
                    name: property.clone(),
                    value,
                });
                assigned.insert(property.as_str());
                constructor_runtime_types.insert(
                    "this".to_string(),
                    lower_class_assigned_this_type(class_decl, &assigned),
                );
                runtime_arg_declarations.push((
                    "this".to_string(),
                    LoweredRuntimeExpression::Object(properties.clone()),
                ));
            }
        }
        for field in &class_decl.fields {
            if assigned.contains(field.name.as_str()) {
                continue;
            }
            let Some(initializer) = field.initializer.as_ref() else {
                continue;
            };
            properties.push(LoweredRuntimeObjectProperty {
                name: field.name.clone(),
                value: lower_runtime_expression(
                    checked,
                    context,
                    all_compartments,
                    initializer,
                    &constructor_constants,
                    &constructor_runtime_locals,
                    &constructor_runtime_types,
                    stack,
                )?,
            });
        }
        properties.extend(
            class_decl
                .methods
                .iter()
                .map(|method| LoweredRuntimeObjectProperty {
                    name: method.name.clone(),
                    value: LoweredRuntimeExpression::Value(LoweredValue::FunctionRef(
                        class_method_ref_name(&class_decl.name, &method.name),
                    )),
                }),
        );
        let mut body = LoweredRuntimeExpression::ClassObject {
            class_name: class_decl.name.clone(),
            properties,
        };
        for (name, value) in runtime_arg_declarations.into_iter().rev() {
            body = LoweredRuntimeExpression::Let {
                name,
                value: Box::new(value),
                body: Box::new(body),
            };
        }
        return Some(body);
    }
    if let Some(ConstructorAssignmentPlan::IfElse {
        if_stmt,
        then_branch,
        else_branch,
        ..
    }) = assignments.as_ref()
    {
        let mut body = LoweredRuntimeExpression::Conditional {
            subject: Box::new(lower_runtime_expression(
                checked,
                context,
                all_compartments,
                &if_stmt.subject,
                &constructor_constants,
                &constructor_runtime_locals,
                &constructor_runtime_types,
                stack,
            )?),
            guard: lower_runtime_narrowing_guard(
                checked,
                context,
                all_compartments,
                &if_stmt.guard,
                &constructor_constants,
                &constructor_runtime_locals,
                &constructor_runtime_types,
                stack,
            )?,
            consequent: Box::new(lower_runtime_constructor_branch_object_expression(
                checked,
                context,
                all_compartments,
                class_decl,
                then_branch,
                &constructor_constants,
                &constructor_runtime_locals,
                &constructor_runtime_types,
                stack,
            )?),
            alternate: Box::new(lower_runtime_constructor_branch_object_expression(
                checked,
                context,
                all_compartments,
                class_decl,
                else_branch,
                &constructor_constants,
                &constructor_runtime_locals,
                &constructor_runtime_types,
                stack,
            )?),
        };
        for (name, value) in runtime_arg_declarations.into_iter().rev() {
            body = LoweredRuntimeExpression::Let {
                name,
                value: Box::new(value),
                body: Box::new(body),
            };
        }
        return Some(body);
    }
    let mut properties = class_decl
        .fields
        .iter()
        .filter_map(|field| {
            let value = match assignments.as_ref() {
                Some(ConstructorAssignmentPlan::Direct { assignments, .. }) => assignments
                    .get(field.name.as_str())
                    .copied()
                    .or(field.initializer.as_ref())
                    .map(|initializer| {
                        lower_runtime_expression(
                            checked,
                            context,
                            all_compartments,
                            initializer,
                            &constructor_constants,
                            &constructor_runtime_locals,
                            &constructor_runtime_types,
                            stack,
                        )
                    })?,
                Some(ConstructorAssignmentPlan::IfElse { .. }) => {
                    unreachable!("if/else constructor returned before per-field runtime lowering")
                }
                None => field.initializer.as_ref().map(|initializer| {
                    lower_runtime_expression(
                        checked,
                        context,
                        all_compartments,
                        initializer,
                        &constructor_constants,
                        &constructor_runtime_locals,
                        &constructor_runtime_types,
                        stack,
                    )
                })?,
            }?;
            Some(Some(LoweredRuntimeObjectProperty {
                name: field.name.clone(),
                value,
            }))
        })
        .collect::<Option<Vec<_>>>()?;
    properties.extend(
        class_decl
            .methods
            .iter()
            .map(|method| LoweredRuntimeObjectProperty {
                name: method.name.clone(),
                value: LoweredRuntimeExpression::Value(LoweredValue::FunctionRef(
                    class_method_ref_name(&class_decl.name, &method.name),
                )),
            }),
    );
    let mut body = LoweredRuntimeExpression::ClassObject {
        class_name: class_decl.name.clone(),
        properties,
    };
    for (name, value) in runtime_arg_declarations.into_iter().rev() {
        body = LoweredRuntimeExpression::Let {
            name,
            value: Box::new(value),
            body: Box::new(body),
        };
    }
    Some(body)
}

fn lower_runtime_constructor_branch_object_expression(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    class_decl: &ClassDecl,
    branch: &ConstructorBranchPlan<'_>,
    constructor_constants: &HashMap<String, LoweredValue>,
    constructor_runtime_locals: &HashSet<String>,
    constructor_runtime_types: &HashMap<String, TypeTerm>,
    stack: &mut Vec<String>,
) -> Option<LoweredRuntimeExpression> {
    let mut constants = constructor_constants.clone();
    let mut runtime_locals = constructor_runtime_locals.clone();
    let mut runtime_types = constructor_runtime_types.clone();
    let mut prefix_declarations = Vec::new();
    for local in &branch.locals {
        let initializer = local.initializer.as_ref()?;
        if let Some(value) = lower_runtime_constant_arg(initializer, &constants, &runtime_locals) {
            constants.insert(local.name.clone(), value);
            continue;
        }
        let lowered = lower_runtime_expression(
            checked,
            context,
            all_compartments,
            initializer,
            &constants,
            &runtime_locals,
            &runtime_types,
            stack,
        )?;
        let annotation = local.type_annotation.as_ref()?;
        runtime_locals.insert(local.name.clone());
        runtime_types.insert(local.name.clone(), lower_type_term(annotation));
        prefix_declarations.push((local.name.clone(), lowered));
    }
    for assignment in &branch.local_assignments {
        let cruftscript_parser::AssignmentTarget::Local(target) = &assignment.target else {
            return None;
        };
        if let Some(value) =
            lower_runtime_constant_arg(&assignment.value, &constants, &runtime_locals)
        {
            constants.insert(target.clone(), value);
            continue;
        }
        let lowered = lower_runtime_expression(
            checked,
            context,
            all_compartments,
            &assignment.value,
            &constants,
            &runtime_locals,
            &runtime_types,
            stack,
        )?;
        runtime_locals.insert(target.clone());
        prefix_declarations.push((target.clone(), lowered));
    }

    let mut initialized = HashSet::new();
    let mut field_temps = Vec::new();
    let mut snapshots: Vec<Vec<LoweredRuntimeObjectProperty>> = Vec::new();
    runtime_locals.insert("this".to_string());
    runtime_types.insert(
        "this".to_string(),
        lower_class_assigned_this_type(class_decl, &initialized),
    );
    for (index, (field_name, value_expr)) in branch.field_assignments.iter().enumerate() {
        let value = lower_runtime_constructor_field_value_expression(
            checked,
            context,
            all_compartments,
            value_expr,
            &constants,
            &runtime_locals,
            &runtime_types,
            stack,
        )?;
        let temp = format!("__cruft_ctor_{}_{}_{}", class_decl.name, field_name, index);
        field_temps.push(((*field_name).to_string(), temp, value));
        initialized.insert(*field_name);
        runtime_types.insert(
            "this".to_string(),
            lower_class_assigned_this_type(class_decl, &initialized),
        );
        snapshots.push(
            field_temps
                .iter()
                .map(|(name, temp, _)| LoweredRuntimeObjectProperty {
                    name: name.clone(),
                    value: LoweredRuntimeExpression::LocalRef(temp.clone()),
                })
                .collect(),
        );
    }

    let mut final_properties = field_temps
        .iter()
        .map(|(name, temp, _)| LoweredRuntimeObjectProperty {
            name: name.clone(),
            value: LoweredRuntimeExpression::LocalRef(temp.clone()),
        })
        .collect::<Vec<_>>();
    for field in &class_decl.fields {
        if initialized.contains(field.name.as_str()) {
            continue;
        }
        let Some(initializer) = field.initializer.as_ref() else {
            continue;
        };
        final_properties.push(LoweredRuntimeObjectProperty {
            name: field.name.clone(),
            value: lower_runtime_expression(
                checked,
                context,
                all_compartments,
                initializer,
                &constants,
                &runtime_locals,
                &runtime_types,
                stack,
            )?,
        });
    }
    final_properties.extend(
        class_decl
            .methods
            .iter()
            .map(|method| LoweredRuntimeObjectProperty {
                name: method.name.clone(),
                value: LoweredRuntimeExpression::Value(LoweredValue::FunctionRef(
                    class_method_ref_name(&class_decl.name, &method.name),
                )),
            }),
    );

    let mut body = LoweredRuntimeExpression::Object(final_properties);
    for ((_, temp, value), snapshot) in field_temps.into_iter().zip(snapshots).rev() {
        body = LoweredRuntimeExpression::Let {
            name: temp,
            value: Box::new(value),
            body: Box::new(LoweredRuntimeExpression::Let {
                name: "this".to_string(),
                value: Box::new(LoweredRuntimeExpression::Object(snapshot)),
                body: Box::new(body),
            }),
        };
    }
    body = LoweredRuntimeExpression::Let {
        name: "this".to_string(),
        value: Box::new(LoweredRuntimeExpression::Object(Vec::new())),
        body: Box::new(body),
    };
    for (name, value) in prefix_declarations.into_iter().rev() {
        body = LoweredRuntimeExpression::Let {
            name,
            value: Box::new(value),
            body: Box::new(body),
        };
    }
    Some(body)
}

fn lower_runtime_constructor_field_value_expression(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    value: &ConstructorFieldAssignmentValue<'_>,
    constants: &HashMap<String, LoweredValue>,
    runtime_locals: &HashSet<String>,
    runtime_types: &HashMap<String, TypeTerm>,
    stack: &mut Vec<String>,
) -> Option<LoweredRuntimeExpression> {
    match value {
        ConstructorFieldAssignmentValue::Expr(expr) => lower_runtime_expression(
            checked,
            context,
            all_compartments,
            expr,
            constants,
            runtime_locals,
            runtime_types,
            stack,
        ),
        ConstructorFieldAssignmentValue::Conditional {
            if_stmt,
            then_value,
            else_value,
        } => {
            let subject = lower_runtime_expression(
                checked,
                context,
                all_compartments,
                &if_stmt.subject,
                constants,
                runtime_locals,
                runtime_types,
                stack,
            )?;
            let guard = lower_runtime_narrowing_guard(
                checked,
                context,
                all_compartments,
                &if_stmt.guard,
                constants,
                runtime_locals,
                runtime_types,
                stack,
            )?;
            let then_expr = lower_runtime_expression(
                checked,
                context,
                all_compartments,
                then_value,
                constants,
                runtime_locals,
                runtime_types,
                stack,
            )?;
            let else_expr = lower_runtime_expression(
                checked,
                context,
                all_compartments,
                else_value,
                constants,
                runtime_locals,
                runtime_types,
                stack,
            )?;
            Some(LoweredRuntimeExpression::Conditional {
                subject: Box::new(subject),
                guard,
                consequent: Box::new(then_expr),
                alternate: Box::new(else_expr),
            })
        }
    }
}

fn lower_runtime_predicate_record_call_expression(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    span: Span,
    callee: &ExprEnvelope,
    args: &[ExprEnvelope],
    optional: bool,
    constant_bindings: &HashMap<String, LoweredValue>,
    runtime_locals: &HashSet<String>,
    runtime_local_types: &HashMap<String, TypeTerm>,
    stack: &mut Vec<String>,
) -> Option<LoweredRuntimeExpression> {
    let ExprEnvelopeKind::ElementAccess { object, index, .. } = &callee.kind else {
        return None;
    };
    if runtime_static_string_key(index, constant_bindings).is_some() {
        return None;
    }
    let [arg] = args else {
        return None;
    };
    let lowered_object = lower_runtime_constant_callee_object(object, context, constant_bindings)?;
    let LoweredValue::Object(properties) = lowered_object else {
        return None;
    };
    let mut candidates = Vec::new();
    for property in properties {
        let LoweredValue::FunctionRef(function_name) = property.value else {
            return None;
        };
        if context.get_function(&function_name).is_none() {
            return None;
        }
        candidates.push(LoweredRuntimePredicateCandidate {
            property: property.name,
            function_name,
        });
    }
    if candidates.is_empty() {
        return None;
    }
    Some(LoweredRuntimeExpression::PredicateRecordCall(
        LoweredRuntimePredicateRecordCall {
            key: Box::new(lower_runtime_expression(
                checked,
                context,
                all_compartments,
                index,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )?),
            arg: Box::new(lower_runtime_expression(
                checked,
                context,
                all_compartments,
                arg,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )?),
            candidates,
            optional,
            span,
        },
    ))
}

fn lower_runtime_callback_call_expression(
    checked: &CruftScriptCheckedUnit,
    context: &LoweringContext<'_>,
    all_compartments: &[&CompartmentDecl],
    span: Span,
    callee: &ExprEnvelope,
    args: &[ExprEnvelope],
    optional: bool,
    constant_bindings: &HashMap<String, LoweredValue>,
    runtime_locals: &HashSet<String>,
    runtime_local_types: &HashMap<String, TypeTerm>,
    stack: &mut Vec<String>,
) -> Option<LoweredRuntimeCallbackCall> {
    let ExprEnvelopeKind::Identifier(callback_name) = &callee.kind else {
        return None;
    };
    if !runtime_locals.contains(callback_name) {
        return None;
    }
    let (policy_id, policy_name, resolution_chain) =
        runtime_callback_authority_record(checked, runtime_local_types.get(callback_name)?)?;
    let args = args
        .iter()
        .map(|arg| {
            lower_runtime_expression(
                checked,
                context,
                all_compartments,
                arg,
                constant_bindings,
                runtime_locals,
                runtime_local_types,
                stack,
            )
        })
        .collect::<Option<Vec<_>>>()?;
    Some(LoweredRuntimeCallbackCall {
        callback_name: callback_name.clone(),
        args,
        optional,
        policy_id,
        policy_name,
        resolution_chain,
        span,
    })
}

fn runtime_callback_authority_record(
    checked: &CruftScriptCheckedUnit,
    callback_type: &TypeTerm,
) -> Option<(u32, String, String)> {
    let aliases = AliasExpansionContext::new(&checked.report.types);
    let mut diagnostics = Vec::new();
    let expanded = aliases.expand_for_assignability(callback_type, &mut diagnostics);
    let TypeTerm::Function { boundary, .. } = function_type_from_callable_callee_type(expanded)?
    else {
        return None;
    };
    let policy_ref = boundary
        .as_ref()
        .and_then(policy_from_clause)
        .or(Some(BoundaryPolicyRef::Default))?;
    let default_policy = checked
        .boundary_facts()
        .default_policy
        .as_ref()
        .map(|default| default.policy.as_str());
    let (policy_id, policy_name) =
        boundary_runtime_call_policy_resolution(checked, &policy_ref, default_policy).ok()?;
    let resolution_chain = boundary_resolution_chain("runtime-callback", &policy_ref, &policy_name);
    Some((policy_id, policy_name, resolution_chain))
}

fn infer_runtime_export_type_args(
    template: &LoweredRuntimeParameterizedExport,
    args: &[LoweredValue],
) -> Result<HashMap<String, TypeTerm>, String> {
    let context = LoweringContext::new(&template.compartment, &template.type_environment);
    let Some(function) = context.get_function(&template.function_name) else {
        return Ok(HashMap::new());
    };
    if function.type_params.is_empty() {
        return Ok(HashMap::new());
    }
    let aliases = AliasExpansionContext::new(&template.type_environment);
    let mut diagnostics = Vec::new();
    let arg_types: Vec<_> = args
        .iter()
        .map(|arg| lowered_value_type_term(arg, template.span, &aliases, &mut diagnostics))
        .collect();
    if diagnostics
        .iter()
        .any(|diagnostic| diagnostic.severity == DiagnosticSeverity::Error)
    {
        return Err(format!(
            "CruftScript runtime export `{}` could not type lowered runtime arguments for generic monomorphization",
            template.function_name
        ));
    }
    let signatures = FunctionSignatureContext::new(&template.type_environment);
    let Some(signature) = signatures.get(&template.function_name) else {
        return Err(format!(
            "CruftScript runtime export `{}` has no checked generic signature",
            template.function_name
        ));
    };
    let inferred = infer_signature_type_args(
        &signature,
        &arg_types,
        template.span,
        &aliases,
        &mut diagnostics,
    );
    if !diagnostics.is_empty() {
        return Err(format!(
            "CruftScript runtime export `{}` could not infer generic parameters from runtime arguments",
            template.function_name
        ));
    }
    for type_param in &signature.type_params {
        let Some(inferred_ty) = inferred.get(&type_param.name) else {
            return Err(format!(
                "CruftScript runtime export `{}` could not infer generic parameter `{}` from runtime arguments",
                template.function_name, type_param.name
            ));
        };
        if type_term_contains_unknown_or_opaque(inferred_ty) {
            return Err(format!(
                "CruftScript runtime export `{}` refuses generic parameter `{}` inferred as unknown/opaque",
                template.function_name, type_param.name
            ));
        }
        if let Some(constraint) = &type_param.constraint {
            let mut constraint_diags = Vec::new();
            if !is_assignable(inferred_ty, constraint, &aliases, &mut constraint_diags) {
                return Err(format!(
                    "CruftScript runtime export `{}` inferred `{}` outside its generic constraint",
                    template.function_name, type_param.name
                ));
            }
        }
    }
    Ok(inferred)
}

fn validate_runtime_export_args(
    template: &LoweredRuntimeParameterizedExport,
    args: &[LoweredValue],
    type_args: &HashMap<String, TypeTerm>,
) -> Result<(), LoweringDiagnostic> {
    let signatures = FunctionSignatureContext::new(&template.type_environment);
    let Some(signature) = signatures.get(&template.function_name) else {
        return Err(LoweringDiagnostic {
            code: LoweringDiagnosticCode::UnsupportedFunctionShape,
            span: template.span,
            message: format!(
                "CruftScript runtime export `{}` has no checked signature",
                template.function_name
            ),
        });
    };
    let aliases = AliasExpansionContext::new(&template.type_environment);
    let substitutions: HashMap<_, _> = signature
        .type_params
        .iter()
        .filter_map(|param| {
            type_args
                .get(&param.name)
                .cloned()
                .map(|ty| (param.name.as_str(), ty))
        })
        .collect();
    let mut diagnostics = Vec::new();
    for (index, (arg, param)) in args.iter().zip(&signature.params).enumerate() {
        let expected = substitute_type_params(&param.ty, &substitutions);
        let expected = aliases.expand_for_assignability(&expected, &mut diagnostics);
        if diagnostics
            .iter()
            .any(|diagnostic| diagnostic.severity == DiagnosticSeverity::Error)
        {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::UnsupportedFunctionShape,
                span: param.span,
                message: format!(
                    "CruftScript runtime export `{}` could not resolve parameter `{}` type",
                    template.function_name, param.name
                ),
            });
        }
        if !runtime_export_param_requires_lowered_validation(&expected) {
            continue;
        }
        if !lowered_value_matches_type(arg, &expected) {
            return Err(LoweringDiagnostic {
                code: LoweringDiagnosticCode::ArgumentTypeMismatch,
                span: param.span,
                message: format!(
                    "argument {} for runtime export `{}` does not conform to parameter `{}`",
                    index, template.function_name, param.name
                ),
            });
        }
    }
    Ok(())
}

fn runtime_export_param_requires_lowered_validation(ty: &TypeTerm) -> bool {
    type_term_has_runtime_assertion_validator(ty)
}

fn type_term_contains_unknown_or_opaque(ty: &TypeTerm) -> bool {
    match ty {
        TypeTerm::Unknown { .. } | TypeTerm::Opaque { .. } => true,
        TypeTerm::Never { .. } | TypeTerm::Named { .. } => false,
        TypeTerm::TypeRef { type_args, .. }
        | TypeTerm::Tuple {
            elements: type_args,
            ..
        } => type_args.iter().any(type_term_contains_unknown_or_opaque),
        TypeTerm::Infer { constraint, .. } => constraint
            .as_deref()
            .is_some_and(type_term_contains_unknown_or_opaque),
        TypeTerm::Union { members, .. } => members.iter().any(type_term_contains_unknown_or_opaque),
        TypeTerm::Function {
            type_params,
            params,
            return_type,
            ..
        } => {
            type_params.iter().any(|param| {
                param
                    .constraint
                    .as_ref()
                    .is_some_and(type_term_contains_unknown_or_opaque)
            }) || params
                .iter()
                .any(|param| type_term_contains_unknown_or_opaque(&param.ty))
                || type_term_contains_unknown_or_opaque(return_type)
        }
        TypeTerm::TypePredicate { target, .. } => type_term_contains_unknown_or_opaque(target),
        TypeTerm::Constructor {
            params,
            instance_type,
            ..
        } => {
            params
                .iter()
                .any(|param| type_term_contains_unknown_or_opaque(&param.ty))
                || type_term_contains_unknown_or_opaque(instance_type)
        }
        TypeTerm::Conditional {
            check,
            extends,
            true_type,
            false_type,
            ..
        } => {
            type_term_contains_unknown_or_opaque(check)
                || type_term_contains_unknown_or_opaque(extends)
                || type_term_contains_unknown_or_opaque(true_type)
                || type_term_contains_unknown_or_opaque(false_type)
        }
        TypeTerm::Mapped {
            key_constraint,
            value_type,
            ..
        } => {
            mapped_key_contains_unknown_or_opaque(key_constraint)
                || type_term_contains_unknown_or_opaque(value_type)
        }
        TypeTerm::Object { properties, .. } => properties
            .iter()
            .any(|property| type_term_contains_unknown_or_opaque(&property.ty)),
        TypeTerm::IndexedAccess { object, index, .. } => {
            type_term_contains_unknown_or_opaque(object)
                || type_term_contains_unknown_or_opaque(index)
        }
    }
}

fn mapped_key_contains_unknown_or_opaque(key: &MappedKeyTerm) -> bool {
    match key {
        MappedKeyTerm::Keyof { target } => type_term_contains_unknown_or_opaque(target),
        MappedKeyTerm::Type(ty) => type_term_contains_unknown_or_opaque(ty),
    }
}

fn lowered_value_type_term(
    value: &LoweredValue,
    span: Span,
    aliases: &AliasExpansionContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> TypeTerm {
    match value {
        LoweredValue::Undefined => TypeTerm::Named {
            name: "undefined".to_string(),
            span,
        },
        LoweredValue::Null => TypeTerm::Named {
            name: "null".to_string(),
            span,
        },
        LoweredValue::String(_) => TypeTerm::Named {
            name: "string".to_string(),
            span,
        },
        LoweredValue::Number(_) => TypeTerm::Named {
            name: "number".to_string(),
            span,
        },
        LoweredValue::Boolean(_) => TypeTerm::Named {
            name: "boolean".to_string(),
            span,
        },
        LoweredValue::BigInt(_) => TypeTerm::Named {
            name: "bigint".to_string(),
            span,
        },
        LoweredValue::FunctionRef(_) | LoweredValue::ClassConstructorRef(_) => {
            TypeTerm::Unknown { span }
        }
        LoweredValue::Array(elements) => {
            let element_types: Vec<_> = elements
                .iter()
                .map(|element| lowered_value_type_term(element, span, aliases, diagnostics))
                .collect();
            let element_type = best_common_type(&element_types, aliases, diagnostics)
                .unwrap_or(TypeTerm::Unknown { span });
            TypeTerm::TypeRef {
                name: "Array".to_string(),
                type_args: vec![element_type],
                span,
            }
        }
        LoweredValue::Object(properties) => TypeTerm::Object {
            properties: properties
                .iter()
                .map(|property| ObjectPropertyTerm {
                    name: property.name.clone(),
                    ty: lowered_value_type_term(&property.value, span, aliases, diagnostics),
                    readonly: false,
                    optional: false,
                    span,
                })
                .collect(),
            span,
        },
    }
}

fn diagnose_async_callback_import_edge(
    compartment: &CompartmentDecl,
    function: &ExportedFunction,
) -> Option<LoweringDiagnostic> {
    if function.body.statements.len() != 1 {
        return None;
    }
    let BodyStmt::Return(ret) = &function.body.statements[0] else {
        return None;
    };
    let argument = ret.argument.as_ref()?;
    let ExprEnvelopeKind::Call { callee, args, .. } = &argument.kind else {
        return None;
    };
    if args.is_empty() {
        return None;
    }
    let ExprEnvelopeKind::Identifier(imported_name) = &callee.kind else {
        return None;
    };
    let import = find_single_named_import(compartment, imported_name)?;
    import.boundary_clause.as_ref()?;
    Some(LoweringDiagnostic {
        code: LoweringDiagnosticCode::AsyncCallbackBoundaryUnsupported,
        span: argument.span,
        message: format!(
            "CruftScript async/callback boundary validation is not derived yet for imported call `{imported_name}` with {} argument(s)",
            args.len()
        ),
    })
}

fn lower_imported_call_export(
    checked: &CruftScriptCheckedUnit,
    compartment: &CompartmentDecl,
    function: &ExportedFunction,
) -> Option<LoweredFunction> {
    if !function.params.is_empty() || function.body.statements.len() != 1 {
        return None;
    }
    let BodyStmt::Return(ret) = &function.body.statements[0] else {
        return None;
    };
    let argument = ret.argument.as_ref()?;
    let ExprEnvelopeKind::Call { callee, args, .. } = &argument.kind else {
        return None;
    };
    if !args.is_empty() {
        return None;
    }
    let ExprEnvelopeKind::Identifier(imported_name) = &callee.kind else {
        return None;
    };
    let import = find_single_named_import(compartment, imported_name)?;
    let policy = import.boundary_clause.as_ref()?;
    let policy_ref = policy_from_clause(policy)?;
    let default_policy = checked
        .boundary_facts()
        .default_policy
        .as_ref()
        .map(|default| default.policy.as_str());
    let (policy_id, policy_name) =
        boundary_policy_resolution(checked, &policy_ref, default_policy).ok()?;
    let aliases = AliasExpansionContext::new(&checked.report.types);
    let mut expected_diagnostics = Vec::new();
    let expected_type = function.return_type.as_ref().map(|return_type| {
        aliases.expand_for_assignability(&lower_type_term(return_type), &mut expected_diagnostics)
    });

    Some(LoweredFunction {
        compartment: compartment.name.clone(),
        function_name: function.name.clone(),
        arity: 0,
        body: LoweredFunctionBody::ImportedCall(LoweredImportedCall {
            imported_name: imported_name.clone(),
            source: import.source.clone(),
            policy_id,
            policy_name: policy_name.clone(),
            resolution_chain: boundary_resolution_chain("import", &policy_ref, &policy_name),
            sanitizer_defaults: sanitizer_defaults_for_policy_name(checked, &policy_name),
            expected_type,
            span: argument.span,
        }),
        span: function.span,
    })
}

fn find_single_named_import<'a>(
    compartment: &'a CompartmentDecl,
    imported_name: &str,
) -> Option<&'a cruftscript_parser::BoundaryQualifiedImport> {
    compartment.body_items.iter().find_map(|item| match item {
        CompartmentItem::Import(import)
            if import.imported_names.len() == 1
                && import
                    .imported_names
                    .first()
                    .is_some_and(|name| name == imported_name) =>
        {
            Some(import)
        }
        CompartmentItem::Compartment(_) => None,
        _ => None,
    })
}

trait BodyStmtSpan {
    fn span(&self) -> Span;
}

impl BodyStmtSpan for BodyStmt {
    fn span(&self) -> Span {
        match self {
            BodyStmt::LocalDecl(stmt) => stmt.span,
            BodyStmt::Assignment(stmt) => stmt.span,
            BodyStmt::Update(stmt) => stmt.span,
            BodyStmt::Return(stmt) => stmt.span,
            BodyStmt::IfGuard(stmt) => stmt.span,
            BodyStmt::If(stmt) => stmt.span,
            BodyStmt::While(stmt) => stmt.span,
            BodyStmt::For(stmt) => stmt.span,
            BodyStmt::DoWhile(stmt) => stmt.span,
            BodyStmt::Switch(stmt) => stmt.span,
            BodyStmt::Unsupported(stmt) => stmt.span,
        }
    }
}

fn collect_body_facts(
    unit: &cruftscript_parser::CruftScriptSourceUnit,
    types: &TypeEnvironment,
) -> BodyFacts {
    let mut facts = BodyFacts::default();
    let signatures = FunctionSignatureContext::new(types);
    for item in &unit.items {
        let SourceItem::Compartment(compartment) = item else {
            continue;
        };
        collect_compartment_body_facts(compartment, &signatures, &mut facts);
    }
    facts
}

fn collect_compartment_body_facts(
    compartment: &CompartmentDecl,
    signatures: &FunctionSignatureContext<'_>,
    facts: &mut BodyFacts,
) {
    for body_item in &compartment.body_items {
        match body_item {
            CompartmentItem::ExportFunction(function) => {
                facts.functions.push(collect_function_body_fact(
                    &compartment.name,
                    function,
                    signatures,
                ));
            }
            CompartmentItem::Compartment(nested) => {
                collect_compartment_body_facts(nested, signatures, facts)
            }
            CompartmentItem::Import(_)
            | CompartmentItem::Class(_)
            | CompartmentItem::TypeAlias(_) => {}
        }
    }
}

fn collect_function_body_fact(
    compartment_name: &str,
    function: &ExportedFunction,
    signatures: &FunctionSignatureContext<'_>,
) -> FunctionBodyFact {
    let mut fact = FunctionBodyFact {
        compartment: compartment_name.to_string(),
        function_name: function.name.clone(),
        span: function.body_span,
        statements: Vec::new(),
        locals: Vec::new(),
        returns: Vec::new(),
        guards: Vec::new(),
        return_paths: Vec::new(),
    };

    fact.statements = collect_body_stmt_facts(
        &function.body.statements,
        &mut fact.locals,
        &mut fact.returns,
        &mut fact.guards,
        &mut fact.return_paths,
        signatures,
    );
    if !body_statements_always_return(&fact.statements) {
        fact.return_paths.push(ReturnPathFact {
            kind: ReturnPathFactKind::FunctionMayFallThrough,
            span: function.body_span,
        });
    }

    fact
}

fn collect_body_stmt_facts(
    statements: &[BodyStmt],
    locals: &mut Vec<LocalDeclFact>,
    returns: &mut Vec<ReturnFact>,
    guards: &mut Vec<NarrowingGuardFact>,
    return_paths: &mut Vec<ReturnPathFact>,
    signatures: &FunctionSignatureContext<'_>,
) -> Vec<BodyStmtFact> {
    let mut facts = Vec::new();
    for statement in statements {
        match statement {
            BodyStmt::LocalDecl(local) => {
                let fact = LocalDeclFact {
                    name: local.name.clone(),
                    mutable: local.mutable,
                    type_annotation: local.type_annotation.as_ref().map(lower_type_term),
                    initializer: local.initializer.as_ref().map(lower_expression_fact),
                    span: local.span,
                };
                locals.push(fact.clone());
                facts.push(BodyStmtFact::LocalDecl(fact));
            }
            BodyStmt::Assignment(assignment) => {
                facts.push(BodyStmtFact::Assignment(AssignmentFact {
                    target: lower_assignment_target_fact(&assignment.target),
                    value: lower_expression_fact(&assignment.value),
                    span: assignment.span,
                }));
            }
            BodyStmt::Update(update) => {
                facts.push(BodyStmtFact::Update(UpdateFact {
                    target: lower_update_target_fact(&update.target),
                    op: update.op,
                    position: update.position,
                    span: update.span,
                }));
            }
            BodyStmt::Return(return_stmt) => {
                let fact = ReturnFact {
                    argument: return_stmt.argument.as_ref().map(lower_expression_fact),
                    span: return_stmt.span,
                };
                returns.push(fact.clone());
                return_paths.push(ReturnPathFact {
                    kind: ReturnPathFactKind::DirectReturn,
                    span: return_stmt.span,
                });
                facts.push(BodyStmtFact::Return(fact));
            }
            BodyStmt::IfGuard(guard) => {
                if let Some(kind) = lower_narrowing_guard_fact(guard) {
                    let fact = NarrowingGuardFact {
                        kind,
                        span: guard.span,
                    };
                    guards.push(fact.clone());
                    facts.push(BodyStmtFact::IfGuard(fact));
                }
            }
            BodyStmt::If(if_stmt) => {
                let subject = lower_expression_fact(&if_stmt.subject);
                if let Some(guard) = lower_expression_narrowing_guard_parts(
                    &subject,
                    &if_stmt.guard,
                    &ValueEnvironment::default(),
                    signatures,
                ) {
                    guards.push(guard.clone());
                    let then_body = collect_body_stmt_facts(
                        &if_stmt.then_body.statements,
                        locals,
                        returns,
                        guards,
                        return_paths,
                        signatures,
                    );
                    let else_body = if let Some(else_body) = &if_stmt.else_body {
                        collect_body_stmt_facts(
                            &else_body.statements,
                            locals,
                            returns,
                            guards,
                            return_paths,
                            signatures,
                        )
                    } else {
                        Vec::new()
                    };
                    let then_returns = body_statements_always_return(&then_body);
                    let else_returns =
                        !else_body.is_empty() && body_statements_always_return(&else_body);
                    if then_returns {
                        return_paths.push(ReturnPathFact {
                            kind: ReturnPathFactKind::IfThenReturns,
                            span: if_stmt.span,
                        });
                    }
                    if else_returns {
                        return_paths.push(ReturnPathFact {
                            kind: ReturnPathFactKind::IfElseReturns,
                            span: if_stmt.span,
                        });
                    }
                    if then_returns && else_returns {
                        return_paths.push(ReturnPathFact {
                            kind: ReturnPathFactKind::IfBothBranchesReturn,
                            span: if_stmt.span,
                        });
                    }
                    facts.push(BodyStmtFact::If(IfFact {
                        guard,
                        then_body,
                        else_body,
                        then_returns,
                        else_returns,
                        span: if_stmt.span,
                    }));
                }
            }
            BodyStmt::While(while_stmt) => {
                let subject = lower_expression_fact(&while_stmt.subject);
                if let Some(guard) = lower_expression_narrowing_guard_parts(
                    &subject,
                    &while_stmt.guard,
                    &ValueEnvironment::default(),
                    signatures,
                ) {
                    guards.push(guard.clone());
                    let body = collect_body_stmt_facts(
                        &while_stmt.body.statements,
                        locals,
                        returns,
                        guards,
                        return_paths,
                        signatures,
                    );
                    facts.push(BodyStmtFact::While(WhileFact {
                        guard,
                        body,
                        span: while_stmt.span,
                    }));
                }
            }
            BodyStmt::For(for_stmt) => {
                let subject = lower_expression_fact(&for_stmt.subject);
                if let Some(guard) = lower_expression_narrowing_guard_parts(
                    &subject,
                    &for_stmt.guard,
                    &ValueEnvironment::default(),
                    signatures,
                ) {
                    guards.push(guard.clone());
                    let body = collect_body_stmt_facts(
                        &for_stmt.body.statements,
                        locals,
                        returns,
                        guards,
                        return_paths,
                        signatures,
                    );
                    facts.push(BodyStmtFact::For(ForFact {
                        guard,
                        body,
                        span: for_stmt.span,
                    }));
                }
            }
            BodyStmt::DoWhile(do_while_stmt) => {
                let subject = lower_expression_fact(&do_while_stmt.subject);
                if let Some(guard) = lower_expression_narrowing_guard_parts(
                    &subject,
                    &do_while_stmt.guard,
                    &ValueEnvironment::default(),
                    signatures,
                ) {
                    guards.push(guard.clone());
                    let body = collect_body_stmt_facts(
                        &do_while_stmt.body.statements,
                        locals,
                        returns,
                        guards,
                        return_paths,
                        signatures,
                    );
                    facts.push(BodyStmtFact::DoWhile(DoWhileFact {
                        guard,
                        body,
                        span: do_while_stmt.span,
                    }));
                }
            }
            BodyStmt::Switch(switch_stmt) => {
                let cases = switch_stmt
                    .cases
                    .iter()
                    .map(|case| {
                        let body = collect_body_stmt_facts(
                            &case.body.statements,
                            locals,
                            returns,
                            guards,
                            return_paths,
                            signatures,
                        );
                        let returns = body_statements_always_return(&body);
                        if returns {
                            return_paths.push(ReturnPathFact {
                                kind: ReturnPathFactKind::DirectReturn,
                                span: case.span,
                            });
                        }
                        SwitchCaseFact {
                            test: lower_expression_fact(&case.test),
                            body,
                            returns,
                            span: case.span,
                        }
                    })
                    .collect();
                let default = switch_stmt
                    .default
                    .as_ref()
                    .map(|body| {
                        collect_body_stmt_facts(
                            &body.statements,
                            locals,
                            returns,
                            guards,
                            return_paths,
                            signatures,
                        )
                    })
                    .unwrap_or_default();
                facts.push(BodyStmtFact::Switch(SwitchFact {
                    subject: lower_expression_fact(&switch_stmt.subject),
                    cases,
                    default,
                    span: switch_stmt.span,
                }));
            }
            BodyStmt::Unsupported(stmt) => {
                facts.push(BodyStmtFact::Unsupported(UnsupportedStmtFact {
                    spelling: stmt.spelling.clone(),
                    span: stmt.span,
                }));
            }
        }
    }
    facts
}

fn body_statements_always_return(statements: &[BodyStmtFact]) -> bool {
    statements.iter().any(|statement| match statement {
        BodyStmtFact::Return(_) => true,
        BodyStmtFact::If(if_fact) => if_fact.then_returns && if_fact.else_returns,
        BodyStmtFact::While(_) => false,
        BodyStmtFact::For(_) => false,
        BodyStmtFact::DoWhile(_) => false,
        BodyStmtFact::Switch(switch_fact) => {
            !switch_fact.default.is_empty()
                && body_statements_always_return(&switch_fact.default)
                && switch_fact.cases.iter().all(|case| case.returns)
        }
        BodyStmtFact::LocalDecl(_)
        | BodyStmtFact::Assignment(_)
        | BodyStmtFact::Update(_)
        | BodyStmtFact::IfGuard(_)
        | BodyStmtFact::Unsupported(_) => false,
    })
}

fn lower_update_target_fact(target: &cruftscript_parser::UpdateTarget) -> UpdateTargetFact {
    match target {
        cruftscript_parser::UpdateTarget::Local(name) => UpdateTargetFact::Local(name.clone()),
        cruftscript_parser::UpdateTarget::Property {
            object,
            property,
            optional,
        } => UpdateTargetFact::Property {
            object: lower_expression_fact(object),
            property: property.clone(),
            optional: *optional,
        },
        cruftscript_parser::UpdateTarget::Element {
            object,
            index,
            optional,
        } => UpdateTargetFact::Element {
            object: lower_expression_fact(object),
            index: lower_expression_fact(index),
            optional: *optional,
        },
        cruftscript_parser::UpdateTarget::Unsupported(expr) => {
            UpdateTargetFact::Unsupported(lower_expression_fact(expr))
        }
    }
}

fn lower_assignment_target_fact(
    target: &cruftscript_parser::AssignmentTarget,
) -> AssignmentTargetFact {
    match target {
        cruftscript_parser::AssignmentTarget::Local(name) => {
            AssignmentTargetFact::Local(name.clone())
        }
        cruftscript_parser::AssignmentTarget::Property {
            object,
            property,
            optional,
        } => AssignmentTargetFact::Property {
            object: lower_expression_fact(object),
            property: property.clone(),
            optional: *optional,
        },
        cruftscript_parser::AssignmentTarget::Element {
            object,
            index,
            optional,
        } => AssignmentTargetFact::Element {
            object: lower_expression_fact(object),
            index: lower_expression_fact(index),
            optional: *optional,
        },
        cruftscript_parser::AssignmentTarget::Unsupported(expr) => {
            AssignmentTargetFact::Unsupported(lower_expression_fact(expr))
        }
    }
}

fn lower_expression_fact(expr: &ExprEnvelope) -> ExpressionFact {
    let kind = match &expr.kind {
        ExprEnvelopeKind::Identifier(name) => ExpressionFactKind::Identifier(name.clone()),
        ExprEnvelopeKind::StringLiteral(value) => ExpressionFactKind::StringLiteral(value.clone()),
        ExprEnvelopeKind::NumberLiteral(value) => ExpressionFactKind::NumberLiteral(value.clone()),
        ExprEnvelopeKind::BooleanLiteral(value) => ExpressionFactKind::BooleanLiteral(*value),
        ExprEnvelopeKind::NullLiteral => ExpressionFactKind::NullLiteral,
        ExprEnvelopeKind::ArrayLiteral(elements) => {
            ExpressionFactKind::ArrayLiteral(elements.iter().map(lower_expression_fact).collect())
        }
        ExprEnvelopeKind::ObjectLiteral(properties) => ExpressionFactKind::ObjectLiteral(
            properties
                .iter()
                .map(|property| ObjectLiteralFact {
                    name: property.name.clone(),
                    value: lower_expression_fact(&property.value),
                    span: property.span,
                })
                .collect(),
        ),
        ExprEnvelopeKind::PropertyAccess {
            object,
            property,
            optional,
        } => ExpressionFactKind::PropertyAccess {
            object: Box::new(lower_expression_fact(object)),
            property: property.clone(),
            optional: *optional,
        },
        ExprEnvelopeKind::ElementAccess {
            object,
            index,
            optional,
        } => ExpressionFactKind::ElementAccess {
            object: Box::new(lower_expression_fact(object)),
            index: Box::new(lower_expression_fact(index)),
            optional: *optional,
        },
        ExprEnvelopeKind::Call {
            callee,
            args,
            optional,
        } => ExpressionFactKind::Call {
            callee: Box::new(lower_expression_fact(callee)),
            args: args.iter().map(lower_expression_fact).collect(),
            optional: *optional,
        },
        ExprEnvelopeKind::New { class_name, args } => ExpressionFactKind::New {
            class_name: class_name.clone(),
            args: args.iter().map(lower_expression_fact).collect(),
        },
        ExprEnvelopeKind::BinaryAdd { left, right } => ExpressionFactKind::BinaryAdd {
            left: Box::new(lower_expression_fact(left)),
            right: Box::new(lower_expression_fact(right)),
        },
        ExprEnvelopeKind::BinarySub { left, right } => ExpressionFactKind::BinarySub {
            left: Box::new(lower_expression_fact(left)),
            right: Box::new(lower_expression_fact(right)),
        },
        ExprEnvelopeKind::BinaryMul { left, right } => ExpressionFactKind::BinaryMul {
            left: Box::new(lower_expression_fact(left)),
            right: Box::new(lower_expression_fact(right)),
        },
        ExprEnvelopeKind::BinaryPow { left, right } => ExpressionFactKind::BinaryPow {
            left: Box::new(lower_expression_fact(left)),
            right: Box::new(lower_expression_fact(right)),
        },
        ExprEnvelopeKind::BinaryDiv { left, right } => ExpressionFactKind::BinaryDiv {
            left: Box::new(lower_expression_fact(left)),
            right: Box::new(lower_expression_fact(right)),
        },
        ExprEnvelopeKind::BinaryRem { left, right } => ExpressionFactKind::BinaryRem {
            left: Box::new(lower_expression_fact(left)),
            right: Box::new(lower_expression_fact(right)),
        },
        ExprEnvelopeKind::NullishCoalesce { left, right } => ExpressionFactKind::NullishCoalesce {
            left: Box::new(lower_expression_fact(left)),
            right: Box::new(lower_expression_fact(right)),
        },
        ExprEnvelopeKind::BinaryBitwiseAnd { left, right } => {
            ExpressionFactKind::BinaryBitwiseAnd {
                left: Box::new(lower_expression_fact(left)),
                right: Box::new(lower_expression_fact(right)),
            }
        }
        ExprEnvelopeKind::BinaryBitwiseOr { left, right } => ExpressionFactKind::BinaryBitwiseOr {
            left: Box::new(lower_expression_fact(left)),
            right: Box::new(lower_expression_fact(right)),
        },
        ExprEnvelopeKind::BinaryBitwiseXor { left, right } => {
            ExpressionFactKind::BinaryBitwiseXor {
                left: Box::new(lower_expression_fact(left)),
                right: Box::new(lower_expression_fact(right)),
            }
        }
        ExprEnvelopeKind::BinaryShiftLeft { left, right } => ExpressionFactKind::BinaryShiftLeft {
            left: Box::new(lower_expression_fact(left)),
            right: Box::new(lower_expression_fact(right)),
        },
        ExprEnvelopeKind::BinaryShiftRight { left, right } => {
            ExpressionFactKind::BinaryShiftRight {
                left: Box::new(lower_expression_fact(left)),
                right: Box::new(lower_expression_fact(right)),
            }
        }
        ExprEnvelopeKind::BinaryLessThan { left, right } => ExpressionFactKind::BinaryLessThan {
            left: Box::new(lower_expression_fact(left)),
            right: Box::new(lower_expression_fact(right)),
        },
        ExprEnvelopeKind::BinaryGreaterThan { left, right } => {
            ExpressionFactKind::BinaryGreaterThan {
                left: Box::new(lower_expression_fact(left)),
                right: Box::new(lower_expression_fact(right)),
            }
        }
        ExprEnvelopeKind::BinaryLessThanOrEqual { left, right } => {
            ExpressionFactKind::BinaryLessThanOrEqual {
                left: Box::new(lower_expression_fact(left)),
                right: Box::new(lower_expression_fact(right)),
            }
        }
        ExprEnvelopeKind::BinaryGreaterThanOrEqual { left, right } => {
            ExpressionFactKind::BinaryGreaterThanOrEqual {
                left: Box::new(lower_expression_fact(left)),
                right: Box::new(lower_expression_fact(right)),
            }
        }
        ExprEnvelopeKind::BinaryStrictEqual { left, right } => {
            ExpressionFactKind::BinaryStrictEqual {
                left: Box::new(lower_expression_fact(left)),
                right: Box::new(lower_expression_fact(right)),
            }
        }
        ExprEnvelopeKind::BinaryStrictNotEqual { left, right } => {
            ExpressionFactKind::BinaryStrictNotEqual {
                left: Box::new(lower_expression_fact(left)),
                right: Box::new(lower_expression_fact(right)),
            }
        }
        ExprEnvelopeKind::LogicalAnd { left, right } => ExpressionFactKind::LogicalAnd {
            left: Box::new(lower_expression_fact(left)),
            right: Box::new(lower_expression_fact(right)),
        },
        ExprEnvelopeKind::LogicalOr { left, right } => ExpressionFactKind::LogicalOr {
            left: Box::new(lower_expression_fact(left)),
            right: Box::new(lower_expression_fact(right)),
        },
        ExprEnvelopeKind::LogicalNot { expr } => ExpressionFactKind::LogicalNot {
            expr: Box::new(lower_expression_fact(expr)),
        },
        ExprEnvelopeKind::UnaryMinus { expr } => ExpressionFactKind::UnaryMinus {
            expr: Box::new(lower_expression_fact(expr)),
        },
        ExprEnvelopeKind::Update {
            target,
            op,
            position,
        } => ExpressionFactKind::Update {
            target: Box::new(lower_expression_fact(target)),
            op: *op,
            position: *position,
        },
        ExprEnvelopeKind::Delete { target } => ExpressionFactKind::Delete {
            target: Box::new(lower_expression_fact(target)),
        },
        ExprEnvelopeKind::Conditional {
            subject,
            guard,
            consequent,
            alternate,
        } => ExpressionFactKind::Conditional {
            subject: Box::new(lower_expression_fact(subject)),
            guard: guard.clone(),
            consequent: Box::new(lower_expression_fact(consequent)),
            alternate: Box::new(lower_expression_fact(alternate)),
        },
        ExprEnvelopeKind::Ternary {
            condition,
            consequent,
            alternate,
        } => ExpressionFactKind::Ternary {
            condition: Box::new(lower_expression_fact(condition)),
            consequent: Box::new(lower_expression_fact(consequent)),
            alternate: Box::new(lower_expression_fact(alternate)),
        },
        ExprEnvelopeKind::LetIn { name, value, body } => ExpressionFactKind::LetIn {
            name: name.clone(),
            value: Box::new(lower_expression_fact(value)),
            body: Box::new(lower_expression_fact(body)),
        },
        ExprEnvelopeKind::Assertion {
            expr,
            target,
            satisfies,
        } => ExpressionFactKind::Assertion {
            expr: Box::new(lower_expression_fact(expr)),
            target: lower_type_term(target),
            satisfies: *satisfies,
        },
        ExprEnvelopeKind::Arrow { params, body } => ExpressionFactKind::Arrow {
            params: params
                .iter()
                .map(|p| ArrowParamFact {
                    name: p.name.clone(),
                    ty: lower_type_term(&p.ty),
                    span: p.span,
                })
                .collect(),
            body: Box::new(lower_expression_fact(body)),
        },
        ExprEnvelopeKind::NonNull { expr } => ExpressionFactKind::NonNull {
            expr: Box::new(lower_expression_fact(expr)),
        },
        ExprEnvelopeKind::Opaque(spelling) => ExpressionFactKind::Opaque(spelling.clone()),
    };
    ExpressionFact {
        kind,
        span: expr.span,
    }
}

fn lower_narrowing_guard_fact(
    guard: &cruftscript_parser::IfGuardStmt,
) -> Option<NarrowingGuardFactKind> {
    lower_narrowing_guard_parts(&guard.subject, &guard.guard)
}

fn lower_narrowing_guard_parts(
    subject_expr: &cruftscript_parser::ExprEnvelope,
    guard: &NarrowingGuard,
) -> Option<NarrowingGuardFactKind> {
    let subject = narrowing_subject_spelling(subject_expr)?;
    match guard {
        NarrowingGuard::TypeofEquals { expected, .. } => {
            Some(NarrowingGuardFactKind::TypeofEquals {
                subject: subject.clone(),
                expected: expected.clone(),
            })
        }
        NarrowingGuard::Instanceof { constructor, .. } => {
            Some(NarrowingGuardFactKind::Instanceof {
                subject: subject.clone(),
                constructor: constructor.clone(),
            })
        }
        NarrowingGuard::OwnProperty { property, .. } => Some(NarrowingGuardFactKind::OwnProperty {
            subject: subject.clone(),
            property: property.clone(),
        }),
        NarrowingGuard::DynamicOwnProperty { key, .. } => {
            Some(NarrowingGuardFactKind::DynamicOwnProperty {
                subject: subject.clone(),
                key: lower_expression_fact(key),
            })
        }
        NarrowingGuard::Truthy { .. } => Some(NarrowingGuardFactKind::Truthy {
            subject: subject.clone(),
        }),
    }
}

fn narrowing_subject_spelling(subject_expr: &cruftscript_parser::ExprEnvelope) -> Option<String> {
    match &subject_expr.kind {
        ExprEnvelopeKind::Identifier(subject) => Some(subject.clone()),
        ExprEnvelopeKind::PropertyAccess {
            object,
            property,
            optional: false,
        } => narrowing_subject_spelling(object).map(|object| format!("{object}.{property}")),
        _ => None,
    }
}

fn check_expressions(
    bindings: &BindingEnvironment,
    types: &TypeEnvironment,
    boundary_facts: &BoundaryFacts,
    body_facts: &BodyFacts,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> ExpressionChecks {
    let mut checks = ExpressionChecks::default();
    let aliases = AliasExpansionContext::new(types);
    let signatures = FunctionSignatureContext::new(types);

    for body in &body_facts.functions {
        let signature = types
            .function_signatures
            .iter()
            .find(|signature| signature.name == body.function_name);
        let compartment_binding = bindings
            .compartments
            .iter()
            .find(|compartment| compartment.name == body.compartment);
        let function_binding = compartment_binding.and_then(|compartment| {
            compartment
                .functions
                .iter()
                .find(|function| function.name == body.function_name)
        });
        let (Some(signature), Some(compartment_binding), Some(function_binding)) =
            (signature, compartment_binding, function_binding)
        else {
            continue;
        };

        checks.functions.push(check_function_expressions(
            body,
            signature,
            compartment_binding,
            function_binding,
            bindings,
            boundary_facts,
            &aliases,
            &signatures,
            diagnostics,
        ));
    }

    checks
}

fn check_function_expressions(
    body: &FunctionBodyFact,
    signature: &FunctionSignature,
    compartment: &CompartmentBinding,
    binding: &FunctionBinding,
    bindings: &BindingEnvironment,
    boundary_facts: &BoundaryFacts,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> FunctionExpressionCheck {
    let mut env = ValueEnvironment::default();
    let mut value_bindings = Vec::new();
    let mut returns = Vec::new();

    for endowment in &compartment.endowments {
        let value = ValueBindingFact {
            name: endowment.name.clone(),
            ty: endowment.ty.clone(),
            source: ValueBindingSource::Endowment,
            mutable: false,
            constructed_class: None,
            span: endowment.span,
        };
        env.insert(value.clone(), diagnostics);
        value_bindings.push(value);
    }

    for name in cruftscript_intrinsic_name_allowlist() {
        if env.get(name).is_some() {
            continue;
        }
        let value = ValueBindingFact {
            name: (*name).to_string(),
            ty: TypeTerm::Unknown {
                span: compartment.span,
            },
            source: ValueBindingSource::Intrinsic,
            mutable: false,
            constructed_class: None,
            span: compartment.span,
        };
        env.insert(value.clone(), diagnostics);
        value_bindings.push(value);
    }

    for function in &compartment.functions {
        if function.name == signature.name || env.get(&function.name).is_some() {
            continue;
        }
        if let Some(function_signature) = signatures.get(&function.name) {
            let value = ValueBindingFact {
                name: function.name.clone(),
                ty: function_signature_type_term(function_signature),
                source: ValueBindingSource::Function,
                mutable: false,
                constructed_class: None,
                span: function.span,
            };
            env.insert(value.clone(), diagnostics);
            value_bindings.push(value);
        }
    }

    for class_constructor in aliases.class_constructors.values() {
        if env.get(&class_constructor.name).is_some() {
            continue;
        }
        let value = ValueBindingFact {
            name: class_constructor.name.clone(),
            ty: class_constructor_type_term(class_constructor),
            source: ValueBindingSource::ClassConstructor,
            mutable: false,
            constructed_class: None,
            span: class_constructor.span,
        };
        env.insert(value.clone(), diagnostics);
        value_bindings.push(value);
    }

    for (idx, param) in signature.params.iter().enumerate() {
        let span = binding
            .params
            .get(idx)
            .map(|binding| binding.span)
            .unwrap_or(param.span);
        let value = ValueBindingFact {
            name: param.name.clone(),
            ty: param.ty.clone(),
            source: ValueBindingSource::Parameter,
            mutable: false,
            constructed_class: None,
            span,
        };
        env.insert(value.clone(), diagnostics);
        value_bindings.push(value);
    }

    let declared_return = signature.return_type.as_ref();
    check_body_statements(
        &body.statements,
        &mut env,
        declared_return,
        &body.compartment,
        bindings,
        boundary_facts,
        aliases,
        signatures,
        diagnostics,
        &mut value_bindings,
        &mut returns,
    );

    FunctionExpressionCheck {
        compartment: body.compartment.clone(),
        function_name: body.function_name.clone(),
        value_bindings,
        returns,
    }
}

fn check_body_statements(
    statements: &[BodyStmtFact],
    env: &mut ValueEnvironment,
    declared_return: Option<&TypeTerm>,
    compartment: &str,
    bindings: &BindingEnvironment,
    boundary_facts: &BoundaryFacts,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
    value_bindings: &mut Vec<ValueBindingFact>,
    returns: &mut Vec<TypedReturnFact>,
) {
    for statement in statements {
        match statement {
            BodyStmtFact::LocalDecl(local) => {
                let initializer_type = local
                    .initializer
                    .as_ref()
                    .map(|expr| type_expression_fact(expr, env, aliases, signatures, diagnostics));

                let annotation_is_any =
                    local.type_annotation.as_ref().is_some_and(type_term_is_any);
                if annotation_is_any {
                    diagnostics.push(CheckDiagnostic {
                        code: CheckDiagnosticCode::AnyTypeRejected,
                        severity: DiagnosticSeverity::Error,
                        span: local.span,
                        message: "`any` is not a CruftScript type; use `unknown` and narrow it"
                            .to_string(),
                    });
                }
                if let (Some(initializer), Some(expected)) =
                    (local.initializer.as_ref(), local.type_annotation.as_ref())
                {
                    if !annotation_is_any
                        && !expression_fact_conforms_to_type(
                            initializer,
                            expected,
                            env,
                            aliases,
                            signatures,
                            diagnostics,
                        )
                    {
                        diagnostics.push(CheckDiagnostic {
                            code: CheckDiagnosticCode::LocalInitializerTypeMismatch,
                            severity: DiagnosticSeverity::Error,
                            span: local.span,
                            message: format!(
                                "initializer for local `{}` does not conform to its annotation",
                                local.name
                            ),
                        });
                    }
                }
                let ty = local_binding_type_after_initializer_proof(
                    local.type_annotation.as_ref(),
                    initializer_type.as_ref(),
                    local.span,
                );
                let constructed_class = immutable_local_constructed_class(
                    local.initializer.as_ref(),
                    initializer_type.as_ref(),
                    local.mutable,
                    env,
                    aliases,
                );
                let value = ValueBindingFact {
                    name: local.name.clone(),
                    ty,
                    source: ValueBindingSource::Local,
                    mutable: local.mutable,
                    constructed_class,
                    span: local.span,
                };
                env.insert(value.clone(), diagnostics);
                env.record_static_primitive(&local.name, local.initializer.as_ref(), local.mutable);
                value_bindings.push(value);
            }
            BodyStmtFact::Assignment(assignment) => {
                check_assignment_fact(assignment, env, aliases, signatures, diagnostics);
            }
            BodyStmtFact::Update(update) => {
                check_update_fact(update, env, aliases, signatures, diagnostics);
            }
            BodyStmtFact::Return(ret) => {
                check_return_fact(
                    ret,
                    env,
                    declared_return,
                    compartment,
                    bindings,
                    boundary_facts,
                    aliases,
                    signatures,
                    diagnostics,
                    returns,
                );
            }
            BodyStmtFact::IfGuard(guard) => {
                validate_supported_narrowing_guard(guard, env, aliases, diagnostics);
                validate_narrowing_guard_value_types(guard, env, aliases, signatures, diagnostics);
                apply_guard_refinement(guard, env);
            }
            BodyStmtFact::If(if_fact) => {
                let mut then_env = env.clone();
                validate_supported_narrowing_guard(&if_fact.guard, env, aliases, diagnostics);
                validate_narrowing_guard_value_types(
                    &if_fact.guard,
                    env,
                    aliases,
                    signatures,
                    diagnostics,
                );
                apply_guard_refinement(&if_fact.guard, &mut then_env);
                check_body_statements(
                    &if_fact.then_body,
                    &mut then_env,
                    declared_return,
                    compartment,
                    bindings,
                    boundary_facts,
                    aliases,
                    signatures,
                    diagnostics,
                    value_bindings,
                    returns,
                );

                let mut else_env = env.clone();
                apply_guard_negative_refinement(&if_fact.guard, &mut else_env, aliases);
                check_body_statements(
                    &if_fact.else_body,
                    &mut else_env,
                    declared_return,
                    compartment,
                    bindings,
                    boundary_facts,
                    aliases,
                    signatures,
                    diagnostics,
                    value_bindings,
                    returns,
                );
            }
            BodyStmtFact::While(while_fact) => {
                diagnostics.push(CheckDiagnostic {
                    code: CheckDiagnosticCode::UnsupportedBodyExpression,
                    severity: DiagnosticSeverity::Error,
                    span: while_fact.span,
                    message: "minimal CruftScript exported function lowering does not admit while loops in this substrate generation"
                        .to_string(),
                });
            }
            BodyStmtFact::For(for_fact) => {
                diagnostics.push(CheckDiagnostic {
                    code: CheckDiagnosticCode::UnsupportedBodyExpression,
                    severity: DiagnosticSeverity::Error,
                    span: for_fact.span,
                    message: "minimal CruftScript exported function lowering does not admit for loops in this substrate generation"
                        .to_string(),
                });
            }
            BodyStmtFact::DoWhile(do_while_fact) => {
                diagnostics.push(CheckDiagnostic {
                    code: CheckDiagnosticCode::UnsupportedBodyExpression,
                    severity: DiagnosticSeverity::Error,
                    span: do_while_fact.span,
                    message: "minimal CruftScript exported function lowering does not admit do while loops in this substrate generation"
                        .to_string(),
                });
            }
            BodyStmtFact::Switch(switch_fact) => {
                validate_bounded_switch_fact(
                    switch_fact,
                    env,
                    declared_return,
                    compartment,
                    bindings,
                    boundary_facts,
                    aliases,
                    signatures,
                    diagnostics,
                    value_bindings,
                    returns,
                );
            }
            BodyStmtFact::Unsupported(stmt) => {
                diagnostics.push(CheckDiagnostic {
                    code: CheckDiagnosticCode::UnsupportedBodyExpression,
                    severity: DiagnosticSeverity::Error,
                    span: stmt.span,
                    message: unsupported_write_or_body_message(&stmt.spelling),
                });
            }
        }
    }
}

fn validate_bounded_switch_fact(
    switch_fact: &SwitchFact,
    env: &mut ValueEnvironment,
    declared_return: Option<&TypeTerm>,
    compartment: &str,
    bindings: &BindingEnvironment,
    boundary_facts: &BoundaryFacts,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
    value_bindings: &mut Vec<ValueBindingFact>,
    returns: &mut Vec<TypedReturnFact>,
) {
    let subject_type =
        type_expression_fact(&switch_fact.subject, env, aliases, signatures, diagnostics);
    if !matches!(
        subject_type,
        TypeTerm::Named { ref name, .. }
            if name == "number" || name == "string" || name == "boolean"
    ) {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span: switch_fact.subject.span,
            message:
                "switch subject must be a bounded number, string, or boolean value in this substrate generation"
                    .to_string(),
        });
    }
    for case in &switch_fact.cases {
        let case_type = type_expression_fact(&case.test, env, aliases, signatures, diagnostics);
        if !switch_case_label_is_bounded_primitive(&case.test, env)
            || !expression_fact_conforms_to_type(
                &case.test,
                &subject_type,
                env,
                aliases,
                signatures,
                diagnostics,
            )
            || !matches!(
                case_type,
                TypeTerm::Named { ref name, .. }
                    if name == "number" || name == "string" || name == "boolean"
            )
        {
            diagnostics.push(CheckDiagnostic {
                code: CheckDiagnosticCode::UnsupportedBodyExpression,
                severity: DiagnosticSeverity::Error,
                span: case.test.span,
                message:
                    "switch case labels must be literal or immutable primitive values conforming to the switch subject"
                        .to_string(),
            });
        }
        let mut case_env = env.clone();
        check_body_statements(
            &case.body,
            &mut case_env,
            declared_return,
            compartment,
            bindings,
            boundary_facts,
            aliases,
            signatures,
            diagnostics,
            value_bindings,
            returns,
        );
    }
    let mut default_env = env.clone();
    check_body_statements(
        &switch_fact.default,
        &mut default_env,
        declared_return,
        compartment,
        bindings,
        boundary_facts,
        aliases,
        signatures,
        diagnostics,
        value_bindings,
        returns,
    );
}

fn switch_case_label_is_literal(expr: &ExpressionFact) -> bool {
    matches!(
        expr.kind,
        ExpressionFactKind::StringLiteral(_)
            | ExpressionFactKind::NumberLiteral(_)
            | ExpressionFactKind::BooleanLiteral(_)
    )
}

fn switch_case_label_is_bounded_primitive(expr: &ExpressionFact, env: &ValueEnvironment) -> bool {
    if switch_case_label_is_literal(expr) {
        return true;
    }
    let ExpressionFactKind::Identifier(name) = &expr.kind else {
        return false;
    };
    env.get(name)
        .is_some_and(|binding| !binding.mutable && env.static_primitive(name).is_some())
}

fn check_assignment_fact(
    assignment: &AssignmentFact,
    env: &mut ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) {
    match &assignment.target {
        AssignmentTargetFact::Local(target) => {
            check_local_assignment_fact(target, assignment, env, aliases, signatures, diagnostics);
        }
        AssignmentTargetFact::Property {
            object,
            property,
            optional,
        } => {
            check_property_assignment_fact(
                object,
                property,
                *optional,
                assignment,
                env,
                aliases,
                signatures,
                diagnostics,
            );
        }
        AssignmentTargetFact::Element {
            object,
            index,
            optional,
        } => {
            check_element_assignment_fact(
                object,
                index,
                *optional,
                assignment,
                env,
                aliases,
                signatures,
                diagnostics,
            );
        }
        AssignmentTargetFact::Unsupported(target) => {
            let _ = type_expression_fact(target, env, aliases, signatures, diagnostics);
            let _ = type_expression_fact(&assignment.value, env, aliases, signatures, diagnostics);
            diagnostics.push(CheckDiagnostic {
                code: CheckDiagnosticCode::UnsupportedBodyExpression,
                severity: DiagnosticSeverity::Error,
                span: assignment.span,
                message: "assignment target is not a supported P2 writable local, object property, or array element"
                    .to_string(),
            });
        }
    }
}

fn check_update_fact(
    update: &UpdateFact,
    env: &mut ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) {
    let _ = update_position_name(update.position);
    match &update.target {
        UpdateTargetFact::Local(target) => {
            let _ = check_local_update_target(target, update.span, env, aliases, diagnostics);
        }
        UpdateTargetFact::Property {
            object,
            property,
            optional,
        } => {
            let _ = check_property_update_target(
                object,
                property,
                *optional,
                update.span,
                env,
                aliases,
                signatures,
                diagnostics,
            );
        }
        UpdateTargetFact::Element {
            object,
            index,
            optional,
        } => {
            let _ = check_element_update_target(
                object,
                index,
                *optional,
                update.span,
                env,
                aliases,
                signatures,
                diagnostics,
            );
        }
        UpdateTargetFact::Unsupported(target) => {
            let _ = type_expression_fact(target, env, aliases, signatures, diagnostics);
            diagnostics.push(CheckDiagnostic {
                code: CheckDiagnosticCode::UnsupportedBodyExpression,
                severity: DiagnosticSeverity::Error,
                span: update.span,
                message: "P2 update expressions support only direct mutable numeric local bindings"
                    .to_string(),
            });
        }
    }
}

fn check_property_update_target(
    object: &ExpressionFact,
    property: &str,
    optional: bool,
    span: Span,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> Option<TypeTerm> {
    if optional {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!(
                "update target property `{property}` is optional/nullish; P2 update requires a proven non-optional object target"
            ),
        });
        return None;
    }
    let ExpressionFactKind::Identifier(object_name) = &object.kind else {
        let _ = type_expression_fact(object, env, aliases, signatures, diagnostics);
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span,
            message:
                "P2 property update supports only direct properties of mutable local object bindings"
                    .to_string(),
        });
        return None;
    };
    let Some(binding) = env.get(object_name).cloned() else {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnresolvedValueRef,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!(
                "update target object `{object_name}` is not a declared local binding"
            ),
        });
        return None;
    };
    if binding.source != ValueBindingSource::Local || !binding.mutable {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!(
                "update target object `{object_name}` is readonly; P2 property update supports only `let` object locals"
            ),
        });
        return None;
    }
    let object_type = aliases.expand_for_assignability(&binding.ty, diagnostics);
    let TypeTerm::Object { properties, .. } = object_type else {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!(
                "update target `{object_name}.{property}` requires a known object type"
            ),
        });
        return None;
    };
    let Some(property_term) = properties
        .iter()
        .find(|candidate| candidate.name == property)
    else {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::PropertyReadUnsupported,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!(
                "update target property `{property}` is not present on local `{object_name}`"
            ),
        });
        return None;
    };
    if property_term.readonly {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!("update target `{object_name}.{property}` is readonly"),
        });
        return None;
    }
    if property_term.optional {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!(
                "update target `{object_name}.{property}` is optional; P2 update requires a required property"
            ),
        });
        return None;
    }
    let property_type = aliases.expand_for_assignability(&property_term.ty, diagnostics);
    if !matches!(property_type, TypeTerm::Named { ref name, .. } if name == "number") {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!(
                "update target `{object_name}.{property}` requires a proven numeric property"
            ),
        });
        return None;
    }
    Some(TypeTerm::Named {
        name: "number".to_string(),
        span,
    })
}

fn check_element_update_target(
    object: &ExpressionFact,
    index: &ExpressionFact,
    optional: bool,
    span: Span,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> Option<TypeTerm> {
    if optional {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span,
            message:
                "update target element is optional/nullish; P2 update requires a proven non-optional array target"
                    .to_string(),
        });
        return None;
    }
    let ExpressionFactKind::Identifier(object_name) = &object.kind else {
        let _ = type_expression_fact(object, env, aliases, signatures, diagnostics);
        let _ = type_expression_fact(index, env, aliases, signatures, diagnostics);
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span,
            message:
                "P2 element update supports only direct elements of mutable local array bindings"
                    .to_string(),
        });
        return None;
    };
    let Some(binding) = env.get(object_name).cloned() else {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnresolvedValueRef,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!("update target array `{object_name}` is not a declared local binding"),
        });
        return None;
    };
    if binding.source != ValueBindingSource::Local || !binding.mutable {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!(
                "update target array `{object_name}` is readonly; P2 element update supports only `let` array locals"
            ),
        });
        return None;
    }
    let array_type = aliases.expand_for_assignability(&binding.ty, diagnostics);
    let TypeTerm::TypeRef {
        name, type_args, ..
    } = array_type
    else {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!("update target `{object_name}[...]` requires a known Array<T> type"),
        });
        return None;
    };
    if name != "Array" || type_args.len() != 1 {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!("update target `{object_name}[...]` requires a known Array<T> type"),
        });
        return None;
    }
    let index_type = aliases.expand_for_assignability(
        &type_expression_fact(index, env, aliases, signatures, diagnostics),
        diagnostics,
    );
    if !matches!(index_type, TypeTerm::Named { ref name, .. } if name == "number") {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!("update target `{object_name}[...]` requires a numeric index"),
        });
        return None;
    }
    let element_type = aliases.expand_for_assignability(&type_args[0], diagnostics);
    if !matches!(element_type, TypeTerm::Named { ref name, .. } if name == "number") {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!(
                "update target `{object_name}[...]` requires a proven numeric element type"
            ),
        });
        return None;
    }
    Some(TypeTerm::Named {
        name: "number".to_string(),
        span,
    })
}

fn check_local_update_target(
    target: &str,
    span: Span,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> Option<TypeTerm> {
    let Some(binding) = env.get(target).cloned() else {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnresolvedValueRef,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!("update target `{target}` is not a declared local binding"),
        });
        return None;
    };
    if binding.source != ValueBindingSource::Local || !binding.mutable {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!(
                "update target `{target}` is readonly; P2 update supports only `let` numeric locals"
            ),
        });
        return None;
    }
    let ty = aliases.expand_for_assignability(&binding.ty, diagnostics);
    if !matches!(ty, TypeTerm::Named { ref name, .. } if name == "number") {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!("update target `{target}` requires a proven numeric local binding"),
        });
        return None;
    }
    Some(TypeTerm::Named {
        name: "number".to_string(),
        span,
    })
}

fn update_position_name(position: cruftscript_parser::UpdatePosition) -> &'static str {
    match position {
        cruftscript_parser::UpdatePosition::Prefix => "prefix",
        cruftscript_parser::UpdatePosition::Postfix => "postfix",
    }
}

fn check_element_assignment_fact(
    object: &ExpressionFact,
    index: &ExpressionFact,
    optional: bool,
    assignment: &AssignmentFact,
    env: &mut ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) {
    let value_type = type_expression_fact(&assignment.value, env, aliases, signatures, diagnostics);
    if optional {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: "assignment target element is optional/nullish; P2 element assignment requires a proven non-optional array target"
                .to_string(),
        });
        return;
    }
    let ExpressionFactKind::Identifier(object_name) = &object.kind else {
        let _ = type_expression_fact(object, env, aliases, signatures, diagnostics);
        let _ = type_expression_fact(index, env, aliases, signatures, diagnostics);
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: "P2 element assignment supports only direct elements of mutable local array bindings"
                .to_string(),
        });
        return;
    };
    let Some(binding) = env.get(object_name).cloned() else {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnresolvedValueRef,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: format!(
                "assignment target array `{object_name}` is not a declared local binding"
            ),
        });
        return;
    };
    if binding.source != ValueBindingSource::Local || !binding.mutable {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: format!(
                "assignment target array `{object_name}` is readonly; P2 element assignment supports only `let` array locals"
            ),
        });
        return;
    }
    let array_type = aliases.expand_for_assignability(&binding.ty, diagnostics);
    let TypeTerm::TypeRef {
        name, type_args, ..
    } = array_type
    else {
        let message = if matches!(array_type, TypeTerm::Unknown { .. }) {
            format!(
                "assignment target `{object_name}[...]` from `unknown` requires a proven Array<T> shape"
            )
        } else {
            format!("assignment target `{object_name}[...]` requires a known Array<T> type")
        };
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message,
        });
        return;
    };
    if name != "Array" || type_args.len() != 1 {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: format!(
                "assignment target `{object_name}[...]` requires a known Array<T> type"
            ),
        });
        return;
    }
    let index_type = aliases.expand_for_assignability(
        &type_expression_fact(index, env, aliases, signatures, diagnostics),
        diagnostics,
    );
    if !matches!(index_type, TypeTerm::Named { ref name, .. } if name == "number") {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: format!("assignment target `{object_name}[...]` requires a numeric index"),
        });
        return;
    }
    let element_type = &type_args[0];
    if matches!(element_type, TypeTerm::Unknown { .. }) {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: format!(
                "assignment target `{object_name}[...]` has element type `unknown`; narrow or declare a concrete Array<T> before mutation"
            ),
        });
        return;
    }
    if !is_assignable(&value_type, element_type, aliases, diagnostics) {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::LocalInitializerTypeMismatch,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: format!(
                "assigned value for element `{object_name}[...]` does not conform to its element type"
            ),
        });
    }
}

fn check_local_assignment_fact(
    target: &str,
    assignment: &AssignmentFact,
    env: &mut ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) {
    let value_type = type_expression_fact(&assignment.value, env, aliases, signatures, diagnostics);
    let Some(binding) = env.get(target).cloned() else {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnresolvedValueRef,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: format!("assignment target `{target}` is not a declared local binding",),
        });
        return;
    };
    if binding.source != ValueBindingSource::Local || !binding.mutable {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: format!(
                "assignment target `{target}` is readonly; P2 local assignment supports only `let` locals",
            ),
        });
        return;
    }
    if !is_assignable(&value_type, &binding.ty, aliases, diagnostics) {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::LocalInitializerTypeMismatch,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: format!(
                "assigned value for local `{target}` does not conform to its binding type",
            ),
        });
        return;
    }
    env.clear_refinements_for_binding(target);
    env.refine(target, binding.ty);
}

fn check_property_assignment_fact(
    object: &ExpressionFact,
    property: &str,
    optional: bool,
    assignment: &AssignmentFact,
    env: &mut ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) {
    let value_type = type_expression_fact(&assignment.value, env, aliases, signatures, diagnostics);
    if optional {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: format!(
                "assignment target property `{property}` is optional/nullish; P2 property assignment requires a proven non-optional object target"
            ),
        });
        return;
    }
    let ExpressionFactKind::Identifier(object_name) = &object.kind else {
        let _ = type_expression_fact(object, env, aliases, signatures, diagnostics);
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: "P2 property assignment supports only direct properties of mutable local object bindings"
                .to_string(),
        });
        return;
    };
    let Some(binding) = env.get(object_name).cloned() else {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnresolvedValueRef,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: format!(
                "assignment target object `{object_name}` is not a declared local binding"
            ),
        });
        return;
    };
    let mutable_property_target = binding.source == ValueBindingSource::Local && binding.mutable;
    let class_receiver_target =
        object_name == "this" && binding.source == ValueBindingSource::ClassReceiver;
    if !mutable_property_target && !class_receiver_target {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: format!(
                "assignment target object `{object_name}` is readonly; P2 property assignment supports only `let` object locals or class receiver fields"
            ),
        });
        return;
    }
    let object_type = aliases.expand_for_assignability(&binding.ty, diagnostics);
    let TypeTerm::Object { properties, .. } = object_type else {
        let message = if matches!(object_type, TypeTerm::Unknown { .. }) {
            format!(
                "assignment target `{object_name}.{property}` from `unknown` requires a proven object shape"
            )
        } else {
            format!("assignment target `{object_name}.{property}` requires a known object type")
        };
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message,
        });
        return;
    };
    let Some(property_term) = properties
        .iter()
        .find(|candidate| candidate.name == property)
    else {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::PropertyReadUnsupported,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: format!(
                "assignment target property `{property}` is not present on local `{object_name}`"
            ),
        });
        return;
    };
    if property_term.readonly {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: format!("assignment target `{object_name}.{property}` is readonly"),
        });
        return;
    }
    if property_term.optional {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: format!(
                "assignment target `{object_name}.{property}` is optional; P2 property assignment requires a required property"
            ),
        });
        return;
    }
    if !is_assignable(&value_type, &property_term.ty, aliases, diagnostics) {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::LocalInitializerTypeMismatch,
            severity: DiagnosticSeverity::Error,
            span: assignment.span,
            message: format!(
                "assigned value for property `{object_name}.{property}` does not conform to its property type"
            ),
        });
    }
    env.clear_refinement_for_property(object_name, property);
}

fn local_binding_type_after_initializer_proof(
    annotation: Option<&TypeTerm>,
    initializer: Option<&TypeTerm>,
    span: Span,
) -> TypeTerm {
    match (annotation, initializer) {
        (Some(TypeTerm::Unknown { .. }), Some(TypeTerm::Object { .. })) => {
            initializer.cloned().unwrap()
        }
        (Some(annotation), _) => annotation.clone(),
        (None, Some(initializer)) => initializer.clone(),
        (None, None) => TypeTerm::Unknown { span },
    }
}

fn check_return_fact(
    ret: &ReturnFact,
    env: &ValueEnvironment,
    declared_return: Option<&TypeTerm>,
    compartment: &str,
    bindings: &BindingEnvironment,
    boundary_facts: &BoundaryFacts,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
    returns: &mut Vec<TypedReturnFact>,
) {
    let expression_type = ret
        .argument
        .as_ref()
        .map(|expr| type_expression_fact(expr, env, aliases, signatures, diagnostics));
    if let Some(TypeTerm::Constructor { instance_type, .. }) = &expression_type {
        let name = match instance_type.as_ref() {
            TypeTerm::Named { name, .. } => name.as_str(),
            _ => "constructor",
        };
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedBodyExpression,
            severity: DiagnosticSeverity::Error,
            span: ret.span,
            message: format!(
                "CruftScript class constructor value `{name}` cannot escape as a returned runtime value"
            ),
        });
    }
    let conforms_to_declared = match (expression_type.as_ref(), declared_return) {
        (_, None) => true,
        (None, Some(expected)) => is_assignable(
            &TypeTerm::Unknown { span: ret.span },
            expected,
            aliases,
            diagnostics,
        ),
        (Some(actual), Some(expected)) => {
            is_assignable(actual, expected, aliases, diagnostics)
                || strict_import_return_runtime_validator_conforms(
                    ret,
                    compartment,
                    expected,
                    bindings,
                    boundary_facts,
                    aliases,
                    diagnostics,
                )
                || sanitize_import_return_default_conforms(
                    ret,
                    compartment,
                    expected,
                    bindings,
                    boundary_facts,
                    aliases,
                    diagnostics,
                )
                || return_expression_proves_type_predicate(ret.argument.as_ref(), expected)
                || literal_expression_conforms_to_type(
                    ret.argument.as_ref(),
                    expected,
                    aliases,
                    diagnostics,
                )
                || return_array_literal_conforms_to_tuple(
                    ret.argument.as_ref(),
                    expected,
                    env,
                    aliases,
                    signatures,
                    diagnostics,
                )
                || return_object_literal_conforms_to_mapped(
                    ret.argument.as_ref(),
                    actual,
                    expected,
                    aliases,
                    diagnostics,
                )
                || return_object_literal_conforms_to_string_record(
                    ret.argument.as_ref(),
                    actual,
                    expected,
                    aliases,
                    diagnostics,
                )
                || return_string_literal_conforms_to_template(
                    ret.argument.as_ref(),
                    expected,
                    aliases,
                    diagnostics,
                )
        }
    };
    if !conforms_to_declared {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::ReturnTypeMismatch,
            severity: DiagnosticSeverity::Error,
            span: ret.span,
            message: "return expression does not conform to declared return type".to_string(),
        });
    }
    returns.push(TypedReturnFact {
        expression_type,
        conforms_to_declared,
        span: ret.span,
    });
}

fn literal_expression_conforms_to_type(
    argument: Option<&ExpressionFact>,
    expected: &TypeTerm,
    aliases: &AliasExpansionContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> bool {
    let Some(argument) = argument else {
        return false;
    };
    let literal_spelling = match &argument.kind {

        ExpressionFactKind::StringLiteral(value) => format!("\"{value}\""),

        ExpressionFactKind::NumberLiteral(value) => value.clone(),
        _ => return false,
    };
    let expanded = aliases.expand_for_assignability(expected, diagnostics);
    opaque_type_contains_spelling(&expanded, &literal_spelling)
}

fn opaque_type_contains_spelling(expected: &TypeTerm, spelling: &str) -> bool {
    match expected {
        TypeTerm::Opaque {
            spelling: member, ..
        } => member.trim() == spelling,
        TypeTerm::Union { members, .. } => members
            .iter()
            .any(|member| opaque_type_contains_spelling(member, spelling)),
        _ => false,
    }
}

fn return_array_literal_conforms_to_tuple(
    argument: Option<&ExpressionFact>,
    expected: &TypeTerm,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> bool {
    let Some(argument) = argument else {
        return false;
    };
    let ExpressionFactKind::ArrayLiteral(elements) = &argument.kind else {
        return false;
    };
    let expanded = aliases.expand_for_assignability(expected, diagnostics);
    let TypeTerm::Tuple {
        elements: tuple_elements,
        ..
    } = &expanded
    else {
        return false;
    };
    if elements.len() != tuple_elements.len() {
        return false;
    }
    elements
        .iter()
        .zip(tuple_elements.iter())
        .all(|(element, tuple_element)| {
            let element_type = type_expression_fact(element, env, aliases, signatures, diagnostics);
            is_assignable(&element_type, tuple_element, aliases, diagnostics)
        })
}

fn return_object_literal_conforms_to_mapped(
    argument: Option<&ExpressionFact>,
    actual: &TypeTerm,
    expected: &TypeTerm,
    aliases: &AliasExpansionContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> bool {
    let Some(argument) = argument else {
        return false;
    };
    if !matches!(&argument.kind, ExpressionFactKind::ObjectLiteral(_)) {
        return false;
    }
    let expanded = aliases.expand_for_assignability(expected, diagnostics);
    if !matches!(&expanded, TypeTerm::Mapped { .. }) {
        return false;
    }

    let mut scratch = Vec::new();
    let Some(reduced) = aliases.reduce_mapped_to_object(&expanded, &mut scratch) else {
        return false;
    };
    is_assignable(actual, &reduced, aliases, diagnostics)
}

fn return_object_literal_conforms_to_string_record(
    argument: Option<&ExpressionFact>,
    actual: &TypeTerm,
    expected: &TypeTerm,
    aliases: &AliasExpansionContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> bool {
    let Some(argument) = argument else {
        return false;
    };
    if !matches!(&argument.kind, ExpressionFactKind::ObjectLiteral(_)) {
        return false;
    }
    let expanded = aliases.expand_for_assignability(expected, diagnostics);
    let TypeTerm::TypeRef {
        name, type_args, ..
    } = &expanded
    else {
        return false;
    };
    if name != "__CruftStringRecord" || type_args.len() != 1 {
        return false;
    }
    let value_type = &type_args[0];
    let TypeTerm::Object { properties, .. } = actual else {
        return false;
    };
    properties
        .iter()
        .all(|property| is_assignable(&property.ty, value_type, aliases, diagnostics))
}

enum TemplateTypeSegment {
    Literal(String),
    AnyString,
    NumberLike,
}

fn parse_template_type_pattern(spelling: &str) -> Option<Vec<TemplateTypeSegment>> {
    let spelling = spelling.trim();
    let inner = spelling
        .strip_prefix('`')
        .and_then(|s| s.strip_suffix('`'))?;
    let mut segments = Vec::new();
    let mut literal = String::new();
    let mut rest = inner;
    while let Some(open) = rest.find("${") {
        literal.push_str(&rest[..open]);
        let after = &rest[open + 2..];
        let close = after.find('}')?;
        let placeholder = after[..close].trim();
        if !literal.is_empty() {
            segments.push(TemplateTypeSegment::Literal(std::mem::take(&mut literal)));
        }
        match placeholder {
            "string" => segments.push(TemplateTypeSegment::AnyString),
            "number" => segments.push(TemplateTypeSegment::NumberLike),
            _ => return None,
        }
        rest = &after[close + 1..];
    }
    literal.push_str(rest);
    if !literal.is_empty() {
        segments.push(TemplateTypeSegment::Literal(literal));
    }
    Some(segments)
}

fn template_type_pattern_matches(segments: &[TemplateTypeSegment], value: &str) -> bool {
    match segments.first() {
        None => value.is_empty(),
        Some(TemplateTypeSegment::Literal(literal)) => value
            .strip_prefix(literal.as_str())
            .is_some_and(|rest| template_type_pattern_matches(&segments[1..], rest)),
        Some(TemplateTypeSegment::AnyString) => {
            if segments.len() == 1 {
                return true;
            }
            (0..=value.len()).any(|split| {
                value.is_char_boundary(split)
                    && template_type_pattern_matches(&segments[1..], &value[split..])
            })
        }
        Some(TemplateTypeSegment::NumberLike) => {
            let digits = value
                .char_indices()
                .take_while(|(_, ch)| ch.is_ascii_digit())
                .count();
            if digits == 0 {
                return false;
            }

            (1..=digits)
                .rev()
                .any(|take| template_type_pattern_matches(&segments[1..], &value[take..]))
        }
    }
}

fn return_string_literal_conforms_to_template(
    argument: Option<&ExpressionFact>,
    expected: &TypeTerm,
    aliases: &AliasExpansionContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> bool {
    let Some(argument) = argument else {
        return false;
    };
    let ExpressionFactKind::StringLiteral(value) = &argument.kind else {
        return false;
    };
    let expanded = aliases.expand_for_assignability(expected, diagnostics);
    let TypeTerm::Opaque { spelling, .. } = &expanded else {
        return false;
    };
    let Some(pattern) = parse_template_type_pattern(spelling) else {
        return false;
    };
    template_type_pattern_matches(&pattern, value)
}

fn return_expression_proves_type_predicate(
    argument: Option<&ExpressionFact>,
    expected: &TypeTerm,
) -> bool {
    let TypeTerm::TypePredicate {
        parameter, target, ..
    } = expected
    else {
        return false;
    };
    let TypeTerm::Named { name: target, .. } = target.as_ref() else {
        return false;
    };
    let Some(ExpressionFact {
        kind:
            ExpressionFactKind::Conditional {
                subject,
                consequent,
                alternate,
                ..
            },
        ..
    }) = argument
    else {
        return false;
    };
    if !matches!(consequent.kind, ExpressionFactKind::BooleanLiteral(true))
        || !matches!(alternate.kind, ExpressionFactKind::BooleanLiteral(false))
        || target != "null"
    {
        return false;
    }
    let ExpressionFactKind::BinaryStrictEqual { left, right } = &subject.kind else {
        return false;
    };
    (expression_fact_is_identifier(left, parameter)
        && matches!(right.kind, ExpressionFactKind::NullLiteral))
        || (matches!(left.kind, ExpressionFactKind::NullLiteral)
            && expression_fact_is_identifier(right, parameter))
}

fn expression_fact_is_identifier(expr: &ExpressionFact, expected: &str) -> bool {
    matches!(&expr.kind, ExpressionFactKind::Identifier(name) if name == expected)
}

fn strict_import_return_runtime_validator_conforms(
    ret: &ReturnFact,
    compartment: &str,
    expected: &TypeTerm,
    bindings: &BindingEnvironment,
    boundary_facts: &BoundaryFacts,
    aliases: &AliasExpansionContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> bool {
    let expanded_expected = aliases.expand_for_assignability(expected, diagnostics);
    if !type_term_has_runtime_import_validator(&expanded_expected) {
        return false;
    }
    let Some(ExpressionFact {
        kind:
            ExpressionFactKind::Call {
                callee,
                args,
                optional: false,
            },
        ..
    }) = ret.argument.as_ref()
    else {
        return false;
    };
    if !args.is_empty() {
        return false;
    }
    let ExpressionFactKind::Identifier(imported_name) = &callee.kind else {
        return false;
    };
    let Some(import_fact) = boundary_facts
        .imports
        .iter()
        .find(|import| import.compartment == compartment && import.imported_name == *imported_name)
    else {
        return false;
    };
    let Some(policy_ref) = import_fact.effective_policy.as_ref() else {
        return false;
    };
    let default_policy = boundary_facts
        .default_policy
        .as_ref()
        .map(|default| default.policy.as_str());
    let Ok((policy_id, _policy_name)) =
        boundary_policy_resolution_from_bindings(bindings, policy_ref, default_policy)
    else {
        return false;
    };
    policy_id != 2
}

fn type_term_has_runtime_import_validator(ty: &TypeTerm) -> bool {
    match ty {
        TypeTerm::Unknown { .. } => true,
        TypeTerm::Named { name, .. } => matches!(
            name.as_str(),
            "unknown"
                | "undefined"
                | "void"
                | "null"
                | "string"
                | "number"
                | "boolean"
                | "bigint"
                | "symbol"
        ),
        TypeTerm::Union { members, .. } => {
            members.iter().all(type_term_has_runtime_import_validator)
        }
        TypeTerm::TypeRef {
            name, type_args, ..
        } if name == "Array" && type_args.len() == 1 => {
            type_term_has_runtime_import_validator(&type_args[0])
        }
        TypeTerm::TypeRef {
            name, type_args, ..
        } if name == "__CruftStringRecord" && type_args.len() == 1 => {
            type_term_has_runtime_import_validator(&type_args[0])
        }
        TypeTerm::Object { properties, .. } => properties
            .iter()
            .all(|property| type_term_has_runtime_import_validator(&property.ty)),
        _ => false,
    }
}

fn sanitize_import_return_default_conforms(
    ret: &ReturnFact,
    compartment: &str,
    expected: &TypeTerm,
    bindings: &BindingEnvironment,
    boundary_facts: &BoundaryFacts,
    aliases: &AliasExpansionContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> bool {
    let Some(ExpressionFact {
        kind:
            ExpressionFactKind::Call {
                callee,
                args,
                optional: false,
            },
        ..
    }) = ret.argument.as_ref()
    else {
        return false;
    };
    if !args.is_empty() {
        return false;
    }
    let ExpressionFactKind::Identifier(imported_name) = &callee.kind else {
        return false;
    };
    let Some(import_fact) = boundary_facts
        .imports
        .iter()
        .find(|import| import.compartment == compartment && import.imported_name == *imported_name)
    else {
        return false;
    };
    let Some(policy_ref) = import_fact.effective_policy.as_ref() else {
        return false;
    };
    let default_policy = boundary_facts
        .default_policy
        .as_ref()
        .map(|default| default.policy.as_str());
    let Ok((policy_id, policy_name)) =
        boundary_policy_resolution_from_bindings(bindings, policy_ref, default_policy)
    else {
        return false;
    };
    if policy_id != 2 {
        return false;
    }
    let Some(policy) = bindings
        .boundary_policies
        .iter()
        .find(|policy| policy.name == policy_name)
    else {
        return false;
    };
    policy
        .sanitizer_defaults
        .iter()
        .any(|default| is_assignable(&default.target_type, expected, aliases, diagnostics))
}

#[derive(Clone, Default)]
struct ValueEnvironment {
    bindings: HashMap<String, ValueBindingFact>,
    property_refinements: HashMap<String, TypeTerm>,
    static_primitive_bindings: HashMap<String, StaticPrimitiveValue>,
}

#[derive(Clone)]
enum StaticPrimitiveValue {
    String(String),
    Number,
    Boolean,
}

impl ValueEnvironment {
    fn insert(&mut self, binding: ValueBindingFact, diagnostics: &mut Vec<CheckDiagnostic>) {
        if let Some(first) = self.bindings.get(&binding.name) {
            diagnostics.push(CheckDiagnostic {
                code: CheckDiagnosticCode::DuplicateBinding,
                severity: DiagnosticSeverity::Error,
                span: binding.span,
                message: format!(
                    "duplicate value binding `{}`; first declared at {}..{}",
                    binding.name, first.span.start, first.span.end
                ),
            });
        } else {
            self.bindings.insert(binding.name.clone(), binding);
        }
    }

    fn get(&self, name: &str) -> Option<&ValueBindingFact> {
        self.bindings.get(name)
    }

    fn property_refinement(&self, name: &str) -> Option<&TypeTerm> {
        self.property_refinements.get(name)
    }

    fn clear_refinements_for_binding(&mut self, name: &str) {
        let prefix = format!("{name}.");
        self.property_refinements
            .retain(|subject, _| !subject.starts_with(&prefix));
    }

    fn clear_refinement_for_property(&mut self, object: &str, property: &str) {
        let subject = format!("{object}.{property}");
        self.property_refinements.remove(&subject);
        let prefix = format!("{subject}.");
        self.property_refinements
            .retain(|candidate, _| !candidate.starts_with(&prefix));
    }

    fn static_string(&self, name: &str) -> Option<&str> {
        match self.static_primitive_bindings.get(name) {
            Some(StaticPrimitiveValue::String(value)) => Some(value.as_str()),
            _ => None,
        }
    }

    fn static_primitive(&self, name: &str) -> Option<&StaticPrimitiveValue> {
        self.static_primitive_bindings.get(name)
    }

    fn record_static_primitive(
        &mut self,
        name: &str,
        initializer: Option<&ExpressionFact>,
        mutable: bool,
    ) {
        if !mutable {
            if let Some(initializer) = initializer {
                let value = match &initializer.kind {
                    ExpressionFactKind::StringLiteral(value) => {
                        StaticPrimitiveValue::String(value.clone())
                    }
                    ExpressionFactKind::NumberLiteral(_) => StaticPrimitiveValue::Number,
                    ExpressionFactKind::BooleanLiteral(_) => StaticPrimitiveValue::Boolean,
                    _ => {
                        self.static_primitive_bindings.remove(name);
                        return;
                    }
                };
                self.static_primitive_bindings
                    .insert(name.to_string(), value);
                return;
            }
        }
        self.static_primitive_bindings.remove(name);
    }

    fn refine(&mut self, name: &str, ty: TypeTerm) {
        if name.contains('.') {
            self.property_refinements.insert(name.to_string(), ty);
        } else if let Some(binding) = self.bindings.get_mut(name) {
            binding.ty = ty;
        }
    }
}

fn extract_callback_params(expected: &TypeTerm) -> Option<&[FunctionTypeParamTerm]> {
    match expected {
        TypeTerm::Function { params, .. } => Some(params),
        TypeTerm::Union { members, .. } => members.iter().find_map(|m| match m {
            TypeTerm::Function { params, .. } => Some(params.as_slice()),
            _ => None,
        }),
        _ => None,
    }
}

fn stdlib_array_receiver_element_type(
    object: &ExpressionFact,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> Option<TypeTerm> {
    let ty = type_expression_fact(object, env, aliases, signatures, diagnostics);
    match aliases.expand_for_assignability(&ty, diagnostics) {
        TypeTerm::TypeRef {
            name, type_args, ..
        } if name == "Array" && type_args.len() == 1 => Some(type_args[0].clone()),
        _ => None,
    }
}

#[allow(clippy::too_many_arguments)]
fn type_array_reduce_call(
    callback_arg: &ExpressionFact,
    initial_arg: &ExpressionFact,
    element: TypeTerm,
    span: Span,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> TypeTerm {
    let acc_ty = type_expression_fact(initial_arg, env, aliases, signatures, diagnostics);
    let param = |name: &str, ty: TypeTerm| FunctionTypeParamTerm {
        name: Some(name.to_string()),
        ty,
        span: stdlib_span(),
    };
    let expected_callback = TypeTerm::Function {
        type_params: Vec::new(),
        params: vec![param("acc", acc_ty.clone()), param("cur", element)],
        return_type: Box::new(acc_ty.clone()),
        boundary: None,
        span: stdlib_span(),
    };
    let callback_actual = type_call_argument_fact(
        callback_arg,
        Some(&expected_callback),
        env,
        aliases,
        signatures,
        diagnostics,
    );

    if let (TypeTerm::Function { params: ap, .. }, TypeTerm::Function { params: ep, .. }) =
        (&callback_actual, &expected_callback)
    {
        if !stdlib_callback_params_conform(ap, ep, aliases) {
            diagnostics.push(CheckDiagnostic {
                code: CheckDiagnosticCode::ArgumentTypeMismatch,
                severity: DiagnosticSeverity::Error,
                span,
                message: "reduce callback does not conform to `(acc, cur) => acc`".to_string(),
            });
        }
    }
    acc_ty
}

fn type_call_argument_fact(
    arg: &ExpressionFact,
    expected: Option<&TypeTerm>,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> TypeTerm {
    if let ExpressionFactKind::Arrow { params, body } = &arg.kind {
        if let Some(callback_params) = expected.and_then(extract_callback_params) {
            let mut arrow_env = env.clone();
            let mut param_terms = Vec::new();
            for (idx, param) in params.iter().enumerate() {
                let ty = if matches!(param.ty, TypeTerm::Unknown { .. }) {
                    callback_params
                        .get(idx)
                        .map(|p| p.ty.clone())
                        .unwrap_or_else(|| param.ty.clone())
                } else {
                    param.ty.clone()
                };
                arrow_env.insert(
                    ValueBindingFact {
                        name: param.name.clone(),
                        ty: ty.clone(),
                        source: ValueBindingSource::Parameter,
                        mutable: false,
                        constructed_class: None,
                        span: param.span,
                    },
                    diagnostics,
                );
                param_terms.push(FunctionTypeParamTerm {
                    name: Some(param.name.clone()),
                    ty,
                    span: param.span,
                });
            }
            let body_type =
                type_expression_fact(body, &arrow_env, aliases, signatures, diagnostics);
            return TypeTerm::Function {
                type_params: Vec::new(),
                params: param_terms,
                return_type: Box::new(body_type),
                boundary: None,
                span: arg.span,
            };
        }
    }
    type_expression_fact(arg, env, aliases, signatures, diagnostics)
}

fn type_expression_fact(
    expr: &ExpressionFact,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> TypeTerm {
    match &expr.kind {
        ExpressionFactKind::Identifier(name) => env
            .get(name)
            .map(|binding| binding.ty.clone())
            .unwrap_or_else(|| {
                signatures
                    .get(name)
                    .map(function_signature_type_term)
                    .unwrap_or_else(|| {
                        diagnostics.push(CheckDiagnostic {
                            code: CheckDiagnosticCode::UnresolvedValueRef,
                            severity: DiagnosticSeverity::Error,
                            span: expr.span,
                            message: format!("unresolved value reference `{name}`"),
                        });
                        TypeTerm::Unknown { span: expr.span }
                    })
            }),
        ExpressionFactKind::Arrow { params, body } => {

            let mut arrow_env = env.clone();
            let mut param_terms = Vec::new();
            for param in params {
                arrow_env.insert(
                    ValueBindingFact {
                        name: param.name.clone(),
                        ty: param.ty.clone(),
                        source: ValueBindingSource::Parameter,
                        mutable: false,
                        constructed_class: None,
                        span: param.span,
                    },
                    diagnostics,
                );
                param_terms.push(FunctionTypeParamTerm {
                    name: Some(param.name.clone()),
                    ty: param.ty.clone(),
                    span: param.span,
                });
            }
            let body_type =
                type_expression_fact(body, &arrow_env, aliases, signatures, diagnostics);
            TypeTerm::Function {
                type_params: Vec::new(),
                params: param_terms,
                return_type: Box::new(body_type),
                boundary: None,
                span: expr.span,
            }
        }
        ExpressionFactKind::StringLiteral(_) => TypeTerm::Named {
            name: "string".to_string(),
            span: expr.span,
        },
        ExpressionFactKind::NumberLiteral(_) => TypeTerm::Named {
            name: "number".to_string(),
            span: expr.span,
        },
        ExpressionFactKind::BooleanLiteral(_) => TypeTerm::Named {
            name: "boolean".to_string(),
            span: expr.span,
        },
        ExpressionFactKind::NullLiteral => TypeTerm::Named {
            name: "null".to_string(),
            span: expr.span,
        },
        ExpressionFactKind::ArrayLiteral(elements) => {
            let element_types: Vec<_> = elements
                .iter()
                .map(|element| type_expression_fact(element, env, aliases, signatures, diagnostics))
                .collect();
            let element_type = best_common_type(&element_types, aliases, diagnostics)
                .unwrap_or(TypeTerm::Unknown { span: expr.span });
            TypeTerm::TypeRef {
                name: "Array".to_string(),
                type_args: vec![element_type],
                span: expr.span,
            }
        }
        ExpressionFactKind::ObjectLiteral(properties) => TypeTerm::Object {
            properties: properties
                .iter()
                .map(|property| ObjectPropertyTerm {
                    name: property.name.clone(),
                    ty: type_expression_fact(
                        &property.value,
                        env,
                        aliases,
                        signatures,
                        diagnostics,
                    ),
                    readonly: false,
                    optional: false,
                    span: property.span,
                })
                .collect(),
            span: expr.span,
        },
        ExpressionFactKind::PropertyAccess {
            object,
            property,
            optional,
        } => type_property_access_expression(
            object,
            property,
            *optional,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::ElementAccess {
            object,
            index,
            optional,
        } => type_element_access_expression(
            object,
            index,
            *optional,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::Call {
            callee,
            args,
            optional,
        } => type_call_expression(
            callee,
            args,
            *optional,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::New { class_name, args } => {
            if let Some(class_constructor) = constructor_term_for_new(class_name, env, aliases) {
                if args.is_empty() && class_constructor.uninitialized_required_field_count == 0 {
                    return TypeTerm::Named {
                        name: class_constructor.name.clone(),
                        span: expr.span,
                    };
                }
                let missing_after_constructor = class_constructor
                    .uninitialized_required_field_count
                    .saturating_sub(class_constructor.constructor_initialized_required_field_count);
                if args.len() == class_constructor.params.len() && missing_after_constructor == 0 {
                    for (idx, (arg, expected)) in
                        args.iter().zip(&class_constructor.params).enumerate()
                    {
                        if !expression_fact_conforms_to_type(
                            arg,
                            &expected.ty,
                            env,
                            aliases,
                            signatures,
                            diagnostics,
                        ) {
                            diagnostics.push(CheckDiagnostic {
                                code: CheckDiagnosticCode::ArgumentTypeMismatch,
                                severity: DiagnosticSeverity::Error,
                                span: expr.span,
                                message: format!(
                                    "argument {} for constructor `{}` does not conform to parameter `{}`",
                                    idx + 1,
                                    class_constructor.name,
                                    expected.name
                                ),
                            });
                        }
                    }
                    return TypeTerm::Named {
                        name: class_constructor.name.clone(),
                        span: expr.span,
                    };
                }
            }

            if let Some(constructed) = stdlib_builtin_constructor_type(class_name) {
                for arg in args {
                    let _ = type_expression_fact(arg, env, aliases, signatures, diagnostics);
                }
                return constructed;
            }
            diagnostics.push(CheckDiagnostic {
                code: CheckDiagnosticCode::ConstructorRuntimeInteropUnsupported,
                severity: DiagnosticSeverity::Error,
                span: expr.span,
                message: format!(
                    "CruftScript constructor runtime interop is not derived yet (`new {class_name}`); only fieldless, optional-field, field-initialized, or definitely field-assigning same-compartment CruftScript class constructors are admitted"
                ),
            });
            TypeTerm::Unknown { span: expr.span }
        }
        ExpressionFactKind::BinaryAdd { left, right } => type_binary_add_expression(
            left,
            right,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::BinarySub { left, right } => type_binary_sub_expression(
            left,
            right,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::BinaryMul { left, right } => type_binary_mul_expression(
            left,
            right,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::BinaryPow { left, right } => type_binary_pow_expression(
            left,
            right,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::BinaryDiv { left, right } => type_binary_div_expression(
            left,
            right,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::BinaryRem { left, right } => type_binary_rem_expression(
            left,
            right,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::NullishCoalesce { left, right } => type_nullish_coalesce_expression(
            left,
            right,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::BinaryBitwiseAnd { left, right } => type_binary_bitwise_and_expression(
            left,
            right,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::BinaryBitwiseOr { left, right } => type_binary_bitwise_or_expression(
            left,
            right,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::BinaryBitwiseXor { left, right } => type_binary_bitwise_xor_expression(
            left,
            right,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::BinaryShiftLeft { left, right } => type_binary_shift_left_expression(
            left,
            right,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::BinaryShiftRight { left, right } => type_binary_shift_right_expression(
            left,
            right,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::BinaryLessThan { left, right } => type_binary_less_than_expression(
            left,
            right,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::BinaryGreaterThan { left, right } => {
            type_binary_greater_than_expression(
                left,
                right,
                expr.span,
                env,
                aliases,
                signatures,
                diagnostics,
            )
        }
        ExpressionFactKind::BinaryLessThanOrEqual { left, right } => {
            type_binary_less_than_or_equal_expression(
                left,
                right,
                expr.span,
                env,
                aliases,
                signatures,
                diagnostics,
            )
        }
        ExpressionFactKind::BinaryGreaterThanOrEqual { left, right } => {
            type_binary_greater_than_or_equal_expression(
                left,
                right,
                expr.span,
                env,
                aliases,
                signatures,
                diagnostics,
            )
        }
        ExpressionFactKind::BinaryStrictEqual { left, right } => {
            type_binary_strict_equal_expression(
                left,
                right,
                expr.span,
                env,
                aliases,
                signatures,
                diagnostics,
            )
        }
        ExpressionFactKind::BinaryStrictNotEqual { left, right } => {
            type_binary_strict_not_equal_expression(
                left,
                right,
                expr.span,
                env,
                aliases,
                signatures,
                diagnostics,
            )
        }
        ExpressionFactKind::LogicalAnd { left, right } => type_logical_and_expression(
            left,
            right,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::LogicalOr { left, right } => type_logical_or_expression(
            left,
            right,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::LogicalNot { expr: inner } => {
            type_logical_not_expression(inner, expr.span, env, aliases, signatures, diagnostics)
        }
        ExpressionFactKind::UnaryMinus { expr: inner } => {
            type_unary_minus_expression(inner, expr.span, env, aliases, signatures, diagnostics)
        }
        ExpressionFactKind::Update {
            target,
            op: _,
            position,
        } => {
            let _ = update_position_name(*position);
            match &target.kind {
                ExpressionFactKind::Identifier(target_name) => {
                    check_local_update_target(target_name, expr.span, env, aliases, diagnostics)
                }
                ExpressionFactKind::PropertyAccess {
                    object,
                    property,
                    optional,
                } => check_property_update_target(
                    object,
                    property,
                    *optional,
                    expr.span,
                    env,
                    aliases,
                    signatures,
                    diagnostics,
                ),
                ExpressionFactKind::ElementAccess {
                    object,
                    index,
                    optional,
                } => check_element_update_target(
                    object,
                    index,
                    *optional,
                    expr.span,
                    env,
                    aliases,
                    signatures,
                    diagnostics,
                ),
                _ => {
                    let _ = type_expression_fact(target, env, aliases, signatures, diagnostics);
                    diagnostics.push(CheckDiagnostic {
                        code: CheckDiagnosticCode::UnsupportedBodyExpression,
                        severity: DiagnosticSeverity::Error,
                        span: expr.span,
                        message:
                            "P2 update expressions support only direct mutable numeric local, property, or bounded element targets"
                                .to_string(),
                    });
                    None
                }
            }
            .unwrap_or(TypeTerm::Unknown { span: expr.span })
        }
        ExpressionFactKind::Delete { target } => {
            type_delete_expression(target, expr.span, env, aliases, signatures, diagnostics)
        }
        ExpressionFactKind::Conditional {
            subject,
            guard,
            consequent,
            alternate,
        } => type_conditional_expression(
            subject,
            guard,
            consequent,
            alternate,
            expr.span,
            env,
            aliases,
            signatures,
            diagnostics,
        ),
        ExpressionFactKind::Ternary {
            condition,
            consequent,
            alternate,
        } => {

            let _ = type_expression_fact(condition, env, aliases, signatures, diagnostics);
            let consequent_type =
                type_expression_fact(consequent, env, aliases, signatures, diagnostics);
            let alternate_type =
                type_expression_fact(alternate, env, aliases, signatures, diagnostics);
            best_common_type(&[consequent_type, alternate_type], aliases, diagnostics)
                .unwrap_or(TypeTerm::Unknown { span: expr.span })
        }
        ExpressionFactKind::LetIn { name, value, body } => {

            let value_type = type_expression_fact(value, env, aliases, signatures, diagnostics);
            let mut body_env = env.clone();
            body_env.insert(
                ValueBindingFact {
                    name: name.clone(),
                    ty: value_type,
                    source: ValueBindingSource::Local,
                    mutable: false,
                    constructed_class: None,
                    span: expr.span,
                },
                diagnostics,
            );
            type_expression_fact(body, &body_env, aliases, signatures, diagnostics)
        }
        ExpressionFactKind::Assertion {
            expr,
            target,
            satisfies,
        } => {
            let actual = type_expression_fact(expr, env, aliases, signatures, diagnostics);

            if *satisfies {
                if !is_assignable(&actual, target, aliases, diagnostics)
                    && !literal_expression_conforms_to_type(
                        Some(expr),
                        target,
                        aliases,
                        diagnostics,
                    )
                {
                    diagnostics.push(CheckDiagnostic {
                        code: CheckDiagnosticCode::AssertionOperatorUnsupported,
                        severity: DiagnosticSeverity::Error,
                        span: expr.span,
                        message:
                            "CruftScript `satisfies` requires the expression to conform to the target type"
                                .to_string(),
                    });
                    return TypeTerm::Unknown { span: expr.span };
                }
                return actual;
            }

            if literal_expression_conforms_to_type(Some(expr), target, aliases, diagnostics) {
                return target.clone();
            }
            if type_term_contains_unknown_or_opaque(target) {
                diagnostics.push(CheckDiagnostic {
                    code: CheckDiagnosticCode::AssertionOperatorUnsupported,
                    severity: DiagnosticSeverity::Error,
                    span: expr.span,
                    message: "CruftScript `as` assertions require concrete target types; `unknown` targets must be narrowed explicitly".to_string(),
                });
                return TypeTerm::Unknown { span: expr.span };
            }
            if type_term_contains_unknown_or_opaque(&actual) {
                if let Some(target_type) =
                    runtime_assertion_target_type(target, aliases, diagnostics)
                {
                    return target_type;
                }
                diagnostics.push(CheckDiagnostic {
                    code: CheckDiagnosticCode::AssertionOperatorUnsupported,
                    severity: DiagnosticSeverity::Error,
                    span: expr.span,
                    message: "CruftScript `as` assertions from `unknown` require a runtime-validator-backed target for this substrate generation".to_string(),
                });
                return TypeTerm::Unknown { span: expr.span };
            }
            if !is_assignable(&actual, target, aliases, diagnostics) {
                if is_assignable(target, &actual, aliases, diagnostics) {
                    if let Some(target_type) =
                        runtime_assertion_target_type(target, aliases, diagnostics)
                    {
                        return target_type;
                    }
                }
                diagnostics.push(CheckDiagnostic {
                    code: CheckDiagnosticCode::AssertionOperatorUnsupported,
                    severity: DiagnosticSeverity::Error,
                    span: expr.span,
                    message: "CruftScript `as` assertion target is not proven by the source expression type".to_string(),
                });
                return TypeTerm::Unknown { span: expr.span };
            }
            target.clone()
        }
        ExpressionFactKind::NonNull { expr } => {
            let actual = type_expression_fact(expr, env, aliases, signatures, diagnostics);
            if type_term_contains_unknown_or_opaque(&actual) {
                return actual;
            }
            if let Some(non_nullish) =
                type_term_without_nullish(&actual, expr.span, aliases, diagnostics)
            {
                return non_nullish;
            }
            if type_term_maybe_nullish(&actual, aliases, diagnostics) {
                diagnostics.push(CheckDiagnostic {
                    code: CheckDiagnosticCode::NonNullAssertionUnsupported,
                    severity: DiagnosticSeverity::Error,
                    span: expr.span,
                    message:
                        "CruftScript non-null assertion requires a type already proven non-nullish"
                            .to_string(),
                });
                return TypeTerm::Unknown { span: expr.span };
            }
            actual
        }
        ExpressionFactKind::Opaque(spelling) => {
            if is_as_assertion_expression(spelling) {
                diagnostics.push(CheckDiagnostic {
                    code: CheckDiagnosticCode::AssertionOperatorUnsupported,
                    severity: DiagnosticSeverity::Error,
                    span: expr.span,
                    message: format!(
                        "CruftScript rejects unchecked `as` assertions (`{spelling}`); narrow or validate explicitly"
                    ),
                });
                return TypeTerm::Unknown { span: expr.span };
            }
            if is_non_null_assertion_expression(spelling) {
                diagnostics.push(CheckDiagnostic {
                    code: CheckDiagnosticCode::NonNullAssertionUnsupported,
                    severity: DiagnosticSeverity::Error,
                    span: expr.span,
                    message: format!(
                        "CruftScript rejects unchecked non-null assertions (`{spelling}`); use an explicit narrowing guard"
                    ),
                });
                return TypeTerm::Unknown { span: expr.span };
            }
            if is_new_expression(spelling) {
                if let Some(class_name) = parse_zero_arg_new_expression(spelling) {
                    if let Some(class_constructor) = aliases
                        .class_constructors
                        .get(class_name)
                        .filter(|constructor| constructor.uninitialized_required_field_count == 0)
                    {
                        return TypeTerm::Named {
                            name: class_constructor.name.clone(),
                            span: expr.span,
                        };
                    }
                }
                diagnostics.push(CheckDiagnostic {
                    code: CheckDiagnosticCode::ConstructorRuntimeInteropUnsupported,
                    severity: DiagnosticSeverity::Error,
                    span: expr.span,
                    message: format!(
                        "CruftScript constructor runtime interop is not derived yet (`{spelling}`); construct signatures remain type-only"
                    ),
                });
                return TypeTerm::Unknown { span: expr.span };
            }
            diagnostics.push(CheckDiagnostic {
                code: CheckDiagnosticCode::UnsupportedBodyExpression,
                severity: DiagnosticSeverity::Error,
                span: expr.span,
                message: unsupported_write_or_body_message(spelling),
            });
            TypeTerm::Unknown { span: expr.span }
        }
    }
}

fn expression_fact_conforms_to_type(
    expr: &ExpressionFact,
    expected: &TypeTerm,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> bool {
    let expected_expanded = aliases.expand_for_assignability(expected, diagnostics);
    if let (
        ExpressionFactKind::ArrayLiteral(elements),
        TypeTerm::Tuple {
            elements: expected_elements,
            ..
        },
    ) = (&expr.kind, &expected_expanded)
    {
        return elements.len() == expected_elements.len()
            && elements
                .iter()
                .zip(expected_elements)
                .all(|(element, expected)| {
                    expression_fact_conforms_to_type(
                        element,
                        expected,
                        env,
                        aliases,
                        signatures,
                        diagnostics,
                    )
                });
    }
    let actual = type_expression_fact(expr, env, aliases, signatures, diagnostics);
    is_assignable(&actual, expected, aliases, diagnostics)

        || literal_expression_conforms_to_type(Some(expr), expected, aliases, diagnostics)
}

fn class_method_expression_fact_conforms_to_type(
    class_decl: &ClassDecl,
    expr: &ExpressionFact,
    expected: &TypeTerm,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> bool {
    if matches!(&expr.kind, ExpressionFactKind::Identifier(name) if name == "this")
        && matches!(env.get("this"), Some(binding) if binding.source == ValueBindingSource::ClassReceiver)
        && matches!(expected, TypeTerm::Named { name, .. } if name == &class_decl.name)
    {
        return true;
    }
    expression_fact_conforms_to_type(expr, expected, env, aliases, signatures, diagnostics)
}

fn type_conditional_expression(
    subject: &ExpressionFact,
    guard: &NarrowingGuard,
    consequent: &ExpressionFact,
    alternate: &ExpressionFact,
    span: Span,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> TypeTerm {
    let mut consequent_env = env.clone();
    let mut alternate_env = env.clone();
    let mut call_shaped_truthy_without_predicate = false;
    if let Some(guard_fact) =
        lower_expression_narrowing_guard_parts(subject, guard, env, signatures)
    {
        validate_supported_narrowing_guard(&guard_fact, env, aliases, diagnostics);
        validate_narrowing_guard_value_types(&guard_fact, env, aliases, signatures, diagnostics);
        if matches!(guard_fact.kind, NarrowingGuardFactKind::Truthy { .. }) {
            validate_conditional_expression_truthy_subject(
                subject,
                env,
                aliases,
                signatures,
                diagnostics,
            );
        }
        apply_guard_refinement(&guard_fact, &mut consequent_env);
        apply_guard_negative_refinement(&guard_fact, &mut alternate_env, aliases);
    } else {
        if matches!(guard, NarrowingGuard::Truthy { .. }) {
            validate_conditional_expression_truthy_subject(
                subject,
                env,
                aliases,
                signatures,
                diagnostics,
            );
        } else {
            let _ = type_expression_fact(subject, env, aliases, signatures, diagnostics);
        }
        call_shaped_truthy_without_predicate = matches!(guard, NarrowingGuard::Truthy { .. })
            && matches!(subject.kind, ExpressionFactKind::Call { .. });
    }
    let consequent_type = type_expression_fact(
        consequent,
        &consequent_env,
        aliases,
        signatures,
        diagnostics,
    );
    let alternate_type =
        type_expression_fact(alternate, &alternate_env, aliases, signatures, diagnostics);
    if call_shaped_truthy_without_predicate
        && (type_term_contains_unknown_or_opaque(&consequent_type)
            || type_term_contains_unknown_or_opaque(&alternate_type))
    {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedNarrowingGuard,
            severity: DiagnosticSeverity::Error,
            span: subject.span,
            message:
                "call-shaped CruftScript narrowing guard requires a supported type-predicate signature"
                    .to_string(),
        });
    }
    best_common_type(&[consequent_type, alternate_type], aliases, diagnostics)
        .unwrap_or(TypeTerm::Unknown { span })
}

fn validate_conditional_expression_truthy_subject(
    subject: &ExpressionFact,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) {
    let subject_type = type_expression_fact(subject, env, aliases, signatures, diagnostics);
    let expected = TypeTerm::Named {
        name: "boolean".to_string(),
        span: subject.span,
    };
    if !is_assignable(&subject_type, &expected, aliases, diagnostics) {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::UnsupportedNarrowingGuard,
            severity: DiagnosticSeverity::Error,
            span: subject.span,
            message:
                "conditional expression requires a supported narrowing guard or proven boolean subject"
                    .to_string(),
        });
    }
}

fn type_term_maybe_nullish(
    ty: &TypeTerm,
    aliases: &AliasExpansionContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> bool {
    let expanded = aliases.expand_for_assignability(ty, diagnostics);
    match expanded {
        TypeTerm::Named { ref name, .. } => name == "null" || name == "undefined",
        TypeTerm::Union { ref members, .. } => members
            .iter()
            .any(|member| type_term_maybe_nullish(member, aliases, diagnostics)),
        TypeTerm::Unknown { .. } | TypeTerm::Opaque { .. } => true,
        _ => false,
    }
}

fn type_term_without_nullish(
    ty: &TypeTerm,
    span: Span,
    aliases: &AliasExpansionContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> Option<TypeTerm> {
    let expanded = aliases.expand_for_assignability(ty, diagnostics);
    let TypeTerm::Union { members, .. } = expanded else {
        return None;
    };
    let non_nullish = members
        .into_iter()
        .filter(|member| !is_nullish_type_term(member))
        .collect::<Vec<_>>();
    if non_nullish.is_empty() {
        return Some(TypeTerm::Never { span });
    }
    if non_nullish.len() == 1 {
        return non_nullish.into_iter().next();
    }
    Some(TypeTerm::Union {
        members: non_nullish,
        span,
    })
}

fn runtime_assertion_target_type(
    target: &TypeTerm,
    aliases: &AliasExpansionContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> Option<TypeTerm> {
    let expanded = aliases.expand_for_assignability(target, diagnostics);
    type_term_has_runtime_assertion_validator(&expanded).then_some(expanded)
}

fn runtime_assertion_target_type_from_type_expr(
    target: &TypeExpr,
    aliases: &AliasExpansionContext<'_>,
) -> Option<TypeTerm> {
    let mut diagnostics = Vec::new();
    let lowered = lower_type_term(target);
    runtime_assertion_target_type(&lowered, aliases, &mut diagnostics)
}

fn type_term_has_runtime_assertion_validator(ty: &TypeTerm) -> bool {
    match ty {
        TypeTerm::Named { name, .. } => {
            matches!(
                name.as_str(),
                "string" | "number" | "boolean" | "bigint" | "symbol" | "null" | "undefined"
            )
        }
        TypeTerm::Union { members, .. } => members
            .iter()
            .all(type_term_has_runtime_assertion_validator),
        TypeTerm::Tuple { elements, .. } => elements
            .iter()
            .all(type_term_has_runtime_assertion_validator),
        TypeTerm::TypeRef {
            name, type_args, ..
        } if name == "Array" && type_args.len() == 1 => {
            type_term_has_runtime_assertion_validator(&type_args[0])
        }
        TypeTerm::TypeRef {
            name, type_args, ..
        } if name == "__CruftStringRecord" && type_args.len() == 1 => {
            type_term_has_runtime_assertion_validator(&type_args[0])
        }
        TypeTerm::Object { properties, .. } => properties
            .iter()
            .all(|property| type_term_has_runtime_assertion_validator(&property.ty)),
        _ => false,
    }
}

fn lowered_value_matches_type(value: &LoweredValue, ty: &TypeTerm) -> bool {
    match ty {
        TypeTerm::Named { name, .. } => match name.as_str() {
            "string" => matches!(value, LoweredValue::String(_)),
            "number" => matches!(value, LoweredValue::Number(_)),
            "boolean" => matches!(value, LoweredValue::Boolean(_)),
            "bigint" => matches!(value, LoweredValue::BigInt(_)),
            "undefined" | "void" => matches!(value, LoweredValue::Undefined),
            "null" => matches!(value, LoweredValue::Null),
            _ => false,
        },
        TypeTerm::Union { members, .. } => members
            .iter()
            .any(|member| lowered_value_matches_type(value, member)),
        TypeTerm::Tuple { elements, .. } => {
            let LoweredValue::Array(actual) = value else {
                return false;
            };
            actual.len() == elements.len()
                && actual
                    .iter()
                    .zip(elements)
                    .all(|(element, ty)| lowered_value_matches_type(element, ty))
        }
        TypeTerm::TypeRef {
            name, type_args, ..
        } if name == "Array" && type_args.len() == 1 => {
            let LoweredValue::Array(elements) = value else {
                return false;
            };
            elements
                .iter()
                .all(|element| lowered_value_matches_type(element, &type_args[0]))
        }
        TypeTerm::TypeRef {
            name, type_args, ..
        } if name == "__CruftStringRecord" && type_args.len() == 1 => {
            let LoweredValue::Object(properties) = value else {
                return false;
            };
            properties
                .iter()
                .all(|property| lowered_value_matches_type(&property.value, &type_args[0]))
        }
        TypeTerm::Object { properties, .. } => {
            let LoweredValue::Object(actual) = value else {
                return false;
            };
            properties.iter().all(|property| {
                actual
                    .iter()
                    .find(|candidate| candidate.name == property.name)
                    .map(|candidate| lowered_value_matches_type(&candidate.value, &property.ty))
                    .unwrap_or(property.optional)
            }) && actual.iter().all(|candidate| {
                properties
                    .iter()
                    .any(|property| property.name == candidate.name)
            })
        }
        _ => false,
    }
}

fn type_delete_expression(
    target: &ExpressionFact,
    span: Span,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> TypeTerm {
    match &target.kind {
        ExpressionFactKind::Identifier(name) => {
            let _ = type_expression_fact(target, env, aliases, signatures, diagnostics);
            diagnostics.push(CheckDiagnostic {
                code: CheckDiagnosticCode::UnsupportedBodyExpression,
                severity: DiagnosticSeverity::Error,
                span,
                message: format!(
                    "delete target `{name}` is a local binding; P2 delete does not remove lexical bindings"
                ),
            });
        }
        ExpressionFactKind::PropertyAccess {
            object,
            property,
            optional,
        } => {
            let _ = type_expression_fact(object, env, aliases, signatures, diagnostics);
            let optional_note = if *optional { " optional/nullish" } else { "" };
            diagnostics.push(CheckDiagnostic {
                code: CheckDiagnosticCode::UnsupportedBodyExpression,
                severity: DiagnosticSeverity::Error,
                span,
                message: format!(
                    "delete target property `{property}` is{optional_note} structural object mutation; typed delete removal is not derived"
                ),
            });
        }
        ExpressionFactKind::ElementAccess {
            object,
            index,
            optional,
        } => {
            let _ = type_expression_fact(object, env, aliases, signatures, diagnostics);
            let _ = type_expression_fact(index, env, aliases, signatures, diagnostics);
            let optional_note = if *optional { " optional/nullish" } else { "" };
            diagnostics.push(CheckDiagnostic {
                code: CheckDiagnosticCode::UnsupportedBodyExpression,
                severity: DiagnosticSeverity::Error,
                span,
                message: format!(
                    "delete target element is{optional_note} array/index mutation; typed delete removal is not derived"
                ),
            });
        }
        _ => {
            let _ = type_expression_fact(target, env, aliases, signatures, diagnostics);
            diagnostics.push(CheckDiagnostic {
                code: CheckDiagnosticCode::UnsupportedBodyExpression,
                severity: DiagnosticSeverity::Error,
                span,
                message: "delete target is not a supported P2 structural removal target"
                    .to_string(),
            });
        }
    }
    TypeTerm::Named {
        name: "boolean".to_string(),
        span,
    }
}

fn validate_supported_narrowing_guard(
    guard: &NarrowingGuardFact,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) {
    match &guard.kind {
        NarrowingGuardFactKind::TypeofEquals { .. } => {}
        NarrowingGuardFactKind::Predicate { .. } => {}
        NarrowingGuardFactKind::OwnProperty { .. } => {}
        NarrowingGuardFactKind::DynamicOwnProperty { key, .. } => {
            if !matches!(
                &key.kind,
                ExpressionFactKind::Identifier(_) | ExpressionFactKind::StringLiteral(_)
            ) {
                diagnostics.push(CheckDiagnostic {
                    code: CheckDiagnosticCode::UnsupportedNarrowingGuard,
                    severity: DiagnosticSeverity::Error,
                    span: guard.span,
                    message: "dynamic `in` narrowing requires a proven string key".to_string(),
                });
            }
        }
        NarrowingGuardFactKind::Instanceof {
            subject,
            constructor,
        } => {
            let subject_matches_constructor = narrowing_subject_constructed_class(subject, env)
                .is_some_and(|class_name| class_name == *constructor)
                || narrowing_subject_type(subject, env, aliases, guard.span).is_some_and(|ty| {
                    if matches!(&ty, TypeTerm::Named { name, .. } if name == constructor) {
                        return true;
                    }
                    let constructor_type = TypeTerm::Named {
                        name: constructor.clone(),
                        span: guard.span,
                    };
                    let mut diagnostics = Vec::new();
                    let expanded_constructor =
                        aliases.expand_for_assignability(&constructor_type, &mut diagnostics);
                    diagnostics.is_empty() && type_terms_equivalent(&ty, &expanded_constructor)
                });
            if !aliases
                .class_constructors
                .contains_key(constructor.as_str())
                || !subject_matches_constructor
            {
                diagnostics.push(CheckDiagnostic {
                    code: CheckDiagnosticCode::UnsupportedNarrowingGuard,
                    severity: DiagnosticSeverity::Error,
                    span: guard.span,
                    message: format!(
                        "`instanceof {constructor}` narrowing requires a same-compartment constructed CruftScript class value"
                    ),
                });
            }
        }
        NarrowingGuardFactKind::Truthy { .. } => {}
    }
}

fn narrowing_subject_type(
    subject: &str,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    span: Span,
) -> Option<TypeTerm> {
    let mut parts = subject.split('.');
    let first = parts.next()?;
    let mut ty = env.get(first)?.ty.clone();
    for property in parts {
        if property.is_empty() {
            return None;
        }
        if let Some(property_type) = aliases.immediate_alias_property_type(&ty, property) {
            ty = property_type;
            continue;
        }
        let mut diagnostics = Vec::new();
        let expanded = aliases.expand_for_assignability(&ty, &mut diagnostics);
        if !diagnostics.is_empty() {
            return None;
        }
        let TypeTerm::Object { properties, .. } = expanded else {
            return None;
        };
        ty = properties
            .into_iter()
            .find(|candidate| candidate.name == property)
            .map(|candidate| candidate.ty)?;
    }
    if matches!(ty, TypeTerm::Unknown { .. }) {
        None
    } else {
        Some(match ty {
            TypeTerm::Named { name, .. } => TypeTerm::Named { name, span },
            other => other,
        })
    }
}

fn narrowing_subject_constructed_class(subject: &str, env: &ValueEnvironment) -> Option<String> {
    if subject.contains('.') {
        return None;
    }
    env.get(subject)?.constructed_class.clone()
}

fn immutable_local_constructed_class(
    initializer: Option<&ExpressionFact>,
    initializer_type: Option<&TypeTerm>,
    mutable: bool,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
) -> Option<String> {
    if mutable {
        return None;
    }
    match &initializer?.kind {
        ExpressionFactKind::New { class_name, .. } => Some(class_name.clone()),
        ExpressionFactKind::Call {
            callee,
            optional: false,
            ..
        } if class_method_return_call_carries_constructed_brand(
            callee,
            initializer_type?,
            env,
            aliases,
        ) =>
        {
            named_constructed_class(initializer_type?, aliases)
        }
        _ => None,
    }
}

fn class_method_return_call_carries_constructed_brand(
    callee: &ExpressionFact,
    return_type: &TypeTerm,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
) -> bool {
    if named_constructed_class(return_type, aliases).is_none() {
        return false;
    }
    let ExpressionFactKind::PropertyAccess {
        object,
        property,
        optional: false,
    } = &callee.kind
    else {
        return false;
    };
    if let ExpressionFactKind::Identifier(class_name) = &object.kind {
        if aliases
            .get_class_static_method(class_name, property)
            .is_some()
        {
            return true;
        }
    }
    expression_fact_constructed_class_name(object, env, aliases).is_some()
}

fn expression_fact_constructed_class_name(
    expr: &ExpressionFact,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
) -> Option<String> {
    match &expr.kind {
        ExpressionFactKind::Identifier(name) => {
            if let Some(constructed) = env
                .get(name)
                .and_then(|binding| binding.constructed_class.clone())
            {
                return Some(constructed);
            }
            match env.get(name).map(|binding| &binding.ty) {
                Some(TypeTerm::Named { name, .. })
                    if aliases.class_constructors.contains_key(name.as_str()) =>
                {
                    Some(name.clone())
                }
                _ => None,
            }
        }
        _ => None,
    }
}

fn named_constructed_class(ty: &TypeTerm, aliases: &AliasExpansionContext<'_>) -> Option<String> {
    match ty {
        TypeTerm::Named { name, .. } if aliases.class_constructors.contains_key(name.as_str()) => {
            Some(name.clone())
        }
        _ => None,
    }
}

fn constructor_term_for_new<'a>(
    class_name: &str,
    env: &ValueEnvironment,
    aliases: &'a AliasExpansionContext<'a>,
) -> Option<&'a ClassConstructorTerm> {
    if let Some(class_constructor) = aliases.class_constructors.get(class_name) {
        return Some(class_constructor);
    }
    let binding = env.get(class_name)?;
    if binding.mutable {
        return None;
    }
    let TypeTerm::Constructor { instance_type, .. } = &binding.ty else {
        return None;
    };
    let TypeTerm::Named { name, .. } = instance_type.as_ref() else {
        return None;
    };
    aliases.class_constructors.get(name.as_str()).copied()
}

fn class_constructor_type_term(constructor: &ClassConstructorTerm) -> TypeTerm {
    TypeTerm::Constructor {
        params: constructor
            .params
            .iter()
            .map(|param| FunctionTypeParamTerm {
                name: Some(param.name.clone()),
                ty: param.ty.clone(),
                span: param.span,
            })
            .collect(),
        instance_type: Box::new(TypeTerm::Named {
            name: constructor.name.clone(),
            span: constructor.span,
        }),
        is_abstract: false,
        span: constructor.span,
    }
}

fn validate_narrowing_guard_value_types(
    guard: &NarrowingGuardFact,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) {
    if let NarrowingGuardFactKind::DynamicOwnProperty { key, .. } = &guard.kind {
        let actual = type_expression_fact(key, env, aliases, signatures, diagnostics);
        let expected = TypeTerm::Named {
            name: "string".to_string(),
            span: key.span,
        };
        if !is_assignable(&actual, &expected, aliases, diagnostics) {
            diagnostics.push(CheckDiagnostic {
                code: CheckDiagnosticCode::UnsupportedNarrowingGuard,
                severity: DiagnosticSeverity::Error,
                span: guard.span,
                message: "dynamic `in` narrowing requires a proven string key".to_string(),
            });
        }
    }
}

fn class_method_if_guard_is_plain_boolean(
    subject: &ExpressionFact,
    guard: &NarrowingGuard,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> bool {
    if !matches!(guard, NarrowingGuard::Truthy { .. }) {
        return false;
    }
    let actual = type_expression_fact(subject, env, aliases, signatures, diagnostics);
    let expected = TypeTerm::Named {
        name: "boolean".to_string(),
        span: subject.span,
    };
    is_assignable(&actual, &expected, aliases, diagnostics)
}

fn lower_expression_narrowing_guard_parts(
    subject_expr: &ExpressionFact,
    guard: &NarrowingGuard,
    env: &ValueEnvironment,
    signatures: &FunctionSignatureContext<'_>,
) -> Option<NarrowingGuardFact> {
    if let Some(predicate) = lower_predicate_call_guard(subject_expr, guard, env, signatures) {
        return Some(predicate);
    }
    let subject = expression_narrowing_subject_spelling(subject_expr)?;
    let kind = match guard {
        NarrowingGuard::TypeofEquals { expected, .. } => NarrowingGuardFactKind::TypeofEquals {
            subject: subject.clone(),
            expected: expected.clone(),
        },
        NarrowingGuard::Instanceof { constructor, .. } => NarrowingGuardFactKind::Instanceof {
            subject: subject.clone(),
            constructor: constructor.clone(),
        },
        NarrowingGuard::OwnProperty { property, .. } => NarrowingGuardFactKind::OwnProperty {
            subject: subject.clone(),
            property: property.clone(),
        },
        NarrowingGuard::DynamicOwnProperty { key, .. } => {
            NarrowingGuardFactKind::DynamicOwnProperty {
                subject: subject.clone(),
                key: lower_expression_fact(key),
            }
        }
        NarrowingGuard::Truthy { .. } => NarrowingGuardFactKind::Truthy {
            subject: subject.clone(),
        },
    };
    Some(NarrowingGuardFact {
        kind,
        span: subject_expr.span,
    })
}

fn expression_narrowing_subject_spelling(subject_expr: &ExpressionFact) -> Option<String> {
    match &subject_expr.kind {
        ExpressionFactKind::Identifier(subject) => Some(subject.clone()),
        ExpressionFactKind::PropertyAccess {
            object,
            property,
            optional: false,
        } => expression_narrowing_subject_spelling(object)
            .map(|object| format!("{object}.{property}")),
        _ => None,
    }
}

fn lower_predicate_call_guard(
    subject_expr: &ExpressionFact,
    guard: &NarrowingGuard,
    env: &ValueEnvironment,
    signatures: &FunctionSignatureContext<'_>,
) -> Option<NarrowingGuardFact> {
    if !matches!(guard, NarrowingGuard::Truthy { .. }) {
        return None;
    }
    let ExpressionFactKind::Call {
        callee,
        args,
        optional: _,
    } = &subject_expr.kind
    else {
        return None;
    };
    let [arg] = args.as_slice() else {
        return None;
    };
    let ExpressionFactKind::Identifier(subject) = &arg.kind else {
        return None;
    };
    let target = predicate_target_for_callee(callee, env, signatures)?;
    let fact = NarrowingGuardFact {
        kind: NarrowingGuardFactKind::Predicate {
            subject: subject.clone(),
            target: signatures
                .aliases
                .expand_for_assignability(&target, &mut Vec::new()),
        },
        span: subject_expr.span,
    };
    Some(fact)
}

fn predicate_target_for_callee(
    callee: &ExpressionFact,
    env: &ValueEnvironment,
    signatures: &FunctionSignatureContext<'_>,
) -> Option<TypeTerm> {
    if let Some(signature) = predicate_record_signature_for_callee(callee, env) {
        return Some(signature.target);
    }
    let callee_type = match &callee.kind {
        ExpressionFactKind::Identifier(callee_name) => {
            if let Some(signature) = signatures.get(callee_name) {
                return predicate_target_from_function_parts(
                    signature.params.iter().map(|param| FunctionTypeParamTerm {
                        name: Some(param.name.clone()),
                        ty: param.ty.clone(),
                        span: param.span,
                    }),
                    signature.return_type.as_ref(),
                );
            }

            let binding = env.get(callee_name)?;
            if binding.mutable {
                return None;
            }
            binding.ty.clone()
        }
        ExpressionFactKind::PropertyAccess {
            object, property, ..
        } => {
            let ExpressionFactKind::Identifier(object_name) = &object.kind else {
                return None;
            };
            let binding = env.get(object_name)?;
            if binding.mutable {
                return None;
            }
            let object_ty = &binding.ty;
            let TypeTerm::Object { properties, .. } = object_ty else {
                return None;
            };
            properties
                .iter()
                .find(|candidate| candidate.name == *property)
                .map(|candidate| candidate.ty.clone())?
        }
        ExpressionFactKind::ElementAccess { object, index, .. } => {
            let ExpressionFactKind::Identifier(object_name) = &object.kind else {
                return None;
            };
            let binding = env.get(object_name)?;
            if binding.source != ValueBindingSource::Local || binding.mutable {
                return None;
            }
            let property = static_string_key(index, env)?;
            let TypeTerm::Object { properties, .. } = &binding.ty else {
                return None;
            };
            properties
                .iter()
                .find(|candidate| candidate.name == property)
                .map(|candidate| candidate.ty.clone())?
        }
        _ => return None,
    };

    predicate_target_from_method_or_function_type(callee_type)
}

fn predicate_target_from_method_or_function_type(ty: TypeTerm) -> Option<TypeTerm> {
    let TypeTerm::Function {
        params,
        return_type,
        ..
    } = ty
    else {
        return None;
    };
    if let Some(target) =
        predicate_target_from_function_parts(params.iter().cloned(), Some(return_type.as_ref()))
    {
        return Some(target);
    }
    if params.first().and_then(|param| param.name.as_deref()) == Some("this") {
        return predicate_target_from_function_parts(
            params.iter().skip(1).cloned(),
            Some(return_type.as_ref()),
        );
    }
    None
}

struct PredicateRecordSignature {
    params: Vec<FunctionTypeParamTerm>,
    target: TypeTerm,
}

fn predicate_record_signature_for_callee(
    callee: &ExpressionFact,
    env: &ValueEnvironment,
) -> Option<PredicateRecordSignature> {
    let ExpressionFactKind::ElementAccess { object, index, .. } = &callee.kind else {
        return None;
    };
    let ExpressionFactKind::Identifier(object_name) = &object.kind else {
        return None;
    };
    let binding = env.get(object_name)?;
    if binding.source != ValueBindingSource::Local || binding.mutable {
        return None;
    }
    if static_string_key(index, env).is_some() {
        return None;
    }
    if !dynamic_predicate_record_key_is_supported(index, env) {
        return None;
    }
    let TypeTerm::Object { properties, .. } = &binding.ty else {
        return None;
    };
    let mut resolved = Vec::new();
    for property in properties {
        let TypeTerm::Function {
            params,
            return_type,
            ..
        } = &property.ty
        else {
            return None;
        };
        let target = predicate_target_from_function_parts(
            params.iter().cloned(),
            Some(return_type.as_ref()),
        )?;
        resolved.push((params.clone(), target));
    }
    let (params, target) = resolved.first()?.clone();
    if resolved
        .iter()
        .skip(1)
        .any(|(candidate_params, candidate_target)| {
            candidate_params != &params || candidate_target != &target
        })
    {
        return None;
    }
    Some(PredicateRecordSignature { params, target })
}

fn dynamic_predicate_record_key_is_supported(
    index: &ExpressionFact,
    env: &ValueEnvironment,
) -> bool {
    let ExpressionFactKind::Identifier(name) = &index.kind else {
        return false;
    };
    let Some(binding) = env.get(name) else {
        return false;
    };
    if binding.mutable {
        return false;
    }
    matches!(&binding.ty, TypeTerm::Named { name, .. } if name == "string")
}

fn predicate_target_from_function_parts(
    mut params: impl Iterator<Item = FunctionTypeParamTerm>,
    return_type: Option<&TypeTerm>,
) -> Option<TypeTerm> {
    let TypeTerm::TypePredicate {
        parameter, target, ..
    } = return_type?
    else {
        return None;
    };
    let predicate_param = params.next()?;
    if predicate_param.name.as_deref() != Some(parameter.as_str()) {
        return None;
    }
    Some(target.as_ref().clone())
}

fn unsupported_write_or_body_message(spelling: &str) -> String {
    if is_write_surface_expression(spelling) {
        format!(
            "CruftScript write/assignment/update/delete forms are not derived yet (`{spelling}`); mutation cannot reach runtime without a mutable lowered-value substrate"
        )
    } else {
        format!("unsupported CruftScript body expression `{spelling}`")
    }
}

fn is_write_surface_expression(spelling: &str) -> bool {
    let trimmed = spelling.trim();
    trimmed.starts_with("delete ")
        || trimmed.contains("++")
        || trimmed.contains("--")
        || ["+=", "-=", "*=", "/=", "%=", "??=", "||=", "&&="]
            .iter()
            .any(|op| trimmed.contains(op))
        || contains_plain_assignment(trimmed)
}

fn contains_plain_assignment(spelling: &str) -> bool {
    let bytes = spelling.as_bytes();
    for (index, byte) in bytes.iter().enumerate() {
        if *byte != b'=' {
            continue;
        }
        let prev = index.checked_sub(1).and_then(|i| bytes.get(i)).copied();
        let next = bytes.get(index + 1).copied();
        if matches!(
            prev,
            Some(b'=' | b'!' | b'<' | b'>' | b'+' | b'-' | b'*' | b'/' | b'%' | b'?' | b'|' | b'&')
        ) || matches!(next, Some(b'=' | b'>'))
        {
            continue;
        }
        return true;
    }
    false
}

fn is_as_assertion_expression(spelling: &str) -> bool {
    let trimmed = spelling.trim();
    trimmed.split_whitespace().any(|part| part == "as")
}

fn is_non_null_assertion_expression(spelling: &str) -> bool {
    let trimmed = spelling.trim();
    trimmed.ends_with('!')
        && trimmed.len() > 1
        && !trimmed.ends_with("!=")
        && !trimmed.ends_with("!==")
}

fn is_new_expression(spelling: &str) -> bool {
    spelling.trim_start().starts_with("new ")
}

fn parse_zero_arg_new_expression(spelling: &str) -> Option<&str> {
    let trimmed = spelling.trim();
    let rest = trimmed.strip_prefix("new ")?.trim_start();
    let name_end = rest.find(|c: char| !(c == '_' || c.is_ascii_alphanumeric()))?;
    let name = &rest[..name_end];
    if name.is_empty() {
        return None;
    }
    let tail = rest[name_end..].trim();
    (tail == "()").then_some(name)
}

fn stdlib_span() -> Span {
    Span { start: 0, end: 0 }
}

fn stdlib_named(name: &str) -> TypeTerm {
    TypeTerm::Named {
        name: name.to_string(),
        span: stdlib_span(),
    }
}

fn stdlib_array_of(elem: TypeTerm) -> TypeTerm {
    TypeTerm::TypeRef {
        name: "Array".to_string(),
        type_args: vec![elem],
        span: stdlib_span(),
    }
}

fn stdlib_method(this_ty: TypeTerm, args: Vec<TypeTerm>, ret: TypeTerm) -> TypeTerm {
    let mut params = vec![FunctionTypeParamTerm {
        name: Some("this".to_string()),
        ty: this_ty,
        span: stdlib_span(),
    }];
    for (index, arg) in args.into_iter().enumerate() {
        params.push(FunctionTypeParamTerm {
            name: Some(format!("arg{index}")),
            ty: arg,
            span: stdlib_span(),
        });
    }
    TypeTerm::Function {
        type_params: Vec::new(),
        params,
        return_type: Box::new(ret),
        boundary: None,
        span: stdlib_span(),
    }
}

fn stdlib_unknown() -> TypeTerm {
    TypeTerm::Unknown {
        span: stdlib_span(),
    }
}

fn stdlib_is_optional_param_type(ty: &TypeTerm) -> bool {
    match ty {
        TypeTerm::Named { name, .. } => name == "undefined",
        TypeTerm::Union { members, .. } => members.iter().any(stdlib_is_optional_param_type),
        _ => false,
    }
}

fn stdlib_optional(inner: TypeTerm) -> TypeTerm {
    TypeTerm::Union {
        members: vec![inner, stdlib_named("undefined")],
        span: stdlib_span(),
    }
}

fn stdlib_receiver_member_type(receiver: &TypeTerm, property: &str) -> Option<TypeTerm> {
    match receiver {
        TypeTerm::Named { name, .. } => match name.as_str() {
            "string" => stdlib_string_member(property),
            "number" => stdlib_number_member(property),
            "boolean" => stdlib_boolean_member(property),
            "RegExp" => stdlib_regexp_member(property),
            "Map" => stdlib_map_member(property),
            "Set" => stdlib_set_member(property),
            _ => None,
        },

        TypeTerm::TypeRef {
            name, type_args, ..
        } if name == "Array" => {
            let elem = type_args.first().cloned().unwrap_or_else(stdlib_unknown);
            stdlib_array_member(property, &elem)
        }
        _ => None,
    }
}

fn stdlib_static_namespace_member(namespace: &str, property: &str) -> Option<TypeTerm> {
    match namespace {
        "JSON" => stdlib_json_member(property),
        "Math" => stdlib_math_member(property),
        "Object" => stdlib_object_static_member(property),
        "Number" => stdlib_number_static_member(property),
        _ => None,
    }
}

const STDLIB_STATIC_NAMESPACES: &[&str] = &["JSON", "Math", "Object", "Number"];

fn stdlib_string_member(property: &str) -> Option<TypeTerm> {
    let s = || stdlib_named("string");
    let num = || stdlib_named("number");
    let boolean = || stdlib_named("boolean");
    let m = |args: Vec<TypeTerm>, ret: TypeTerm| stdlib_method(s(), args, ret);
    Some(match property {
        property if property == STRING_CHAR_CODE_AT_STDLIB_SIGNATURE.property => {
            string_char_code_at_generated_stdlib_signature_type()
        }
        "length" => num(),
        "replace" => m(
            vec![stdlib_string_or_regexp(), stdlib_string_replacement()],
            s(),
        ),
        "replaceAll" => m(
            vec![stdlib_string_or_regexp(), stdlib_string_replacement()],
            s(),
        ),
        "match" => m(
            vec![stdlib_named("RegExp")],
            stdlib_nullable(stdlib_array_of(s())),
        ),
        "search" => m(vec![stdlib_named("RegExp")], num()),
        "split" => m(vec![stdlib_string_or_regexp()], stdlib_array_of(s())),
        "trim" => m(vec![], s()),
        "trimStart" => m(vec![], s()),
        "trimEnd" => m(vec![], s()),
        "toUpperCase" => m(vec![], s()),
        "toLowerCase" => m(vec![], s()),
        "toString" => m(vec![], s()),
        "includes" => m(vec![s()], boolean()),
        "startsWith" => m(vec![s()], boolean()),
        "endsWith" => m(vec![s()], boolean()),
        "charAt" => m(vec![num()], s()),
        "codePointAt" => m(vec![num()], stdlib_optional(num())),
        "repeat" => m(vec![num()], s()),
        "padStart" => m(vec![num(), stdlib_optional(s())], s()),
        "padEnd" => m(vec![num(), stdlib_optional(s())], s()),
        "indexOf" => m(vec![s()], num()),
        "lastIndexOf" => m(vec![s()], num()),
        "concat" => m(vec![s()], s()),
        "slice" => m(vec![num(), stdlib_optional(num())], s()),
        "substring" => m(vec![num(), stdlib_optional(num())], s()),
        "at" => m(vec![num()], stdlib_optional(s())),
        _ => return None,
    })
}

pub fn string_char_code_at_generated_stdlib_signature_type() -> TypeTerm {
    let spec = string_char_code_at_generated_stdlib_signature_spec();
    debug_assert_eq!(spec.receiver, GeneratedStdlibReceiver::String);
    debug_assert_eq!(spec.args, &[GeneratedStdlibDomain::Number]);
    debug_assert_eq!(spec.returns, &[GeneratedStdlibDomain::Number]);
    stdlib_method(
        stdlib_named("string"),
        vec![stdlib_named("number")],
        stdlib_named("number"),
    )
}

