fn stdlib_array_member(property: &str, elem: &TypeTerm) -> Option<TypeTerm> {
    let s = || stdlib_named("string");
    let num = || stdlib_named("number");
    let boolean = || stdlib_named("boolean");
    let arr = || stdlib_array_of(elem.clone());
    let this_ty = stdlib_array_of(elem.clone());
    let m = |args: Vec<TypeTerm>, ret: TypeTerm| stdlib_method(this_ty.clone(), args, ret);
    Some(match property {
        "length" => num(),
        "join" => m(vec![s()], s()),
        "push" => m(vec![elem.clone()], num()),
        "pop" => m(vec![], stdlib_optional(elem.clone())),
        "shift" => m(vec![], stdlib_optional(elem.clone())),
        "indexOf" => m(vec![elem.clone()], num()),
        "lastIndexOf" => m(vec![elem.clone()], num()),
        "includes" => m(vec![elem.clone()], boolean()),
        "concat" => m(vec![arr()], arr()),
        "slice" => m(vec![num(), stdlib_optional(num())], arr()),
        "reverse" => m(vec![], arr()),
        "at" => m(vec![num()], stdlib_optional(elem.clone())),

        "map" => m(
            vec![stdlib_callback(elem.clone(), stdlib_unknown())],
            stdlib_array_of(stdlib_unknown()),
        ),
        "flatMap" => m(
            vec![stdlib_callback(elem.clone(), stdlib_unknown())],
            stdlib_array_of(stdlib_unknown()),
        ),
        "filter" => m(vec![stdlib_callback(elem.clone(), boolean())], arr()),
        "forEach" => m(
            vec![stdlib_callback(elem.clone(), stdlib_unknown())],
            stdlib_named("undefined"),
        ),
        "find" => m(
            vec![stdlib_callback(elem.clone(), boolean())],
            stdlib_optional(elem.clone()),
        ),
        "findIndex" => m(vec![stdlib_callback(elem.clone(), boolean())], num()),
        "some" => m(vec![stdlib_callback(elem.clone(), boolean())], boolean()),
        "every" => m(vec![stdlib_callback(elem.clone(), boolean())], boolean()),
        "reduce" => m(vec![stdlib_unknown(), stdlib_unknown()], stdlib_unknown()),
        _ => return None,
    })
}

fn stdlib_callback(elem: TypeTerm, ret: TypeTerm) -> TypeTerm {
    TypeTerm::Function {
        type_params: Vec::new(),
        params: vec![FunctionTypeParamTerm {
            name: Some("x".to_string()),
            ty: elem,
            span: stdlib_span(),
        }],
        return_type: Box::new(ret),
        boundary: None,
        span: stdlib_span(),
    }
}

fn stdlib_callback_params_conform(
    actual_params: &[FunctionTypeParamTerm],
    expected_params: &[FunctionTypeParamTerm],
    aliases: &AliasExpansionContext<'_>,
) -> bool {

    if actual_params.len() > expected_params.len() {
        return false;
    }
    let mut scratch = Vec::new();
    expected_params
        .iter()
        .zip(actual_params)
        .all(|(exp, act)| is_assignable(&exp.ty, &act.ty, aliases, &mut scratch))
}

fn refine_map_return_type(declared_return: &TypeTerm, arg_types: &[TypeTerm]) -> Option<TypeTerm> {

    let TypeTerm::TypeRef {
        name, type_args, ..
    } = declared_return
    else {
        return None;
    };
    if name != "Array" || type_args.len() != 1 || !matches!(type_args[0], TypeTerm::Unknown { .. })
    {
        return None;
    }
    let TypeTerm::Function { return_type, .. } = arg_types.first()? else {
        return None;
    };
    if matches!(**return_type, TypeTerm::Unknown { .. }) {
        return None;
    }
    Some(stdlib_array_of((**return_type).clone()))
}

fn refine_flat_map_return_type(
    declared_return: &TypeTerm,
    arg_types: &[TypeTerm],
) -> Option<TypeTerm> {
    let TypeTerm::TypeRef {
        name, type_args, ..
    } = declared_return
    else {
        return None;
    };
    if name != "Array" || type_args.len() != 1 || !matches!(type_args[0], TypeTerm::Unknown { .. })
    {
        return None;
    }
    let TypeTerm::Function { return_type, .. } = arg_types.first()? else {
        return None;
    };
    if matches!(**return_type, TypeTerm::Unknown { .. }) {
        return None;
    }
    if let TypeTerm::TypeRef {
        name, type_args, ..
    } = return_type.as_ref()
    {
        if name == "Array" && type_args.len() == 1 {
            return Some(stdlib_array_of(type_args[0].clone()));
        }
    }
    Some(stdlib_array_of((**return_type).clone()))
}

