fn stdlib_string_replacement() -> TypeTerm {
    let s = || stdlib_named("string");
    let param = |name: &str| FunctionTypeParamTerm {
        name: Some(name.to_string()),
        ty: s(),
        span: stdlib_span(),
    };
    let replacer = TypeTerm::Function {
        type_params: Vec::new(),
        params: vec![param("match"), param("g1"), param("g2"), param("g3")],
        return_type: Box::new(s()),
        boundary: None,
        span: stdlib_span(),
    };
    TypeTerm::Union {
        members: vec![s(), replacer],
        span: stdlib_span(),
    }
}

