fn type_property_access_expression(
    object: &ExpressionFact,
    property: &str,
    optional: bool,
    span: Span,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> TypeTerm {
    let subject = ExpressionFact {
        kind: ExpressionFactKind::PropertyAccess {
            object: Box::new(object.clone()),
            property: property.to_string(),
            optional,
        },
        span,
    };
    if let Some(subject_name) = expression_narrowing_subject_spelling(&subject) {
        if let Some(refined) = env.property_refinement(&subject_name) {
            return refined.clone();
        }
    }
    if let ExpressionFactKind::Identifier(class_name) = &object.kind {
        if let Some(static_field) = aliases.get_class_static_field(class_name, property) {

            if static_field.optional {
                return TypeTerm::Union {
                    members: vec![
                        static_field.ty.clone(),
                        TypeTerm::Named {
                            name: "undefined".to_string(),
                            span,
                        },
                    ],
                    span,
                };
            }
            return static_field.ty.clone();
        }
    }
    let raw_object_type = type_expression_fact(object, env, aliases, signatures, diagnostics);

    let optional_adds_undefined = optional
        && type_term_includes_nullish(
            &aliases.expand_for_assignability(&raw_object_type, diagnostics),
        );
    if let Some(property_type) = aliases.immediate_alias_property_type(&raw_object_type, property) {
        return if optional_adds_undefined {
            TypeTerm::Union {
                members: vec![
                    property_type,
                    TypeTerm::Named {
                        name: "undefined".to_string(),
                        span,
                    },
                ],
                span,
            }
        } else {
            property_type
        };
    }

    if let Some(member_type) = stdlib_receiver_member_type(&raw_object_type, property) {
        return if optional_adds_undefined {
            TypeTerm::Union {
                members: vec![member_type, stdlib_named("undefined")],
                span,
            }
        } else {
            member_type
        };
    }

    if let ExpressionFactKind::Identifier(namespace) = &object.kind {
        if STDLIB_STATIC_NAMESPACES.contains(&namespace.as_str()) {
            if let Some(member_type) = stdlib_static_namespace_member(namespace, property) {
                return member_type;
            }
        }
    }
    let object_type = aliases.expand_for_assignability(&raw_object_type, diagnostics);
    let object_type = match object_type {
        TypeTerm::Union { members, .. } => {
            let non_nullish = members
                .into_iter()
                .filter(|member| !is_nullish_type_term(member))
                .collect::<Vec<_>>();
            if non_nullish.len() == 1 {
                non_nullish.into_iter().next().unwrap()
            } else {
                TypeTerm::Union {
                    members: non_nullish,
                    span,
                }
            }
        }
        other => other,
    };
    if let TypeTerm::TypeRef {
        name, type_args, ..
    } = &object_type
    {
        if name == "__CruftStringRecord" && type_args.len() == 1 {
            let property_type = type_args[0].clone();
            return if optional || optional_adds_undefined {
                TypeTerm::Union {
                    members: vec![
                        property_type,
                        TypeTerm::Named {
                            name: "undefined".to_string(),
                            span,
                        },
                    ],
                    span,
                }
            } else {
                property_type
            };
        }
    }
    let TypeTerm::Object { properties, .. } = object_type else {
        let message = if matches!(object_type, TypeTerm::Unknown { .. }) {
            format!("property read `{property}` from `unknown` requires a proven object shape")
        } else {
            format!("property read `{property}` requires a known object type")
        };
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::PropertyReadUnsupported,
            severity: DiagnosticSeverity::Error,
            span,
            message,
        });
        return TypeTerm::Unknown { span };
    };
    let Some(property_term) = properties
        .iter()
        .find(|candidate| candidate.name == property)
    else {
        diagnostics.push(CheckDiagnostic {
            code: CheckDiagnosticCode::PropertyReadUnsupported,
            severity: DiagnosticSeverity::Error,
            span,
            message: format!("property `{property}` is not present on the object type"),
        });
        return TypeTerm::Unknown { span };
    };
    if property_term.optional || optional_adds_undefined {
        TypeTerm::Union {
            members: vec![
                property_term.ty.clone(),
                TypeTerm::Named {
                    name: "undefined".to_string(),
                    span,
                },
            ],
            span,
        }
    } else {
        property_term.ty.clone()
    }
}

fn is_nullish_type_term(term: &TypeTerm) -> bool {
    matches!(
        term,
        TypeTerm::Named { name, .. } if name == "undefined" || name == "null"
    )
}

fn type_term_is_any(ty: &TypeTerm) -> bool {
    match ty {
        TypeTerm::Named { name, .. } => name.trim() == "any",
        TypeTerm::Opaque { spelling, .. } => spelling.trim() == "any",
        _ => false,
    }
}

fn type_term_includes_nullish(term: &TypeTerm) -> bool {
    match term {
        TypeTerm::Union { members, .. } => members.iter().any(type_term_includes_nullish),
        other => is_nullish_type_term(other),
    }
}

fn type_binary_add_expression(
    left: &ExpressionFact,
    right: &ExpressionFact,
    span: Span,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> TypeTerm {
    let left_type = type_expression_fact(left, env, aliases, signatures, diagnostics);
    let right_type = type_expression_fact(right, env, aliases, signatures, diagnostics);
    let left_name = primitive_type_name(&left_type);
    let right_name = primitive_type_name(&right_type);
    match (left_name, right_name) {
        (Some("number"), Some("number")) => TypeTerm::Named {
            name: "number".to_string(),
            span,
        },
        (Some("string"), Some("string"))
        | (Some("string"), Some("number"))
        | (Some("number"), Some("string")) => TypeTerm::Named {
            name: "string".to_string(),
            span,
        },
        _ => {
            diagnostics.push(CheckDiagnostic {
                code: CheckDiagnosticCode::UnsupportedBodyExpression,
                severity: DiagnosticSeverity::Error,
                span,
                message: "binary `+` requires proven number/number or string/primitive operands"
                    .to_string(),
            });
            TypeTerm::Unknown { span }
        }
    }
}

