fn type_nullish_coalesce_expression(
    left: &ExpressionFact,
    right: &ExpressionFact,
    span: Span,
    env: &ValueEnvironment,
    aliases: &AliasExpansionContext<'_>,
    signatures: &FunctionSignatureContext<'_>,
    diagnostics: &mut Vec<CheckDiagnostic>,
) -> TypeTerm {
    let left_type = type_expression_fact(left, env, aliases, signatures, diagnostics);
    if !type_term_includes_nullish(&aliases.expand_for_assignability(&left_type, diagnostics)) {
        let _ = type_expression_fact(right, env, aliases, signatures, diagnostics);
        return left_type;
    }
    let right_type = type_expression_fact(right, env, aliases, signatures, diagnostics);
    let Some(non_nullish_left) = type_term_without_nullish(&left_type, span, aliases, diagnostics)
    else {
        return right_type;
    };
    normalize_union_members(vec![non_nullish_left, right_type], span)
}

