    fn span() -> Span {
        Span::new(0, 1)
    }

    fn ty(name: &str) -> TypeExpr {
        TypeExpr {
            kind: TypeExprKind::Named(name.to_string()),
            span: span(),
        }
    }

    fn type_ref(name: &str, type_args: Vec<TypeExpr>) -> TypeExpr {
        TypeExpr {
            kind: TypeExprKind::TypeRef {
                name: name.to_string(),
                type_args,
            },
            span: span(),
        }
    }

    fn union_ty(members: Vec<TypeExpr>) -> TypeExpr {
        TypeExpr {
            kind: TypeExprKind::Union(members),
            span: span(),
        }
    }

    fn object_ty(properties: Vec<cruftscript_parser::ObjectTypeProperty>) -> TypeExpr {
        TypeExpr {
            kind: TypeExprKind::Object(cruftscript_parser::ObjectTypeExpr { properties }),
            span: span(),
        }
    }

    fn object_prop(
        name: &str,
        ty: TypeExpr,
        readonly: bool,
        optional: bool,
    ) -> cruftscript_parser::ObjectTypeProperty {
        cruftscript_parser::ObjectTypeProperty {
            name: name.to_string(),
            ty,
            readonly,
            optional,
            span: span(),
        }
    }

    fn fn_ty(param: TypeExpr, return_type: TypeExpr) -> TypeExpr {
        TypeExpr {
            kind: TypeExprKind::Function {
                type_params: Vec::new(),
                params: vec![FunctionTypeParam {
                    name: Some("x".to_string()),
                    ty: param,
                    span: span(),
                }],
                return_type: Box::new(return_type),
                boundary_clause: None,
            },
            span: span(),
        }
    }

    fn function_ty(params: Vec<(&str, TypeExpr)>, return_type: TypeExpr) -> TypeExpr {
        TypeExpr {
            kind: TypeExprKind::Function {
                type_params: Vec::new(),
                params: params
                    .into_iter()
                    .map(|(name, ty)| FunctionTypeParam {
                        name: Some(name.to_string()),
                        ty,
                        span: span(),
                    })
                    .collect(),
                return_type: Box::new(return_type),
                boundary_clause: None,
            },
            span: span(),
        }
    }

    fn constructor_ty(params: Vec<(&str, TypeExpr)>, instance_type: TypeExpr) -> TypeExpr {
        TypeExpr {
            kind: TypeExprKind::Constructor {
                params: params
                    .into_iter()
                    .map(|(name, ty)| FunctionTypeParam {
                        name: Some(name.to_string()),
                        ty,
                        span: span(),
                    })
                    .collect(),
                instance_type: Box::new(instance_type),
                is_abstract: true,
            },
            span: span(),
        }
    }

    fn ident(name: &str) -> ExprEnvelope {
        ExprEnvelope {
            kind: ExprEnvelopeKind::Identifier(name.to_string()),
            span: span(),
        }
    }

    fn number_lit(value: &str) -> ExprEnvelope {
        ExprEnvelope {
            kind: ExprEnvelopeKind::NumberLiteral(value.to_string()),
            span: span(),
        }
    }

    fn call(callee: &str, args: Vec<ExprEnvelope>) -> ExprEnvelope {
        ExprEnvelope {
            kind: ExprEnvelopeKind::Call {
                callee: Box::new(ident(callee)),
                args,
                optional: false,
            },
            span: span(),
        }
    }

    fn secure_boundary(site: BoundarySite) -> BoundaryClause {
        BoundaryClause {
            span: span(),
            site,
            directives: vec![BoundaryDirective::Policy("secure".to_string())],
        }
    }

    fn exported_function_with_returns(
        name: &str,
        type_params: Vec<TypeParam>,
        params: Vec<FunctionParam>,
        return_type: Option<TypeExpr>,
        returns: Vec<ExprEnvelope>,
    ) -> ExportedFunction {
        ExportedFunction {
            name: name.to_string(),
            exported: true,
            type_params,
            params,
            return_type,
            boundary_clause: Some(secure_boundary(BoundarySite::FunctionDeclaration)),
            body_span: span(),
            body: FunctionBody {
                span: span(),
                statements: returns
                    .into_iter()
                    .map(|argument| {
                        BodyStmt::Return(ReturnStmt {
                            argument: Some(argument),
                            span: span(),
                        })
                    })
                    .collect(),
            },
            span: span(),
        }
    }

    fn unit_with_functions(functions: Vec<ExportedFunction>) -> CruftScriptSourceUnit {
        unit_with_type_aliases_and_functions(Vec::new(), functions)
    }

    fn type_alias(name: &str, aliased_type: TypeExpr) -> TypeAliasDecl {
        TypeAliasDecl {
            name: name.to_string(),
            type_params: Vec::new(),
            aliased_type,
            span: span(),
        }
    }

    fn unit_with_type_aliases_and_functions(
        aliases: Vec<TypeAliasDecl>,
        functions: Vec<ExportedFunction>,
    ) -> CruftScriptSourceUnit {
        let mut items = vec![SourceItem::BoundaryDefault(BoundaryDefaultDecl {
            policy_name: "secure".to_string(),
            span: span(),
        })];
        items.extend(aliases.into_iter().map(SourceItem::TypeAlias));
        items.push(SourceItem::Compartment(CompartmentDecl {
            name: "Core".to_string(),
            boundary_clause: Some(secure_boundary(BoundarySite::Compartment)),
            endowments: Vec::new(),
            span: span(),
            body_span: span(),
            body_items: functions
                .into_iter()
                .map(CompartmentItem::ExportFunction)
                .collect(),
        }));
        CruftScriptSourceUnit {
            source_kind: SourceKind::NativeCruftScript,
            span: span(),
            items,
            diagnostics: Vec::new(),
        }
    }

    #[test]
    fn accepts_unknown_bottom_surface() {
        let report = check_source_text(ACCEPTED_FIXTURE);

        assert!(report.accepted, "{report:#?}");
        assert!(report.diagnostics.is_empty(), "{report:#?}");
    }

