    #[test]
    fn collects_current_parser_binding_environment() {
        let report = check_source_text(ACCEPTED_FIXTURE);

        assert_eq!(report.bindings.boundary_defaults.len(), 1);
        assert_eq!(report.bindings.boundary_defaults[0].policy_name, "secure");
        assert_eq!(report.bindings.compartments.len(), 1);
        let compartment = &report.bindings.compartments[0];
        assert_eq!(compartment.name, "Core");
        assert_eq!(compartment.imports[0].name, "getUser");
        assert_eq!(compartment.functions[0].name, "process");
        assert_eq!(compartment.functions[0].type_params[0].name, "T");
        assert_eq!(compartment.functions[0].params[0].name, "input");
    }

    #[test]
    fn lowers_current_parser_signature_to_type_terms() {
        let report = check_source_text(ACCEPTED_FIXTURE);

        assert_eq!(report.types.function_signatures.len(), 1);
        let signature = &report.types.function_signatures[0];
        assert_eq!(signature.name, "process");
        assert!(signature.boundary.is_some());
        assert_eq!(signature.type_params[0].name, "T");
        assert!(matches!(
            signature.type_params[0].constraint,
            Some(TypeTerm::Named { ref name, .. }) if name == "User"
        ));
        assert!(matches!(
            signature.params[0].ty,
            TypeTerm::Named { ref name, .. } if name == "T"
        ));
        assert!(matches!(
            signature.return_type,
            Some(TypeTerm::Union { ref members, .. })
                if members.len() == 2
                    && matches!(members[0], TypeTerm::Named { ref name, .. } if name == "T")
                    && matches!(members[1], TypeTerm::Unknown { .. })
        ));
    }

    #[test]
    fn lowers_conditional_and_opaque_parser_type_terms() {
        let conditional = TypeExpr {
            kind: TypeExprKind::Conditional {
                check: Box::new(named_type("T", 61)),
                extends: Box::new(opaque_type("Serializable", 63)),
                true_type: Box::new(named_type("unknown", 76)),
                false_type: Box::new(named_type("never", 84)),
            },
            span: Span::new(61, 89),
        };
        let unit = source_unit_with_function(exported_function(
            "process",
            vec![type_param("T", 40)],
            vec![param("input", named_type("T", 51))],
            Some(conditional),
        ));
        let report = check_source_unit(&unit);

        assert!(report.accepted, "{report:#?}");
        let signature = &report.types.function_signatures[0];
        assert!(matches!(
            signature.return_type,
            Some(TypeTerm::Conditional {
                ref check,
                ref extends,
                ref true_type,
                ref false_type,
                ..
            }) if matches!(**check, TypeTerm::Named { ref name, .. } if name == "T")
                && matches!(**extends, TypeTerm::Opaque { ref spelling, .. } if spelling == "Serializable")
                && matches!(**true_type, TypeTerm::Unknown { .. })
                && matches!(**false_type, TypeTerm::Never { .. })
        ));
    }

    #[test]
    fn derives_boundary_policy_facts_from_current_parser_fixture() {
        let report = check_source_text(ACCEPTED_FIXTURE);

        assert_eq!(
            report
                .boundary_facts
                .default_policy
                .as_ref()
                .map(|fact| &fact.policy),
            Some(&"secure".to_string())
        );
        assert!(matches!(
            report.boundary_facts.compartments[0].effective_policy,
            Some(BoundaryPolicyRef::Named(ref policy)) if policy == "secure"
        ));
        assert!(matches!(
            report.boundary_facts.imports[0].explicit_policy,
            Some(BoundaryPolicyRef::Named(ref policy)) if policy == "debug"
        ));
        assert!(matches!(
            report.boundary_facts.functions[0].visible_policy,
            Some(BoundaryPolicyRef::Named(ref policy)) if policy == "secure"
        ));
        assert!(report.obligations.iter().any(|obligation| matches!(
            obligation,
            StaticObligation::ImportBoundaryQualified {
                imported_name,
                policy: BoundaryPolicyRef::Named(policy),
                ..
            } if imported_name == "getUser" && policy == "debug"
        )));
        assert!(report.obligations.iter().any(|obligation| matches!(
            obligation,
            StaticObligation::FunctionBoundaryVisible {
                function_name,
                policy: BoundaryPolicyRef::Named(policy),
                ..
            } if function_name == "process" && policy == "secure"
        )));
    }

