    #[test]
    fn records_weaken_and_skip_return_boundary_posture() {
        let mut function = exported_function(
            "legacy",
            vec![],
            vec![param("input", named_type("unknown", 51))],
            Some(named_type("User", 60)),
        );
        function.boundary_clause = Some(boundary_clause(
            BoundarySite::FunctionDeclaration,
            vec![
                BoundaryDirective::WeakenTo("debug".to_string()),
                BoundaryDirective::SkipReturnValidation,
            ],
            70,
        ));
        let report = check_source_unit(&source_unit_with_function(function));

        assert!(matches!(
            report.boundary_facts.functions[0].visible_policy,
            Some(BoundaryPolicyRef::WeakenTo(ref policy)) if policy == "debug"
        ));
        assert!(report.boundary_facts.functions[0].skip_return_yields_unknown);
        assert!(report.obligations.iter().any(|obligation| matches!(
            obligation,
            StaticObligation::SkipReturnValidationYieldsUnknown {
                function_name,
                ..
            } if function_name == "legacy"
        )));
    }

    #[test]
    fn nested_compartment_import_inherits_weakened_policy() {
        let report = check_source_text(
            r#"boundary default = secure

compartment Outer boundary(secure) {
  compartment Inner boundary(weaken to debug) {
    import { legacy } from "./legacy.js"

    export function main(): unknown boundary(secure) {
      return legacy()
    }
  }
}
"#,
        );

        assert!(report.accepted, "{report:#?}");
        let inner = report
            .boundary_facts
            .compartments
            .iter()
            .find(|fact| fact.compartment == "Inner")
            .expect("inner compartment fact");
        assert!(matches!(
            inner.effective_policy,
            Some(BoundaryPolicyRef::WeakenTo(ref policy)) if policy == "debug"
        ));
        let import = report
            .boundary_facts
            .imports
            .iter()
            .find(|fact| fact.imported_name == "legacy")
            .expect("legacy import fact");
        assert_eq!(import.compartment, "Inner");
        assert!(import.explicit_policy.is_none());
        assert!(matches!(
            import.effective_policy,
            Some(BoundaryPolicyRef::WeakenTo(ref policy)) if policy == "debug"
        ));
        assert!(report.obligations.iter().any(|obligation| matches!(
            obligation,
            StaticObligation::ImportBoundaryQualified {
                compartment,
                imported_name,
                policy: BoundaryPolicyRef::WeakenTo(policy),
                ..
            } if compartment == "Inner" && imported_name == "legacy" && policy == "debug"
        )));
    }

