    #[test]
    fn rejects_never_generic_constraint() {
        let mut constrained = type_param("T", 40);
        constrained.constraint = Some(named_type("never", 50));
        let unit = source_unit_with_function(exported_function(
            "process",
            vec![constrained],
            vec![param("input", named_type("T", 61))],
            Some(named_type("T", 70)),
        ));
        let report = check_source_unit(&unit);

        assert!(!report.accepted);
        assert!(report.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == CheckDiagnosticCode::InvalidGenericConstraint
                && diagnostic
                    .message
                    .contains("cannot be constrained to `never`")
        }));
    }

    #[test]
    fn emits_handoff_facts_after_sound_acceptance() {
        let report = check_source_text(ACCEPTED_FIXTURE);

        assert!(report.accepted, "{report:#?}");
        assert!(report.handoff.erased_annotations.iter().any(|annotation| {
            annotation.kind == ErasedAnnotationKind::ParameterType
                && annotation.owner == "process::input"
        }));
        assert!(report.handoff.erased_annotations.iter().any(|annotation| {
            annotation.kind == ErasedAnnotationKind::ReturnType && annotation.owner == "process"
        }));
        assert!(report
            .handoff
            .build_time_declarations
            .iter()
            .any(|declaration| {
                declaration.kind == BuildTimeDeclarationKind::BoundaryDefault
                    && declaration.name == "secure"
            }));
        assert!(report
            .handoff
            .boundary_qualified_imports
            .iter()
            .any(|fact| fact.imported_name == "getUser"
                && matches!(fact.policy, BoundaryPolicyRef::Named(ref policy) if policy == "debug")));
        assert!(report
            .handoff
            .boundary_qualified_functions
            .iter()
            .any(|fact| fact.function_name == "process"
                && matches!(fact.policy, BoundaryPolicyRef::Named(ref policy) if policy == "secure")));
        assert_eq!(
            report.handoff.static_obligations.len(),
            report.obligations.len()
        );
    }

    #[test]
    fn named_boundary_policy_blocks_enter_handoff_declarations() {
        let src = r#"boundary secure = {
  at process { install: wrapper, mode: strict }
  at call {
    on violation(expected: unknown, received: unknown) {
      throw new CruftTypeError("boundary")
    }
  }
}

compartment Core boundary(secure) {
  export function main(): string boundary(secure) {
    return "ok"
  }
}
"#;
        let report = check_source_text(src);

        assert!(report.accepted, "{report:#?}");
        assert!(report
            .handoff
            .build_time_declarations
            .iter()
            .any(|declaration| {
                declaration.kind == BuildTimeDeclarationKind::BoundaryPolicy
                    && declaration.name == "secure"
            }));
    }

    #[test]
    fn sanitize_boundary_policy_defaults_enter_handoff_declarations() {
        let src = r#"type User = { name: string, tags: Array<string> }

boundary tolerant = {
  at process { install: wrapper, mode: sanitize }
  at sanitize {
    default string = ""
    default number = 0
    default boolean = false
    default null = null
    default undefined = undefined
    default Array<string> = [""]
    default User = { name: "", tags: [""] }
  }
}

compartment Core boundary(tolerant) {
  export function main(): string boundary(tolerant) {
    return "ok"
  }
}
"#;
        let checked = CruftScriptCheckedUnit::parse_and_check("sanitize.fts", src)
            .expect("declared sanitize policy defaults should check");
        let declarations = &checked.report.handoff.build_time_declarations;

        assert!(declarations.iter().any(|declaration| {
            declaration.kind == BuildTimeDeclarationKind::BoundaryPolicy
                && declaration.name == "tolerant"
        }));
        assert_eq!(
            declarations
                .iter()
                .filter(|declaration| {
                    declaration.kind == BuildTimeDeclarationKind::BoundarySanitizerDefault
                })
                .count(),
            7
        );
        assert!(declarations.iter().any(|declaration| {
            declaration.kind == BuildTimeDeclarationKind::BoundarySanitizerDefault
                && declaration.name == "tolerant::User"
        }));
    }

