    #[test]
    fn declared_strict_boundary_policy_resolves_to_secure_runtime_policy() {
        let src = r#"boundary default = audit

boundary audit = {
  at process { install: wrapper, mode: strict }
  at call {
    on violation(expected: unknown, received: unknown) {
      throw new CruftTypeError("audit")
    }
  }
}

compartment Core boundary(audit) {
  import { getUser } from "./legacy.js" boundary(audit)

  export function main(): string boundary {
    return "ok"
  }
}
"#;
        let checked = CruftScriptCheckedUnit::parse_and_check("audit.fts", src)
            .expect("declared strict policy should check");
        let plan = CruftScriptBoundaryWrapperPlan::emit_installs(&checked)
            .expect("declared strict policy should emit wrapper installs");

        assert!(plan.installs.iter().any(|install| {
            install.target_name == "getUser"
                && install.policy_id == 1
                && matches!(install.policy, BoundaryPolicyRef::Named(ref policy) if policy == "audit")
        }));
        assert!(plan.installs.iter().any(|install| {
            install.target_name == "main"
                && install.policy_id == 1
                && matches!(install.policy, BoundaryPolicyRef::Default)
        }));
    }

