    #[test]
    fn diagnostic_record_marks_parser_diagnostic_stage() {
        let rejected = CruftScriptCheckedUnit::parse_and_check(
            "decorator.fts",
            r#"boundary default = secure

compartment Core boundary(secure) {
  @trace
  export function main(): string boundary(secure) {
    return "decorated"
  }
}
"#,
        )
        .expect_err("decorator fixture should reject before checked unit");
        let diagnostic = rejected.report.diagnostics.first().unwrap();
        let record = CruftScriptDiagnosticRecord::from_check(&rejected.provenance, diagnostic, 70);

        assert_eq!(record.stage, CruftScriptDiagnosticStage::Parse);
        assert_eq!(record.code, "UnsupportedDecorator");
        assert!(record.tooling_line().contains("stage=parse"));
        assert!(record.tooling_line().contains("exit=70"));
    }

    #[test]
    fn diagnostic_record_marks_lowering_stage() {
        let checked = CruftScriptCheckedUnit::parse_and_check("fixture.fts", ACCEPTED_FIXTURE)
            .expect("accepted fixture should construct checked unit");
        let diagnostics = CruftScriptLoweredUnit::lower_minimal_erased_body(&checked)
            .expect_err("parameterized accepted fixture should not lower");
        let record = CruftScriptDiagnosticRecord::from_lowering(
            &checked.provenance,
            diagnostics.first().unwrap(),
            70,
        );

        assert_eq!(record.stage, CruftScriptDiagnosticStage::Lower);
        assert_eq!(record.code, "UnsupportedFunctionShape");
        assert!(record.tooling_line().contains("path=fixture.fts"));
        assert!(record.tooling_line().contains("stage=lower"));
    }

