    #[test]
    fn generated_char_code_at_stdlib_signature_feeds_string_member_type() {
        let spec = string_char_code_at_generated_stdlib_signature_spec();
        assert_eq!(spec.api, "String.prototype.charCodeAt");
        assert_eq!(spec.receiver, GeneratedStdlibReceiver::String);
        assert_eq!(spec.property, "charCodeAt");
        assert_eq!(spec.arity, 1);
        assert_eq!(spec.args, &[GeneratedStdlibDomain::Number]);
        assert_eq!(spec.returns, &[GeneratedStdlibDomain::Number]);
        assert!(spec.nullish_receiver_rejects);
        assert!(spec.boundary_safe);

        let generated = string_char_code_at_generated_stdlib_signature_type();
        let member = stdlib_string_member(spec.property)
            .expect("String.prototype.charCodeAt should be an admitted stdlib member");
        assert_eq!(member, generated);

        let TypeTerm::Function {
            params,
            return_type,
            ..
        } = member
        else {
            panic!("expected generated charCodeAt stdlib signature to be a function");
        };
        assert_eq!(params.len(), 2);
        assert_eq!(params[0].name.as_deref(), Some("this"));
        assert!(matches!(
            params[0].ty,
            TypeTerm::Named { ref name, .. } if name == "string"
        ));
        assert_eq!(params[1].name.as_deref(), Some("arg0"));
        assert!(matches!(
            params[1].ty,
            TypeTerm::Named { ref name, .. } if name == "number"
        ));
        assert!(matches!(
            *return_type,
            TypeTerm::Named { ref name, .. } if name == "number"
        ));
    }

