    #[test]
    fn boundary_wrapper_plan_carries_sanitize_policy_defaults() {
        let checked = CruftScriptCheckedUnit::parse_and_check(
            "sanitize-wrapper.fts",
            r#"type User = { name: string, tags: Array<string> }

boundary tolerant = {
  at process { install: wrapper, mode: sanitize }
  at sanitize {
    default string = ""
    default number = 0
    default boolean = false
    default null = null
    default undefined = undefined
    default Array<string> = [""]
    default User = { name: "", tags: [""] }
  }
}

compartment Core boundary(tolerant) {
  import { legacyName } from "./legacy.js" boundary(tolerant)

  export function main(): string boundary(tolerant) {
    return "ok"
  }
}
"#,
        )
        .expect("declared sanitize fixture should check");
        let wrapper_plan = CruftScriptBoundaryWrapperPlan::emit_installs(&checked)
            .expect("sanitize fixture should emit wrapper installs");

        assert_eq!(wrapper_plan.installs.len(), 2);
        for install in &wrapper_plan.installs {
            assert_eq!(install.policy_id, 2);
            assert_eq!(install.opcode.policy_id, 2);
            assert_eq!(install.sanitizer_defaults.len(), 7);
            assert_eq!(install.opcode.sanitizer_defaults.len(), 7);
            assert!(install.sanitizer_defaults.iter().any(|default| {
                matches!(default.target_type, TypeTerm::Named { ref name, .. } if name == "User")
            }));
        }

        let call_plan = CruftScriptRuntimePolicyCallPlan::from_wrapper_plan(&wrapper_plan)
            .expect("sanitize wrapper plan should project to runtime call plan");
        assert_eq!(call_plan.calls.len(), 2);
        assert!(call_plan
            .calls
            .iter()
            .all(|call| call.policy_id == 2 && call.sanitizer_defaults.len() == 7));
    }

