    #[test]
    fn accepts_parser_emitted_type_alias_handoff() {
        let src = r#"boundary default = secure
type Box<T extends User> = T | unknown;

compartment Core boundary(secure) {
  export function process(input: Box<User>): Box<User> boundary(secure) {
    return input
  }
}
"#;
        let report = check_source_text(src);

        assert!(report.accepted, "{report:#?}");
        assert_eq!(report.types.type_aliases.len(), 1);
        assert_eq!(report.types.type_aliases[0].name, "Box");
        assert!(matches!(
            report.types.type_aliases[0].aliased_type,
            TypeTerm::Union { .. }
        ));
        assert!(report
            .handoff
            .build_time_declarations
            .iter()
            .any(
                |declaration| declaration.kind == BuildTimeDeclarationKind::TypeAlias
                    && declaration.name == "Box"
            ));
        assert!(report.handoff.erased_annotations.iter().any(|annotation| {
            annotation.kind == ErasedAnnotationKind::TypeAlias && annotation.owner == "Box"
        }));
    }

