    #[test]
    fn lowers_parser_emitted_boundary_function_type_alias() {
        let src = r#"boundary default = secure
type Handler<T extends User> = (input: T, fallback: unknown) => User boundary(secure);

compartment Core boundary(secure) {
  export function process(input: Handler<User>): Handler<User> boundary(secure) {
    return input
  }
}
"#;
        let report = check_source_text(src);

        assert!(report.accepted, "{report:#?}");
        assert_eq!(report.types.type_aliases[0].type_params[0].name, "T");
        let TypeTerm::Function {
            type_params,
            params,
            return_type,
            boundary,
            ..
        } = &report.types.type_aliases[0].aliased_type
        else {
            panic!("expected function type term");
        };
        assert!(type_params.is_empty());
        assert_eq!(params[0].name.as_deref(), Some("input"));
        assert!(matches!(params[0].ty, TypeTerm::Named { ref name, .. } if name == "T"));
        assert!(matches!(**return_type, TypeTerm::Named { ref name, .. } if name == "User"));
        assert!(matches!(
            boundary.as_ref().and_then(|clause| clause.directives.first()),
            Some(BoundaryDirective::Policy(policy)) if policy == "secure"
        ));
    }

