    #[test]
    fn derives_body_facts_for_local_returns_and_typeof_guard() {
        let src = r#"boundary default = secure

compartment Core boundary(secure) {
  export function process(input: unknown): string boundary(secure) {
    const raw: unknown = input
    if (typeof raw === "string") {
      return raw
    }
    return "fallback"
  }
}
"#;
        let report = check_source_text(src);

        assert!(report.accepted, "{report:#?}");
        assert_eq!(report.body_facts.functions.len(), 1);
        let body = &report.body_facts.functions[0];
        assert_eq!(body.compartment, "Core");
        assert_eq!(body.function_name, "process");
        assert_eq!(body.locals[0].name, "raw");
        assert!(matches!(
            body.locals[0].type_annotation,
            Some(TypeTerm::Unknown { .. })
        ));
        assert!(matches!(
            body.locals[0].initializer.as_ref().map(|expr| &expr.kind),
            Some(ExpressionFactKind::Identifier(name)) if name == "input"
        ));
        assert!(matches!(
            body.guards[0].kind,
            NarrowingGuardFactKind::TypeofEquals {
                ref subject,
                ref expected,
            } if subject == "raw" && expected == "string"
        ));
        assert_eq!(body.returns.len(), 2);
        assert!(matches!(
            body.returns[0].argument.as_ref().map(|expr| &expr.kind),
            Some(ExpressionFactKind::Identifier(name)) if name == "raw"
        ));
        assert!(matches!(
            body.returns[1].argument.as_ref().map(|expr| &expr.kind),
            Some(ExpressionFactKind::StringLiteral(value)) if value == "fallback"
        ));
    }

    #[test]
    fn body_facts_preserve_call_and_truthy_guard_shapes() {
        let src = r#"boundary default = secure

compartment Core boundary(secure) {
  export function process(input: unknown): unknown boundary(secure) {
    let value: unknown = getUser(input)
    if (value) {
      return value
    }
    return input
  }
}
"#;
        let report = check_source_text(src);

        assert!(report.accepted, "{report:#?}");
        let body = &report.body_facts.functions[0];
        let Some(ExpressionFact {
            kind:
                ExpressionFactKind::Call {
                    callee,
                    args,
                    optional,
                },
            ..
        }) = &body.locals[0].initializer
        else {
            panic!("expected call initializer");
        };
        assert!(matches!(
            &callee.kind,
            ExpressionFactKind::Identifier(name) if name == "getUser"
        ));
        assert_eq!(args.len(), 1);
        assert!(!optional);
        assert!(matches!(
            args[0].kind,
            ExpressionFactKind::Identifier(ref name) if name == "input"
        ));
        assert!(matches!(
            body.guards[0].kind,
            NarrowingGuardFactKind::Truthy { ref subject } if subject == "value"
        ));
    }

