    #[test]
    fn object_field_type_predicate_signature_lowers_if_statement_branch() {
        let checked = CruftScriptCheckedUnit::parse_and_check(
            "member-predicate-if.fts",
            r#"boundary default = secure

compartment Core boundary(secure) {
  export function isString(input: unknown): input is string boundary(secure) {
    return typeof input === "string" ? true : false
  }

  export function main(value: unknown): string boundary(secure) {
    const guard = { check: isString }
    if (guard.check(value)) {
      return value
    }
    return "fallback"
  }
}
"#,
        )
        .expect("field-carried predicate if should check");
        let module = CruftScriptExportModule::lower_exports(&checked)
            .expect("field-carried predicate if should lower");
        let export = module.get("main").expect("main export present");

        let string_result = export
            .function
            .call_with_lowered_args(vec![LoweredValue::String("member-if".to_string())])
            .expect("string branch should execute");
        assert_eq!(string_result, LoweredValue::String("member-if".to_string()));
        let fallback_result = export
            .function
            .call_with_lowered_args(vec![LoweredValue::Number("7".to_string())])
            .expect("fallback branch should execute");
        assert_eq!(
            fallback_result,
            LoweredValue::String("fallback".to_string())
        );
    }

