    #[test]
    fn mapped_type_homomorphic_modifiers_lower_from_source_text() {
        let src = r#"boundary default = secure
type PartialUser<T> = { +readonly [K in keyof T]+?: T };

compartment Core boundary(secure) {
  export function process(input: PartialUser<User>): PartialUser<User> boundary(secure) {
    return input
  }
}
"#;
        let report = check_source_text(src);

        assert!(report.accepted, "{report:#?}");
        let alias = report
            .types
            .type_aliases
            .iter()
            .find(|alias| alias.name == "PartialUser")
            .unwrap();
        let TypeTerm::Mapped {
            key_name,
            key_constraint,
            readonly_modifier,
            optional_modifier,
            homomorphic,
            ..
        } = &alias.aliased_type
        else {
            panic!("expected mapped type");
        };
        assert_eq!(key_name, "K");
        assert!(matches!(
            key_constraint,
            MappedKeyTerm::Keyof { target }
                if matches!(&**target, TypeTerm::Named { name, .. } if name == "T")
        ));
        assert_eq!(*readonly_modifier, MappedModifierTerm::Add);
        assert_eq!(*optional_modifier, MappedModifierTerm::Add);
        assert!(*homomorphic);
    }

    #[test]
    fn partial_utility_expands_to_homomorphic_optional_mapped_type() {
        let unit = unit_with_functions(vec![exported_function_with_returns(
            "process",
            Vec::new(),
            vec![param("input", type_ref("Partial", vec![ty("User")]))],
            Some(type_ref("Partial", vec![ty("User")])),
            vec![ident("input")],
        )]);
        let report = check_source_unit(&unit);

        assert!(report.accepted, "{report:#?}");
        let aliases = AliasExpansionContext::new(&report.types);
        let mut diagnostics = Vec::new();
        let expanded = aliases.expand_for_assignability(
            &TypeTerm::TypeRef {
                name: "Partial".to_string(),
                type_args: vec![TypeTerm::Named {
                    name: "User".to_string(),
                    span: span(),
                }],
                span: span(),
            },
            &mut diagnostics,
        );
        assert!(diagnostics.is_empty(), "{diagnostics:#?}");
        let TypeTerm::Mapped {
            key_constraint,
            readonly_modifier,
            optional_modifier,
            homomorphic,
            ..
        } = expanded
        else {
            panic!("expected Partial to expand to mapped type");
        };
        assert!(matches!(key_constraint, MappedKeyTerm::Keyof { .. }));
        assert_eq!(readonly_modifier, MappedModifierTerm::Inherit);
        assert_eq!(optional_modifier, MappedModifierTerm::Add);
        assert!(homomorphic);
    }

