    #[test]
    fn record_optional_string_literal_read_refines_to_value_or_undefined() {
        let src = r#"boundary default = secure
type Counts = Record<string, number>;

compartment Core boundary(secure) {
  export function read(counts: Counts): number | undefined boundary(secure) {
    return counts?.["alpha"]
  }
}
"#;
        let report = check_source_text(src);

        assert!(report.accepted, "{report:#?}");
        let check = report
            .expression_checks
            .functions
            .iter()
            .find(|check| check.function_name == "read")
            .unwrap();
        assert!(check.returns[0].conforms_to_declared);
        assert!(matches!(
            check.returns[0].expression_type,
            Some(TypeTerm::Union { ref members, .. })
                if members.iter().any(|member| matches!(member, TypeTerm::Named { name, .. } if name == "number"))
                    && members.iter().any(|member| matches!(member, TypeTerm::Named { name, .. } if name == "undefined"))
        ));
    }

