    #[test]
    fn pick_object_state_is_structurally_observed() {
        let picked = TypeTerm::Object {
            properties: vec![ObjectPropertyTerm {
                name: "name".to_string(),
                ty: TypeTerm::Named {
                    name: "string".to_string(),
                    span: span(),
                },
                readonly: false,
                optional: true,
                span: span(),
            }],
            span: span(),
        };
        let expected = TypeTerm::Object {
            properties: vec![ObjectPropertyTerm {
                name: "name".to_string(),
                ty: TypeTerm::Named {
                    name: "string".to_string(),
                    span: span(),
                },
                readonly: false,
                optional: true,
                span: span(),
            }],
            span: span(),
        };
        let wider = TypeTerm::Object {
            properties: vec![
                ObjectPropertyTerm {
                    name: "name".to_string(),
                    ty: TypeTerm::Named {
                        name: "string".to_string(),
                        span: span(),
                    },
                    readonly: false,
                    optional: true,
                    span: span(),
                },
                ObjectPropertyTerm {
                    name: "id".to_string(),
                    ty: TypeTerm::Named {
                        name: "number".to_string(),
                        span: span(),
                    },
                    readonly: false,
                    optional: false,
                    span: span(),
                },
            ],
            span: span(),
        };

        assert!(is_assignable_expanded(&picked, &expected));
        assert!(is_assignable_expanded(&wider, &expected));
        assert!(!type_terms_equivalent(&wider, &expected));
    }

