    #[test]
    fn best_common_type_selects_union_for_simple_candidates() {
        let unit = unit_with_functions(vec![
            exported_function_with_returns(
                "choose",
                vec![type_param("T", 0)],
                vec![param("left", ty("T")), param("right", ty("T"))],
                Some(ty("T")),
                vec![ident("left")],
            ),
            exported_function_with_returns(
                "process",
                Vec::new(),
                vec![param("input", ty("string"))],
                Some(union_ty(vec![ty("string"), ty("number")])),
                vec![call("choose", vec![ident("input"), number_lit("1")])],
            ),
        ]);
        let report = check_source_unit(&unit);

        assert!(report.accepted, "{report:#?}");
        let check = report
            .expression_checks
            .functions
            .iter()
            .find(|check| check.function_name == "process")
            .unwrap();
        assert!(matches!(
            check.returns[0].expression_type,
            Some(TypeTerm::Union { ref members, .. })
                if members.iter().any(|member| matches!(member, TypeTerm::Named { name, .. } if name == "string"))
                    && members.iter().any(|member| matches!(member, TypeTerm::Named { name, .. } if name == "number"))
        ));
        assert!(check.returns[0].conforms_to_declared);
    }

    #[test]
    fn inference_failure_without_candidates_suppresses_handoff() {
        let unit = unit_with_functions(vec![
            exported_function_with_returns(
                "make",
                vec![type_param("T", 0)],
                Vec::new(),
                Some(ty("T")),
                Vec::new(),
            ),
            exported_function_with_returns(
                "process",
                Vec::new(),
                vec![param("input", ty("string"))],
                Some(ty("string")),
                vec![call("make", Vec::new())],
            ),
        ]);
        let report = check_source_unit(&unit);

        assert!(!report.accepted);
        assert!(report.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == CheckDiagnosticCode::InferenceFailed
                && diagnostic.message.contains("no candidates")
        }));
        assert!(report.handoff.erased_annotations.is_empty());
    }

    #[test]
    fn inference_candidate_conflict_suppresses_handoff() {
        let unit = unit_with_functions(vec![
            exported_function_with_returns(
                "choose",
                vec![type_param("T", 0)],
                vec![param("left", ty("T")), param("right", ty("T"))],
                Some(ty("T")),
                vec![ident("left")],
            ),
            exported_function_with_returns(
                "process",
                Vec::new(),
                vec![
                    param("fnValue", fn_ty(ty("string"), ty("string"))),
                    param("input", ty("string")),
                ],
                Some(ty("unknown")),
                vec![call("choose", vec![ident("fnValue"), ident("input")])],
            ),
        ]);
        let report = check_source_unit(&unit);

        assert!(!report.accepted);
        assert!(report.diagnostics.iter().any(|diagnostic| {
            diagnostic.code == CheckDiagnosticCode::InferenceCandidateConflict
                && diagnostic.message.contains("conflicting candidates")
        }));
        assert!(report.handoff.erased_annotations.is_empty());
    }

