    #[test]
    fn accepts_bounded_class_as_structural_type_before_handoff() {
        let src = r#"boundary default = secure

compartment Core boundary(secure) {
  export class Box {
    readonly label: string
    value?: number
  }
  export function read(input: Box): string boundary(secure) {
    return input.label
  }
}
"#;
        let report = check_source_text(src);

        assert!(report.accepted);
        let class_alias = report
            .types
            .type_aliases
            .iter()
            .find(|alias| alias.name == "Box")
            .expect("expected class structural alias");
        let TypeTerm::Object { properties, .. } = &class_alias.aliased_type else {
            panic!("expected class to lower to object type");
        };
        assert_eq!(properties.len(), 2);
        assert_eq!(properties[0].name, "label");
        assert!(properties[0].readonly);
        assert_eq!(properties[1].name, "value");
        assert!(properties[1].optional);
    }

